pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into
    // capacity-fraction bands. Small-but-nonzero residuals are the worst
    // because few future items (>= 1) can use them.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 200.0;
    } else {
        // Dead-space band penalty: residual in (0, 10] is nearly unusable.
        if post_residual <= 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 30 {
            score += 8.0;
        }

        // Modulo-10 harmonic class: residuals that are multiples of common
        // item-size granularities are more reusable.
        if post_residual % 10 == 0 {
            score -= 15.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        }

        // Fractional class: residual above half capacity is very flexible.
        if pr > cap * 0.5 {
            score -= 20.0;
        } else if pr > cap * 0.25 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // big reward; if it nearly fits, small penalty for blocking a better bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
            // reward if next item lands in a harmonic class matching residual
            if post_residual % 10 == 0 && next_item_size % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow here; slight penalty scaled by closeness
            score += (nx - pr).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity and few bins fit it.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: keep it high so it's chosen only when needed.
        score += 40.0;
        if item_size as f64 > cap * 0.5 && fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // If open bins are already crowded on average, a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild preference for fuller bins when many are open.
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize unusable "dead" gaps: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Penalize gaps that cannot fit the lookahead item (k=2) when it's real.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also serve the next item.
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.7 {
        score -= 40.0 * (fill_ratio - 0.7);
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading into new bins.
    score += 4.0 * open_bins_count as f64;

    // Prefer bins with residual below mean (consolidating small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // New empty bin candidate: neutral baseline, slightly above good fits,
    // below bad fits, so it is chosen only when all open fits are poor.
    if bin_residual == bin_capacity {
        score = 180.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is less costly (fewer future items to serve).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 80.0 * progress;
        // If next item is large and this item is small, a fresh bin keeps flexibility.
        if next_item_size > item_size + 20 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap <= 10.0 {
            // Tiny gaps are dead space: big penalty, tighter gap = worse.
            score += (11.0 - gap) * 12.0;
        } else if gap < 20.0 {
            score += (20.0 - gap) * 2.5;
        }
        // Reward usable residual chunks that can still host plausible items.
        if gap >= 20.0 {
            score -= 8.0;
        }
        if gap >= 50.0 {
            score -= 10.0;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 40.0;
    }

    // Reward tightness relative to bin capacity (best-fit core).
    let tightness = (bin_capacity - bin_residual.min(bin_capacity)) as f64 / bin_capacity as f64;
    score -= tightness * 6.0;

    // Open-bins pressure: with many open bins, prefer reusing existing bins;
    // with few open bins, allow new bins more readily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.35;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or mean residual is very low.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        let desperation = if fitting_bins_count == 0 {
            25.0
        } else {
            (mean_gap / 10.0).min(20.0)
        };
        // Base new-bin cost plus desperation discount.
        score = 55.0 - desperation + open_bins_count as f64 * 0.15;
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Lookahead synergy: placing here leaves room for the next item.
        if post_residual as i64 >= next_item_size as i64 {
            score -= 5.0;
        } else if (post_residual as i64) > 0 && (post_residual as i64) < next_item_size as i64 {
            score += 3.0;
        }
    }

    score
}

