pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 150.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize wasting a good residual
        score += 30.0;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    let rel = post_residual as f64 - mean_residual;
    score += 0.5 * rel;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin unless the item is large relative to residual
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 60.0 * (1.0 - fill_ratio);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin serves the next item too
        }
    }

    // Late-stream tightening: fewer open bins pressure toward consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small dead-space penalty (nonlinear): residuals in awkward mid-range
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect two-step match (next item exactly fills leftover).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Reward if next item fits into post residual (chainable bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    }
    // Penalize dead space smaller than next item (unusable gap).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.8 * (next_item_size - post_residual) as f64;
    }

    // Penalize waste relative to mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer keeping it closed early; allow opening when
    // current bin would leave a tiny dead gap.
    if bin_residual == bin_capacity {
        let tight_elsewhere = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 5;
        if tight_elsewhere {
            score += 60.0; // existing bin chains nicely, don't open new one
        } else if next_item_size > 0 && post_residual < next_item_size && post_residual <= 10 {
            score -= 55.0; // current fit is poor; fresh bin better
        } else {
            score += 10.0;
        }
    }

    // Late-stream tightening: prefer filling bins completely near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are wasted forever.
    if post_residual > 0 {
        let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
        if post_residual < min_useful {
            // Dead space penalty: proportionally severe.
            score += 60.0 * (1.0 - post_residual as f64 / min_useful as f64);
        }
        // Post-residual that cannot fit the known next item is risky.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 25.0;
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist; encourage using existing capacity.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }
    score += 0.15 * open_bins_count as f64;

    // Pull toward mean residual state: bins far from the pack's typical
    // fullness are less attractive unless the fit is tight.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when current bins are crowded
    // or this is the last fitting bin (avoid forcing bad fits).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.25 + 20.0 * (1.0 - fill_ratio);
        let last_chance = if fitting_bins_count == 1 { 10.0 } else { 0.0 };
        // Base cost of a fresh bin, discounted when many bins are open.
        score = 55.0 - pressure.min(45.0) + last_chance;
        // Late in the stream, opening new bins is more acceptable.
        score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post == next {
            // Perfect match: this bin's leftover exactly fits the next item
            score -= 60.0;
        } else if post > next {
            // Leftover still usable by the next item; closer match is better
            let slack = (post - next) / cap;
            score -= 18.0 * (1.0 - slack);
        } else {
            // Dead space for the next item: penalize proportionally to the gap
            score += 22.0 + (next - post);
        }
    }

    // --- Relative-to-mean coupling: prefer bins tighter than average ---
    score -= 0.35 * (post - mean_residual);

    // --- Last-chance bonus: only open bin that fits, avoid wasting it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin: high so it loses to decent fits
        score = cap + 40.0;
        if fitting_bins_count == 1 {
            // No open bin can fit the item -> opening a new bin is necessary
            score -= 200.0;
        } else if next_item_size > 0 {
            let next = next_item_size as f64;
            // A fresh bin gives a perfect post-fit for the next item
            if post == next {
                score -= 90.0;
            } else if (item_size as f64 + next) <= cap {
                score -= 45.0;
            }
        }
        // Late in the stream, avoid spawning extra bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the item: which capacity fraction does it live in? ---
    // Classes: (0,25], (25,50], (50,75], (75,100]
    let item_class = ((item_size - 1) * 4 / bin_capacity) as i64; // 0..3
    let next_class = if next_item_size == 0 { -1 } else { ((next_item_size - 1) * 4 / bin_capacity) as i64 };

    // --- Reward tight fits, scaled by post-residual harmonic class ---
    // post_residual in small "dead" classes is bad unless it's exactly 0.
    if post_residual == 0 {
        score -= 60.0; // perfect fill is always best
    } else {
        let post_class = ((post_residual - 1) * 4 / bin_capacity) as i64; // 0..3
        // Penalize dead space quadratically within its harmonic class
        score += (post_residual as f64) * (1.0 + 0.25 * post_class as f64);
        // Dead space in the lowest class (1..25) is nearly unusable
        if post_class == 0 {
            score += 18.0;
        }
        // Mid-class residual (25..50) is moderately useful
        if post_class == 1 {
            score -= 6.0;
        }
    }

    // --- Modulo pairing logic: does the next item fit the post-residual exactly or near-exactly? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 45.0; // sets up a perfect follow-up fill
        } else if gap <= 10 {
            score -= 20.0;
        } else if gap <= 25 {
            score -= 8.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: residual becomes pure waste
        score += 12.0;
    }

    // --- Harmonic complementarity: item class + next class summing near capacity ---
    if next_item_size > 0 {
        let pair_sum = item_size + next_item_size;
        if pair_sum == bin_capacity {
            score -= 30.0; // ideal harmonic pair
        } else if pair_sum > bin_capacity {
            score += 5.0; // pair overflows capacity, less attractive
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0; // strongly prefer using the only fitting bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: attractive early in the stream or when open bins are all tight,
        // but never free — must be worse than a genuinely good fit.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 22.0 + 10.0 * progress;
        // If the item is large (top harmonic class), a fresh bin is natural
        if item_class >= 2 {
            score = base - 6.0;
        } else {
            score = base;
        }
        // Many open bins with slack: discourage adding another
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 14.0;
        }
    }

    // --- Mild preference to keep bin count low ---
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

