pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits into the post-residual gap exactly or well
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use the gap; penalize dead space proportionally
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last chance: only this bin can fit the item -> strongly favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize leaving very small unusable slivers (< 10 assumed min item, use small threshold)
    if post_residual > 0 && post_residual < 5 {
        score += 80.0;
    }

    // Time horizon: early in stream, prefer keeping residuals large (flexibility);
    // late in stream, prefer tighter packing (minimize post residual harder)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += score * 0.2 * progress;

    // New-bin candidate handling: empty bin gets moderate penalty so it's chosen
    // only when no open bin offers a good fit; scale with how many bins already fit.
    if bin_residual == bin_capacity {
        score += 120.0 + 40.0 * (fitting_bins_count as f64);
        // late in stream, opening new bins is less costly than wasting capacity
        score -= 60.0 * progress;
    }

    // Global state: if mean residual across open bins is high, prefer filling
    // already-open bins (consolidation); if low, mild preference for tight fits.
    score -= mean_residual * 0.1;

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is close to item size (tight fit among candidates)
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let mean_r = mean_residual / cap;

    // Base: post residual, mildly damped by progress (late stream => waste matters more)
    let mut score = pr * (1.0 + 0.35 * progress);

    // Smooth polynomial interaction: residual vs progress curvature
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 25.0 * norm_pr * norm_item * (1.0 - progress);

    // Prefer bins whose residual is near mean (balance residuals) with smooth coupling
    let diff = norm_pr - mean_r;
    score += 15.0 * diff * diff;

    // Last-chance bonus (only fitting bin) — strong reward, scaled by tightness
    if fitting_bins_count == 1 {
        score -= 30.0 + 50.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits into post residual (smooth quadratic)
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        if gap >= 0.0 {
            score -= 20.0 * gap * (1.0 - gap);
        } else {
            score += 10.0 * gap * gap;
        }
    }

    // Penalize near-full bins slightly less as stream ends (avoid opening bins late)
    score -= 8.0 * progress * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (dead space) are penalized; leftovers that
    // match common item sizes are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Integer-division thresholds on post_residual (harmonic bands of capacity)
    let band = post_residual / (bin_capacity / 4); // 0..=4 harmonic band
    match band {
        0 => score -= 12.0,          // tiny leftover: near-perfect fit
        1 => score += 3.0,           // 25-ish leftover: moderately useful
        2 => score -= 2.0,           // ~50 leftover: still very usable
        3 => score += 5.0,           // ~75 leftover: risky dead space
        _ => {}
    }

    // Modulo arithmetic: leftover divisible by common item granularities is reusable
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else { score += 1.5; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained perfect fit).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // next item fits: leftover after that would be post - n
            let second_left = post_residual - next_item_size;
            if second_left % 10 == 0 { score -= 8.0; }
            score -= 4.0 * (1.0 - (second_left as f64) / cap);
        } else {
            // next item won't fit here: penalize more for larger overshoot
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 + 4.0 * (gap / cap);
        }
        // harmonic class of next item: big next items favor tight fits now
        if next_item_size >= 60 && frac < 0.2 { score -= 3.0; }
        if next_item_size <= 20 && frac > 0.5 { score += 2.0; }
    } else {
        // last item: just minimize leftover
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin offers a good (small) leftover.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened by stream position and load
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = cap * 0.55 + 20.0 * (1.0 - progress);
        if open_bins_count == 0 { new_bin_score -= 30.0; }
        // if mean residual across open bins is small, open bins are crowded -> new bin ok
        new_bin_score -= 0.5 * mean_residual.min(cap);
        score = score.min(new_bin_score);
        score = new_bin_score.max(score); // keep as-is: score already set above
    }

    // Mild pressure against hoarding many open bins with scattered residual
    score += 0.15 * open_bins_count as f64;

    // Slight tie-break toward tighter fits as the stream progresses
    score += 0.02 * (step_index as f64) * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (tight packing bonus).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize waste proportional to how much of the bin is left unused.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // (penalize the new-bin candidate implicitly via residual == capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no open bin fits well.
        score += 15.0 + (open_bins_count as f64) * 2.5;
        // If next item is large and current item is small, opening a fresh bin
        // may preserve residual structure — mild discount.
        if next_item_size > item_size * 2 {
            score -= 10.0;
        }
    } else {
        // Reusing an open bin is generally good: reward it.
        score -= 12.0;
        // Last-chance bin: if this is the only bin that fits, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < dead_threshold {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: avoid creating outliers far below mean residual
    // (fragmenting the bin set).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // Slight stream-progression pressure: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post-residual can still host the next item: mild reward proportional to tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the next item: penalize more if gap is large.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.35;
    }

    // Reward tight fits overall (small post_residual relative to capacity).
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far below the mean residual (wasteful use of a fuller bin context),
    // but reward bins near the mean residual.
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev.abs();

    // Late in the stream, prefer consolidating into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for opening a brand-new bin when others fit.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional progress through the stream (0..1).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Identify the brand-new empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // Base preference: tight fits (small post_residual) are good.
    // Amplify tightness reward as the stream progresses (less room to waste later).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0 * (0.5 + progress);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin remains usable for the next item: reward.
            score -= 8.0;
            // Extra reward if post_residual is close to next item size (efficient chaining).
            let chain_waste = post_residual - next_item_size;
            score -= (1.0 - chain_waste as f64 / bin_capacity as f64) * 6.0;
        } else {
            // Placing here strands the next item: penalize proportionally.
            score += 5.0 + (next_item_size as f64 - post_residual as f64) * 0.2;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Global pressure: many open bins with low mean residual -> conserve bins,
    // prefer filling existing ones.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.5 {
            // Bins are mostly full: discourage opening new bins.
            if is_new_bin {
                score += 20.0 * (1.0 - pressure);
            }
        } else {
            // Plenty of slack overall: a fresh bin is less harmful.
            if is_new_bin {
                score -= 3.0 * pressure;
            }
        }
    }

    // New-bin handling: opening a bin wastes capacity when the item is small.
    if is_new_bin {
        // Penalize proportional to unused capacity that must be filled later.
        score += (bin_capacity - item_size) as f64 * 0.3;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= (1.0 - progress) * 10.0;
    } else {
        // Reward using existing bins, more so with many open bins.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Slight reward for placing large items into tight remaining space
    // (best-fit with size awareness).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 10.0 * (fill_ratio - 0.8);
    }

    // Time-horizon scaling: as the end approaches, minimize immediate waste harder.
    score *= 1.0 + progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: penalize large post-residual more as stream progresses
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * (100.0 + 200.0 * progress);

    // Reward tight fits (small post-residual) more strongly early on
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 30.0 * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Penalize leaving dead space below the smallest possible item (1..=100 unknown, use item_size as reference)
    if pr < item_size as f64 && pr > 0.0 {
        score += 15.0 * (1.0 - pr / cap);
    }

    // Lookahead coupling: reward residual that can still fit the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 12.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 8.0 * (n - pr) / cap;
        }
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).sqrt() * (0.5 + progress);
    }

    // Diversification: encourage balancing residuals toward mean
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post_residual (tight packing).
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of the post-residual: residuals that are "usable"
    // for typical small items (multiples of 10-ish, or >= 20) are better
    // than awkward leftovers. Penalize dead space in (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Mid-range awkward residuals (11..=19) are semi-dead.
    if post_residual >= 11 && post_residual <= 19 {
        score += 10.0;
    }

    // Modulo arithmetic on residual: residuals congruent to small
    // remainders mod 10 are slightly less flexible.
    let rmod = post_residual % 10;
    if post_residual > 0 && rmod >= 1 && rmod <= 3 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item fits: keep residual class of (post - next) tight.
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score += 6.0; // would leave dead space after next
            }
            score -= 8.0;
        } else {
            // Next item won't fit here: slight penalty if this bin's
            // leftover is unusable anyway.
            if post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, but discourage when the
    // item fits well somewhere else (small post_residual elsewhere).
    if bin_residual == bin_capacity {
        // Opening a new bin leaves residual = C - item_size.
        score += 15.0;
        // If current stream is early and open bins exist, mild penalty.
        if open_bins_count > 0 {
            score += 5.0;
        }
        // If many bins fit the item, opening new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.8 {
            score += 8.0;
        }
    } else {
        // Existing bin: reward using bins with larger residual first
        // (best-fit already via base score); small bonus for reducing
        // bin count pressure.
        score -= 2.0;
    }

    // Coupling with mean residual: if this bin is far below the mean
    // residual (already tight), mildly prefer other bins.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the minimum item size
    // (1 in the general interface, but small gaps < 10 are near-unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Mild preference for tighter fits generally: normalize post residual by capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Lookahead coupling: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack < 10 {
            score -= 15.0;
        }
    }
    // If next item cannot fit into post residual, this bin's leftover is dead weight
    // unless the bin is essentially full; slight penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (a new bin has bin_residual == bin_capacity, so its post_residual is large;
    //  add an explicit surcharge proportional to open bins for such candidates).
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 5.0;
    } else {
        // Reward using existing bins more when bin count is high.
        score -= open_bins_count as f64 * 1.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean residual context: if this bin's residual is far below mean, it's a good
    // candidate to consolidate into (it's the " fullest" bin).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.5;
    }

    // Late-stream urgency: near the end, close out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the
