        } else if post_residual >= next_item_size {
            // next item still fits: mild reward proportional to tightness
            score -= 50.0 * (1.0 - (post - nxt) / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize proportionally to waste
            score += 40.0 * (nxt - post) / 10.0;
        }
    }

    // Penalize small nonzero residuals that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Prefer tighter-than-average bins when many bins are open.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when open bins are very full
    // (high mean residual means little room left overall).
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted when existing bins are crowded
        score = 100.0 + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can always take the next item
            score -= 30.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Penalize dead space: residuals too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Tight fit reward: item occupies most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
            // Bonus if the next item would then nearly fill the bin.
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 {
                score -= 25.0;
            }
        } else {
            // Post-residual can't host next item: penalize proportionally to waste.
            score += 12.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Crowding pressure: many open bins → encourage consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: bins deviating below mean residual (tighter than average) are better targets.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin, more so late in the stream,
    // unless the item is huge and fits almost nothing else.
    if bin_residual == bin_capacity {
        let huge_item = item_size >= 80;
        let no_real_fit = fitting_bins_count == 0;
        if !(huge_item && no_real_fit) {
            score += 150.0 + 100.0 * progress;
        } else {
            score += 20.0;
        }
        // Early stream: opening bins is cheaper.
        score -= 60.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit)
    let mut score = pr as f64;

    // Smooth non-linear coupling: polynomial in normalized post residual,
    // weighted by stream progress. Late in the stream, dead space is
    // increasingly penalized super-linearly.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * norm_pr);
    score += 40.0 * progress * poly;

    // Early in the stream, mildly prefer keeping some headroom (larger post residual
    // is less bad), realized as a smooth decay bonus.
    score -= 15.0 * (1.0 - progress) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward bins whose post residual can still host the next item
    if next_item_size > 0 {
        let nxs = next_item_size as f64;
        if pr >= nxs {
            let slack = (pr - nxs) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            let miss = (nxs - pr) / cap;
            score += 20.0 * miss * miss;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Crowding penalty: many open bins with high mean residual -> discourage
    // spreading; slight penalty scaled by normalized residual deviation.
    let dev = (mean_residual - pr).abs() / cap;
    score += 5.0 * (open_bins_count as f64).ln().max(0.0) * dev * dev;

    // New-bin candidate: penalize mildly so it's chosen only when it truly
    // beats poor fits (its post_residual = capacity - item_size is large).
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let mut score = post;

    // Harmonic class of the post residual: modulo-10 buckets.
    // Residuals that are "dead" (very small but nonzero) are worst;
    // large residuals are reusable. Class 0 (multiple of 10) is neutral.
    let cls = post_residual % 10;
    let class_penalty = match cls {
        0 => -2.0,
        1..=3 => 8.0,       // dead space: too small for most items
        4..=6 => 2.0,       // marginal: fits only tiny items
        7..=9 => -1.0,      // decent chance of reuse
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: post_residual / 20 gives coarse size class.
    let size_class = post_residual / 20; // 0..=5
    score -= size_class as f64 * 3.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 10.0 * fill;
        } else {
            // next item cannot use this residual: mild penalty scaled by wasted space
            score += (post / cap) * 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling bins with large residuals relative to fleet mean (balance).
    score += ((post - mean_residual) / cap) * 5.0;

    // New empty bin candidate: make it unattractive unless the item is huge
    // and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.75;
        // If the item is large relative to capacity, a fresh bin is reasonable.
        score -= (item_size as f64 / cap) * cap * 0.55;
        // If many bins fit the item, definitely prefer an existing one.
        score += fitting_bins_count as f64 * 4.0;
        // Late in the stream, opening bins is less costly (less future risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // If next item is also large, a fresh bin gives flexibility.
        if (next_item_size as f64) > cap * 0.5 {
            score -= 8.0;
        }
    }

    // Slight preference to pack into fewer bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the minimum item (<= ~10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual < 25 {
        // Small awkward gaps: moderately penalize, scaled by gap tininess.
        score += 1.5 * (25.0 - post_residual as f64);
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0; // next item plugs this bin almost perfectly
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Next item cannot use this dead gap: extra penalty.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (penalize the empty-bin candidate implicitly by rewarding reuse).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or
        // mean residual is still large enough to absorb the item.
        score += 20.0 + 2.5 * open_bins_count as f64 + (mean_residual / item_size.max(1) as f64) * 10.0;
    } else {
        // Fitting into an existing bin is good; extra reward under pressure.
        score -= 1.0 + 0.3 * bin_pressure + 2.0 * progress;
    }

    // Mild preference for filling bins with larger residuals first
    // (keeps small residuals from accumulating across many bins).
    score -= 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: heavily reward bins where the item fills them exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits too: mild reward, scaled by how well it fits.
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual: penalize dead space potential.
            score += 30.0;
        }
    }

    // Compare post_residual against mean residual: avoid leaving residuals
    // far below the mean (fragmenting) while keeping large residuals available.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 {
        score += 40.0; // creating small unusable-ish residual
    } else if pr > mean_residual * 1.5 {
        score -= 20.0; // keeping big residual is good
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and would otherwise create tight fits elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 250.0;
        // Reward new bin if current item is large (better to isolate big items).
        if item_size >= bin_capacity / 2 {
            score -= 200.0;
        }
        // If lookahead item is large, a fresh bin may pair well.
        if next_item_size >= bin_capacity / 2 {
            score -= 50.0;
        }
        // Late in stream, prefer closing out existing bins instead.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 * progress;
    }

    // Slight preference for tighter existing fits (smaller bin_residual waste).
    score += (bin_residual - item_size) as f64 * 0.1;

    // Mild bonus for keeping the number of open bins manageable.
    if open_bins_count > 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual dominates ranking.
    score -= 0.45 * (post_residual as f64).sqrt() * 2.0;

    // Penalize creating dead space that nothing small could use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item nearly fills a fresh bin.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.85 {
            score -= 30.0; // big item: fresh bin is fine
        } else if fitting_bins_count == 0 {
            score -= 20.0; // forced opening
        } else {
            score += 15.0 + 0.5 * mean_residual; // discourage wasting open space
        }
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 12.0;
        } else {
            let gap = (next_item_size as i64 - post_residual as i64).max(0) as f64;
            score += 0.3 * gap;
        }
    }

    // Global state: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64;
    score += (mean_residual - post_residual as f64) * 0.15;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are rewarded more aggressively.
    let tightness = 1.0 - pr / cap; // in (0,1], higher = tighter fit
    score -= tightness * tightness * (2.0 + 3.0 * progress);

    // Penalize dead space that is too small to be useful for typical future items,
    // with a smooth saturating function of post_residual.
    let dead = (pr / cap).powi(3);
    score += 4.0 * dead * (1.0 - progress);

    // Reward using bins when few bins can fit the item (avoid opening new bins unnecessarily).
    if fitting_bins_count <= 1 {
        score -= 3.0;
    } else {
        score -= (fitting_bins_count as f64).ln() * 0.5;
    }

    // Slight preference for bins whose residual is close to the mean residual
    // (keeps the pool of open bins homogeneous).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 2.0;

    // Lookahead: reward leaving space for the next item smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).max(0.0) * 1.5;
    }

    // New-bin candidate: bin_residual == bin_capacity. Penalize opening a new bin
    // unless the fit is very tight, with a smooth penalty growing over the stream.
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * progress - 6.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post-residual (capacity fractions) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Which harmonic band does the leftover fall into?
    // Bands: (0,10], (10,20], (20,33], (33,50], (50,100]
    let band = if post_residual == 0 { 0.0 }
        else if post_residual <= 10 { 1.0 }
        else if post_residual <= 20 { 2.0 }
        else if post_residual <= 33 { 3.0 }
        else if post_residual <= 50 { 4.0 }
        else { 5.0 };

    // Small leftovers are dead space unless exactly usable by next item.
    let next_fits = next_item_size > 0 && next_item_size <= post_residual;
    if post_residual > 0 && !next_fits {
        // Dead-space penalty grows the smaller the unusable leftover
        score += (12.0 - pr / 10.0).max(0.0) * 2.0;
    }
    if next_fits {
        // Reward leftovers that exactly accommodate the lookahead item
        score -= 6.0 + (post_residual as i32 - next_item_size as i32).unsigned_abs() as f64 * 0.5;
        // Perfect match for next item: strong reward
        if next_item_size == post_residual { score -= 15.0; }
    }

    // Integer-division thresholds: leftover divisible into common item classes
    // Items 10..80 -> useful chunk sizes 10,20,25,40,50
    for &chunk in &[10u32, 20, 25, 40, 50] {
        if post_residual >= chunk && post_residual % chunk == 0 {
            score -= 3.0; // leftover lies on a harmonic grid -> reusable
        }
    }
    // Modulo coupling between item and capacity
    if item_size % 10 == 0 && bin_residual % 10 == 0 {
        score -= 2.0;
    }

    // Tight-fit reward: waste ratio
    let waste_ratio = pr / cap;
    score -= (1.0 - waste_ratio) * 4.0;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation elsewhere
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 0.8;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap * 0.62;
        // Large items justify a fresh bin more (less likely to waste it)
        if item_size >= 50 { score -= 12.0; }
        if item_size >= 70 { score -= 8.0; }
        // Early in stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // If many open bins already, discourage proliferation
        score += open_bins_count as f64 * 1.5;
        // If lookahead is small, a fresh bin can absorb it too
        if next_item_size > 0 && next_item_size <= 30 { score -= 4.0; }
        // If this is the only option (no fitting open bins), make it cheap
        if fitting_bins_count == 0 { score -= 30.0; }
    }

    // Mean-residual coupling: prefer bins whose residual deviates from mean
    // (filling outlier-small residuals consolidates waste)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream tightening: be greedier about tight fits near the end
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - waste_ratio) * 4.0 * progress;
    score += band * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.85;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // 2-step lookahead: strongly reward post_residual matching next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0; // perfect chain: this bin will be filled exactly next step
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + slack / 20.0); // next item still fits with modest slack
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5; // next item won't fit here; penalize proportionally
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let openness = (open_bins_count as f64 / (1.0 + progress * 5.0)).min(3.0);
        // Base penalty for opening a new bin, reduced when mean residual is low
        // (existing bins are packed) or many items remain.
        let mut new_bin_penalty = 120.0 - 80.0 * (1.0 - avg_fill).min(1.0);
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            new_bin_penalty -= 25.0; // fresh bin fits the next item nicely too
        }
        score += new_bin_penalty + 10.0 * openness;
    }

    // Mild penalty for leaving large dead space relative to smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny unusable slivers are fine; large gaps already penalized
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary tight-fit reward: strongly favor minimal post residual.
    score -= 0.35 * (bin_capacity as f64 - post_residual as f64);

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead (k=2): reward bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // Penalize leaving a dead sliver that no plausible item (>=1) can use well.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current fit is bad.
    if bin_residual == bin_capacity {
        // Base penalty for proliferation of open bins.
        score += 12.0 + 0.5 * open_bins_count as f64;
        // If the item fits the empty bin very loosely (large residual waste), discourage.
        if item_size <= bin_capacity / 2 {
            score += 10.0;
        }
        // Early in the stream, new bins are cheaper; later, consolidation matters.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If many open bins have slack, discourage yet another bin.
        if mean_residual > item_size as f64 * 1.5 {
            score += 8.0;
        }
    } else {
        // Reward using bins that are already well-utilized (low residual relative to mean).
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 0.15 * dev;
        } else {
            score += 0.15 * (-dev);
        }
    }

    // Slight global pressure: with many open bins, tighten packing.
    score += 0.05 * open_bins_count as f64;

    // Late-stream urgency: minimize wasted residual as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening over time.
    let mut score = norm_pr * (1.0 + 2.0 * progress * progress);

    // Polynomial coupling: post_residual^2 scaled by progress penalizes
    // dead space more aggressively as the stream unfolds.
    score += 0.5 * norm_pr * norm_pr * (0.5 + progress);

    // Tight fits (post_residual near zero) get a smooth reward.
    score -= 0.8 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin: smooth bonus scaled by how few alternatives exist.
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 1.5 * scarcity * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 0.6 * snug * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 0.4 * progress;
    }

    // Divergence from mean residual: prefer bins near the mean early,
    // prefer below-mean (tighter) bins late.
    let dev = (pr - mean_residual) / cap;
    score += dev * (1.0 - 2.0 * progress) * 0.5;

    // Mild penalty for spreading across many open bins late in stream.
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: neutral base so it wins only when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 1.2 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (multiples of 10, or large enough) are preferred.
    let class = post_residual / 10;
    let in_class = post_residual % 10;
    // Reward exact decade alignment (harmonic with typical item granularity).
    if in_class == 0 {
        score -= 6.0;
    } else {
        score += in_class as f64 * 0.35; // penalize ragged remainders
    }

    // Prefer bins whose residual class can host the next item harmonically.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nxt_class = next_item_size / 10;
            // reward when next item size is a harmonic divisor of post_residual class
            if class > 0 && nxt_class > 0 && class % nxt_class == 0 {
                score -= 8.0;
            } else {
                score -= 4.0;
            }
            // tight two-item packing: next item exactly fills remainder
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else {
            // next item cannot fit here: penalize dead space creation
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // last item: any fit is fine, favor tightest
        score -= 10.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // Penalize very small unusable remainders (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 9.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 18.0;
        // If no open bin fits, opening is mandatory-ish: reduce penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if fitting_bins_count == 1 {
            score += 6.0; // keep the last-chance bin preferred
        }
        // Early in stream, new bins are cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If many open bins already, discourage proliferation.
        score += open_bins_count as f64 * 0.15;
    }

    // Slight preference for tighter (fuller) bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Nudge toward bins below mean residual when mean residual is high (fragmentation risk).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: penalize small unusable gaps heavily (non-linear).
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure on number of open bins: penalize spreading when many bins open.
    score += open_bins_count as f64 * 0.35;

    // Prefer bins whose residual is below mean (fill fuller bins first).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Lookahead: if next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover gap: penalize if gap is small.
        if (post_residual as f64) < dead_threshold * 2.0 {
            score += 5.0;
        }
    }

    // New-bin candidate: neutral baseline with mild penalty so it is chosen
    // only when all open bins have poor fits (large residuals wasted).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 0.2;
        // Discourage opening new bins when a decent fit exists elsewhere.
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect lookahead match: strong bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Slightly larger post_residual that still fits next item: mild bonus.
        else if post_residual > next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Penalize small dead space (unusable residuals) relative to typical item sizes.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin unless current residual is truly unusable.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if next item exactly matches a fresh bin after this placement, allow it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in stream, tighten packing to avoid stranded residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: leftover space that cannot fit the next (lookahead) item
    // is likely wasted unless it's very small.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Post-residual is unusable by the next item: mild penalty proportional to waste.
            score += 0.35 * post_residual as f64;
        } else {
            // Post-residual can host the next item: reward this chaining opportunity.
            let chain_tight = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * chain_tight;
        }
    } else {
        // Last item in stream: only tightness matters, penalize any leftover.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is penalized more when many
    // bins are already open (consolidation pressure), less when few are open.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 8.0 + 2.5 * open_pressure;
        // Early in the stream, new bins are cheaper to open (future flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
    }

    // Global state coupling: when mean residual across open bins is low (bins are
    // nearly full), prefer squeezing into existing bins; when mean residual is high,
    // be pickier and penalize loose fits.
    let mean_r = mean_residual.max(0.0);
    if mean_r > 0.0 {
        let relative_waste = post_residual as f64 / mean_r;
        score += 2.0 * (relative_waste - 1.0).abs().min(3.0);
        score -= 1.5 * (mean_r / bin_capacity as f64);
    }

    // Small exact-fit celebration: perfectly filling the bin is the best outcome.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Tiny residual fragments (< smallest plausible item) are dead weight.
    if post_residual > 0 && post_residual < 5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills mildly; late in the stream, penalize wasted space harder.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 20.0 * poly;

    // Reward near-perfect fits (low post residual) more strongly as stream advances
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Last-chance bonus: only bin that fits -> strong incentive to use it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits in the post residual, reward leaving that space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_fit = 1.0 - ((pr - nxt) / cap);
            score -= 12.0 * slack_fit * slack_fit;
        } else {
            // post residual too small for next item -> mild penalty for dead space
            score += 8.0 * (nxt - pr) / cap * (0.5 + progress);
        }
    }

    // Penalize bins far below mean residual (keeps residual distribution balanced)
    score += 3.0 * ((mean_residual - pr) / cap).abs();

    // Slight preference for filling existing bins over opening new ones as stream grows
    score += 5.0 * (bin_residual as f64 / cap) * (1.0 - progress);

    // New-bin candidate: discourage opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) + 5.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into
    // capacity-fraction bands. Small-but-nonzero residuals are the worst
    // because few future items (>= 1) can use them.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 200.0;
    } else {
        // Dead-space band penalty: residual in (0, 10] is nearly unusable.
        if post_residual <= 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 30 {
            score += 8.0;
        }

        // Modulo-10 harmonic class: residuals that are multiples of common
        // item-size granularities are more reusable.
        if post_residual % 10 == 0 {
            score -= 15.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        }

        // Fractional class: residual above half capacity is very flexible.
        if pr > cap * 0.5 {
            score -= 20.0;
        } else if pr > cap * 0.25 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // big reward; if it nearly fits, small penalty for blocking a better bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
            // reward if next item lands in a harmonic class matching residual
            if post_residual % 10 == 0 && next_item_size % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow here; slight penalty scaled by closeness
            score += (nx - pr).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity and few bins fit it.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: keep it high so it's chosen only when needed.
        score += 40.0;
        if item_size as f64 > cap * 0.5 && fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // If open bins are already crowded on average, a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild preference for fuller bins when many are open.
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits: filling most of the residual is good.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Reward exact or near-exact closure.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * 2.0;

    // New-bin candidate: make it attractive only when the current bin would
    // leave a dead gap AND the next item could use a fresh bin's residual.
    if bin_residual == bin_capacity {
        let dead_gap = post_residual > 0 && post_residual < 10;
        let next_fits_fresh = next_item_size as f64 <= bin_capacity as f64;
        if dead_gap && next_fits_fresh {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Lookahead: if the post residual exactly fits the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 10.0;
    }

    // Slight preference for bins below mean residual (balancing).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a super-linear penalty
    // on wasted space so that dead space is strongly discouraged.
    let waste = post_residual as f64;
    score = waste + 0.02 * waste * waste / 10.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly (or
    // nearly) matches the next item size — this creates a perfect follow-up fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            // Reward small gaps after which the next item still fits.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 40.0; // perfect two-item pairing
            }
        } else {
            // Next item cannot fit here afterwards; mild penalty unless this
            // bin is now nearly full anyway.
            if post_residual > 0 {
                score += 8.0;
            }
        }
        // Coupling with mean residual: if this bin's post_residual sits close to
        // the mean residual of open bins, it keeps the pool of usable bins healthy.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    } else {
        // Last item: just pack as tightly as possible.
        score += 0.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // current item leaves a large awkward remainder in every existing bin, or
    // when there are no open bins. Penalize the fresh-bin option by default, but
    // discount the penalty when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: post_residual == item_size here.
        let fresh_score = item_size as f64 + 0.02 * item_size as f64 * item_size as f64 / 10.0;
        score = fresh_score + 15.0; // default handicap vs. reusing bins
        // If the stream is early, allow more bins to be opened (flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, opening a new bin is
        // wasteful; penalize more.
        score += 0.02 * open_bins_count as f64 + 0.03 * mean_residual;
        // If next item is large and would fit nicely in a fresh bin alongside a
        // follow-up, slightly favor opening a new bin.
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) <= bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Small global pressure: with many open bins, favor consolidation into
    // existing bins rather than spreading items.
    score += 0.01 * open_bins_count as f64 * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    score -= (item_size as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Penalize creating dead space that can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 10.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere. An empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 - 10.0 * progress;
        // If item is large, a fresh bin is more attractive (leaves big symmetric space).
        if item_size as f64 > bin_capacity as f64 * 0.6 {
            score -= 12.0;
        }
    } else {
        // Reward using already-open bins, especially ones with low residual.
        score -= 5.0;
        // Prefer bins whose residual is below mean (tighter bins).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: prefer tight fits (small post_residual), with smooth quadratic coupling
    // to stream progress: late in the stream, dead space is penalized harder.
    let mut score = pr + 30.0 * (pr / cap).powi(2) * (0.5 + progress);

    // Smooth interaction: reward filling bins deeply as stream progresses.
    score -= 12.0 * (it / cap) * (0.4 + 0.6 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin needlessly). Smoothly scaled by scarcity.
    if fitting_bins_count <= 1 {
        score -= 25.0 + 10.0 * progress;
    } else {
        // Mild congestion penalty: many alternatives -> prefer best-fit elsewhere.
        score += 2.0 * ((fitting_bins_count as f64).ln() + 1.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it;
    // if post-residual is too small for the next item but nonzero, penalize (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if nxt <= pr {
            score -= 10.0 * (1.0 - gap / cap) * (0.5 + progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Contextual coupling with mean residual: if this bin's residual deviates
    // strongly below the mean, it is a "cramped" bin — prefer using it.
    let bin_res_f = bin_residual as f64;
    score += 4.0 * ((mean_residual - bin_res_f) / cap).tanh();

    // New-bin candidate handling: an empty bin has post_residual == cap - item.
    // Penalize opening a new bin unless the current bin would leave a large
    // unusable gap; smooth threshold via sigmoid on pr.
    if bin_residual == bin_capacity {
        let sigmoid = 1.0 / (1.0 + (-8.0 * (pr / cap - 0.35)).exp());
        score += 15.0 * sigmoid + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: integer division into capacity/8 buckets.
    // Smaller post_residual class = tighter fit = lower score.
    let class = post_residual / 13; // ~capacity/8 harmonic buckets
    score += class as f64 * 2.0;

    // Exact or near-exact fills are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residuals in the "unusable gap" zone are risky
    // since item sizes up to 100 may never fit them.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward strongly; if it wastes the residual, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let next_class = (post_residual - next_item_size) / 13;
            score += next_class as f64 * 1.5;
        } else {
            // next item cannot use this bin's leftover: slight penalty
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual <= 20 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin is neutral-to-slightly
    // attractive when open bins are crowded and the fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; competing bins with decent fits
        // (low post_residual) should beat this.
        score = 45.0;
        // Opening a new bin is more attractive early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is safer
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        // If many bins are open and mean residual is high, prefer reusing
        score += (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: post-placement residual (lower is better fit).
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Strict dead-space avoidance: gaps that nothing (min item = 1, but
    // practically small gaps) can use are heavily penalized.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual > 0 && post_residual < dead_threshold.max(4) {
        // Unusable sliver: penalize proportional to how much capacity is wasted.
        score += 45.0 + 0.5 * post_residual as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (sets up a perfect follow-up).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Next item cannot use the leftover: mild penalty, stronger for tiny gaps.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (0.5 + 0.5 * progress);
    if is_new_bin {
        score += 18.0 + 6.0 * pressure;
    } else {
        score -= 2.0 * pressure;
    }

    // Prefer bins whose residual deviates favorably from the mean: a bin with
    // residual close to item_size is a "destined" fit.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.10 * residual_gap;
    if mean_residual > 0.0 {
        score -= 0.05 * (bin_residual as f64 - mean_residual).abs().min(30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // chain two items perfectly
        } else if diff <= 10.0 {
            score -= 30.0 * (1.0 - diff / 10.0);
        } else {
            // penalize leaving space that next item can't use well
            score += diff * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Reward tight fits relative to capacity (low post residual fraction)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Penalize creating very small unusable slivers (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Contextual coupling with mean residual: prefer bins below mean residual
    // (concentrate filling into already-small bins, keep big-residual bins flexible)
    score += 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, keep bins open/flexible; late, fill aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    // Slight preference for many open bins early (avoid opening too many later is handled above)
    if open_bins_count > 10 && post_residual as f64 > mean_residual {
        score += 5.0;
    }

    // New-bin candidate: make it unattractive unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 40.0;
        // but if next item is large and this item is small, opening a fresh bin may chain well
        if next_item_size > 0 && post_residual == bin_capacity - item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: fill bins as tightly as possible.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio;

    // Penalize small dead space that likely cannot be reused (post_residual < 10 or < next item).
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 25.0 * dead * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: reward if next item fits exactly into the resulting residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Default penalty for opening a new bin.
        score += 55.0;
        // If the item would leave large unusable residue in every existing bin, opening is better.
        let poor_fit_everywhere = fitting_bins_count == 0
            || (fitting_bins_count <= 2 && post_residual > 0 && post_residual < 10);
        if poor_fit_everywhere {
            score -= 90.0;
        }
        // Late in stream, avoid opening new bins unless really necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // Many open bins with large mean residual: reuse is likely, penalize new bins.
        if mean_residual > item_size as f64 {
            score += 20.0;
        }
    } else {
        // Existing-bin bonus scaled by how much residual this bin has vs. mean.
        score -= 10.0 * (bin_residual as f64 - mean_residual).clamp(-20.0, 20.0) / 20.0;
        // Slight preference for bins that are already partially filled (waste avoidance).
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Global congestion: if many bins are open, consolidate.
    score += 1.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr_norm;

    // Non-linear polynomial coupling with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early: tolerate loose fits; late: penalize them more strongly
    let tightness_weight = 0.4 + 1.2 * p2 + 0.6 * p3;
    score += tightness_weight * (pr_norm * pr_norm) * 2.0;

    // Reward filling bins deeply, modulated by progress
    score -= (1.0 - (1.0 - fit_ratio) * (1.0 - fit_ratio)) * (0.5 + progress);

    // Dead-space penalty: post_residual too small for typical future items
    let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += dead * dead * (1.5 - progress);

    // Last-chance bonus: strongly favor using a scarce fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.5 * progress;
    } else if fitting_bins_count > 1 {
        score += 0.1 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 0.8 * (1.0 - slack) * (1.0 - slack) * (0.6 + 0.8 * progress);
        } else {
            score += 0.3 * ((nx - pr) / cap);
        }
    }

    // Prefer bins with residual below mean (consolidate large gaps)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.25 * dev * dev.abs();

    // New-bin candidate: penalize opening a new bin mildly, less so early
    if bin_residual == bin_capacity {
        score += 1.2 + 1.8 * progress - 0.5 * (open_bins_count as f64).ln().max(0.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal waste after placement.
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual (integer division thresholds) ----
    // Class 0: perfect/near-perfect fit (post_residual <= 5) -> strong reward.
    // Class 1: small dead space (<= 10) -> moderate reward.
    // Class 2: medium gap (<= 20) -> slight reward.
    // Class 3+: large gap -> penalty grows super-linearly.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else {
        score += 0.15 * (post_residual as f64 - 20.0);
    }

    // ---- Modulo-arithmetic harmonic classes ----
    // Residuals divisible by common item-size classes (10/20/25/50) are
    // more likely to be reusable by future items; reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 3.0; }
        // Odd, non-harmonic residuals are hard to fill later.
        if pr % 10 != 0 && pr % 5 != 0 { score += 3.0; }
    }

    // ---- Lookahead: does next item fit into the post residual? ----
    if next_item_size > 0 && next_item_size <= pr {
        // Next item chains nicely: strong reward proportional to how well
        // the next item fills the remaining gap.
        let fill_ratio = next_item_size as f64 / pr as f64;
        score -= 10.0 + 12.0 * fill_ratio;
    } else if next_item_size > 0 && next_item_size > pr && pr > 0 {
        // Post residual can't host the next item: penalize proportionally.
        score += 0.1 * (next_item_size as f64 - pr as f64);
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin fits; opening a new bin wastes bin_residual entirely.
        // Reward heavily unless the fit is terrible (huge dead space).
        if post_residual <= 30 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline. Only attractive when no good fit exists.
        // Add a mild penalty so tight fits in open bins win, but subtract a
        // bonus when the stream is early and bins are few (future flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 60.0 - 20.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // ---- Capacity fraction coupling ----
    // Items filling a bin to >= 80% capacity are excellent; reward via
    // the fill fraction of the current placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    if fill_frac >= 0.8 {
        score -= 15.0;
    } else if fill_frac >= 0.5 {
        score -= 5.0;
    }

    // ---- Mean residual coupling: avoid stranding bins with tiny residuals ----
    if (bin_residual as f64) < mean_residual * 0.35 && bin_residual >= item_size {
        // This bin is nearly full relative to fleet mean: using it consolidates.
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A residual gap that is too small to hold even the minimum plausible item
    // is "dead space": heavily penalize it so tight-but-usable fits win instead.
    let min_item = 1u32; // interface allows sizes down to 1; treat tiny gaps as dead
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 500.0; // effectively unusable bin
    }
    // General dead-space curve: residual below the typical small-item scale
    // is progressively worthless; superlinear penalty.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * (20.0 - pr) * 0.15; // up to +60 for near-zero gap
    }

    // --- Reward tight fits (low post_residual relative to item size) ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0; // prefer packing large items into tight spots

    // --- Last-chance pressure: if this is the only bin that fits, use it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0; // strongly prefer the sole fitting open bin over opening a new one
    }

    // --- New-bin candidate (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins would leave
        // large dead space or when open-bin count pressure is low.
        // Baseline: new bin post_residual = capacity - item_size (already in score).
        // Penalize slightly so a decent existing fit beats a new bin...
        score += 12.0;
        // ...but relieve the penalty when many bins are open (consolidation pressure)
        score -= (open_bins_count as f64).sqrt() * 2.0;
        // And when the current item would leave a very poor gap in any bin,
        // the +12 is outweighed by the dead-space penalties above.
    }

    // --- Open-bins pressure: discourage spreading across many bins ---
    score += open_bins_count as f64 * 0.8;

    // --- Lookahead coupling: if the next item fits the post-residual,
    // reward this placement (keeps bins chain-friendly). ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward when the next item fits *snugly* after this one
        let after = post_residual - next_item_size;
        if after < 10 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty proportional to waste
        score += (next_item_size as f64).min(pr) * 0.1;
    }

    // --- Mean-residual coupling: if this bin is far below mean residual
    // (already fragmented), slightly deprioritize it. ---
    let res = bin_residual as f64;
    if mean_residual > 0.0 && res < mean_residual - 15.0 {
        score += (mean_residual - res) * 0.2;
    }

    // --- Stream progression: late in the stream, be more conservative
    // about opening new bins (fewer chances to recover). ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64;

    // Perfect match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near match: next item fits into the post residual -> moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Dead-space penalty: post_residual too small for anything (min item 1).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Penalize creating unusable gap relative to mean residual of open bins.
    let gap_vs_mean = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * gap_vs_mean;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits poorly everywhere. Make new bin mildly attractive on tight fits.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral base but discourage unless existing fits are bad.
        score += 10.0;
        // If item is large relative to capacity, a fresh bin keeps flexibility.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 12.0;
        }
        // Early in stream, fresh bins are cheaper (more future items to pair).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If next item is huge and won't fit with this one anywhere, fresh bin helps.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 8.0;
        }
    }

    // Slight preference for bins with large residual when fit is loose.
    score -= 0.05 * bin_residual as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: residual <= 10 is dead-space-free.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Penalize awkward residuals that only large items could use,
    // weighted by how much of the stream remains.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item would fit into the post-residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward for exact chain fit.
        if post_residual - next_item_size <= 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        // Next item fits this bin only if we DON'T place current item here:
        // penalize blocking a good future fit unless current fit is tight.
        if post_residual > 20 {
            score += 15.0;
        }
    }

    // Mild penalty for scattering across many bins when mean residual is high.
    if open_bins_count > 3 {
        let avg = mean_residual;
        if (post_residual as f64) > avg {
            score += 3.0;
        } else {
            score -= 3.0;
        }
    }

    // New-bin candidate: opening a fresh bin is only attractive when the
    // item is large (would leave big dead space anywhere) or nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual > 30);
        if item_size >= 70 || poor_fit_elsewhere {
            score -= 20.0;
        } else {
            // Discourage premature bin opening.
            score += 30.0 + 0.3 * item_size as f64;
        }
    }

    // Early in the stream, slightly prefer consolidating into fewer bins.
    if progress < 0.2 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = post / cap;                       // 0..1 leftover fraction
    let tightness = 1.0 - fit_norm;                  // how well the item fills the bin

    // Core: prefer small post-residual, with smooth non-linear reward for very tight fits.
    let mut score = post;

    // Quadratic coupling: tight fits (small post_residual) get super-linear reward.
    score -= 24.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (residual / cap);

    // Cubic term: extra reward when the bin becomes almost exactly full.
    score -= 12.0 * tightness * tightness * tightness * cap * 0.1;

    // Stream progress: later in the stream, avoid leaving awkward mid-size gaps
    // (dead space grows more costly as remaining items dwindle).
    let gap_awkwardness = {
        let g = fit_norm;
        // smooth bump penalizing residuals around 20-50% of capacity
        let center = 0.35;
        let width = 0.25;
        (-(g - center) * (g - center) / (2.0 * width * width)).exp()
    };
    score += 10.0 * gap_awkwardness * (0.4 + 0.6 * progress);

    // Lookahead coupling: if next item fits the resulting gap, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            // smooth reward decaying with slack after the next item also fits
            score -= 8.0 * (1.0 - slack / cap) * (1.0 + progress);
        } else {
            // next item cannot use the gap: mild penalty, stronger if gap is large
            score += 4.0 * fit_norm * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count <= 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Mean-residual coupling: placing into a bin below average residual tends to
    // consolidate space; reward bins tighter than the mean, penalize looser ones.
    let mean_gap = (residual - mean_residual) / cap;
    score += 6.0 * mean_gap;

    // New-bin candidate: empty bin has residual == capacity. Penalize opening a
    // new bin unless the current fit is genuinely poor (large post_residual),
    // with the penalty relaxing as the stream progresses.
    if bin_residual == bin_capacity {
        let poor_fit = (post / cap).clamp(0.0, 1.0);
        score += (18.0 - 8.0 * progress) * (1.0 - poor_fit * poor_fit);
        score += 3.0 * (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Small tie-breaker noise-free smoothing via item size interaction.
    score += 0.01 * (item_size as f64) * fit_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer bins leaving least residual.
    let mut score = pr;

    // ---- Harmonic class logic on post_residual (modulo arithmetic) ----
    // Residuals are grouped into decade classes; class 0 (pr % 10 == 0) is a
    // "harmonic" residual that future items of round sizes can reuse well.
    let harmonic = (post_residual % 10) as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect closure: best possible outcome
    } else {
        // Non-harmonic small residuals are dead space: penalize the offset
        // from the nearest lower decade, weighted harder for tiny leftovers.
        score += harmonic * 0.6;
        if post_residual < 10 {
            score += 12.0; // sub-dead-zone: almost unusable sliver
        }
        // Quarter-capacity harmonic classes: residuals near C/4, C/2, 3C/4
        // are reusable by mid-sized items; reward proximity.
        let quarter = cap / 4.0;
        let dist_q = (pr - quarter * (pr / quarter).round()).abs();
        score -= (quarter - dist_q).max(0.0) * 0.05;
    }

    // ---- Integer-division threshold on next_item_size ----
    // If the lookahead item fits the post residual, this bin chains well.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0;
            // Extra chaining reward when the leftover splits into harmonic
            // decades usable by the next item (nx and pr share a class).
            if (post_residual as u32) % 10 == next_item_size % 10 {
                score -= 3.0;
            }
        } else if pr > 0.0 && pr < nx {
            // Residual too small for the known next item: future dead space.
            score += 5.0 + (nx - pr) * 0.2;
        }
    }

    // ---- Last-chance bin before opening a new one ----
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0; // strongly prefer using the only fitting open bin
    }

    // ---- New-bin candidate handling ----
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open a new bin
        } else {
            // A fresh bin competes with open bins; penalize so it only wins
            // when open-bin placements would leave very poor fits.
            score += 15.0;
            // Late in the stream, keep bins consolidated rather than spreading.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += progress * 10.0;
            // Many open bins with high mean residual: avoid fragmentation.
            if mean_residual > cap * 0.5 && open_bins_count > 2 {
                score += 8.0;
            }
        }
    }

    // Mild consolidation pressure: fewer open bins is better, all else equal.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..=10) are pure waste; penalize them harshly, scaled by depth of waste.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    } else if post_residual < 20 {
        // Moderately unusable zone: many item sizes cannot land here.
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: strongly prefer bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // dead-ends the bin before the next item arrives
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // favor consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual < bin_capacity {
        score -= pressure * 0.5;
    } else {
        // New-bin candidate: accept it only if no good fit exists,
        // i.e. penalize when open bins are plentiful and residuals healthy.
        score += pressure * 0.8;
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
    }

    // Slight preference for bins below mean residual (consolidation).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack / 10.0);
    }

    // Penalize if next item cannot fit into post residual (dead space risk)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Compare post_residual against mean residual across open bins:
    // leave residuals near the mean to keep flexibility
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    // Reward filling bins tightly relative to capacity
    score -= 0.3 * item_size as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in stream: prefer compacting into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate penalty: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 10.0 };
        score += 30.0 - pressure + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization core).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - tightness) * (1.0 - tightness);

    // Lookahead: penalize leaving residuals that neither fit nor match next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can land here; reward proportional to leftover utility.
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // Dead space for the known future item.
            score += 8.0 + 0.25 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Perfect closure bonus: exactly filling a bin is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Small unusable sliver: mild penalty, but less bad than opening a bin.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage hoarding capacity in large-residual bins.
    if open_bins_count > 3 {
        let pressure = (open_bins_count as f64).ln();
        score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Global state: if mean residual is high, prefer consolidating into fuller bins.
    if post_residual as f64 > mean_residual {
        score += 4.0;
    } else {
        score -= 4.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large item, poor fits everywhere) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_ratio = item_size as f64 / bin_capacity as f64;
        let poor_fit_everywhere = fitting_bins_count == 0
            || (fitting_bins_count <= 1 && tightness > 0.5);
        if poor_fit_everywhere {
            score -= 18.0 + 20.0 * item_ratio;
        } else {
            // Keep new bins expensive; urgency grows with open bin count.
            score += 30.0 + 3.0 * open_bins_count as f64 - 15.0 * progress;
        }
    }

    // Mild time-horizon coupling: late in stream, waste matters more per bin.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * horizon * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), with a non-linear
    // polynomial shaping that emphasizes very small residuals.
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, residual
    // waste becomes more costly (quadratic growth in progress).
    score += pr * (0.6 * progress + 1.4 * progress * progress);

    // Lookahead coupling: reward leaving a gap that can still host the
    // next item; penalize gaps that neither fit it nor are tiny.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if pr >= next_item_size as f64 {
            // next item fits: reward proportionally to usable slack
            score -= 6.0 * nx * (1.0 - norm_pr * norm_pr);
        } else {
            // dead space relative to lookahead: penalize non-linearly
            score += 8.0 * (next_item_size as f64 - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor
    // using it over opening a new bin (smooth reward, capped by fit quality).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let fit_quality = 1.0 - norm_pr * 0.5;
        score -= 12.0 * fit_quality * (1.0 + progress);
    }

    // Mean-residual coupling: when open bins are generally full (low mean
    // residual), filling an existing bin is extra valuable.
    let norm_mean = mean_residual / cap;
    score -= 3.0 * norm_item * (1.0 - norm_mean) * (1.0 - norm_mean);

    // New-bin candidate handling: an empty bin must lose unless the item
    // fits poorly everywhere (large post_residual on existing bins).
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * (1.0 - progress);
        // if the item is huge, a fresh bin is naturally attractive
        score -= 15.0 * norm_item;
    }

    // Slight preference to close out bins: fewer open bins is better.
    score += 0.15 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: exact or near-exact fits are excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post residual, this placement
    // preserves a usable bin. Reward proportionally to next item size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + (next_item_size as f64) * 0.15;
        } else {
            // Dead space relative to the lookahead item: penalize small unusable gaps.
            let gap = next_item_size - post_residual.min(next_item_size);
            if post_residual < next_item_size && post_residual > 0 {
                score += (gap as f64) * 0.4;
            }
        }
    }

    // Harmonic class logic: classify post_residual into remainder classes
    // modulo 10 (typical granularity of item sizes). Residuals whose remainder
    // is close to 0 are "aligned" and more likely reusable by future items.
    let r = post_residual % 10;
    if post_residual > 0 {
        let alignment = (r as f64).min((10 - r) as f64); // 0 = aligned, 5 = worst
        score += alignment * 2.0;
        // Dead-space zone: residual too small for the smallest plausible item.
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Integer-division threshold on post_residual: half-full or emptier bins
    // are flexible; nearly-full bins risk stranded space.
    let half = bin_capacity / 2;
    if post_residual < half {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Default penalty: prefer existing bins with decent fits.
        score += 40.0;
        // But open a new bin when existing fits are poor: many fitting bins
        // with large residuals means fragmentation; a fresh bin is cleaner.
        if post_residual == bin_capacity {
            if item_size as f64 >= 0.7 * bin_capacity as f64 {
                // Large item: fresh bin is fine.
                score -= 20.0;
            }
            if fitting_bins_count == 0 {
                score -= 100.0; // no alternative anyway
            }
            if mean_residual > 30.0 && open_bins_count > 2 {
                // Open bins are fragmented; a fresh bin keeps tight bins tight.
                score -= 25.0;
            }
        }
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing
    // bins tighter to avoid straggler bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 {
            score -= (progress - 0.8) * 40.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Mild penalty proportional to how far this bin's residual deviates from
    // the mean residual: keep the bin population homogeneous.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can only trap small future
    // items are heavily penalized. Gaps below the typical item floor (<=10)
    // are pure waste; gaps in (10, 20] are near-waste.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 15.0;
    } else if post_residual > 40 {
        // Large leftover space is flexible; mildly reward it.
        score -= 8.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer tighter packing
    // (lower post_residual already does that); add mild pressure to fill
    // existing bins rather than spreading.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Lookahead: if the next item fits exactly in the post_residual,
    // strongly favor this placement (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Mean-residual coupling: if this bin is below the mean residual, it is
    // relatively full; reward filling the emptiest-relative bins less than
    // filling near-full ones — i.e., penalize placing into very empty bins.
    if (bin_residual as f64) > mean_residual * 1.2 {
        score += 6.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin, more so
    // early in the stream when consolidation is cheap, and when other
    // fitting bins exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * (open_bins_count as f64);
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
        // But if the item is large (>= half capacity), a fresh bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 35.0;
        }
    }

    // Progression: late in the stream, be more aggressive about closing bins
    // tightly (favor low post_residual even more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when next item fits the post residual exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 25.0; // perfect pair
        }
    } else if next_item_size > 0 {
        // next item cannot follow into this bin: penalize dead space
        score += 8.0;
    }

    // Tight fits are good
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Compare residual to mean residual: prefer below-average residual bins (denser)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bin when a reasonable fit exists
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 10.0; // would waste lookahead chance too
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post residual, the bigger the bonus.
    score -= 12.0 / (post_residual as f64 + 1.0);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 6.0;
    }

    // Lookahead coupling (k=2): reward bins whose post residual can still
    // host the next item; penalize bins that would strand space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Time horizon: as the stream progresses, mildly prefer consolidating
    // into existing bins (closing out residual space).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * t;

    // Global state coupling: if this bin's residual deviates from the mean,
    // nudge selection toward bins with larger-than-average space when the
    // item is large, and toward smaller-than-average space when small.
    let deviation = mean_residual - post_residual as f64;
    score += deviation * (item_size as f64 / bin_capacity as f64) * 0.04;

    // New-bin candidate handling: an empty bin gets a penalty so it is only
    // chosen when open bins fit poorly. The penalty grows when many open
    // bins could still fit the item, and shrinks when the item leaves little
    // dead space in a fresh bin.
    if bin_residual == bin_capacity {
        let alternatives_pressure = if fitting_bins_count > 1 { fitting_bins_count as f64 * 0.8 } else { 0.0 };
        score += 5.0 + alternatives_pressure - post_residual as f64 * 0.03;
    }

    // If no bins are open yet, always open one.
    if open_bins_count == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tightest fit).
    let mut score = post;

    // Reward tight fits more strongly as stream progresses (consolidation pressure).
    let tightness = 1.0 - post / cap; // 1.0 = perfect fit
    score -= tightness * tightness * (30.0 + 70.0 * progress);

    // Penalize very small unusable residuals (dead space) with smooth cubic term.
    let dead = post / cap;
    score += 40.0 * dead * dead * dead * (1.0 - progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead coupling: reward residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            // Post residual too small for next item: mild penalty scaled by near-miss.
            let miss = (nxt - post) / cap;
            score += 20.0 * miss * miss;
        }
    }

    // Prefer bins with below-mean residual (concentrate emptiness in few bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev;

    // Mild penalty for spreading across many open bins early on.
    score += 2.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // New-bin candidate: keep it attractive only when it beats poor fits;
    // add a smooth cost so existing bins are usually preferred.
    if bin_residual == bin_capacity {
        score += 25.0 + 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers divisible by common
    // item-size classes (10/20/25/50) are more reusable downstream.
    let class_bonus = if post_residual == 0 {
        40.0
    } else if post_residual % 50 == 0 {
        25.0
    } else if post_residual % 25 == 0 {
        15.0
    } else if post_residual % 20 == 0 {
        12.0
    } else if post_residual % 10 == 0 {
        8.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Penalize dead space in the awkward 1..10 band (unusable for items >= 10,
    // but items can be as small as 1 here, so scale by how "dead" it is).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Reward pairing: if next_item_size fits exactly into post_residual,
    // this bin creates a perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Harmonic class match between leftover and next item.
        if post_residual % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize spreading residual mass when many bins are open with slack.
    if bin_residual < bin_capacity {
        score += (mean_residual - post_residual as f64).max(0.0) * 0.15;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity and no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base cost of a new bin, discounted when the item is huge or nothing fits.
        score += 55.0 - 30.0 * pressure - 45.0 * scarcity;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If the next item is large and current item small, a fresh bin
        // preserves a full bin for the big one.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 25.0;
        }
    }

    // Mild preference for tighter existing bins (smaller residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0; // nearly dead space
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits: post_residual close to 0 relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 35.0 * tightness * tightness;

    // Penalize bins whose residual is far above what the item consumes
    // (leaving a large awkward gap), scaled by how full the bin already is.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    if post_residual > 40 {
        score += 12.0 * (1.0 - fill_ratio);
    }

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement (chains well); otherwise slight penalty.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin (unless fit is awful).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        if post_residual < 10 {
            score += 30.0; // still avoid dead space even under pressure
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing fits are poor
        // (large post residual) or few bins are open early in the stream.
        score -= 15.0 * (1.0 - progress) * (1.0 - open_pressure * 0.12).max(0.0);
        score += 20.0 * open_pressure * 0.1;
    } else {
        score -= 4.0 * open_pressure * 0.5;
    }

    // Mean-residual alignment: prefer bins whose residual is below the mean
    // (i.e., the fullest bins), pushing consolidation.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on post_residual to prefer tight fits.
    score += 0.5 * post_residual as f64;

    // 2-step lookahead: reward if the leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Bonus proportional to how snugly the next item fits the leftover.
            let snug = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 10.0 * (1.0 - snug);
        } else {
            // Dead space: leftover too small for the next item.
            score += 12.0;
            // Especially bad if leftover is tiny (unusable).
            if post_residual < 10 {
                score += 15.0;
            }
        }
        // If next item exactly fills this bin's leftover, huge reward.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: simply prefer the tightest fit.
        score += 0.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it expensive unless few bins fit or item is large.
    if bin_residual == bin_capacity {
        let base_new = 30.0;
        let relief = if fitting_bins_count <= 1 { 25.0 } else { 0.0 };
        let big_item = if item_size > 60 { 10.0 } else { 0.0 };
        score += base_new - relief - big_item;
        // Early in the stream, opening bins is cheaper (builds options).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference to fill already-open bins as stream progresses.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 2.5; // sweet spot for small items
    } else if post_residual > 60 {
        score += 3.0; // large leftovers indicate poor fit
    }

    // Lookahead: if the next item fits exactly-ish into post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_tight = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 10.0 * next_tight;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // residual too small for anything useful; mild penalty
        score += 2.0;
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.05 * (item_size as f64);
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in the
    // stream and when many bins are already open; relax it when mean residual is low
    // (existing bins are nearly full anyway).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 14.0 + 6.0 * (1.0 - progress) + 0.4 * crowding;
        // But if the item is huge relative to typical residual, opening a fresh bin
        // is safer.
        if item_size as f64 > mean_residual {
            score -= 9.0;
        }
    }

    // Mild global pressure: when many bins are open relative to stream length,
    // discourage wasteful placements (keep score near post_residual otherwise).
    let waste_pressure = mean_residual / bin_capacity as f64;
    score += 4.0 * (1.0 - waste_pressure) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap; // fraction of bin used after placement
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    let mut score = post;

    // Smooth non-linear coupling: reward high fill with a saturating polynomial.
    let fill2 = fill * fill;
    let fill3 = fill2 * fill;
    score -= 40.0 * fill3 + 25.0 * fill2;

    // Progress coupling: late in the stream, tighter packing matters more.
    let prog_term = progress * progress * (1.0 - progress);
    score -= 30.0 * prog_term * fill2;

    // Lookahead: penalize leaving residual that cannot fit the next item,
    // but reward leaving exactly the space the next item needs.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (nxt - post) / cap; // dead space for next item
        } else {
            let gap = (post - nxt) / cap;
            score -= 8.0 * (1.0 - gap * gap); // next item fits snugly
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless the current item
    // leaves very little residual (big item needing a fresh bin).
    if is_new_bin {
        let tightness = (post / cap).powi(2);
        score += 20.0 * (1.0 - tightness) + 0.5 * open_bins_count as f64;
    }

    // Mild penalty for spreading residual far above the mean (fragmentation).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and near-perfect fits are gold.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always take it
    } else if post_residual <= 5 {
        score -= 200.0; // near-perfect: dead space is negligible
    } else {
        // Dead-space penalty grows super-linearly for unusable slivers.
        let frac = post_residual as f64 / cap;
        if frac < 0.10 {
            score += (0.10 - frac) * 900.0; // unusable sliver for typical items (>= ~10)
        }
    }

    // Harmonic class thresholds on post_residual (integer division bands).
    let band = post_residual / 10; // 0..10 band index
    score += match band {
        0 => -150.0,
        1 => -60.0,
        2 => -20.0,
        3 => 0.0,
        4 => 10.0,
        _ => 25.0,
    } as f64;

    // Modulo coupling: post_residual mod 10 — small residues often unusable.
    let m = post_residual % 10;
    if post_residual > 0 && m < 3 && post_residual < 12 {
        score += 60.0; // awkward tiny remainder
    }

    // Lookahead: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 45.0; // keeps chain going
            // Bonus if post_residual is a tight wrapper for next item.
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 35.0;
            }
        } else {
            score += 30.0; // this placement likely strands the bin
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists (item large relative to all residuals) or stream end.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = (mean_residual < item_size as f64) && (item_size as f64 / cap > 0.6);
        let mut s = 40.0; // default: prefer existing bins
        if tight {
            s -= 90.0; // nothing fits well; fresh bin is fine
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            s += 50.0; // fresh bin keeps flexibility — slight penalty vs using it later
        }
        if progress > 0.9 && open_bins_count > 12 {
            s -= 20.0; // late stream: consolidation pressure
        }
        score += s;
    }

    // Mild preference for fuller bins among comparable options.
    score -= (bin_residual as f64 / cap) * 8.0;

    // Spread-aware: if many bins fit, discourage wasting a tight bin on loose fit.
    if fitting_bins_count > 3 && post_residual > 20 {
        score += (fitting_bins_count as f64 - 3.0) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are pure waste — penalize hard.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // very hard to fill
        } else if post_residual < 35 {
            score += 8.0;  // moderately awkward gap
        } else {
            // Larger residuals remain usable; reward keeping flexible space.
            score -= (post_residual as f64 - 35.0) * 0.05;
        }
    } else {
        // Perfect fill: strongly reward closing a bin exactly.
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - gap / 100.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize alternatives via relative advantage).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading items
    // into yet another bin unless the fit is excellent; when few bins are open,
    // be more permissive.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "tight" bin — favor packing it down to keep others flexible.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.15;
    } else {
        score += (-dev) * 0.05;
    }

    // New-bin candidate: empty bin gets a mild default score; only choose it
    // when open bins would create bad dead space. Penalize it progressively
    // as the stream progresses to consolidate packing.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * progress;
        // But if no open bin fits well, new bin must remain viable:
        // handled by the fact that poor fits above get large penalties.
        score -= 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            // Perfect chain: next item exactly fills this bin afterwards.
            score -= 45.0;
        } else if diff > 0 {
            // Leftover space after the next item: penalize proportional dead space,
            // more so if that gap is too small for any future item (size >= 1... keep gap either ~0 or large).
            let d = diff as f64;
            score += d * 0.35;
            if diff < 10 {
                score += 6.0; // awkward unusable sliver
            }
        } else {
            // Next item will NOT fit this bin after placement: strong penalty,
            // scaled by how badly it misses.
            let d = (-diff) as f64;
            score += 8.0 + d * 0.5;
        }
        // Double lookahead: if post_residual minus next_item leaves a tight remnant, small reward.
        let after_next = post_residual as i64 - next_item_size as i64;
        if after_next > 0 && after_next <= 5 {
            score -= 4.0;
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 10.0;
    }

    // --- Tightness relative to fleet state ---
    // Favor bins whose residual after placement sits below the mean residual (compact packing).
    score -= (mean_residual - pr) * 0.2;

    // --- Last-chance rescue ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper late in the stream.
        score += 15.0 + 25.0 * (1.0 - progress);
        // If decent alternatives exist, make the new bin clearly unattractive.
        if fitting_bins_count > 0 {
            score += 10.0;
            // Extra penalty when the item fits some bin with below-average leftover waste.
            if pr >= mean_residual {
                score += 12.0;
            }
        }
        // Very late in the stream, avoid spawning bins for small leftovers.
        if progress > 0.85 && item_size < 30 {
            score += 15.0;
        }
    }

    // Discourage creating mid-range dead zones (hard to fill later).
    if post_residual >= 11 && post_residual <= 19 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual is already favored by the base term.
    // Add a quadratic bonus for near-perfect fits (post_residual close to 0).
    let pr = post_residual as f64;
    score -= 30.0 * (1.0 - pr / bin_capacity as f64).powi(2);

    // Penalize dead space that is too small for any plausible future item
    // (items are 1..100; residual < 10 is essentially unusable dead space).
    if post_residual < 10 {
        score -= 25.0; // perfect fill is great, keep it favored
    } else if post_residual <= 20 {
        score += 8.0; // awkward sliver: risky dead space
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly penalize leaving a bin that blocks lookahead
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Global pressure: when many bins are open relative to stream progress,
    // discourage opening new bins (handled implicitly by the new-bin candidate scoring),
    // and encourage consolidating into existing bins.
    let density = open_bins_count as f64 / (1.0 + t * 50.0);
    if bin_residual < bin_capacity {
        score -= 5.0 * density.min(10.0);
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (i.e., bins that are already mostly full get prioritized).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Make it attractive only when the item is huge relative to typical residuals
    // or no good fit exists; otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Late in the stream with large items, a fresh bin is more acceptable.
        score -= 30.0 * t;
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // Mild time-horizon scaling: early on, be greedy about tight fits; later,
    // be more conservative about fragmenting bins.
    score *= 1.0 + 0.1 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    // Early on, prefer moderate residuals; later, strongly punish large residuals.
    let shape = 1.0 + 2.0 * progress;
    score += 0.5 * shape * prn * prn * cap;

    // Reward tight fits with a cubic term (low post_residual gets extra discount).
    score -= 30.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - prn) * (1.0 - prn);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 {
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += 0.8 * waste * (0.5 + progress);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many bins relative to mean residual.
    score += 0.02 * (open_bins_count as f64) * ((mean_residual - pr).abs());

    // New-bin candidate: only attractive when item is large relative to residual
    // alternatives; give it a mild default penalty.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.02;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit: big reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 15.0 * (fill_ratio - 0.8);
    }

    // Pressure from number of open bins: discourage scattering when many bins open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
        // If next item could combine with current in a fresh bin, slightly favor new bin.
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score -= 5.0;
        }
    }

    // Lookahead: if next item exactly fits the post residual, reward this placement.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap == 0 {
            // Perfect match: next item exactly consumes the leftover.
            score -= 40.0;
        } else if next_item_size as u32 <= post_residual {
            // Next item fits too: mild reward scaled by how well it nests.
            score -= 18.0 * (1.0 - gap as f64 / (bin_capacity as f64));
        } else {
            // Next item won't fit in this leftover: penalize dead space.
            score += 10.0 + 0.25 * (gap as f64);
        }
    }

    // Relative-to-mean residual alignment: prefer bins whose post_residual
    // sits near the mean residual (keeps bin population homogeneous).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it attractive only when no open bin
    // offers a good fit (large item_size relative to mean_residual).
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) > mean_residual * 1.35 || fitting_bins_count == 0;
        if poor_fit {
            score -= 8.0;
        } else {
            // Discourage wasting a fresh bin when existing bins fit decently.
            score += 20.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins rather than spreading across many.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that becomes unusable for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            // Dead space that cannot host the lookahead item.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            1.0
        } else {
            (item_size as f64 / bin_capacity as f64).powi(3) / fitting_bins_count as f64
        };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 45.0 * pressure - 10.0 * progress;
    }

    // Mild preference for bins already below mean residual (consolidate slack).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer denser bin pools slightly early on, sparser later.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 0.02 * open_bins_count as f64 - t * 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let size_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.35 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tolerate larger residuals slightly; later, penalize dead space harder
    let progress_coupling = 1.0 + 0.6 * progress * progress + 0.4 * progress * pr_norm;
    score *= progress_coupling;

    // Reward exact-ish fits: quadratic bonus decaying smoothly
    score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * size_norm;

    // Lookahead: reward if next item fits the post-residual, smooth kernel
    if next_item_size > 0 && pr >= next_item_size {
        let fit_quality = next_norm / (pr_norm + 1e-6);
        score -= 4.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 2.0 * next_norm * (1.0 - pr_norm / (next_norm + 1e-6)).max(0.0);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when this bin is far above mean residual (keep balance), smooth cubic
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev * dev.abs().max(0.0) * cap * 0.01;

    // New-bin candidate: make it attractive only when residuals are hopeless
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let pressure = mean_residual / cap;
        score = 40.0 + 10.0 * open_f * 0.1 + 25.0 * pressure * pressure - 15.0 * progress;
        if fitting_bins_count <= 1 {
            score += 30.0; // don't open when it's the only fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: tiny dead space (0..=5) -> excellent, strong reward
    // Class 1: small (6..=15) -> good
    // Class 2: medium (16..=30) -> neutral-ish
    // Class 3: large (31..=60) -> wasteful
    // Class 4: huge (61..=99) -> very wasteful (could have gone elsewhere)
    let class = match post_residual {
        0..=5 => 0u8,
        6..=15 => 1,
        16..=30 => 2,
        31..=60 => 3,
        _ => 4,
    };

    match class {
        0 => score -= 40.0,
        1 => score -= 20.0,
        2 => score += 5.0,
        3 => score += 25.0,
        _ => score += 45.0,
    }

    // Perfect fill bonus: exact fit is ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic residue: bins whose residual is a multiple of common item
    // granularity (gcd-friendly to 10) remain splittable; odd leftovers hurt
    if post_residual % 10 != 0 {
        score += 8.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this bin
    // (chaining two items here saves capacity elsewhere)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Extra reward if next item exactly consumes the remainder
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // Next item won't fit: penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin
    // would leave a bad fit / dead space
    if bin_residual == bin_capacity {
        // Base cost of a new bin
        score += 70.0;
        // If the item would leave a large awkward remainder anyway, opening
        // a new bin is more acceptable (reduce penalty)
        let waste = bin_capacity - item_size;
        if waste > 30 {
            score -= 35.0;
        }
        // Early in the stream, new bins are cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // Many open bins already: discourage yet another
        score += open_bins_count as f64 * 2.0;
    }

    // Prefer bins tighter than the mean residual (better local fit)
    score += (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (items are 1..=100, but small leftovers < 15 are nearly unusable) get
    // an amplified penalty.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (15.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 120.0;
    } else {
        // Larger leftovers are fine; mildly favor bigger usable gaps.
        score -= 8.0;
    }

    // Reward tight fits relative to bin capacity (waste ratio penalty).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Open-bin pressure: discourage spreading across many bins; with few
    // fitting bins, this bin is a last chance -> strong reward.
    if fitting_bins_count <= 1 {
        score -= 50.0;
    } else {
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    // Prefer bins whose residual deviates above the mean (consolidate fullness).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: penalize proportional dead space.
            score += 15.0;
        }
    }

    // Early in the stream, be more willing to open new bins (keep options open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    // New-bin candidate (empty bin): make it attractive only when this bin
    // would leave a very poor fit; otherwise keep existing bins preferred.
    if bin_residual == bin_capacity {
        if post_residual < 15 {
            score -= 100.0; // opening fresh beats creating dead space
        } else {
            score += 25.0; // default: prefer placing into an existing bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residual that exactly matches next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        if post == nxt {
            // Perfect chain: next item exactly fills this bin afterwards.
            score -= 120.0;
        } else if post >= nxt {
            // Next item still fits after this placement: mild bonus scaled by tightness.
            let slack = post - nxt;
            score -= 40.0 - (slack as f64).min(40.0) * 0.5;
        } else {
            // Next item would NOT fit here: penalize creating near-dead space.
            let dead = nxt - post;
            score += dead * 1.5;
            if post < 10.0 {
                score -= 25.0; // tiny residual is fine, effectively closed bin
            }
        }
    } else {
        // Last item: just close bins as tightly as possible.
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins already tighter than average
    // (filling tight bins preserves loose bins for future large items).
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item fits badly everywhere or bin count is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity as f64 - item_size as f64 - next_item_size as f64).max(0.0);
        // Penalize opening a new bin; relax slightly as stream progresses or when
        // the next item chains well into the fresh bin.
        let mut new_bin_penalty = 70.0 + waste * 0.8 - progress * 20.0;
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            new_bin_penalty -= 25.0; // chain two items into a fresh bin
        }
        score += new_bin_penalty.max(0.0);
    }

    // Small nudge toward using fewer open bins (consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize creating dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item can use the post residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            // Next item would have fit before this placement but not after: penalize.
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: empty bin gets a baseline penalty so it's only chosen
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.05 * open_bins_count as f64;
        // Late in the stream, avoid opening new bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Prefer using bins with residuals close to the item (minimize fragmentation).
    let slack = (bin_residual - item_size) as f64;
    score += 0.1 * slack * slack / bin_capacity as f64;

    // Mild reward for consolidating into bins below-average residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += poly * 12.0;

    // Tight fits rewarded; dead space penalized non-linearly
    score -= (item_size as f64 / cap) * 6.0;
    score += (norm_post * norm_post * norm_post) * 8.0;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 4.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 2.0 * ((nxt - post) / cap);
        }
    }

    // Pressure from open bins vs mean residual
    score += (open_bins_count as f64) * 0.05;
    score -= (mean_residual - post) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod 10 classes) ---
    let pr = post_residual;
    let class = (pr % 10) as f64;
    // Residuals that are "harmonically useful" (multiples of 5/10) are rewarded.
    if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        // awkward residues are penalized proportionally to how awkward
        score += class * 0.4;
    }

    // Dead-space threshold: residuals too small for the smallest item (1..=100 range)
    if pr > 0 && pr < 10 {
        score += 25.0; // nearly unusable sliver
    }

    // --- Coupling with the lookahead item (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: strong reward, scaled by tightness
            let tight = (pr - next_item_size) as f64;
            score -= 12.0 + tight * 0.5;
            // harmonic bonus if the pair leaves a clean residue
            if (pr - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else if next_item_size <= bin_capacity {
            // next item won't fit here; penalize mildly if this bin becomes a trap
            score += 4.0;
        }
    }

    // --- Integer-division thresholds on residual fraction of capacity ---
    let frac = pr as f64 / bin_capacity as f64;
    if frac >= 0.5 {
        score -= 4.0; // roomy bin, keep it attractive
    } else if frac <= 0.1 && pr > 0 {
        score += 3.0; // nearly full bin: fine to fill but not prioritize over perfect fits
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 {
        // avoid opening a new bin when this is the only option
        score -= 15.0;
    } else {
        score += 2.0;
    }

    // --- New empty bin candidate: only prefer it when no open bin gives a decent fit ---
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_score = bin_capacity as f64 - 20.0;
        // if the current item leaves a harmonic residual in a fresh bin, cheapen it
        if (bin_capacity - item_size) % 10 == 0 {
            new_bin_score -= 8.0;
        }
        // if lookahead is huge and would waste space in any partially-filled bin,
        // opening a fresh bin becomes more attractive
        if next_item_size > 0 && next_item_size > mean_residual {
            new_bin_score -= 10.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 10.0 + open_bins_count as f64 * 0.3;
        score = score.min(new_bin_score);
        // empty bin should never beat a genuinely good existing fit:
        score = score.max(1.0);
    }

    // --- Slight preference for tighter fits overall ---
    score += (bin_residual - item_size) as f64 * 0.05;
    score += mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 12.0; // tiny leftovers are almost wasted capacity
    } else if post >= 10.0 && post < 20.0 {
        score += (20.0 - post) * 4.0; // moderate dead space, milder penalty
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - post / cap;
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // by penalizing the empty-bin candidate implicitly via residual baseline.
    let pressure = open_bins_count as f64 * 0.8;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with number of open bins.
        score += 30.0 + pressure;
        // Allow a new bin if next item cannot fit the resulting residual well.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score -= 20.0; // next item won't fit here anyway -> new bin is fine
        }
    } else {
        // Slight preference for reusing existing bins under pressure.
        score -= pressure * 0.5;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 8.0; // residual becomes dead for the next item
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 15.0;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is a
    // good filler candidate; if far above, deprioritize.
    let dev = mean_residual - post;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mut score = post;

    // Perfect closure: item exactly fills the bin.
    if post_residual == 0 {
        score -= cap * 2.0;
    }

    // Aggressive 2-step lookahead matching.
    if next > 0.0 && next <= cap {
        if post == next {
            // Perfect two-item chain: current item + next item fill bin exactly.
            score -= cap * 1.5;
        } else if next < post {
            // Next item still fits: reward bins where the follow-up fit is snug.
            let gap = post - next;
            score -= 15.0 * (1.0 - gap / post);
        } else {
            // Next item cannot use this bin's leftover; residual risks becoming dead space.
            if post > 0.0 && post < 10.0 {
                score += (10.0 - post) * 3.0;
            }
        }
        // Coupling with mean residual: prefer bins whose outcome stays near fleet average.
        score += 0.3 * (post - mean_residual).abs();
    }

    // General tiny-leftover (dead space) penalty.
    if post > 0.0 && post < 5.0 {
        score += 20.0;
    }

    // Last chance: if this is the only open bin that fits, strongly prefer using it
    // over opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap;
    }

    // New-bin candidate: slight penalty so reuse wins unless the existing fit is bad.
    if bin_residual == bin_capacity {
        score += 5.0;
        // Late in the stream, consolidating matters more; early on, opening is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is small but non-zero less,
    // penalize large leftover dead space more.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize near-perfect waste less if it exactly fills the bin.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; grows with number of open bins.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If the item would leave a very tight fit elsewhere, opening a new bin
        // becomes more attractive (score already low for bad fits).
        if fit_ratio < 0.35 {
            score += 10.0;
        }
        // Late in the stream, prefer closing out bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Global residual pressure: when mean residual across bins is low,
    // conserve space by preferring bins that waste less.
    score += 0.1 * mean_residual;

    // Mild time-horizon coupling: early in stream, be more tolerant of imperfect fits
    // to keep bins flexible; later, be greedy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * (1.0 - progress) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;

    let mut score = pr;

    // Non-linear polynomial coupling: quadratic dead-space penalty that grows
    // smoothly with stream progress (later in the stream, dead space costs more).
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + t);
    score += 4.0 * norm_pr.powi(3) * (1.0 - t);

    // Tight-fit reward: polynomial bump when post_residual is small relative to item.
    score -= 6.0 * (1.0 - norm_pr).powi(3);

    // Prefer bins tighter than the current mean residual (smooth linear term).
    score += 3.0 * (br - mean_residual) / cap;

    // Lookahead coupling: reward when the next item still fits in the post residual
    // (smooth sigmoid of the gap, no hard piecewise switch).
    let gap = pr - next_item_size as f64;
    let sigmoid = 1.0 / (1.0 + (-gap / 8.0).exp());
    score -= 7.0 * sigmoid * (1.0 - norm_pr);

    // Last-chance bonus: stronger when fewer bins can fit the item (smooth in 1/k).
    score -= 10.0 / (fitting_bins_count.max(1) as f64);

    // Mild congestion penalty: spreading across many open bins is fine, but
    // discourage over-fragmentation late in the stream.
    score += 0.3 * (open_bins_count as f64) * t * norm_pr;

    // New-bin candidate detection via smooth polynomial: (residual/capacity)^8
    // is ~1 only for a brand-new empty bin, ~0 otherwise.
    let newness = (br / cap).powi(8);
    score += 8.0 * newness * (1.0 + 2.0 * (1.0 - t));
    // Opening a new bin is more tolerable for large items (they'd leave big
    // post_residual anywhere), so ease the penalty smoothly with item size.
    score -= 6.0 * newness * (it / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity.
    let class = post_residual % (bin_capacity / 4).max(1); // classes of 25
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward tight fits: post_residual in low harmonic classes is good.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect dead space
    } else if class == 0 {
        score -= 12.0; // post residual is a clean quarter multiple: reusable slot
    } else if post_residual < quarter {
        score -= 5.0;
    } else if post_residual < half {
        score += 3.0;
    } else {
        score += 8.0; // large residual after a small item = wasteful placement
    }

    // Lookahead: penalize if next item cannot use the post residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 10.0; // next item forced elsewhere
        } else {
            // Reward if post residual forms a good harmonic slot for next item
            let slot = post_residual - next_item_size;
            if slot <= 10 {
                score -= 15.0;
            } else if slot % quarter == 0 {
                score -= 8.0;
            }
            // Integer-division threshold: how many future items of next size fit
            let fits = post_residual / next_item_size.max(1);
            if fits >= 2 {
                score -= 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no tight fit exists among open bins.
    if bin_residual == bin_capacity {
        if item_size >= half {
            score -= 5.0; // large items start fresh bins comfortably
        } else {
            score += 15.0; // avoid scattering small items into fresh bins
        }
        if open_bins_count > 0 && next_item_size > 0 && next_item_size > item_size {
            score -= 8.0; // big next item benefits from a fresh bin
        }
    }

    // Mild pressure to consolidate: fewer open bins is better late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 2.0 * progress);

    // Prefer bins whose residual is far from the mean (specialized slots).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item (<= 12) are wasted capacity. Penalize hard.
    if post_residual < 12 && post_residual > 0 {
        score += 40.0 + (12 - post_residual) as f64 * 3.0;
    }

    // "Almost perfect" fits are gold: reward tight packing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 4 {
        score -= 25.0;
    } else if post_residual <= 8 {
        score -= 10.0;
    }

    // Bonus if the leftover gap can still host the lookahead item:
    // keeps the bin useful for the next arrival.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many
    // are already open (discourages bin sprawl).
    score += (open_bins_count as f64) * 0.35;

    // Mild mean-residual coupling: bins with residual far below the mean
    // are closer to saturation; placing there is slightly favored.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate: an empty bin leaves a large post_residual; make it
    // less attractive than decent existing fits, but viable when the item
    // is huge (poor fit everywhere) or the item nearly fills the bin.
    if bin_residual == bin_capacity {
        score += 55.0 - (item_size as f64) * 0.55;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        // Exact or near-exact match for the upcoming item is highly desirable
        let match_gap = (post_residual as u32 - next_item_size) as f64;
        score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
        // Perfect chain (item + next item fills bin completely)
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportional to wasted lookahead
        let waste = (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
        score += 12.0 * (waste / 100.0);
    }

    // Relative to mean residual: prefer bins tighter than average
    let resid_f = post_residual as f64;
    score += 0.5 * (resid_f - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless lookahead really needs it
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0;
        }
    }

    // Dead-space penalty: tiny unusable residuals are wasted capacity
    if resid_f > 0.0 && resid_f < 10.0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward tight fits (small post_residual) non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = 1.0 - (pr / cap); // 1.0 = perfect fill
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the minimum item (1) are fine,
    // but residuals in the awkward small-but-nonzero band waste capacity.
    if pr > 0.0 && pr < 10.0 {
        score += 6.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 15.0; // perfect chained fit
            } else {
                score -= 6.0 * (1.0 - slack / cap);
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overflow gap.
            score += 3.0 * ((nxt - pr) / cap).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Many candidates: prefer tighter fits more aggressively.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin identified by bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly, but rewarded when the item is large
        // (large items pair better with fresh space) or when existing bins fit poorly.
        score += 8.0;
        let fill = item_size as f64 / cap;
        score -= 10.0 * fill * fill; // large items favor fresh bins
        // If existing alternatives are scarce, tilt toward opening.
        if fitting_bins_count <= 1 {
            score -= 14.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than spreading.
    if open_bins_count > 0 {
        let density = mean_residual / cap;
        score += 4.0 * density * (open_bins_count as f64).ln();
    }

    // Dynamic time horizon: late in the stream, prefer closing bins tightly
    // (avoid leaving many near-empty bins at the end).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fit_ratio;

    // Small penalty for extreme fragmentation: item barely fits with lots left over.
    let usage = item_size as f64 / cap;
    if usage < 0.2 && pr > cap * 0.7 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;                       // 0..1 normalized post residual
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post residual (tight fit), with non-linear emphasis
    let mut score = post;

    // Smooth polynomial coupling with stream progress:
    // early on, waste is cheap; later, dead space is increasingly penalized.
    let tightness = (norm_post * norm_post) * (1.0 + 3.0 * progress);
    score += 40.0 * tightness;

    // Cubic dead-space term: residuals that are too small to ever be useful
    // (below typical small item size) are quadratic-to-cubic bad, worse late.
    let useless = if post < 10.0 { 0.0 } else { ((10.0 - post) / 10.0).powi(2) };
    let _ = useless; // (kept smooth alternative below)

    // Smooth "unusable gap" measure: gap decays smoothly as post approaches 0
    let gap = (1.0 - (-post / 20.0).exp()) * (1.0 - norm_post);
    score += 15.0 * gap * (0.5 + progress);

    // New-bin candidate handling: penalize opening a new bin when the item
    // fits elsewhere, unless the fit in existing bins would be terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 60.0 + 40.0 * progress;
        // If this bin would be nearly full immediately (huge item), soften:
        score -= 50.0 * norm_item * norm_item;
    } else {
        // Reward using existing bins, more when few bins can fit the item.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
        // Reward reducing mean residual spread: placing into a small-residual
        // bin keeps big residual bins available for big future items.
        score -= 6.0 * (1.0 - (bin_residual as f64 / cap)) * (1.0 + progress);
    }

    // Lookahead coupling: if next item would fit snugly in the post residual,
    // reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 12.0 * snug * snug;
        } else {
            // next item won't fit here; mild penalty proportional to excess
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // Mean-residual alignment: prefer bins near the mean to keep residuals uniform
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1
    let quarters = post_residual / 25; // integer division: 0..4 classes
    let eighths = post_residual % 8;   // fine harmonic class

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Penalize dead space in awkward harmonic bands (unusable slivers)
        if post_residual < 10 {
            score += 150.0; // dead space below min item size
        }
        // Modulo-based reward: residuals that are multiples of 25 pair well with future items
        if post_residual % 25 == 0 {
            score -= 40.0;
        }
        if post_residual % 10 == 0 {
            score -= 15.0;
        }
        // Penalize residuals in "awkward" bands (just above small item sizes)
        let awkward = matches!(post_residual, 11..=14 | 21..=24 | 31..=34 | 41..=44 | 51..=54 | 61..=64 | 71..=74 | 81..=84);
        if awkward {
            score += 25.0;
        }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // perfect chain
        } else if next_item_size < post_residual {
            let nr = next_item_size as f64;
            let fill_ratio = nr / pr;
            score -= 60.0 * fill_ratio; // reward bins that can also host next item
            // harmonic match: next_item divides post_residual
            if post_residual % next_item_size == 0 {
                score -= 50.0;
            }
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 10 {
                score -= 80.0; // chain leaves near-zero waste
            }
        } else {
            score += 20.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening new bin is fine early or when existing fits are poor
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 0.55 * cap;
        score = base + 30.0 * (1.0 - progress);
        if post_residual as f64 > mean_residual + 0.5 * cap && fitting_bins_count > 0 {
            score += 60.0; // prefer existing bins when their residuals are large
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 40.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - frac);

    // Small tie-break by fine harmonic class
    score += eighths as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to plausibly hold
    // any future item (min size 1..100 unknown; treat < 35 as near-dead)
    // are heavily penalized, but zero residual (perfect fit) is rewarded.
    if post_residual == 0 {
        score -= 500.0; // perfect fit: strong reward
    } else if post_residual < 35 {
        // unusable dead space: penalize the more useless it is
        let dead = 35.0 - post_residual as f64;
        score += 3.0 * dead + 20.0;
    } else if post_residual <= 50 {
        // moderate gap: mildly penalize to prefer tighter fits
        score += 0.5 * (50.0 - post_residual as f64);
    } else {
        // large residual left: good, mild reward
        score -= 0.25 * (post_residual as f64 - 50.0);
    }

    // Fit tightness: reward small bin_residual - item_size waste relative
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage proliferation of open bins;
    // favor consolidating into existing bins as open_bins_count grows.
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // new-bin candidate: penalize slightly unless many bins open or
        // item is large relative to what any residual could absorb
        score += 15.0 + 1.5 * open_bins_count as f64;
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 80.0; // no open bin can really take a big item
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 0.8 * next_item_size as f64;
        } else {
            // next item won't fit here: penalize leaving this gap
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual,
    // it is the "worst" bin; prefer filling it to balance residuals.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Stream progression: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual).
    score -= 60.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64);

    // 2-step lookahead: reward bins whose post_residual matches next_item_size,
    // so the following item can fill this bin exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect chain: post_residual exactly equals next item -> big bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space that neither the next item nor anything small can use.
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins that are above-average residual
    // (consume space from "wasteful" bins), penalize draining tight bins.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    // (many fitting bins with low residual) or item is large relative to residuals.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count == 0 {
            1.0
        } else {
            (mean_residual < item_size as f64 * 1.05) as i32 as f64
        };
        // Slight inherent penalty so open bins are preferred unless they fit poorly.
        score += 40.0;
        if pressure > 0.5 {
            score -= 55.0;
        }
        // If the next item could chain into a fresh bin's residual, mild bonus.
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) >= 0 {
            score -= 8.0;
        }
    }

    // Late-stream tightening: as the stream progresses, prefer filling bins nearly full.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits beyond raw residual: fill ratio bonus.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for consuming a bin when alternatives exist, scaled by scarcity.
        score += 3.0 / fitting_bins_count as f64;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Dead space relative to the next item: penalize proportionally.
            let waste = (post_residual as f64 - (next_item_size as f64 - 1.0).max(0.0)).max(0.0);
            score += 0.05 * waste;
        }
    }

    // New-bin candidate: penalize opening a new bin, but relax late in the stream
    // or when the item is large and would leave a big unusable residual elsewhere.
    if is_new_bin {
        let mut new_bin_penalty = 18.0;
        // Large items fragment open bins less; allow new bins more freely.
        new_bin_penalty -= 10.0 * fill_ratio;
        // Early in stream, new bins are cheaper; late, prefer consolidation.
        new_bin_penalty += 12.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        new_bin_penalty += 2.0 * fitting_bins_count as f64;
        score += new_bin_penalty.max(0.0);
    } else {
        // Prefer bins with residual below mean (consolidate fragmented space).
        score += 0.1 * (mean_residual - bin_residual as f64);
        // Slight preference for bins among many open ones (reduce bin count pressure).
        score -= 0.05 * open_bins_count as f64;
    }

    // Time horizon: as stream progresses, tighten tolerance for residual waste.
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: smooth polynomial coupling of post_residual with stream progress
    let poly = pr * (1.0 + 0.8 * progress + 0.6 * progress * progress);

    // Penalize large leftover dead space non-linearly (quartic-ish growth)
    let dead = pr_norm * pr_norm * pr_norm * pr_norm * cap;

    // Reward tight fits, stronger early when bins are scarce
    let tight_bonus = -(cap - pr) as f64 * (1.0 / (1.0 + pr_norm));

    // Lookahead coupling: if next item fits the post-residual, reward this bin
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -8.0 * (1.0 - pr_norm)
    } else if next_item_size > 0 {
        4.0 * pr_norm
    } else {
        0.0
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -12.0
    } else {
        0.0
    };

    // New-bin candidate: keep it slightly unattractive unless residuals are messy
    let new_bin = if bin_residual == bin_capacity {
        6.0 + 10.0 * (mean_residual / cap) * (1.0 - progress)
    } else {
        0.0
    };

    // Mild dispersion penalty relative to mean residual
    let disp = (pr - mean_residual).abs() * 0.15;

    poly + dead + tight_bonus + lookahead + last_chance + new_bin + disp
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new = bin_residual == bin_capacity;

    // Harmonic class: prefer residuals in "round" capacity fractions (multiples of 10).
    let rem = post_residual % 10;
    score += (rem as f64) * 0.35;

    // Integer-division thresholds on dead-space magnitude.
    let q = post_residual / 10; // 0..=10 decades of leftover space
    if q == 0 {
        score -= 5.0; // perfect or near-perfect fill
    } else if q <= 2 {
        score -= 3.0; // small usable leftover
    } else if q >= 7 {
        score += 4.0; // wastefully empty bin chosen
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new {
        score -= 15.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // bonus if next item fills the bin almost exactly (harmonic pairing)
            let gap = post_residual - next_item_size;
            if gap <= 10 { score -= 4.0; }
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.2;
        }
    }

    // New-bin candidate penalty: discourage opening fresh bins when fits exist,
    // softened as the stream progresses and when many bins are already open.
    if is_new {
        score += 14.0 * (1.0 - 0.5 * progress)
               + (open_bins_count as f64).sqrt() * 2.0
               - post_residual as f64 * 0.1;
    }

    // Coupling with mean residual across open bins.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // tiny gaps worst
    } else if post_residual > 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Pressure from number of open bins: discourage spreading; but if many
    // bins are open, prefer consolidating into existing bins.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If the next item is large, a fresh bin may be valuable.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 20.0;
        }
        // Late in the stream, avoid leaving many half-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly prefer leaving usable space.
        score += (post_residual as f64) * 0.1;
    }

    // Mean-residual coupling: prefer bins deviating favorably from the mean.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits here too: mild reward proportional to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 100.0 * fill;
        } else {
            // Next item cannot use the leftover dead space: penalize small leftovers.
            let tightness = (post_residual as f64) / (bin_capacity as f64);
            score += 80.0 * (1.0 - tightness) * (1.0 - tightness);
        }
    }

    // Last-chance bin (only one fitting bin): strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize creating very small unusable gaps (dead space) relative to mean residual.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < mean_residual * 0.5 {
            score += 40.0;
        }
        // Reward leaving gaps that are likely reusable by typical items.
        if gap >= 30.0 && gap <= 60.0 {
            score -= 20.0;
        }
    }

    // New empty bin candidate: prefer it only when it beats packing into
    // existing bins; discourage early opening, more permissive later.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 150.0 - 100.0 * progress;
        // If no existing bin is a good fit (many bins but few fit), allow opening.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer fuller bins over emptier ones slightly.
    score += (bin_residual as f64 - post_residual as f64) * -0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize small dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward if the lookahead item fits the post-residual (chain packing).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nx {
            score -= 8.0 + 12.0 * (nx / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0;
    }

    // Last chance: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or none exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = item_size as f64 / cap;
        score += 45.0;
        score -= 20.0 * tightness;
        score -= 15.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild diversity preference: avoid bins far from mean residual to keep options.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for filling larger-residual bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.02 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit = fitting_bins_count as f64;
    let mean_r = mean_residual / cap;

    // Base: prefer tight fits (low post residual), scaled by stream progress.
    let mut score = pr * (0.5 + 0.5 * progress);

    // Non-linear coupling: quadratic post-residual penalty grows with progress
    // (dead space matters more later in the stream).
    score += (pr_norm * pr_norm) * cap * (0.3 + 0.7 * progress * progress);

    // Smooth last-chance reward: subtract strongly when this is the only fitting bin,
    // modulated by how tight the fit is.
    let last_chance = (1.0 / fit).min(1.0);
    score -= 40.0 * last_chance * (1.0 - pr_norm) * (0.4 + 0.6 * progress);

    // Lookahead coupling: reward if next item fits into post residual (smooth sigmoid-ish).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (1.0 - (pr - nxt).abs() / cap).max(0.0);
        let ratio = pr / nxt.max(1.0);
        let bonus = (ratio.min(2.0) / 2.0) * fits_next;
        score -= 25.0 * bonus * (1.0 - progress * 0.5);
    } else {
        // Last item: strongly favor tightest possible closure.
        score -= 30.0 * (1.0 - pr_norm);
    }

    // Penalize bins far below the mean residual (wasteful early filling),
    // smoothly via exponential coupling.
    score += 8.0 * (1.0 - (-2.0 * (pr_norm - mean_r).abs()).exp());

    // Mild penalty for too many open bins relative to stream, encouraging consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - pr_norm);

    // New-bin candidate handling: make empty bin attractive only when fit elsewhere is bad.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - last_chance) * (1.0 - progress * 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (divisible well by common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        // residue classes mod 10, 20, 25, 50 — typical item-size divisors
        if pr % 10 == 0 { harmony += 6.0; }
        if pr % 20 == 0 { harmony += 4.0; }
        if pr % 25 == 0 { harmony += 4.0; }
        if pr % 50 == 0 { harmony += 6.0; }
        if pr == bin_capacity / 2 { harmony += 5.0; }
        // tiny dead zones are bad
        if pr < 10 { harmony -= 25.0; }
        else if pr < 20 { harmony -= 10.0; }
        score -= harmony;
    } else {
        // perfect fill
        score -= 60.0;
    }

    // Lookahead coupling: does the post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact class match is excellent
            if post_residual == next_item_size {
                score -= 40.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                // reward proportional fit, penalize if slack becomes dead space
                score -= 12.0 * (1.0 - slack / cap);
                if slack < 10.0 { score -= 8.0; }
            }
        } else {
            // next item won't fit here: mild penalty unless bin nearly full anyway
            let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
            score += 6.0 * (1.0 - fill_ratio);
        }
    }

    // Integer-division thresholds on residual
    let q = post_residual / 25; // quarter classes
    match q {
        0 => score += 15.0,   // <25: nearly dead
        1 => score += 5.0,
        2 => score -= 4.0,    // sweet zone 50-75
        _ => score -= 8.0,    // large residual: prefer filling big bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current stream is early
    // or all fits are poor (large post_residual everywhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_waste = mean_residual / cap;
        // opening a new bin costs ~one full residual; make it unattractive by default
        score = cap * (0.85 + 0.3 * progress) - 15.0 * avg_waste;
        if next_item_size > 0 && next_item_size >= item_size && fitting_bins_count <= 1 {
            score -= 20.0; // big item coming, fresh bin may help
        }
    }

    // Mild dispersion penalty: prefer bins far from mean residual (extreme fill)
    score -= 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to be
    // useful are heavily penalized (dead space). Gaps >= 10 remain usable.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if pr < 10 {
        // Unusable sliver: dead space penalty proportional to how close to full.
        score += (10 - pr) as f64 * 6.0;
    } else if pr < 20 {
        // Marginal zone: only usable by tiny items.
        score += (20 - pr) as f64 * 1.5;
    }

    // Reward tight packing: fraction of bin consumed.
    let fill = (bin_capacity - pr) as f64 / cap;
    score -= 20.0 * fill;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            score += 4.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins below average residual
    // (fill the emptier-relative bins less, keep large gaps available).
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless current bin is hopeless.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Slight stream-progression tilt: later in the stream, tolerate opening
    // new bins less (favor filling existing ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // Perfect chain: post_residual exactly matches next item -> strong reward.
            let exact = ((pr - nxt) / bin_capacity as f64).min(1.0);
            score -= 18.0 * (1.0 - exact);
        } else {
            // Dead space relative to next item: penalize proportionally to waste.
            let waste = (nxt - pr) / bin_capacity as f64;
            score += 14.0 * waste;
        }
        // Coupling with mean residual: bin far below mean residual is "tight" — prefer filling it.
        let tightness = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score -= 6.0 * tightness.max(0.0);
        score += 3.0 * (-tightness).max(0.0);
    } else {
        // Last item: purely minimize leftover.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            // New bin still gives room for the next item; soften penalty.
            score -= 4.0;
        }
        // Early in stream, new bins are cheap; late in stream, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * progress;
    }

    // Mild preference for tighter fits overall (small post_residual already dominates).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual close to 0 is good.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for exact two-item pairing.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Penalize leaving a leftover that cannot fit the next item,
            // scaled by how much dead space that creates.
            let waste = next_item_size - post_residual;
            score += (waste as f64).min(30.0) * 0.5;
        }
    }

    // New-bin candidate handling: penalize opening a new bin by default,
    // but relax the penalty late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 55.0;
        new_bin_penalty -= progress * 15.0;
        new_bin_penalty -= (open_bins_count as f64).min(10.0) * 1.5;
        // If next item is large and current item leaves big residual in new bin,
        // opening a fresh bin is more attractive.
        if next_item_size > 0 && item_size >= next_item_size {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty;
    }

    // Prefer filling bins that are already relatively empty (consolidation):
    // among fitting bins, favor low residual relative to the mean.
    if bin_residual < bin_capacity {
        let rel = bin_residual as f64 - mean_residual;
        score += rel * 0.15;
    }

    // Mild time-varying exploration term to break ties differently over the stream.
    let phase = ((step_index % 16) as f64) / 16.0;
    score += phase * 2.0 * ((post_residual % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * progress) + 900.0 * (post / cap).powi(3);

    // Dead-space penalty: residuals too small for the smallest item (1) are worthless,
    // but residuals below the typical item band are strongly discouraged.
    let dead = ((20.0_f64).min(post) - post).abs().min(post);
    score += 0.5 * (post - dead).powi(2) / cap;

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 60.0 + 40.0 * progress;
    } else if next_item_size > 0 {
        // Slight penalty for leaving a gap the next item nearly fits.
        let gap = (next_item_size as f64 - post).max(0.0);
        score += 0.3 * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is discouraged early,
    // but allowed late in the stream when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score = cap as f64 * (1.0 + progress)
            + 200.0 * (1.0 - progress)
            - 80.0 * progress * fragmentation
            - 5.0 * pressure * progress;
    }

    // Mild preference for bins below mean residual (consolidate fuller bins).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover: usable space is anything >= min item size (1).
    // With sizes in 1..100, dead space is post_residual that no plausible future item fills.
    // Penalize leftovers in awkward bands using modulo classes of capacity.
    let pr = post_residual as f64;

    // Exact lookahead harmony: next item exactly fills the post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: mild reward proportional to how snugly it nests.
        score -= 30.0 * (next_item_size as f64 / pr);
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: penalize proportionally to wasted fraction.
        score += 15.0 * (pr / cap);
    }

    // Dead-space classes: leftovers in (0..=5] are nearly unusable if min size is larger;
    // use modulo-10 classes on capacity fractions to grade residual quality.
    let class = post_residual % 10;
    if post_residual <= 10 {
        score += 40.0; // tiny leftover = dead space
    } else if class == 0 {
        score -= 20.0; // leftover is a multiple of 10: harmonic with typical sizes
    } else if class >= 7 {
        score += 10.0; // awkward remainder
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless open bins are congested
    // or mean residual is already very low (nothing useful left anywhere).
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (mean_residual / cap).max(0.05);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty high; relax late in stream or when mean residual is tiny.
        let mut new_bin_penalty = 90.0 + 0.5 * congestion.min(200.0);
        if mean_residual < 15.0 {
            new_bin_penalty -= 80.0;
        }
        if progress > 0.9 {
            new_bin_penalty -= 30.0;
        }
        // If item is huge relative to capacity, a fresh bin is often the best home.
        if item_size as f64 > 0.8 * cap {
            new_bin_penalty -= 50.0;
        }
        score += new_bin_penalty.max(10.0);
    }

    // Global pressure: when many bins are open with high mean residual, prefer
    // filling existing space (slight extra penalty on any bin with big residual).
    if mean_residual > 0.6 * cap {
        score += 5.0 * (pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post) / 10.0;
    }
    // Mid-range gaps (10..20) are moderately penalized since few item sizes fit.
    if post >= 10.0 && post < 20.0 {
        score += 8.0 * (20.0 - post) / 10.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: penalize opening new bins when decent fits exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are nearly full
        // or the item would leave a bad gap elsewhere.
        score += 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            // If any open bin fits, discourage opening a new one unless its
            // post_residual would be near zero (perfectly packable item).
            let new_post = cap - item_size as f64;
            if new_post > 0.5 {
                score += 20.0;
            }
        }
    } else {
        // Existing bin: slight bonus when it's one of few fitting bins.
        if fitting_bins_count == 1 {
            score -= 12.0;
        } else {
            score -= 3.0;
        }
    }

    // Lookahead: if next item fits in the post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0;
    }
    // If next item almost fits (small shortfall), mild penalty for stranding it.
    if next_item_size > 0 && post > 0.0 && (next_item_size as f64) > post && (next_item_size as f64) - post <= 10.0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.15 * (mean_residual - (bin_residual as f64)).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (0..1), used for gentle adaptive pressure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: how well does post_residual match the next item? ----
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        if post >= next {
            // The next item can fit exactly into the leftover space: strong reward,
            // scaled by how tight the match is (post - next near 0 is best).
            let match_tightness = 1.0 - (post - next) / bin_capacity as f64;
            score -= 8.0 + 10.0 * match_tightness;
        } else if post > 0.0 {
            // Dead space: post_residual is too small for the next item.
            // Penalize proportionally to how much of the next item cannot use it.
            let waste_ratio = post / next;
            score += 4.0 + 6.0 * waste_ratio;
        }
    } else {
        // Last item in the stream: prefer tightest possible fit.
        score -= 2.0;
    }

    // ---- Relative-to-mean coupling: bins with residual far below mean are
    //      "almost full"; filling them tightly is valuable. ----
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post_f - mean_residual) / mean_residual;
        // Reward placing into bins that end up below the mean residual (tight fit),
        // penalize leaving this bin far above the mean (loose fit).
        score -= 3.0 * (-rel).max(0.0);
        score += 2.0 * rel.max(0.0);
    }

    // ---- Last-chance bonus: if this is the only bin that fits the item,
    //      strongly prefer it over opening a new bin. ----
    if fitting_bins_count == 1 {
        score -= 12.0 + 5.0 * progress;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mildly discourage hoarding into this particular bin
        // so tight matches elsewhere can win.
        score += 1.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin wastes capacity equal to post_residual on average.
        // Add a fixed opening cost so it only wins when all open bins fit poorly.
        // The cost shrinks slightly as the stream progresses (early on, having
        // fresh bins available is cheap insurance).
        score += 6.0 + 10.0 * (1.0 - progress);
        // If the item fills a fresh bin perfectly, allow it eagerly.
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Small structural nudge: prefer bins whose post-residual is a "usable" size
    // (multiples of common small item sizes keep future flexibility).
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Penalize wasted space nonlinearly: large leftovers are increasingly bad.
    score += 0.05 * (post_residual as f64).powf(1.3);

    // Reward near-perfect fills (small dead space).
    if post_residual <= 5 {
        score -= 10.0;
    } else if post_residual <= 15 {
        score -= 4.0;
    }

    // Lookahead: if the next item also fits in the residual, this bin is doubly valuable.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 6.0 + 0.05 * next_item_size as f64;
    }
    // Lookahead mismatch: post_residual is too small for the next item (awkward slot).
    if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 0.08 * post_residual as f64 * (0.5 + t);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Brand-new empty bin candidate: only attractive when existing bins are crowded.
    if bin_residual == bin_capacity {
        score += 18.0 - 0.25 * mean_residual + 6.0 * t;
        if open_bins_count == 0 {
            score -= 30.0; // must place somewhere
        }
    }

    // Late in the stream, be more conservative with open bins (consolidate).
    score += 2.0 * t * (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_norm = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let mut score = post + 40.0 * residual_norm * residual_norm;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space (future items may use it); late,
    // dead space is nearly worthless, so penalize it super-linearly.
    let dead_weight = (residual_norm * residual_norm) * (0.5 + 2.5 * progress * progress);
    score += 30.0 * dead_weight;

    // Lookahead: reward bins whose post_residual can host the next item
    // (smooth reward, stronger later in the stream).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= (1.0 - slack) * (6.0 + 10.0 * progress);
        } else {
            // leftover after this placement likely wasted relative to next item
            let waste = (nxt - post) / cap;
            score += 8.0 * waste * waste * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but less so when
    // existing fits are poor (high mean residual spread) or late in stream.
    if bin_residual == bin_capacity {
        score += 45.0 - 20.0 * progress;
        // If many bins fit the item, opening a new one is rarely justified.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // If mean residual of open bins is large, a fresh bin is more attractive.
        score -= (mean_residual / cap).min(1.0) * 10.0;
    }

    // Mild congestion effect: many open bins -> prefer consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * residual_norm * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into capacity-fraction buckets.
    // Residuals that are "harmonically useful" (multiples of common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that divide cleanly into small item sizes (harmonic classes mod 10, mod 20).
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 {
        score -= 3.0;
    }

    // Penalize dead space: leftover too small for the minimum item (1..100 unknown, but
    // treat leftovers below ~15 as high-risk dead space unless it's an exact tight fit).
    if pr > 0.0 && pr < 15.0 {
        score += (15.0 - pr) * 1.5;
    }

    // Reward very tight fits (post_residual near 0) more aggressively.
    score -= (1.0 - pr / cap) * 8.0;

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        score -= 5.0;
        if diff == 0 {
            score -= 12.0;
        } else if (diff as u32) < 15 {
            score += diff as f64 * 0.4; // slightly wasteful for the next item
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty if this creates stranded space.
        score += pr * 0.05;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress and congestion.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.75 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // If no open bin can fit at all, opening is fine.
        if fitting_bins_count == 0 {
            score -= cap * 0.9;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below average
    // (concentrate packing into tighter bins, keep loose bins flexible).
    score += (pr - mean_residual).max(-30.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strong reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Strict dead-space avoidance: any leftover gap smaller than the smallest
    // plausible item is unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small-but-usable gaps are risky; mild penalty.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate penalty: opening a bin should only win when existing
    // fits are poor (e.g. they would create dead space). Scale slightly with
    // open bin count to discourage bin proliferation.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item can also fit into the resulting
    // residual, this placement chains nicely -> reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    }

    // Mild consolidation pressure toward bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item would leave tiny dead space after its placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - next_post / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow in this bin: penalize proportionally to wasted lookahead.
        score += 0.15 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits relative to mean residual of open bins.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 10.0 * tightness * (mean_residual / cap);

    // Last chance: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: mildly favor filling existing bins over spreading.
    score -= 0.5 * open_bins_count as f64 * tightness;

    // Penalize creating very small unusable slivers (dead space < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // New-bin candidate: prefer it only when current item is large and
    // no open bin offers a good 2-step fit (mean residual is small).
    if bin_residual == bin_capacity {
        let poor_existing = if next_item_size > 0 {
            mean_residual < (item_size as f64 + next_item_size as f64) * 0.6
        } else {
            mean_residual < item_size as f64 * 0.8
        };
        if poor_existing {
            score -= 15.0;
        } else {
            score += 25.0;
        }
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mildly penalize leaving large unusable gaps
            let gap_waste = post_residual as f64 / (bin_capacity as f64);
            score += 4.0 * gap_waste;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer the emptiest (largest residual)
        score -= 2.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Global state: many open bins -> encourage filling existing bins, discourage new bins.
    let load_factor = open_bins_count as f64 / (1.0 + total_items as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when there are already many open bins or good fits exist.
        score += 10.0 + 20.0 * load_factor;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    } else {
        // Prefer bins whose residual is above the mean (big capacity to spare).
        score -= 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Time-horizon effect: late in stream, be greedy about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: best-fit preference for minimal post residual (quadratic to sharpen).
    let mut score = post * (1.0 + 0.9 * post / cap);

    // Smooth non-linear coupling: small post residuals become more valuable
    // as the stream progresses (pack tightly later, keep flexibility early).
    let tightness = (1.0 - post / cap).clamp(0.0, 1.0);
    score -= 18.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Reward bins whose residual after placement matches the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = post - nxt;
            score -= 10.0 * (1.0 - gap / cap) * (1.0 - progress);
        } else {
            // Penalize residuals that waste space relative to lookahead item.
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (smooth ramp in fitting_bins_count).
    if fitting_bins_count <= 1 {
        score -= 14.0 * (1.0 - progress.min(1.0));
    } else {
        score += 2.0 * ((fitting_bins_count as f64 - 1.0).ln() + 1.0);
    }

    // Mild penalty when this bin is far below the mean residual (fragmentation).
    let dev = (mean_residual - post) / cap;
    score += 3.0 * dev * dev;

    // Discard bins with tiny unusable residuals unless the fit is near-perfect.
    if post > 0.0 && post < 10.0 {
        score += 5.0 * (1.0 - post / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space?
    // Residuals that are multiples of common item-size classes (e.g. 10, 20, 25, 50)
    // are more likely to be filled by future items -> reward them.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fill is best
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -7.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        4.0 // awkward residual class: penalize
    };
    score += harmonic_bonus;

    // Dead space zone: residuals too small for the minimum item are dead.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does the leftover fit the next item's harmonic class?
    if next_item_size > 0 {
        let ni = next_item_size;
        if pr >= ni {
            // leftover can host next item -> reward, stronger if class-aligned
            let class_align = if pr % ni == 0 { 12.0 } else if (pr - ni) % 10 == 0 { 6.0 } else { 2.0 };
            score -= class_align;
            // tight fit for next item: nearly exact
            let slack = (pr - ni) as f64;
            if slack <= 5.0 {
                score -= 10.0;
            }
        } else {
            // leftover cannot host next item; penalize proportionally to waste
            score += 5.0 + (ni as f64 - pr as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin wastes (capacity - item) immediately.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its post residual is large, but add an
        // explicit opening penalty that shrinks when few bins fit the item
        // (forced open) and grows when many alternatives exist.
        score += 45.0 - (fitting_bins_count as f64).min(10.0) * 4.0;
        // If no open bin can fit (this is the only candidate), remove penalty.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // Late in stream with many open bins, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Mild tie-break: prefer bins whose residual deviates favorably from the mean
    // (packing into below-average-residual bins keeps large leftovers available).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Prefer tighter fits overall: small bin_residual before placement is good.
    score += (bin_residual as f64 - item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: gaps too small to hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Non-linear penalty on small post-residuals (wasted capacity).
    let pr = post_residual as f64;
    score += (1.0 - pr / bin_capacity as f64).powi(6) * 30.0;

    // Reward tight fits: small post_residual relative to item size.
    score -= (item_size as f64) / (item_size as f64 + pr + 1.0) * 10.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64 / (1.0 + open_bins_count as f64);
    }

    // Prefer bins with below-mean residual (keep large residuals for future large items).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    // Late in the stream, tighten packing (avoid opening new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Reward when post_residual can still host next item (>=), but not too loosely
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is below mean residual (tight packing)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(30.0) * 0.5;
    } else {
        score += (res - mean_residual).min(30.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize the new-bin candidate unless current bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && item_size + next_item_size <= bin_capacity
                && open_bins_count > 0
                && fitting_bins_count <= 1
                && post_residual as i64 - next_item_size as i64 > 20);
        if poor_fit {
            score -= 15.0;
        } else {
            score += 50.0;
        }
    }

    // Penalize very small dead space that is hard to fill later
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Penalize squared dead space: small leftovers are fine, mid-size gaps are wasteful.
    if post_residual > 0 {
        score += 0.6 * post * post / cap;
    }

    // Lookahead pairing: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 + 4.0 * (1.0 - post / cap); // tight + chainable is best
        } else {
            score += 0.25 * (nxt - post).min(25.0); // leftover useless for next item
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: add opening penalty so it only wins on genuinely tight fits.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.2 * open_bins_count as f64 + 0.06 * item_size as f64;
    }

    // Prefer bins whose residual is near the global mean (keeps portfolio balanced).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Time horizon: later in the stream, favor tighter packs; early, keep flexibility.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * t * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = (pr / cap).clamp(0.0, 1.0);

    // Base: minimize post residual (tight fits preferred).
    let mut score = pr;

    // Smooth polynomial shaping of residual: mid-range dead space penalized extra.
    let dead = x * (1.0 - x) * 4.0; // peaks at x=0.5 (unusable mid-size gap)
    score += dead * (0.25 * cap) * (0.5 + progress);

    // Perfect-fit reward (smooth exponential rather than hard threshold).
    if pr == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline; encourage it when the item fits
    // poorly everywhere (large post residual relative to capacity) and
    // many bins are already open.
    if bin_residual == bin_capacity {
        let load = item_size as f64 / cap;
        score = 0.55 * cap - load * cap + open_bins_count as f64 * 2.0 - progress * 10.0;
    }

    // Lookahead coupling: reward residual that can host the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack) * 8.0 * (1.0 - progress);
        }
    }

    // Mild preference for bins already below average fullness.
    score -= (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: group post_residual into capacity-fraction buckets
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let class = (post_f * 4.0 / cap).floor(); // 0..3 harmonic class of remaining space

    // Penalize mid-class residuals (awkward dead space), reward near-full or large usable space
    match class {
        0 => score -= 30.0,                      // bin almost perfectly filled
        1 => score += 10.0,                      // small awkward remainder (25%..50%)
        2 => score -= 5.0,                       // moderately usable (50%..75%)
        _ => {}                                  // large space, neutral
    }

    // Harmonic compatibility: does next_item_size fit into post_residual's class?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_f {
            // next item fits here: reward tighter couplings (integer division harmony)
            let coupling = ((post_f / nxt).floor() * nxt - post_f).abs();
            score -= 8.0 + 4.0 * (1.0 - coupling / cap);
        } else {
            // next item cannot use this leftover: penalize proportional dead space
            score += 6.0 + 0.15 * nxt;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless current bins are very full or item is huge
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let threshold = 0.5 * cap * (1.0 - 0.3 * progress);
        if post_f > threshold {
            score -= 20.0; // item large relative to capacity, fresh bin reasonable
        } else {
            score += 15.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Mild pressure toward consolidating into bins tighter than the mean
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Moderate penalty for medium gaps that few typical items can use.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Pressure from number of open bins: prefer existing bins when many are open,
    // but allow new bins when few are open and fit is poor.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost of opening a bin, softened when
        // the current fit would create dead space or when few bins are open.
        score += 90.0 - 0.6 * open_pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin is attractive if the next item fits well into a full bin.
            let gap = bin_capacity.saturating_sub(next_item_size);
            if gap < 15 {
                score -= 60.0;
            }
        }
    } else {
        // Existing bin: mild reward for keeping bins consolidated.
        score -= 0.4 * open_pressure;
    }

    // Prefer bins whose residual is close to what the item consumes (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // Penalize placements leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Late in the stream, avoid opening new bins unless necessary.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize wasted (dead) space that is too small to hold any typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item (perfect chain fill).
    if next_item_size > 0 {
        let post = post_residual as i64;
        let nxt = next_item_size as i64;
        let diff = (post - nxt).abs();
        if diff == 0 {
            score -= 120.0; // perfect two-step match
        } else if diff <= 5 {
            score -= 60.0;  // near match, still good
        } else {
            score += (diff as f64) * 0.5; // mismatch penalty grows with gap
        }

        // If next item cannot fit anywhere else after this placement, avoid
        // burning residual that would have served it.
        if post < nxt && post > 0 {
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer bins that are already tight
    // (below-mean residual) to consolidate items.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: default mild penalty so existing bins are preferred,
    // but allow opening a new bin when all fits would create heavy dead space
    // or when the bin set is very fragmented.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // With lookahead: a fresh bin can serve both current and next item well.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 35.0;
        }
        // Fragmented open-bin set: a clean bin helps.
        if open_bins_count > 6 {
            score -= 10.0;
        }
    }

    // Late in the stream, tighten packing (avoid leaving many half-empty bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: post_residual too small for any plausible item (>=1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits the post-residual of this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item almost fits but not quite (wasted opportunity).
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && next_item_size - post_residual as u32 <= 8 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: default penalty so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 60.0;
        // If this bin is the only fitting option, opening new bin is fine.
        if fitting_bins_count <= 1 {
            new_bin_score -= 30.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 40.0 * progress;
        // Many open bins with low mean residual: opening new bin less attractive.
        new_bin_score += open_bins_count as f64 * 1.5;
        // If mean residual across bins is small, opening new bin is more attractive.
        new_bin_score -= (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
        // Very tight fit in existing bin beats new bin anyway.
        if fit_ratio > 0.9 {
            new_bin_score += 50.0;
        }
        score = new_bin_score;
    }

    // Mild time-dependent consolidation pressure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic in fill ratio of the bin after placement.
    let fill = 1.0 - post_residual as f64 / cap;
    score -= 12.0 * fill * fill;

    // Penalize large dead space non-linearly, more so late in the stream.
    let dead = post_residual as f64 / cap;
    score += 8.0 * dead * dead * (0.5 + progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            let snug = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 6.0 * snug;
        } else {
            // Next item won't fit here; slight penalty scaled by how close it is.
            score += 2.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is penalized, but the
    // penalty shrinks when existing residuals are fragmented (high mean residual
    // relative to item) or when many bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
        score -= 3.0 * (mean_residual / cap).min(1.0);
        // If current item is large relative to capacity, new bin is more acceptable.
        score -= 4.0 * (item_size as f64 / cap);
    }

    // Smooth coupling: prefer bins whose residual is close to the item size
    // (near-perfect packing), via a smooth bump.
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * gap * gap;

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * dead;

    // Small smooth stream-progress tilt toward reusing bins later.
    score -= 2.0 * progress * (1.0 - dead);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (dead space) are penalized.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Fraction of capacity left after placement.
    let post_frac = post_f / cap;

    // Penalize leftover space that is too small to be useful for typical items
    // (items 1..=100; leftover < ~20 is usually dead space).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 - post_f / 20.0); // up to +40 for nearly-full bins... wait, lower is better
        // invert: near-full bin (post ~1) is actually GOOD, reward it instead
    }

    // Reward tight fits: post_residual small but nonzero.
    if post_residual > 0 && post_residual <= 15 {
        score -= 30.0 * (1.0 - post_f / 15.0);
    }

    // Perfect fit is best.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class: leftover divisible into useful chunks (e.g. multiples of 10, 25)
    // are more reusable than awkward residues like 7, 13, 37.
    let residue_class = post_residual % 10;
    if post_residual >= 20 {
        if residue_class == 0 {
            score -= 12.0; // clean class (10,20,...)
        } else if residue_class <= 3 || residue_class >= 7 {
            score += 6.0;  // awkward residue
        }
    }

    // Large leftovers are flexible; mildly reward them relative to mid-range waste.
    if post_frac >= 0.5 {
        score -= 8.0 * (post_frac - 0.5);
    } else if post_frac >= 0.2 {
        score += 4.0 * (0.5 - post_frac);
    }

    // Lookahead: if next item fits in the post residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 20.0 + 0.3 * slack as f64;
    } else if next_item_size > 0 {
        // next item won't fit here; penalize mildly, more if this was the only fitting bin
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter competition handling
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: bin_residual == bin_capacity (empty bin).
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if open bins are all quite full
        // (mean residual small) or none fit well. Penalize new bin normally,
        // but reduce penalty when the stream is early and mean residual is low.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mean_r = mean_residual / cap; // fraction of mean leftover
        // New bin baseline: its post_residual == capacity - item_size.
        // Add penalty so we prefer existing bins unless they're hopeless.
        score += 15.0 + 30.0 * mean_r - 10.0 * (1.0 - progress);
        // If the current item is large and mean residual is small, new bin is fine.
        if item_size as f64 > cap * 0.6 && mean_r < 0.15 {
            score -= 20.0;
        }
    }

    // Slight preference to fill bins that are already mostly full relative to mean.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 150.0;
    } else {
        // Penalize mid-range dead space quadratically, normalized by capacity.
        let pr = post_residual as f64;
        score += 0.004 * pr * pr;
    }

    // Reward bins whose residual after placement can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 15.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items;
    // with few open bins, favor reusing existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - 0.3 * progress);
    score += 0.05 * pressure;

    // Prefer bins below the mean residual (tighter bins get priority).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when current bin fits poorly
    // (large post_residual dead space). Otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 60.0 + 2.0 * open_bins_count as f64;
        if post_residual == bin_capacity && item_size <= bin_capacity / 2 {
            score -= 20.0; // big item in fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * 8.0;

    // 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetically placing next item
            score += gap * 0.35;
            if gap < 10.0 {
                score -= 10.0; // near-chain bonus
            }
        } else {
            // next item won't fit here; penalize proportionally to mismatch
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.25;
        }
    } else {
        // last item: strongly prefer minimal post_residual
        score += 15.0;
    }

    // Relative to mean residual: bins with more room than average are better targets
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Penalize creating dead space below the minimum item size (1..100 unknown, assume ~10 floor)
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual elsewhere
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 20.0;
        // but if existing bins fit poorly (high mean residual waste), new bin becomes attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // fresh bin can chain the next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor bins where the next item also fits (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.35 * next_item_size as f64;
        } else {
            // Dead space relative to lookahead: penalize wasted gap.
            let gap = post_residual as f64;
            score += 4.0 + 0.25 * gap;
        }
    }

    // Last chance bin: strongly reward using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Penalize bins deviating from mean residual (keep residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate: penalize so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.3 * item_size as f64;
    }

    // Late in stream: be more conservative, prefer using existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 6.0 * progress;
    }

    // Slight preference for bins with more open bins competing (avoid bin sprawl).
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post-residual, with non-linear (quadratic) tightening
    let mut score = post * (1.0 + 0.9 * (post / cap));

    // Smooth stream-progress coupling: later in the stream, demand tighter fits more strongly
    let tightness = 1.0 + 1.3 * progress * progress;
    score *= tightness;

    // Interaction: post_residual relative to mean residual of open bins
    let mean = if mean_residual.is_finite() { mean_residual } else { cap };
    let rel = post - mean;
    score += 0.35 * rel * rel / cap;

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = (next_item_size as f64) / (post + 1.0);
        // good if next item nearly fills the post residual
        score -= 6.0 * fit_quality * fit_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        // next item won't fit in the residual: penalize dead space mildly
        score += 2.0 * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate handling: opening a new bin is expensive, but attractive
    // when the item fits badly everywhere (large post_residual) or bins are few.
    if bin_residual == bin_capacity {
        let waste = post / cap; // for empty bin, post = capacity - item
        let badness = 1.0 - waste; // large when item is small -> lots of leftover
        let pressure = (open_bins_count as f64).recip();
        score += 10.0 + 8.0 * badness * (1.0 + progress) - 4.0 * pressure * progress;
        // If no open bin can fit, new bin must be chosen effectively
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Small penalty for many open bins (encourage consolidation)
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose residual falls into
    // "usable" residue classes (multiples of common small item sizes) are
    // more likely to be filled later, so reward them.
    let pr = post_residual;
    if pr > 0 {
        let harmonic_bonus = if pr % 10 == 0 {
            -6.0
        } else if pr % 5 == 0 {
            -3.0
        } else if pr % 2 == 0 {
            -1.5
        } else {
            2.0 // odd residuals pair poorly with even-dominant streams
        };
        score += harmonic_bonus;
    } else {
        // Perfect fill: strongly reward.
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small for the minimum item size
    // (interface allows items down to 1, but small residuals under ~10 are
    // statistically hard to fill) become dead weight.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.0;
    }

    // Exact-fit reward relative to capacity fractions.
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.9 {
        score -= 8.0;
    } else if fill_frac > 0.7 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a chained harmonic match — reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's remainder: mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current item leaves a large, well-structured residual or no open bin
    // fits well. Penalize opening a new bin by default.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But allow fresh bins when many bins are open and mean residual is
        // fragmented (high mean residual with many bins suggests poor fits).
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 10.0;
        }
        // Prefer a fresh bin for very large items that leave clean residuals.
        if item_size >= 70 && item_size % 10 == 0 {
            score -= 6.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, favor tightening
    // existing bins over spreading items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // Slight preference for tighter existing bins via mean residual anchor.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post_residual that cannot fit even the smallest plausible item (1..=10)
    // or cannot fit the lookahead item is nearly worthless space.
    let tiny_gap = (post_residual > 0 && post_residual < 10) as f64;
    let lookahead_wasted = (next_item_size > 0 && post_residual > 0 && post_residual < next_item_size) as f64;
    score += 60.0 * tiny_gap + 35.0 * lookahead_wasted;

    // Reward tight fits (small post_residual relative to item size) with a
    // non-linear bonus that saturates: perfect fits get a large discount.
    let tightness = item_size as f64 / (post_residual as f64 + item_size as f64);
    score -= 40.0 * tightness * tightness;

    // If post_residual exactly matches the next item, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Open-bin pressure: with many bins open, prefer packing into existing
    // bins rather than spreading; with few bins, allow more freedom.
    let pressure = (open_bins_count as f64).ln() * 8.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward that unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // Mean-residual coupling: when average residual across open bins is low
    // (bins are nearly full), prioritize conserving the emptiest usable space.
    if mean_residual < 25.0 && post_residual >= 10 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Only make
    // it attractive when the current fit is truly bad (large dead space or
    // nothing fits well), otherwise keep the new bin as a fallback.
    if bin_residual == bin_capacity {
        if post_residual >= 10 && fitting_bins_count >= 1 {
            // Existing bins can take the item; make new bin clearly worse.
            score += 70.0 + 0.5 * open_bins_count as f64;
        } else {
            // Poor fits everywhere: a fresh bin is preferable.
            score -= 15.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, slightly favor
    // filling bins that are already well-utilized.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit wins, but not brutally so.
    score = post_residual as f64 * 0.5;

    // 2-step lookahead: reward when post_residual exactly (or nearly) matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if post >= nxt {
            // Next item still fits here: reward tight 2-step chains.
            score -= (nxt / (1.0 + diff)) * 8.0;
            // Perfect chain match gets a big bonus.
            if diff == 0.0 {
                score -= 25.0;
            }
        } else {
            // Dead space relative to the lookahead item: penalize proportionally.
            let waste = nxt - post;
            score += waste * 0.8;
            // Extra penalty if the dead space is unusable for typical small items.
            if post < 10.0 {
                score += 15.0;
            }
        }
    }

    // Relative-to-mean-residual coupling: bins with residual far below mean are
    // already "tight"; placing here consolidates waste.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        if post_f < mean_residual {
            score -= (mean_residual - post_f) * 0.3;
        } else {
            score += (post_f - mean_residual) * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): default penalty so we only open when
    // existing fits are bad; relax the penalty late in the stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 45.0;
        if next_item_size > 0 && next_item_size as f64 > post_f + 0.5 {
            // Item fits here but leaves nothing for the next item -> opening
            // a fresh bin may be better; reduce penalty.
            new_bin_penalty -= 20.0;
        }
        if fitting_bins_count == 1 {
            new_bin_penalty += 15.0; // avoid abandoning the last usable bin
        }
        score += new_bin_penalty * (1.0 - 0.3 * progress);
    }

    // Small global tie-breaker toward very tight residual usage.
    score += (bin_capacity as f64 - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 18.0; // tiny unusable fragment
        } else if dead < 25.0 {
            score += 6.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.25 * item_size as f64;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // if next item is large and would be stranded, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 8.0;
        } else if post_residual > 0 && nxt > post_residual as f64 {
            score += 0.15 * (nxt - post_residual as f64);
        }
    }

    // Global state: many open bins with high mean residual → prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 5.0 * consolidation * (1.0 + progress);

    // New empty bin candidate: baseline cost of opening a bin, softened when
    // the item is large (large items pack best in fresh space) or when the
    // current bin's fit is poor.
    if bin_residual == bin_capacity {
        let large_item_bonus = 0.2 * (item_size as f64 - 50.0).max(0.0);
        score += 20.0 - large_item_bonus;
    }

    // Mild preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Smooth non-linear reward for tight fits (small post_residual)
    score -= 30.0 * (1.0 - fit_ratio).powi(2) * (1.0 - fit_ratio);

    // Dead-space penalty grows smoothly with stream progress
    score += 25.0 * fit_ratio.powi(3) * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer the single fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 15.0 * (gap / cap).powi(2);
        } else {
            score += 8.0 * (-gap / cap).powi(2);
        }
    }

    // Mild pressure toward consolidating into fewer bins as stream advances
    score += (open_bins_count as f64).powf(0.5) * progress * 2.0;

    // New-bin candidate: penalize opening a bin unless post_residual is small relative to capacity
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else {
        // dead-space penalty grows for residuals that few item sizes can use
        let usable = (1..=100u32).filter(|&s| s <= pr).count() as f64;
        score += (100.0 - usable) * 0.4;
        // harmonic class: residuals divisible by 10 or 25 are friendlier
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr < 10 { score += 15.0; } // tiny dead space
    }

    // Lookahead coupling: reward if post_residual exactly fits next item
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 25.0;
        } else if pr > next_item_size {
            score -= 6.0;
        } else {
            score += (next_item_size - pr) as f64 * 0.3; // next item can't use this bin
        }
        // modulo harmony: post_residual % next_item_size small => good chain
        if next_item_size > 0 && pr >= next_item_size {
            let r = pr % next_item_size;
            score -= (next_item_size as f64 - r as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64).sqrt() * 2.0;
        // but if current item leaves a large awkward residual elsewhere, new bin ok
        if post_residual < 20 && item_size <= 40 {
            score -= 10.0;
        }
    }

    // Prefer tighter bins (small residual relative to capacity)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Prefer bins below mean residual (relatively emptier handled by tightness term)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are nearly unusable
    // (min item size is 10), so penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits that leave exactly zero residual.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Perfect fill of the bin's residual (item exactly matches space).
    if item_size == bin_residual {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item could fit into the post residual,
    // reward leaving that much usable space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit in post residual but would fit in a fresh bin,
    // and post residual is small-but-usable, add mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // opening a new bin (residual == capacity) gets penalized progressively.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) + 5.0 * progress;
    }

    // Mild penalty for bins far below the mean residual (keeps packing balanced).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Slight preference for tighter fits overall.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // New-bin candidate handling: make it expensive unless nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is justified only when no open bin gives a good fit.
        // Penalize moderately; the lookahead logic below can still override.
        score += 40.0 + (open_bins_count as f64).sqrt() * 3.0;
        // If the lookahead item would fit perfectly in the new bin's residual,
        // this is a strong reason to open it (reserve space for next item).
        if next_item_size > 0 && next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 90.0;
            } else if gap <= 5 {
                score -= 45.0;
            }
        }
        // Last-chance situation: only one fitting bin -> new bin is a real option.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        return score;
    }

    // --- Aggressive 2-step lookahead matching for existing bins ---
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;

        if pr >= ni {
            let gap = pr - ni;
            if gap == 0.0 {
                // Perfect: next item exactly fills the remaining space.
                score -= 80.0;
            } else if gap <= 3.0 {
                score -= 50.0;
            } else if gap <= 10.0 {
                score -= 25.0 * (1.0 - gap / 10.0);
            } else {
                // Large leftover after next item: mildly penalize wasted space
                // but still better than leaving residual < next_item_size.
                score -= 10.0 * (1.0 - ((gap - 10.0) / 80.0).min(1.0));
            }
        } else {
            // post_residual < next_item_size: this space becomes dead after now
            // unless a later small item fits. Penalize proportional to deadness.
            let deadness = (ni - pr) / ni;
            score += 20.0 * deadness;
            // But if post_residual is tiny (< 10), the bin is essentially closed
            // efficiently — that's actually fine, reward tight closure.
            if post_residual <= 8 {
                score -= 15.0;
            }
        }
    } else {
        // Last item: pure tight-fit greedy.
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // Contextual adjustments.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Last-chance bin: strongly favor using it to avoid opening a bin for one item.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Many options: be pickier about dead space.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual > 8 {
            score += 15.0;
        }
    }

    // Compare against mean residual: prefer bins that are already depleted
    // relative to the fleet average (consolidate waste into few bins).
    let rel = if mean_residual > 0.0 { post_residual as f64 / mean_residual } else { 1.0 };
    if rel < 0.7 {
        score -= 12.0 * (0.7 - rel);
    } else if rel > 1.3 {
        score += 8.0 * (rel - 1.3).min(1.0);
    }

    // Late in stream: tighten everything, avoid opening bins.
    if progress > 0.8 {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalize opening a new bin; penalty grows with number of open bins
        // (encourages consolidation) and shrinks slightly late in the stream.
        score += 55.0 + 0.35 * open_bins_count as f64 - 10.0 * progress;
        // If the item is large, a fresh bin is more acceptable (large items
        // leave little usable space anyway).
        score -= 0.2 * item_size as f64;
    } else {
        // Reward tight fits: item filling a large fraction of the residual.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 12.0 * fill_ratio;

        // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Lookahead: penalize placements that leave a residual too small for
        // the next item, wasting the remaining space (dead space).
        if next_item_size > 0 && next_item_size > post_residual {
            let block = (next_item_size - post_residual) as f64;
            score += 0.25 * block * (1.0 - progress);
        }

        // Slight penalty if this bin's residual deviates strongly from the mean
        // (favors balanced residual distribution, avoids extreme fragmentation).
        score += 0.04 * (mean_residual - post_residual as f64).abs();

        // Reward zero post-residual (perfect closure of a bin).
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress;
    score += 40.0 * poly;

    // Reward tight fits, more so later in the stream
    let fit_quality = 1.0 - pr_norm;
    score -= 25.0 * fit_quality * fit_quality * (0.5 + progress);

    // Penalize creating dead space that no plausible next item can use
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 12.0 * (ni - pr) / cap * (1.0 + progress);
        } else {
            // reward leaving room exactly for the next item
            let slack = (pr - ni) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + 0.5 * progress);
    }

    // Mild pressure against spreading across many open bins
    score += 0.3 * open_bins_count as f64 * pr_norm;

    // Prefer bins whose residual deviates from mean residual (consolidation)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    // Penalize new-bin candidate smoothly, relax as stream progresses
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).

    // Harmonic class of post_residual: dead space classes.
    // Residuals that are "harmonically useful" (small, or divisible into common item sizes) get rewarded.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward very small residuals (near-perfect packing).
    if post_residual <= 5 {
        score -= 18.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize awkward mid-range dead space (25..50): too big to ignore, too small for typical items.
    if post_residual > 25 && post_residual < 50 {
        score += 6.0;
    }

    // Harmonic divisibility: residuals divisible by common size classes (10, 20, 25, 50) are reusable.
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: how many "typical small items" (size ~20) still fit?
    let slots = post_residual / 20;
    score -= slots as f64 * 1.5;

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + 0.3 * (cap_f - slack) / cap_f;
        // Perfect chain: next item exactly fills the bin.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }
    // If next item cannot fit here, penalize slightly (this bin becomes dead space).
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0 + pr / cap_f * 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        // Neutral base: slightly worse than a decent fit, better than terrible fits.
        score = cap_f * 0.5;
        // Late in the stream, opening new bins is less costly (fewer future consequences).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
        // If many open bins with high mean residual, prefer consolidating instead.
        score += 0.05 * mean_residual;
        // If only one fitting bin (last chance), strongly discourage the new bin.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
        // If next item is large, a fresh bin may be strategically good.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    }

    // Mild preference to fill already-open bins when many are open.
    score += 0.3 * open_bins_count as f64 * (pr / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small to hold any plausible future item
    // (item sizes 1..100, so a residual below ~10 is nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (small post_residual is good, but zero is a perfect fill).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening another one.
    // The new-bin candidate has bin_residual == bin_capacity, so penalize it
    // proportionally to how crowded the current bin set is.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward leaving that gap; if post_residual cannot hold the next item
    // but the current bin could hold both, mildly discourage splitting.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        }
    }

    // Mild stream-progress term: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    // Prefer bins whose residual is close to the item (best-fit behavior).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect two-step match (next item exactly fills leftover).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Reward if next item fits into post residual (chainable bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    }
    // Penalize dead space smaller than next item (unusable gap).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.8 * (next_item_size - post_residual) as f64;
    }

    // Penalize waste relative to mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer keeping it closed early; allow opening when
    // current bin would leave a tiny dead gap.
    if bin_residual == bin_capacity {
        let tight_elsewhere = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 5;
        if tight_elsewhere {
            score += 60.0; // existing bin chains nicely, don't open new one
        } else if next_item_size > 0 && post_residual < next_item_size && post_residual <= 10 {
            score -= 55.0; // current fit is poor; fresh bin better
        } else {
            score += 10.0;
        }
    }

    // Late-stream tightening: prefer filling bins completely near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating awkward dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: reward leaving room for the next item; penalize if
    // this placement strands the next item.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 4.0 + 3.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if (bin_residual as f64) >= next_item_size as f64
            && post_residual > 0
            && (post_residual as f64) < next_item_size as f64
        {
            // This bin could have held the next item, but we destroy that option.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 15.0;
        // Escalate penalty when many bins are open with slack available.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // If plenty of bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0 + 5.0 * (fitting_bins_count as f64);
        }
        // Early in the stream, opening bins is cheaper (build a portfolio of residuals).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is large, prefer reusing them.
        score += (mean_residual - item_size as f64).max(0.0) * 0.3;
    }

    // Prefer bins whose residual is below the mean (consolidate the tightest bins),
    // keeping looser bins available for future large items.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Late-stream urgency: as the stream ends, avoid opening new bins even more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 && bin_residual == bin_capacity {
            score += 20.0 * (progress - 0.8);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap; // normalized dead space after placement

    // Base: quadratic penalty on post residual (dead space), smoothed by progress
    let mut score = pr * (1.0 + 0.9 * progress) + 40.0 * fit_frac * fit_frac * cap;

    // Reward tight fits more strongly as stream progresses
    score -= 25.0 * (1.0 - fit_frac) * (1.0 - fit_frac) * (0.5 + 0.5 * progress);

    // Penalize bins whose residual deviates from mean residual (imbalance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when
    // the item fits reasonably elsewhere; relax late in stream.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let next_pressure = if next_item_size > 0 {
            (next_item_size as f64 / cap).powi(2)
        } else {
            0.0
        };
        score += 60.0 + 80.0 * (1.0 - progress) - 40.0 * next_pressure;
    } else {
        // Reward bins that can also host the lookahead item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (modulo logic) ---
    // Residuals that are "harmonically useful" for future items get rewards.
    // Classes: exact 0 (perfect), multiples of 10, multiples of 25, small dead space.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit: bin closes cleanly
    } else if r % 25 == 0 {
        score -= 22.0;
    } else if r % 10 == 0 {
        score -= 14.0;
    } else if r < 10 {
        // dead space: too small for any item (min size 1..100, but tiny slivers waste)
        score += 18.0 * (1.0 - r as f64 / 10.0);
    } else if r % 5 == 0 {
        score -= 6.0;
    }

    // Integer-division threshold coupling: does the leftover fit the lookahead item?
    if next_item_size > 0 {
        if r >= next_item_size {
            // pair-friendly: leftover can host next item
            let slack = (r - next_item_size) as f64;
            score -= 10.0 - 0.05 * slack;
            // harmonic bonus if leftover is an exact multiple of next item's class
            if next_item_size > 0 && r % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            // leftover cannot host the next item: penalize proportionally to closeness
            let miss = (next_item_size - r) as f64;
            score += 4.0 + 0.12 * miss.min(40.0);
        }
    }

    // Fraction-of-capacity harmonic bands on the item size
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.75 {
        score -= 9.0; // big item: place it anywhere it fits, avoid fragmenting elsewhere
    } else if frac < 0.25 {
        score += 3.0; // tiny item: prefer bins where it plugs residual exactly
        if r == item_size {
            score -= 25.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless necessary
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 55.0 + 25.0 * (1.0 - progress);
        // opening is fine if item is huge (little waste risk)
        penalty -= 0.4 * item_size as f64;
        // or if no open bin can fit at all
        if fitting_bins_count == 0 {
            penalty = -10.0;
        }
        // avoid opening when mean residual is large and item is small
        if mean_residual > item_size as f64 + 15.0 {
            penalty += 20.0;
        }
        score += penalty;
    }

    // Mild tie-break toward filling fuller bins first
    score += 0.02 * (bin_capacity as f64 - bin_residual as f64).recip() * 10.0;

    // Slight preference to keep many open bins balanced late in the stream
    if open_bins_count > 4 && mean_residual > 0.0 {
        score += 0.01 * (mean_residual - r as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space after placement.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Mild penalty for medium gaps that rarely fit future items.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }
    // If next item would NOT fit in post residual, penalize slightly (fragmentation risk).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Prefer bins with residual below the mean (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: keep it slightly unattractive unless it's genuinely better.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
