pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness preference: strongly favor minimal dead space (superlinear).
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Post residual becomes dead space relative to known next demand.
            score += 0.25 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
        // Exact chain fit: item then next item perfectly fills bin.
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into fuller bins.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: when mean residual is high (wasteful state),
    // penalize leaving more waste; when low, be more tolerant.
    score += 0.20 * (post_residual as f64 - mean_residual).max(-30.0).min(50.0) * 0.5;

    // Time horizon: late in the stream, avoid creating small unusable gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * progress;
    }

    // New-bin candidate handling: baseline competitive score, but penalize
    // opening a new bin when existing bins can fit, unless the fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count > 0 && post_residual <= 20 {
            score += 40.0; // good fits exist elsewhere -> don't open new bin
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
        // Early stream: opening bins is cheaper (more future items to fill them).
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post residual), with non-linear shaping.
    let mut score = pr / cap;

    // Smooth non-linear coupling: post residual weighted by stream progress.
    // Later in the stream, dead space matters more (fewer chances to fill it).
    score += (pr / cap).powi(3) * (0.5 + 2.0 * progress);

    // Interaction with mean residual: placing into a bin far above the mean
    // residual concentrates waste; reward bins near/below mean residual.
    let mean_norm = mean_residual / cap;
    score += 0.35 * (pr / cap - mean_norm).abs().sqrt();

    // Perfect fit bonus (post_residual == 0).
    if post_residual == 0 {
        score -= 2.0;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5 + progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 1.2;
    } else if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        // Post residual likely dead space if next item can't use it.
        score += 0.4 * (pr / cap);
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // fit in existing bins is poor. Penalize the empty bin mildly by default.
    if bin_residual == bin_capacity {
        // Base penalty scales with how many bins could otherwise fit the item.
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 + 0.5 * fitting_bins_count as f64 };
        // Late in the stream, avoid opening bins with little future utility.
        let late_penalty = 0.8 * progress;
        // If item is large relative to capacity, a fresh bin is more attractive.
        let size_relief = 0.9 * (item_size as f64 / cap);
        score += 1.0 + fit_pressure + late_penalty - size_relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // residue classes modulo 10 (typical item granularity).
    let post_class = post_residual % 10;
    // Penalize leftover space that is "odd" in the harmonic sense:
    // residuals that are small-but-nonzero are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Perfect fits are golden.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward residuals that fall into "reusable" harmonic classes:
    // multiples of 10 pair well with typical item sizes.
    if post_class == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_class >= 5 {
        score += post_class as f64 * 0.3;
    } else {
        score += post_class as f64 * 0.1;
    }

    // Integer-division threshold: fraction of the bin consumed.
    let fill_quintile = (bin_residual * 5) / bin_capacity; // 0..4
    // Prefer filling bins that are already substantially filled (best-fit flavor),
    // with a harmonic weighting across quintiles.
    score -= fill_quintile as f64 * 2.5;

    // Lookahead coupling: if the next item fits the post residual exactly
    // (same harmonic class), strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            if post_residual == next_item_size {
                score -= 10.0;
            } else if post_residual % next_item_size == 0 {
                score -= 3.0;
            }
        } else {
            // This placement strands the next item in a new bin: penalize
            // proportionally to how close we came to fitting it.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.4;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are nearly saturated. Penalize opening new bins otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let saturation = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
        score = 100.0 - progress * 30.0 - saturation.min(20.0);
        // If nothing currently open can fit, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild global pressure: more open bins with high mean residual -> consolidate.
    score += (open_bins_count as f64) * 0.15 + (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are "dead". Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Gaps that cannot fit the lookahead item are less useful; mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward near-perfect fits (post_residual 0 is already minimal; boost it).
    if post_residual == 0 {
        score -= 15.0;
    }

    // New-bin candidate: opening a new bin wastes the residual of this bin.
    // Penalize opening when fitting bins exist, scaled by how much space
    // would be stranded and how many alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        score += 30.0 + stranded * 0.8 + (fitting_bins_count as f64) * 12.0
               + (open_bins_count as f64) * 2.0 * (0.5 + progress);
    } else {
        // Slight preference for bins with larger residuals (keep tight bins
        // for later, spread load), scaled by open-bin pressure.
        score -= 0.05 * bin_residual as f64;
        // Last-chance bin: if this is the only bin that fits, strongly favor
        // using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Penalize leaving residual that is close to but below the next item
        // size when many bins are open (fragmentation risk).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size + 3 {
            score += 5.0 * (open_bins_count.min(20) as f64) / 20.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below the
    // mean (i.e., tighter bins) when the item fits well — encourages filling
    // nearly-full bins first.
    score += 0.10 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial lookahead: how close post_residual is to next_item_size (relative).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.35 * gap;
        // If next item fits exactly into the gap band, mild bonus.
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Penalize tiny unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare residual against mean residual: prefer bins with less residual (tighter packs)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in stream: conserve bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Prefer placing into nearly-full bins (small residual) when fit is good.
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 100.0 * 0.0; // neutralized
    score += 0.15 * post_residual as f64 * (1.0 - progress);

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space), non-linear.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(3);

    // Exact or near-exact fill is extremely valuable.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item would then fit snugly too.
        let next_leftover = post_residual - next_item_size;
        if next_leftover < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a small gap the next item cannot use (dead space).
        score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize new empty bin slightly so it's chosen only when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is large relative to capacity, a fresh bin is more attractive.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // Late in the stream, fewer open bins -> cheaper to consolidate; early on new bins are fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins with smaller residuals (compact them) over large-residual bins.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild pressure to reduce number of open bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear sharpening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear penalty for "awkward" residuals: mid-range dead space is worst
    let dead = norm_pr * (1.0 - norm_pr);
    score += 18.0 * dead * (0.5 + progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: reward residuals that can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_margin = 1.0 - ((pr - nxt) / cap);
            score -= 10.0 * fit_margin * (1.0 - progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild reward for consolidating into bins below mean residual (tight bins first)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight penalty proportional to open bins, encouraging reuse over sprawl
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues that are "nice"
    // (multiples of common item sizes / small classes) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best outcome
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 22.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Harmonic class bonus: post_residual divisible by common item classes
    // (10, 20, 25, 50) tends to admit future items exactly.
    let hbonus = if post_residual % 50 == 0 {
        12.0
    } else if post_residual % 25 == 0 {
        8.0
    } else if post_residual % 20 == 0 {
        6.0
    } else if post_residual % 10 == 0 {
        4.0
    } else {
        0.0
    };
    score -= hbonus;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this leftover: penalize large dead space
            score += 0.15 * pr * (1.0 - (step_index as f64 / total_items.max(1) as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // this bin is a poor fit or the stream is nearly done.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a fresh bin scaled by how many bins are already open.
        score += 40.0 + 2.0 * open_bins_count as f64;
        // If other bins fit, only prefer a new bin when mean residual is huge
        // (all open bins are fragmented) — otherwise it should lose.
        if fitting_bins_count > 0 {
            score += 0.3 * mean_residual;
        }
        // Late in the stream, fewer future items: new bin less costly.
        score -= 15.0 * progress;
        // Large items prefer fresh bins.
        score -= 0.2 * item_size as f64;
    } else {
        // Prefer filling bins with larger residuals when fragmentation is low.
        score -= 0.05 * bin_residual as f64;
        // Slight preference for bins below mean residual (balance avoidance
        // of many half-empty bins).
        score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Non-linear penalty for mid-range leftovers (harmonic "dead zone" classes).
    let cls = post_residual % 30;
    if cls > 12 && cls < 22 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable gaps (< 10% of capacity): dead space
    let dead_threshold = (bin_capacity as f64 * 0.1).floor();
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += 60.0 + (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward placements that leave space usable by the next item (lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64 * 0.5) {
        // leaves a gap too small for next item
        score += 20.0;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open bins pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate gets penalized when many bins are open)
    if bin_residual == bin_capacity {
        // New bin candidate: base cost of opening a fresh bin
        score = bin_capacity as f64 * 0.9;
        score += open_bins_count as f64 * 8.0;
        // Early in stream, opening bins is cheaper; late, avoid it
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
        // If only one bin fits and its fit is bad, new bin becomes attractive
        if fitting_bins_count == 1 && post_residual > 0 && (post_residual as f64) <= dead_threshold {
            score -= 80.0;
        }
    } else {
        // Existing bin: slight bonus when it's the only fitting bin (avoid new bin)
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Prefer bins with residual below mean (consolidate fullness)
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
        // Many open bins: favor filling existing ones aggressively
        score -= open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the post-residual: good chaining
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Tighter chain match rewarded more
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize unusable leftover space
        score += 10.0;
        if post_residual < 10 {
            score += 6.0; // tiny dead space is bad too
        }
    }

    // Tight fit now (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: bins with below-mean residual are more "spent",
    // prefer packing into them to close them out
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless nothing else is decent
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host a good pair
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, must open
        }
    }

    // Late in stream: consolidate aggressively, avoid leftover fragments
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already rewarded).

    // Penalize dead space that can never be reused by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item can still go here: mild reward proportional to leftover after next
            score -= 5.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item cannot fit here: penalize by how far off we are
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is generally costly; penalize unless this is a last-chance
        // situation (no open bin fits) or the fit elsewhere would be terrible.
        score += 20.0;
        // Late in the stream, avoid proliferation of barely-used bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If many bins are already open, prefer consolidating into one.
        score += open_bins_count as f64 * 1.5;
        // But if no open bin can fit (fitting_bins_count == 1 and this is the empty bin),
        // the penalty stands so the empty bin is chosen anyway.
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big items coming: fresh bin is fine
        }
    }

    // Prefer bins whose residual is already below average (consolidation of waste).
    let residual_diff = bin_residual as f64 - mean_residual;
    score += residual_diff * 0.15;

    // Slight preference for filling bins with larger residual early on,
    // keeping tight bins flexible: mild non-linear coupling.
    if bin_residual > 50 {
        score -= 2.0;
    }

    // Small time-horizon nudge: near the end, just minimize post_residual aggressively.
    if total_items > 0 && step_index + 1 >= total_items {
        score = post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, modulated by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear coupling: quadratic dead-space penalty weighted by progress.
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic interaction: large residuals late in the stream become costly dead space.
    score += 20.0 * norm_pr.powi(3) * progress;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward residuals that can still hold the next item.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 8.0 * fits_next * (1.0 - gap);
        score += 6.0 * gap * (1.0 - fits_next) * (0.5 + progress);
    }

    // Slight preference for tighter bins relative to mean residual.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor,
    // with penalty easing late in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes mod small integers.
    let pr = post_residual;
    let mod5 = (pr % 5) as f64;
    let mod10 = (pr % 10) as f64;
    let mod20 = (pr % 20) as f64;

    // Reward post-residuals that sit in "usable" residue classes (multiples of 10/20),
    // since future items (1..100) more often leave re-packable slack.
    score -= (10.0 - mod10) * 0.4;
    score -= (20.0 - mod20) * 0.25;
    score -= (5.0 - mod5) * 0.1;

    // Integer-division thresholds: small post-residuals are near-perfect fits.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 30.0;
    } else if pr <= 20 {
        score -= 12.0;
    } else if pr <= 30 {
        score -= 4.0;
    }

    // Tightness ratio coupling.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= tight * 15.0;

    // Lookahead: reward if next item fits exactly in the post-residual (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            let npr = pr - next_item_size;
            score -= 8.0 - ((npr % 10) as f64) * 0.3;
        } else {
            // next item won't fit here; slight penalty for wasting big residual
            score += (next_item_size - pr).min(30) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += ((post_residual as f64) - mean_residual) * 0.2;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 0.0 }
            else if fitting_bins_count == 1 { 35.0 }
            else { 70.0 };
        // Penalize new bin; relax penalty late in stream when open bins are fragmented.
        score += desperation * (1.0 - 0.3 * progress) + 5.0;
        // A new bin's post_residual = cap - item; if item is huge, new bin is actually fine.
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

