    score -= 15.0 * tightness;

    // Penalize bins that are already very full relative to capacity (waste risk).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += 8.0 * fill_ratio * fill_ratio;

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: prefer compacting into existing bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean residual (keeps spread small).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if the next item would fit exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., current bin is the fresh candidate and many bins are open with large residuals).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins mildly; slightly less later in the stream.
        score += 30.0 - 10.0 * progress;
        // If several bins already fit, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 12.0 * fitting_bins_count as f64;
        }
        // If the item is large, a fresh bin is more acceptable.
        score -= 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

