    // Perfect chain bonus: next item exactly consumes post_residual
    if next_item_size == post_residual && next_item_size > 0 {
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins already below-average residual (consolidation)
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening new bins as stream progresses / many bins open
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (step_index as f64 / total_items as f64)
            + 0.5 * open_bins_count as f64;
        // But allow new bin if next item is large and no good fit exists
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 8.0;
        }
    }

    // Late stream: tighten packing further
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
