    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Global state coupling: penalize spreading across many open bins when mean residual
    // is high (bins are fragmented); reward consolidating into bins below mean residual.
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev;
    }

    // New-bin candidate handling: empty bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if item is large and current bins are crowded.
        let large_item = item_size as f64 / cap;
        let crowding = (mean_residual / cap).max(0.0);
        let penalty = 20.0 + 40.0 * (1.0 - large_item) + 30.0 * crowding;
        score += penalty;
        // Late in the stream with many open bins, opening a new bin is even less attractive.
        if open_bins_count > 2 {
            score += 10.0 * progress;
        }
        // But if no open bin fits well (this is a fallback call anyway), the base score
        // naturally competes; large items with high crowding get relief above.
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.8 && large_item < 0.5 {
            score += 15.0; // save space for a big upcoming item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer small post residual (tight fits) with non-linear shaping
    let mut score = 3.0 * post + 40.0 * norm_post * norm_post;

    // Smooth coupling: tight fits matter more late in the stream
    score -= 60.0 * (1.0 - norm_post).powi(3) * (0.5 + progress);

    // Penalize large dead space super-linearly (unusable slack)
    if post < 10.0 {
        score += 0.0;
    } else {
        score += 0.15 * post * (post / cap);
    }

    // Lookahead: reward bins whose post residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_ratio = (post - nxt) / cap;
            score -= 25.0 * (1.0 - slack_ratio).powi(2);
        } else {
            score += 15.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 + progress);
    }

    // Mean residual context: prefer bins below mean residual (tighter than average)
    score += 8.0 * ((post - mean_residual) / cap).abs() * ((post - mean_residual).signum());

    // New empty bin candidate: penalize unless it enables a near-perfect fill
    if bin_residual == bin_capacity {
        let perfect = (cap - item_size as f64) / cap;
        score = 120.0 - 90.0 * (1.0 - perfect).powi(2) - 30.0 * progress;
    }

    // Mild open-bin pressure: encourage consolidation early, allow spread late
    score += 2.0 * open_bins_count as f64 * (1.0 - progress) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Harmonic class of post_residual: dead space in low classes is worse
    let class = (post_residual / 10) as f64;
    score += class * class * 2.0;

    // Penalize small unusable remainders that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this bin strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item won't fit here; penalize leaving awkward gap
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened when many items remain
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 40.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can host next item too
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative, new bin is fine
        }
    }

    // Prefer tighter bins among comparable fits
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Mean residual coupling: if open bins are generally loose, slightly prefer filling this one
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Dead space threshold: gaps below ~10 (min item size) are unusable.
        if pr < 10.0 {
            score += (10.0 - pr) * 12.0;
        } else if pr < 20.0 {
            score += (20.0 - pr) * 4.0;
        }
        // Non-linear penalty for mid-size gaps that few items can fill.
        score += 30.0 / (1.0 + (pr / 15.0).powf(2.0));
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bin pressure: discourage spreading across too many bins,
    // but allow opening a new bin when current fits are poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score += pressure * 0.15;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // existing residuals are large/fragmented relative to the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Compare mean residual to item; if mean residual is much larger
        // than item size, existing bins are roomy -> opening new bin is fine.
        let roominess = mean_residual / (item_size as f64 + 1.0);
        if roominess > 2.5 {
            score -= 15.0;
        } else {
            score += 18.0;
        }
        // If next item is large, prefer keeping small residual bins for it.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if this placement leaves a gap fitting the next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base preference: tight fits (small post_residual) are good.
    score -= 40.0 / (post_residual as f64 + 4.0);

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (gap + 3.0);
        // Perfect chain: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize leaving residual too small for next item (dead space).
        if post_residual > 0 && post_residual < next_item_size.min(10) {
            score += 25.0;
        }
        // Penalize large unusable residual relative to next item.
        if post_residual > next_item_size * 2 {
            score += (post_residual - next_item_size * 2) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate: default penalty so we only open when existing fits are bad.
    if is_new_bin {
        score += 20.0;
        // Early in stream, opening bins is cheaper (build flexibility).
        score -= (1.0 - progress) * 25.0;
        // If many open bins and current fit is terrible, new bin relatively better.
        if post_residual > 60 {
            score -= 10.0;
        }
    } else {
        // Slight preference for reusing bins over opening new ones.
        score -= 5.0;
    }

    // Penalize creating very small residuals (wasted slivers) more strongly later in stream.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 + progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.18 * next_item_size as f64;
        } else {
            // penalize dead space that blocks the lookahead item
            score += 0.08 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening another bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0 + 22.0 * progress;
    }

    // New-bin candidate: usually penalized when open bins exist,
    // but allowed if this item would leave near-zero usable space elsewhere.
    if is_new_bin && open_bins_count > 0 {
        score += 24.0 + 0.35 * mean_residual;
        if post_residual <= 5 {
            score -= 45.0;
        }
    }

    // Tight-fit reward for existing bins (small post-residual is good packing).
    if !is_new_bin && post_residual < 10 {
        score -= 6.0 + 0.5 * (10 - post_residual) as f64;
    }

    // Mild dispersion penalty: prefer residuals near the global mean state.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Late-stream consolidation: favor filling existing bins as stream ends.
    if progress > 0.8 && !is_new_bin {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fits).
    let mut score = post;

    // Smooth non-linear coupling: quadratic penalty on wasted space, modulated by stream progress.
    // Early in the stream, waste matters less (bins can be reused later); late, waste is costly.
    let waste_norm = post / cap;
    let progress_coupling = 0.5 + 1.5 * progress;
    score += 40.0 * waste_norm * waste_norm * progress_coupling;

    // Penalize large post-residual that cannot fit the lookahead item (dead space for next item).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt && post > 0.0 {
            // Smooth penalty proportional to how close the dead space is to being useful.
            let dead_frac = 1.0 - post / nxt;
            score += 25.0 * dead_frac * dead_frac * (0.4 + 1.2 * progress);
        } else if post >= nxt {
            // Reward bins whose residual can host the next item (chain-packing bonus).
            let chain = post / cap;
            score -= 15.0 * chain * (1.0 - chain) * 4.0;
        }
    }

    // Last-chance bin: strongly reward using it, else a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New empty bin candidate: penalize mildly so open bins are preferred unless fits are terrible;
    // but reward opening a new bin early in the stream (keeps future flexibility).
    if bin_residual == bin_capacity {
        score += 12.0 - 20.0 * (1.0 - progress) * (1.0 - progress);
        // Extra penalty if a decent-fitting open bin exists (post_residual small).
        if post > cap * 0.5 {
            score += 8.0;
        }
    }

    // Slight reward when bin residual is close to mean residual (balanced packing),
    // smooth sinusoidal-free polynomial term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild preference for filling fuller bins: subtract based on fill fraction squared.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 20.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but dead space that is
    // unusable for typical small items is worse than moderately-sized gaps.
    if post_residual > 0 {
        // Penalize dead space quadratically, scaled by fraction of capacity.
        let frac = post_residual as f64 / cap;
        score += 40.0 * frac * frac;
    }

    // Harmonic class of the post_residual modulo small integers:
    // residuals that are "nice" multiples (divisible by 5 or 10) tend to be
    // re-fillable by future items; odd/prime-ish gaps are less reusable.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else if post_residual % 2 == 1 {
        score += 3.0; // odd gaps are awkward
    }

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the resulting
    // gap, this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        score -= 12.0;
        if gap_after_next == 0 {
            score -= 15.0;
        } else if gap_after_next % 10 == 0 {
            score -= 6.0;
        }
        // Penalize if next item would leave a tiny unusable sliver.
        if gap_after_next > 0 && gap_after_next < 10 {
            score += 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: it becomes dead space unless a
        // small item later arrives. Penalize proportionally.
        score += 6.0 + 0.3 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // bad fit unless the fit is actually decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual as f64 <= cap * 0.2 {
            score -= 10.0; // good fit in the only option: take it
        } else {
            score += 8.0; // poor fit in the only option: consider new bin
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no open bin offers a reasonable fit.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score = 55.0;
        // Cheaper to open a bin when few are open (early stream) or when
        // mean residual across open bins is high (open bins are full-ish).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        score -= 0.2 * mean_residual;
        if open_bins_count == 0 {
            score -= 60.0;
        }
        // If the current item itself is large, a fresh bin is attractive.
        if item_size >= 50 {
            score -= 10.0;
        }
        // Lookahead: a new bin can host both current and next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    } else {
        // For existing bins, scale preference by how full the bin already is:
        // prefer filling nearly-full bins (best-fit with consolidation).
        let used_frac = (bin_capacity - bin_residual) as f64 / cap;
        score -= 10.0 * used_frac;
    }

    // Mild penalty on spreading across many open bins when a tight option exists.
    if open_bins_count > 3 && post_residual > 20 {
        score += 0.5 * ((open_bins_count as f64).ln());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..10)
    // can use are pure waste. Penalize tiny unusable gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last chance before opening a new bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer reusing existing bins,
    // penalize opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the item is large or fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a bin; offset by lookahead benefit.
        score += 15.0 - large_item * 12.0;
        if next_item_size > post_residual && next_item_size > 0 {
            // Next item can use the fresh bin's large residual.
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual cannot hold the next item: mild penalty proportional
        // to how far off it is (dead space relative to lookahead).
        let gap = (next_item_size - post_residual) as f64;
        if gap < 20.0 {
            score += gap * 0.8;
        }
    }

    // Mean residual coupling: bins far from the mean residual are either
    // nearly full (good) or awkwardly large; prefer bins below mean residual
    // (i.e., more filled).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: leave exactly room for next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post-residual can hold next item comfortably (tight-ish fit for next too).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Dead space: small but unusable leftovers are bad.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0 * (1.0 - post_residual as f64 / 40.0).max(0.0);
    }

    // Prefer bins tighter than the mean residual (fill crowded bins first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins slightly.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: only attractive when the item fits poorly here anyway
    // (i.e., placing would leave a large post residual relative to capacity).
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual <= next_item_size {
            score += 20.0; // fresh bin pairs well with next item too
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that likely cannot be reused: residuals below 10.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / (bin_capacity as f64));
    }
    // If next item does not fit here but this is the only fitting bin, prefer using it.
    if next_item_size > post_residual && fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Last-chance bonus: when this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.25 * (item_size as f64);
    }

    // New-bin candidate handling: mildly discourage opening a new bin when
    // open bins exist and mean residual is large enough to absorb the item.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let absorbable = mean_residual / (item_size as f64);
            score += 8.0 + 10.0 * (1.0 - absorbable.min(1.0));
        } else {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be more conservative about wasting
    // space (long future); late in the stream, prefer quick placements.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean residual:
    // placing into below-average-residual bins keeps large holes available.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score -= 5.0 * dev;

    // Mild penalty for proliferation of open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_frac = post / cap;

    // Base: prefer small post residual, with non-linear sharpening.
    let mut score = post + 40.0 * residual_frac * residual_frac;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger leftovers (future items can use them);
    // late in the stream, penalize dead space progressively harder.
    let progress_coupling = 1.0 + 1.8 * progress * progress + 1.2 * progress;
    score *= progress_coupling;

    // Non-linear penalty on large leftover relative to mean residual across bins:
    // a bin whose post residual diverges from the mean creates awkward future fits.
    let mean_gap = (post - mean_residual) / cap;
    score += 25.0 * mean_gap * mean_gap;

    // Tight-fit reward: smooth polynomial bonus as post residual approaches zero.
    let tightness = 1.0 - residual_frac;
    score -= 30.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly reward using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // mild preference for bins among many options that still fit tightly
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate (empty bin): post_residual == cap - item_size and residual == cap.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin; escalate penalty with stream progress and
        // when other fitting bins exist, so new bins are only chosen for poor fits.
        let mut new_penalty = 55.0 + 45.0 * progress;
        if fitting_bins_count > 1 {
            new_penalty += 30.0;
        }
        // If the item leaves a large usable chunk in the new bin, soften penalty slightly.
        new_penalty -= 10.0 * (residual_frac - 0.5) * (residual_frac - 0.5) * 4.0;
        score += new_penalty;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 35.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            // Next item slightly larger than leftover: mild penalty for near-miss dead space.
            score += 12.0 * (gap / cap);
        }
    }

    // Slight penalty for proliferating open bins late in the stream.
    score += 0.4 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals in "usable" bands
    // (residuals that common item sizes 10..80 can still fill later).
    let pr = post_residual;
    let band = match pr {
        0 => 0.0_f64,                 // perfect fit — best possible
        1..=9 => 0.0,                 // tiny dead space, nearly perfect
        10..=20 => -6.0,              // very reusable by small items
        21..=33 => -3.0,              // moderately reusable
        34..=50 => 2.0,               // awkward middle zone
        51..=66 => -4.0,              // reusable by mid items
        67..=80 => 1.0,               // only fits small items
        _ => 5.0,                     // >80: near-full, mostly dead
    };
    score += band;

    // Modulo-10 harmonic: residuals divisible by 10 pair cleanly with
    // the decimal item grid; reward alignment.
    if pr % 10 == 0 && pr > 0 {
        score -= 2.5;
    }
    // Penalize odd residuals slightly (harder to fill exactly).
    if pr % 2 == 1 && pr > 0 {
        score += 1.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 4.0 + (pr - next_item_size) as f64 * 0.05;
        // Exact chain fit (post_residual == next size) is excellent.
        if next_item_size == pr {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // Next item cannot use this bin's leftover; mild penalty scaled
        // by how much dead space is created.
        score += (next_item_size - pr) as f64 * 0.03;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid forcing
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the current item leaves a bad post_residual in
    // every existing bin (large dead space) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = (pr as f64) > 0.35 * cap && pr > 0;
        // Empty bin starts with a base score equal to its residual;
        // subtract so it's competitive but not dominant on good fits.
        score -= 8.0;
        if bad_fit {
            score -= 6.0;
        }
        if open_bins_count == 0 {
            score -= 20.0; // must open a bin
        }
        let _ = progress;
    }

    // Mean-residual coupling: when average residual is low (bins nearly
    // full), tighten selection — prefer bins with small post_residual.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Mild late-stream tightening: waste matters more as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.10 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer filling bins tightly (low post_residual).
    let mut score = post;

    // Strict dead-space avoidance: small nonzero gaps are highly unusable.
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post) * 3.0; // dead-space penalty, strongest near 0
    }
    if post == 0.0 {
        score -= 10.0; // perfect fit reward
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) == post {
        score -= 8.0;
    }
    // If next item cannot fit in the gap, penalize slightly (dead space locked).
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins implicitly
    // by favoring existing bins; with few open bins, opening is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.4 * (1.0 - progress);

    // New-bin candidate: empty bin gets a moderate baseline so it wins only
    // when existing bins have bad fits (large post_residual / dead space).
    if bin_residual == bin_capacity {
        score = 55.0 + post * 0.0;
        score += mean_residual * 0.3; // opening a new bin is better when open bins are full-ish
        if fitting_bins_count <= 1 {
            score -= 20.0; // still avoid new bin if this is the only fitting open bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it neutral-to-slightly-high so we only open a new bin
    // when placement in existing bins is truly bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        return bin_capacity as f64 * 0.75 + mean_residual * 0.1;
    }

    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Perfect 2-step match: post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Slack that can still host the next item: reward proportionally to fit quality.
            let slack = post - next;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to the lookahead item: penalize harder as gap shrinks to 0.
            let gap = next - post;
            score += 12.0 * (1.0 - gap / 100.0);
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers of waste.
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild preference for tighter bins among many candidates.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Reward near-closure of the bin (small post_residual is good unless it's dead space).
    score -= 0.25 * (bin_capacity as f64 - post);

    // Late in the stream, prefer closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.9 * tightness * (bin_residual as f64);

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead space penalty: small residual that likely cannot host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.35 * (next_item_size as f64);
        // Perfect chain: next item exactly fills remaining space.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting large residual.
        score += 0.15 * (post_residual as f64);
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, unless many open bins
    // are nearly full or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 8.0 + 3.0 * (open_bins_count as f64).sqrt();
        // Late in stream, prefer closing out existing bins.
        new_bin_penalty += 10.0 * progress;
        // If mean residual is small (bins nearly full), opening is more acceptable.
        new_bin_penalty -= 0.05 * mean_residual;
        // If many bins can fit, definitely prefer an existing bin.
        if fitting_bins_count > 2 {
            new_bin_penalty += 12.0;
        }
        // Large items relative to capacity benefit from fresh bins.
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 6.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference for filling bins with larger residuals when many bins open
    // (consolidation pressure).
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post_residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * pr / cap) + 0.25 * (pr * pr) / cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= (1.0 + 2.0 * progress) * 8.0 * tightness * tightness * tightness;

    // Penalize large dead space quadratically, amplified late in the stream.
    score += progress * (pr * pr) / cap;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Interaction with mean residual: prefer bins tighter than average.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 2.0 * (gap / cap);
        }
    }

    // New-bin candidate: penalize opening a bin unless residuals elsewhere are large.
    if bin_residual == bin_capacity {
        let avg_fill = cap - mean_residual;
        let urgency = (it / cap) * (1.0 + progress);
        score = cap + pr - 4.0 * urgency - (fitting_bins_count as f64) * 0.5
                + if avg_fill > it { 8.0 + 8.0 * progress } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let ni = next_item_size;

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        let mut penalty = 55.0;
        // No open bin can fit: opening a new bin is mandatory-ish
        if fitting_bins_count == 0 {
            penalty -= 100.0;
        } else {
            // Opening a new bin is attractive only if the fresh residual
            // forms a harmonic pair with the lookahead item (nearly full combo)
            if ni > 0 && ni as u32 <= pr {
                let combo = pr + ni as u32;
                if combo >= bin_capacity - 5 {
                    penalty -= 60.0; // pair perfectly fills the new bin
                } else if combo % 10 == 0 && combo >= 80 {
                    penalty -= 25.0; // harmonic class pair (residual multiple of 10)
                }
            }
            // Late in the stream, avoid opening bins that waste capacity
            let progress = step_index as f64 / total_items.max(1) as f64;
            penalty += progress * 10.0;
        }
        score += penalty;
    }

    // ---- Harmonic classes on post_residual ----
    if pr == 0 {
        score -= 60.0; // perfect fill, best possible outcome
    } else {
        if pr % 10 == 0 {
            score -= 6.0; // residual in friendly class, likely reusable
        }
        if pr % 20 == 0 {
            score -= 3.0; // doubly harmonic
        }
        // Lookahead coupling: residual can host next item
        if ni > 0 && ni as u32 <= pr {
            score -= 4.0;
            if pr as i64 - ni as i64 <= 5 {
                score -= 4.0; // next item nearly fills this bin too
            }
        }
        // Dead-space penalty: tiny unusable fragments
        if pr < 10 {
            score += 10.0;
        } else if pr < 20 && ni > 0 && ni as u32 > pr {
            score += 5.0; // residual too small for lookahead
        }
    }

    // ---- Dispersion coupling with mean residual ----
    let diff = pr as f64 - mean_residual;
    if diff > 0.0 {
        score += diff * 0.04; // prefer bins tighter than average
    } else {
        score += diff * 0.02;
    }

    // ---- Last-chance bonus: sole fitting bin avoids a new bin ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: strongly favor this bin when it is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // by making the empty-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
    } else {
        // Mild reward for using existing bins as open-bin count grows.
        score -= 0.3 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Penalize if next item is close but leaves a near-dead gap.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 10.0;
    }

    // Early-stream: allow slight preference for spreading (keeps flexible residuals),
    // late-stream: tighten packing to close bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing) but avoid bins with tiny residuals relative to mean.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (small post_residual is good).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: strongly reward.
            score -= 25.0;
            // Extra reward for a near-perfect chain (post_residual ~ next_item_size).
            let chain_gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 15.0 * (1.0 - chain_gap / bin_capacity as f64).max(0.0);
        } else {
            // Next item won't fit here: penalize proportionally to wasted residual.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste;
            // Small residual that fits nothing is dead space.
            if post_residual < 10 {
                score += 30.0;
            }
        }
    } else {
        // Last item: just minimize post_residual tightly.
        score -= 10.0 * fit_ratio;
    }

    // Penalize bins far above mean residual (they hoard space); favor tight bins.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open a new bin when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Opening a new bin is more attractive when many bins are already open
        // and the current item is large (poor fit prospects elsewhere).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Slight penalty for opening too many bins overall.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward tight fits: small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: this is the only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // When several bins fit, prefer the one where item is a larger fraction of residual
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Dead space for the known next item: penalize proportionally
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize post_residual (already does)
        score -= 10.0;
    }

    // Prefer bins with below-average residual (compact the "emptiest first" effect)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, be slightly more willing to spread out (keep flexibility);
    // late in the stream, pack tightly to avoid opening bins.
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize creating very small unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless nothing decent fits.
    if bin_residual == bin_capacity {
        let base_cost = 110.0;
        // If few bins fit, or item is large relative to mean residual, new bin becomes attractive
        let desperation = if fitting_bins_count > 0 {
            (item_size as f64 / mean_residual.max(1.0)).min(2.0)
        } else {
            2.0
        };
        score = base_cost - 45.0 * desperation + 10.0 * (1.0 - progress);
        // If next item also large, a fresh bin gives flexibility
        if next_item_size >= 50 {
            score -= 15.0;
        }
        if post_residual == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Core fit term: strongly reward small post_residual, with smooth polynomial shaping.
    let post_norm = post / cap; // 0..1
    let mut score = 4.0 * post_norm * post_norm + 2.0 * post_norm;

    // Non-linear coupling: as the stream progresses, tight fits matter more.
    let tightness = 1.0 - post_norm;
    score -= progress * tightness * tightness * 3.0;

    // Penalize post_residual that neither fits the lookahead item nor is near zero (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            // dead space relative to lookahead: smooth quadratic penalty
            let gap = (nxt - post) / cap;
            score += 2.5 * gap * gap * cap / 10.0;
        } else {
            // lookahead fits: reward using this bin's residual for the next item
            let use_ratio = nxt / post.max(1.0);
            score -= 1.5 * use_ratio * (1.0 - post_norm);
        }
    } else {
        // last item: prefer minimal post_residual
        score += post_norm * 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling: opening a new bin wastes capacity; penalize,
    // but relax the penalty when existing bins would leave large dead space.
    if is_new_bin {
        let mean_gap = (mean_residual - item).max(0.0) / cap;
        let best_existing_dead = if fitting_bins_count > 0 {
            // rough proxy: mean residual minus item, normalized
            mean_gap
        } else {
            1.0
        };
        score += 6.0 - 4.0 * best_existing_dead * best_existing_dead;
        // late in the stream, prefer consolidating into open bins
        score += progress * 2.0;
    } else {
        // Mild preference for filling bins that are already small-residual (compactness).
        let res_norm = bin_residual as f64 / cap;
        score += 0.5 * (1.0 - res_norm) * (1.0 - res_norm);
        // Slight penalty when many bins are open (encourage closing bins out).
        score += (open_bins_count as f64).ln().max(0.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that pair well with
    // common item sizes (multiples of 10/20) are more reusable.
    let r = post_residual;
    let class_bonus = match r % 10 {
        0 => 12.0,
        5 => 6.0,
        _ => 0.0,
    };
    // Dead-space penalty: tiny unusable remainders.
    if r > 0 && r < 10 {
        score += 15.0;
    }
    // Exact fill is ideal.
    if r == 0 {
        score -= 30.0;
    }
    // Large post-residual means wasteful placement.
    if r > 50 {
        score += 0.35 * ((r - 50) as f64);
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 && next_item_size == r {
        score -= 25.0;
    } else if next_item_size > 0 && r >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to residual space of open bins (poor fit situation).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin when this item is huge and post-residual would
        // still be large in an existing bin.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 18.0;
        } else {
            score += 10.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let tight = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tight;

    // Mean residual coupling: when open bins are mostly full (low mean
    // residual), favor using existing bins; otherwise slight new-bin bias.
    score += 0.05 * (mean_residual - r as f64);

    // Late-stream consolidation: as the stream progresses, prefer closing
    // bins tightly rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tight;

    score -= class_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward leaving zero dead space.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: small leftover gaps are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    if post_residual > 0 && next_item_size > 0 && (post_residual as u64) < next_item_size as u64 {
        // This gap cannot host the lookahead item: penalize proportionally.
        score += 4.0 + 0.1 * (next_item_size as f64 - post_residual as f64);
    }

    // Lookahead harmony: reward gaps that exactly fit the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Deviation from mean residual: prefer bins consistent with fleet state.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Open-bins pressure: mildly favor consolidating into existing bins
    // as the number of open bins grows (larger fill => larger reward).
    score -= 0.4 * (open_bins_count as f64) * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only open bin that fits, use it
    // rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is mandatory.
            score -= 200.0;
        } else {
            // Prefer existing bins; penalty grows with open bin count.
            score += 35.0 + 1.5 * (open_bins_count as f64);
            // Late in the stream, be extra reluctant to open bins.
            if total_items > 0 {
                let progress = step_index as f64 / total_items as f64;
                score += 15.0 * progress;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let urgency = 1.0 + 2.0 * progress;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Next item can follow into this bin: reward tight chaining.
            let gap = post_residual as f64 - nxt;
            score -= 14.0 * urgency * (1.0 - gap / bin_capacity as f64);
            // Perfect chain bonus: next item exactly fills the bin.
            if post_residual == next_item_size {
                score -= 20.0 * urgency;
            }
        } else {
            // Next item cannot use the leftover: penalize dead space,
            // scaled by how badly it misses.
            let miss = nxt - post_residual as f64;
            score += 0.10 * urgency * miss;
            // Small post_residual that nothing can chain into is bad.
            if post_residual < 10 {
                score += 8.0 * urgency;
            }
        }
    } else {
        // Last item: simply prefer tightest fill.
        score -= 10.0;
    }

    // --- Relative to mean residual ---
    // Prefer bins whose residual deviates favorably from the mean:
    // a bin with small residual (tight fit) gets extra reward.
    let dev = mean_residual - post_residual as f64;
    score -= 0.05 * dev;
    // Penalize selecting a bin far above the mean residual (loose fit).
    if dev < 0.0 {
        score += 0.10 * (-dev);
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits; strongly favor using it
        // rather than opening a new bin, unless post_residual is huge.
        score -= 12.0 * urgency;
        if post_residual > bin_capacity / 2 {
            score += 6.0; // still wasteful, soften the reward
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty new bin: baseline penalty so it is only chosen when
        // no open bin offers a good (chained or tight) placement.
        score += 25.0 * urgency;
        // If the next item also fits comfortably after this one, a fresh
        // bin is more attractive (it will hold both).
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
        // Few open bins and a large item: opening fresh is fine.
        if open_bins_count <= 2 && item_size > 50 {
            score -= 15.0;
        }
    }

    // Slight preference to consolidate into fewer bins.
    score -= 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of the bin filled by this item
    let fill_frac = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: subtract proportional to how well the item fills the bin
    score -= 40.0 * fill_frac * fill_frac;

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    // Dead space that can never be used is worse than a clean near-empty bin.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_frac);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * fill_frac;
    } else {
        // Mild penalty for spreading across many bins when alternatives exist
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if the next item could use the post-residual, reward saving room
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: leftover space stays useful
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            // Bad: leftover space is too small for the next item -> dead space risk
            score += 8.0 + 0.3 * post_residual as f64;
        }
    } else {
        // Last item in stream: maximize fill aggressively
        score -= 20.0 * fill_frac;
    }

    // Global state coupling: when mean residual is high (lots of slack), prefer
    // consolidating into the emptiest bins; when tight, be more frugal.
    let mean_frac = mean_residual / bin_capacity as f64;
    score += 15.0 * mean_frac * (1.0 - fill_frac);

    // As the stream progresses, discourage opening new bins more strongly.
    // New-bin candidate detection: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, growing over time
        let new_bin_penalty = 18.0 + 45.0 * progress + 0.5 * open_bins_count as f64;
        score += new_bin_penalty;
        // But if no open bin fits well (large item, few fitting bins), relax the penalty
        if fitting_bins_count <= 1 {
            score -= new_bin_penalty * 0.9;
        }
        // Never open a new bin for a tiny item late in the stream
        if fill_frac < 0.25 && progress > 0.3 {
            score += 15.0;
        }
    }

    // Small early-stream exploration: prefer filling bins evenly at the start,
    // prefer consolidation later (via post_residual minimization which dominates).
    score += 5.0 * (1.0 - progress) * post_frac;

    // Tie-breaker noise-free deterministic jitter based on bin state to break ties
    score += (bin_residual as f64 * 0.001) % 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual (tight fit), with smooth non-linear scaling.
    let mut score = pr + 0.35 * (pr / cap) * (pr / cap) * cap;

    // Reward tight fits more strongly as the stream progresses (non-linear coupling).
    let tightness = 1.0 - pr / cap;
    score -= 18.0 * tightness.powf(2.2) * (0.5 + progress);

    // Penalize leaving dead space that the next item cannot use (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * (1.0 + progress) * (1.0 + gap);
        } else {
            // Reward residual that exactly or nearly accommodates next item.
            let fit = 1.0 - (pr - nx) / cap;
            score -= 6.0 * fit * fit;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - progress);
    } else {
        // Mild penalty for many competing bins (prefer consolidation).
        score += (fitting_bins_count as f64).powf(0.6);
    }

    // Prefer bins whose residual deviates from the mean (balance-aware, smooth).
    score += 0.12 * (pr - mean_residual).abs();

    // New-bin candidate: make it attractive only when it is genuinely better,
    // i.e., early stream or item barely fits anywhere. Otherwise keep it costly.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        score = cap - 12.0 * (1.0 - progress) * scarcity - 8.0 * (1.0 - pr / cap);
        if fitting_bins_count > 1 && progress > 0.25 {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: classify the post_residual into capacity-fraction classes.
    // Residuals in "harmonic" classes (small, near-zero waste) are strongly rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = pr / cap;

    // Non-linear waste penalty (quadratic dead-space growth)
    score += 60.0 * waste_frac * waste_frac;

    // Harmonic class reward: post_residual in {0,1,2,5,10} classes are golden fits
    let golden: [u32; 6] = [0, 1, 2, 4, 5, 10];
    if golden.contains(&post_residual) {
        score -= 25.0;
    }

    // Integer-division harmonic classes: post_residual divisible by 10 is "harmonic"
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Reward tight fits relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let nxt = next_item_size as f64;
        let exact = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (1.0 - exact / cap);
        // harmonic class match between next item and post residual
        if post_residual % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: penalize leaving a large unusable residual
        score += 0.15 * pr;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely better
    if bin_residual == bin_capacity {
        // penalize opening a new bin, more so if other bins can fit the item
        score += 35.0 + 5.0 * (fitting_bins_count as f64);
        // late in the stream, opening new bins is riskier
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // but if item is large and mean residual is small, new bin is attractive
        if (mean_residual < item_size as f64) && item_size > bin_capacity / 2 {
            score -= 45.0;
        }
    }

    // Slight preference for bins with residual close to mean (balance)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are unusable
    let min_item = 1u32;
    if post_residual < min_item * 10 && post_residual > 0 {
        score += 1000.0; // creating a tiny unusable gap is terrible
    }

    // Reward tight fits (small but usable post_residual)
    if post_residual > 0 && post_residual <= 20 {
        score -= 40.0;
    } else if post_residual == 0 {
        score -= 60.0; // perfect fill
    }

    // Penalize large leftover space when a tighter bin exists
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, prefer consolidation
    let pressure = open_bins_count as f64 * 0.3;
    if bin_residual != bin_capacity {
        score -= pressure * (item_size as f64 / bin_capacity as f64);
    } else {
        // New-bin candidate: penalize when open bins could absorb the item,
        // especially if the next item could then use the leftover
        score += 15.0 + pressure;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // new bin is fine if it can host the next item too
        }
        if mean_residual < item_size as f64 {
            score -= 30.0; // no open bin is roomy enough in aggregate -> open new bin
        }
    }

    // Lookahead: reward bins whose residual will still fit the next item
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 10.0;
    }

    // Late in the stream: tighten up, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    } else {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: residual exactly matches the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match lookahead: post_residual can host next item with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack / 10.0);
    }

    // Penalize dead space too small for any plausible future item (min size 1..=10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: bins tighter than average are attractive.
    let diff = post_residual as f64 - mean_residual;
    score += 0.35 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early stream: be conservative, prefer filling existing bins gently.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // New-bin candidate: penalize opening a bin unless it enables a great lookahead match.
    if bin_residual == bin_capacity {
        let great_fit = next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 5;
        if great_fit {
            score -= 55.0;
        } else {
            score += 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Tight-fit reward: subtract proportionally to how well the item fills the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Dead-space penalty: small post-residuals that are hard to reuse later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if the next item can fit into the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (1.0 - t);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // and when other bins already fit the item. Relax late in the stream when
    // fragmentation dominates.
    if is_new_bin {
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let base_penalty = 20.0 + 10.0 * pressure.sqrt();
        let late_relief = 8.0 * t * (mean_residual / bin_capacity as f64).min(1.0);
        score += base_penalty - late_relief;
        // Reward new bin only if it enables a very tight future pairing.
        if next_item_size > 0 && next_item_size >= post_residual.saturating_sub(next_item_size) && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Slight preference to balance residuals across open bins.
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with smooth non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.6 * x * x);

    // Dead-space penalty: small nonzero residuals are wasteful
    if x > 0.0 {
        score += 12.0 * (1.0 - x) * x * x * cap; // penalize tiny residuals smoothly
    }

    // Lookahead: reward residuals that can fit the next item, smoothly
    let ns = next_item_size as f64;
    if ns > 0.0 {
        let fit = if pr >= ns { 1.0 - (pr - ns) / cap } else { 0.0 };
        score -= 8.0 * fit * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Crowding: mild penalty when many bins are open relative to progress
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 5.0 * crowding * (0.5 + progress);

    // Mean residual coupling: prefer bins near the mean (balanced usage)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * cap;

    // New-bin candidate: neutral-ish base, penalized unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress - (fitting_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are
    // "harmonic" and likely reusable by future items; penalize awkward classes.
    let r = post_residual;
    let class = r % 10;
    if class == 0 {
        score -= 8.0; // perfectly harmonic residual
    } else if class == 5 {
        score += 2.0; // half-harmonic, mildly awkward
    } else {
        score += 4.0 + (class as f64) * 0.3; // non-harmonic dead-space risk
    }

    // Integer-division thresholds: very small residuals are wasted space.
    if r <= 10 {
        score += 6.0; // nearly dead bin
    } else if r <= 20 {
        score += 2.0;
    } else if r >= 40 {
        score -= 3.0; // plenty of room left for follow-ups
    }

    // Lookahead coupling: reward residuals that can still hold the next item.
    if next_item_size > 0 {
        if r >= next_item_size {
            score -= 5.0;
            // extra reward if next item lands harmonically too
            if (r - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: baseline cost so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 14.0;
        // opening early is worse mid-stream when many bins are open
        score += (open_bins_count as f64) * 0.5;
        // but if the item is huge relative to capacity, a fresh bin is fine
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Prefer tighter bins among many options (best-fit bias).
    score += (bin_residual as f64) * 0.05;

    // Slight stream-phase modulation: conserve capacity early, pack tight late.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * 2.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post-residuals are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving a gap that the next item cannot use (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward a residual that exactly or nearly fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // emptier bins; with few bins, prefer tight packing anywhere.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);
    score -= 0.25 * (mean_residual - post_residual as f64);

    // New-bin candidate (empty bin): only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted by how bad the
        // alternatives likely are (large item, few fitting bins).
        score += 45.0
            - 0.5 * item_size as f64
            - 8.0 * fitting_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host a sequence of large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Two-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step packing: this bin absorbs both items completely.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: moderately good, reward proportional closeness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the post-residual: penalize dead space creation,
            // scaled by how much space is wasted.
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.15 * waste;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving a post-residual well below mean concentrates waste in one bin.
    let mean_post = mean_residual - item_size as f64;
    if (post_residual as f64) < mean_post {
        score -= 5.0;
    } else {
        score += 0.05 * (post_residual as f64 - mean_post);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // can fit the item, or when the item is huge and fits nothing tightly.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Forced to open a new bin: make this the obvious choice.
            score -= 1000.0;
        } else {
            // Opening a new bin wastes the residual of existing bins; penalize
            // unless the fit in existing bins is terrible (post_residual high).
            let worst_fit = post_residual as f64 > 0.55 * bin_capacity as f64;
            if worst_fit {
                score -= 10.0;
            } else {
                score += 50.0 + 0.5 * (bin_capacity as f64 - post_residual as f64);
            }
            // Early in the stream, opening bins is cheaper (more future items to fill them).
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score -= 30.0 * (1.0 - progress);
        }
    }

    // Slight preference to fill fewer bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fills (low post_residual relative to capacity).
    score -= (1.0 - post / cap) * 8.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead (k=2): bonus if the next item can still fit in the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 7.0 + 4.0 * (1.0 - nxt / cap);
        } else {
            // leftover dead space for the known next item
            score += 3.0 + 0.05 * (nxt - post);
        }
    }

    // New-bin candidate handling: discourage opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.4 * open_bins_count as f64;
        // If very few bins can fit this item, a new bin becomes attractive.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        } else if fitting_bins_count <= 2 {
            score -= 20.0;
        }
        // Large items are risky to defer: encourage a fresh bin for them.
        score -= 0.25 * item;
    }

    // Prefer bins whose residual is below the mean (more "committed" bins).
    score += (bin_residual as f64 - mean_residual) * 0.06;

    // Time horizon: later in the stream, pack more aggressively (amplify tightness signal).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with a non-linear
    // polynomial coupling to stream progress. Early in the stream we
    // tolerate looser packing (keep flexibility); late we demand tightness.
    let base = pr * (1.0 + 1.5 * norm_pr * norm_pr);
    let progress_tilt = base * (0.5 + 2.0 * progress * progress);

    // Reward bins whose post-residual can still host the next item
    // (smooth quadratic coupling of fit margin with progress).
    let mut score = progress_tilt;
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 + 2.0 * progress) * (slack / cap) * (slack / cap) * 30.0;
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize quadratically.
        let gap = (next_item_size - post_residual) as f64;
        score += (gap * gap) / cap;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 40.0 * progress;
    }

    // New-bin candidate: mildly penalize early, allow late when open bins
    // are crowded (their mean residual is small).
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress - mean_residual * 0.15;
    }

    // Mild preference to spread load when many bins are open.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: items of size 10..80 partition
    // residuals into classes of 10. Residuals in class 0..9 (tiny) are dead
    // space; class 90..99 is nearly full (good). Penalize "middle" classes
    // that no typical item can fill exactly.
    let class = post_residual / 10;
    let class_mod = post_residual % 10;

    // Dead-space penalty: residuals below the smallest item size are wasted.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Middle classes (40..70) are the least reusable for integer sizes;
    // harmonic weighting punishes them, favors exact-fit classes.
    let harmonic_weight = match class {
        0 => 40.0,
        1 => 18.0,
        2 => 8.0,
        3 => 14.0,
        4 => 20.0,
        5 => 22.0,
        6 => 20.0,
        7 => 12.0,
        _ => 0.0,
    };
    score += harmonic_weight;

    // Reward residuals that are multiples of 10 (clean packing classes).
    if class_mod == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if it nearly fits, mild penalty for blocking.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 12.0 * (1.0 - gap as f64 / 100.0);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer filling bins that are already low on space (tight packing).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Early in the stream, tolerate opening new bins slightly more to keep
    // flexibility; late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., current bin would leave bad residual) and many bins are open.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual == bin_capacity { 0.0 } else if post_residual < 20 { 1.0 } else { 0.0 };
        score += 25.0 - 20.0 * bad_fit + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Tie-break against mean residual: prefer bins below average fill
    // (balances load) slightly.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a residual that is too small to hold any
    // plausible future item is wasted space. Penalize small-but-nonzero gaps
    // harshly (unusable slivers), with a smooth ramp.
    let min_useful = 10.0f64; // smallest practical item footprint
    let pr = post_residual as f64;
    if pr > 0.0 && pr < min_useful {
        score += (min_useful - pr) * 8.0; // sliver penalty
    }
    // Moderately small gaps (11..30) are also risky: few items fit them.
    if pr >= min_useful && pr < 30.0 {
        score += (30.0 - pr) * 0.6;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + (next_item_size as f64) * 0.1;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Open-bin pressure: mildly discourage proliferating bins when many are open.
    score += (open_bins_count as f64) * 0.15;

    // Late-stream consolidation: as the stream ends, prefer tight packing
    // of existing bins over opening fresh ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Tight-fit reward: minimize residual relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 {
        // Reward proximity of post_residual to next_item_size (soft lookahead matching).
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.4;
        // Extra reward if next item fits comfortably (post_residual >= next_item_size).
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Penalize tiny unusable dead space (< 10) relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: bins tighter than average are preferred targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, be more willing to open bins (less penalty for new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless lookahead suggests it's a good split.
        let mut new_bin_penalty = 8.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
            new_bin_penalty -= 10.0; // fresh bin can host both items well
        }
        score += new_bin_penalty * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual creates dead-space penalty.
    score += 0.35 * (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover waste
            score += 0.25 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0 + 0.3 * bin_residual as f64;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing
    // residuals are large relative to item size (poor fits elsewhere).
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // cheaper to open a new bin when open bins are already quite full on average
        score -= 0.4 * mean_residual;
        // early in the stream, new bins are more acceptable (plenty of future items)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // if item is large, a fresh bin gives best flexibility
        score -= 0.15 * item_size as f64;
        // if nothing else fits, new bin is the only option
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Mild preference for filling more-occupied bins first (best-fit bias).
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    // Time horizon: later in stream, consolidate harder (penalize spreading).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage closing them out by preferring fuller bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fill = item_size as f64 / cap;

    let mut score = pr_norm;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = 0.5 + progress;
    score += 0.35 * pr_norm * pr_norm * p;
    score -= 0.55 * pr_norm * pr_norm * pr_norm * (1.0 - progress);

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= 0.30 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.4 + progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.20 * (pr_norm - mean_residual / cap).abs() * (0.5 + 0.5 * progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 0.80 * (1.0 - pr_norm);
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if nx <= pr_norm {
            score -= 0.25 * nx * (1.0 - pr_norm + nx);
        } else {
            score += 0.25 * (nx - pr_norm);
        }
    }

    // New-bin candidate: discourage opening a bin unless the fit is poor
    if bin_residual == bin_capacity {
        score += 0.60 + 0.40 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 1.20;
        }
    }

    // Mild penalty for many open bins, encouraging consolidation
    score += 0.015 * open_bins_count as f64 * (0.3 + 0.7 * progress) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 buckets.
    let post_mod = (post_residual % 10) as f64;
    score += post_mod * 0.35;

    // Dead-space penalty: post residual too small for any item (min size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Perfect fit reward via integer division thresholds.
    let quarter = bin_capacity / 4;
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual == quarter || post_residual == quarter * 2 || post_residual == quarter * 3 {
        score -= 8.0;
    }

    // Lookahead coupling: next item must fit or bin becomes a trap.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        }
        // Harmonic class match: next item pairs well with residual mod 10 == 0.
        if post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Crowd penalty: many open bins favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.25 * (0.5 + progress);

    // Mean residual deviation: prefer bins far below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64).clamp(-20.0, 20.0) * 0.2;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted by stream progress.
        score = cap * 0.9 + progress * 10.0;
        if fitting_bins_count == 0 {
            score -= cap * 0.95; // forced new bin
        } else if fitting_bins_count == 1 {
            score += 8.0; // discourage wasting a last-chance bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps superlinearly.
    // A gap is "dead" if it's too small for the next item (or generally tiny).
    let min_useful = if next_item_size > 0 { next_item_size.min(60) } else { 10 };
    if post_residual < min_useful {
        // Dead space: heavy quadratic penalty proportional to wasted capacity.
        let dead = (min_useful - post_residual) as f64;
        score += 40.0 + dead * dead * 0.5;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    } else {
        // Usable gap: mild reward, more if next item can also fit here.
        score -= 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when several are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 18.0 + open_bins_count as f64 * 1.5;
        // But if the current bin would leave dead space anyway, relax new-bin penalty.
        if post_residual < min_useful {
            score -= 30.0;
        }
    } else {
        // Reward packing into already-open bins, scaled by stream progression.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 + 4.0 * progress;
    }

    // Prefer bins with residuals close to the item (tight fits) over loose fits.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Slight preference for bins below mean residual (balancing open bins).
    score += ((post_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits too; mildly favor this.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot use remaining space; penalize dead space creation.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    } else {
        // Last item: strongly prefer minimizing post_residual.
        score += 0.5 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins that are already fuller than average.
    let rel = (bin_residual as f64) - mean_residual;
    score -= 0.2 * rel;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin unless the fit is very tight.
    if bin_residual == bin_capacity {
        let eff = item_size as f64 / bin_capacity as f64;
        score += 45.0 * (1.0 - eff);
        // If other bins fit the item, opening a new bin is even less attractive.
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Temporal horizon: fraction of stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward last-chance bins (avoid opening new bins unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 25.0 * t;
    }

    // Penalize creating tiny dead space that likely cannot host future items,
    // but soften the penalty late in the stream when waste matters less.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - t);
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this bin (perfect pair); if next item cannot fit anywhere here,
    // slightly penalize leaving large awkward gaps.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 6.0;
        }
    }

    // New-bin candidate: opening a fresh bin is only attractive when many bins
    // fit the item (i.e. this bin is not scarce) or residuals across the fleet
    // are low. Otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let scarcity_bonus = if fitting_bins_count == 0 { 0.0 } else { 8.0 };
        let mean_gap = (mean_residual - (bin_capacity - item_size) as f64).max(0.0);
        score += 15.0 + scarcity_bonus + mean_gap * 0.3 - 10.0 * t;
    }

    // Mild preference for tighter existing bins as the fleet grows.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; later, waste becomes increasingly costly.
    let waste_penalty = post * post / cap * (0.5 + 1.5 * progress * progress);
    score += waste_penalty;

    // Cubic interaction: penalize near-full-but-unusable residuals more as stream ends,
    // since dead space late in the stream almost never gets filled.
    let unusable = (post / cap).powi(3) * cap * (0.3 + 1.7 * progress);
    score += unusable;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward preserving that perfect continuation.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= (1.0 - gap / cap) * 6.0 * (1.0 - progress);
        } else {
            // next item too big for this residual: mild penalty proportional to overflow
            score += (nxt - post) / cap * 4.0;
        }
    }

    // Mean-residual context: if this bin's residual deviates strongly below the mean,
    // it is a "crumb" bin; penalize slightly to keep residuals homogeneous.
    let dev = (post - mean_residual) / cap;
    score += dev * dev * cap * 0.25;

    // New-bin candidate (empty bin): post_residual == cap - item_size is naturally large;
    // add extra penalty so new bins are only chosen when no open bin fits acceptably.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
        // but late in the stream, consolidating is cheaper than opening bins
        score -= 20.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals in "usable" classes.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals that nothing (>=1) can usefully fill.
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Modulo-10 class logic: residuals divisible by 10 are "harmonic" — likely
    // to be exactly filled by future items (sizes 10..80 multiples of 10).
    if pr % 10 == 0 {
        score -= 8.0;
    }
    if pr % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: classify post residual into capacity fractions.
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score -= 6.0; // still roomy, good bin
    } else if frac > 0.25 {
        score -= 2.0;
    } else if frac > 0.0 {
        score += 4.0; // small residual, risk of dead space
    }

    // Lookahead coupling: if next item fits into post residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // Harmonic bonus: next item exactly fills remaining space.
        if next_item_size == pr {
            score -= 30.0;
        }
        // next item leaves another harmonic residual
        if (pr - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: mildly penalize tight residuals
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we prefer
    // reusing open bins unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.05 * open_bins_count as f64;
    }

    // Late in stream: prefer closing bins tightly, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Prefer bins tighter than the mean residual (good fill discipline).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are wasted forever.
    if post_residual > 0 {
        let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
        if post_residual < min_useful {
            // Dead space penalty: proportionally severe.
            score += 60.0 * (1.0 - post_residual as f64 / min_useful as f64);
        }
        // Post-residual that cannot fit the known next item is risky.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 25.0;
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist; encourage using existing capacity.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }
    score += 0.15 * open_bins_count as f64;

    // Pull toward mean residual state: bins far from the pack's typical
    // fullness are less attractive unless the fit is tight.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when current bins are crowded
    // or this is the last fitting bin (avoid forcing bad fits).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.25 + 20.0 * (1.0 - fill_ratio);
        let last_chance = if fitting_bins_count == 1 { 10.0 } else { 0.0 };
        // Base cost of a fresh bin, discounted when many bins are open.
        score = 55.0 - pressure.min(45.0) + last_chance;
        // Late in the stream, opening new bins is more acceptable.
        score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size,
    // penalize post_residuals that are small but useless for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let gap = post - nxt;
            // Smaller gap => better lookahead match.
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            score += 2.0 * (nxt - post);
        }
    }

    // Compare residual against mean residual of open bins:
    // prefer using bins with below-average residual (tight bins) to
    // keep large residuals available for large future items.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor filling the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a brand-new bin when open bins could fit;
    // the new-bin candidate has bin_residual == bin_capacity and post_residual
    // large, so give it an offset penalty unless it's a near-perfect fit.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 100.0;
        }
    }

    // Slight preference early in the stream to keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty reduction for very small post residuals.
    let pr = post_residual as f64;
    if pr <= 10.0 {
        score -= 25.0 * (1.0 - pr / 10.0);
    } else if pr <= 25.0 {
        score -= 8.0 * (1.0 - (pr - 10.0) / 15.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the item is large and
    // existing residuals are poor fits (mean residual far from item size).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_gap = (mean_residual - item_size as f64).abs() / bin_capacity as f64;
        let late_game = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty keeps open bins preferred; shrinks for big items / poor fits.
        let mut nb = 20.0 - 18.0 * item_frac - 15.0 * mean_gap;
        if late_game > 0.7 { nb += 5.0 * (late_game - 0.7) / 0.3; }
        score += nb.max(-2.0);
    }

    // Mild preference for filling bins with small residuals relative to fleet mean.
    score -= 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Early stream: slightly favor keeping residual flexibility (avoid over-committing).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / capacity; // normalized post residual

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let mut score = pr;
    score += 40.0 * x * x * capacity;          // super-linear penalty on large dead space
    score -= 25.0 * x * (1.0 - x) * capacity;  // reward "sweet spot" fills

    // Stream-progress coupling: later in stream, tolerate less waste
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Tight fit bonus: reward small post residual relative to item size
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 60.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening new bins
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else {
        // More competing bins -> mild penalty unless fit is excellent
        score += 2.0 * ((fitting_bins_count as f64) - 1.0).min(10.0) * (1.0 - tightness);
    }

    // Lookahead: penalize if post residual can't host the next item but could nearly
    let next = next_item_size as f64;
    if next > 0.0 {
        if pr >= next {
            score -= 15.0; // keeps bin useful for lookahead
        } else {
            score += 10.0 * (next - pr) / capacity * 100.0; // dead space relative to lookahead
        }
    }

    // Mean-residual coupling: prefer bins deviating below mean (balance loads)
    let dev = (bin_residual as f64 - mean_residual) / capacity;
    score += 8.0 * dev * dev * capacity - 5.0 * dev * capacity;

    // New-bin candidate handling: empty bin gets a moderate default so it's chosen
    // only when open-bin scores are worse (large post residuals).
    if bin_residual == bin_capacity {
        score += 0.35 * capacity + 25.0 * (1.0 - progress);
    }

    // Mild penalty for bin proliferation
    score += 0.5 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25 create
    // "usable" vs "dead" residual classes. Dead space (small nonzero residue)
    // is penalized strongly.
    let post = post_residual as i64;
    let r10 = post % 10;
    let r25 = post % 25;

    if post > 0 {
        // tiny unusable slivers are dead space
        if post < 10 {
            score += 40.0 - post as f64 * 2.0;
        }
        // residue class 1..4 mod 10 is hard to fill with items >= 10
        if r10 >= 1 && r10 <= 4 {
            score += 12.0;
        }
        // residue classes that align with common item sizes (multiples of 5/10)
        if r10 == 0 {
            score -= 8.0;
        }
        if r25 == 0 {
            score -= 6.0;
        }
        // half-capacity residuals are versatile
        let half = (bin_capacity / 2) as i64;
        if (post - half).abs() <= 5 {
            score -= 5.0;
        }
    } else {
        // perfect closure: strongly reward exact fill
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let nxt = next_item_size as i64;
        // exact or near-exact chaining is valuable
        if post == nxt {
            score -= 35.0;
        } else if (post - nxt) % 10 == 0 {
            score -= 18.0;
        } else if post - nxt >= 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: residual is dead for the lookahead
        score += 15.0;
        if post > 0 && post < 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap_f * 0.9;
        // opening a bin is good if no bin fits or fit would leave dead space
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else if fitting_bins_count == 1 {
            // prefer using the last fitting bin instead of a new one
            score += 20.0;
        }
        // early in stream: fewer open bins, opening is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // large item into fresh bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Tight fit reward: fraction of bin consumed
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 20.0;

    // Spread pressure: many open bins -> prefer consolidating into tight fits
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * (post_residual as f64 / cap_f) * 3.0;
    }

    // mean residual coupling: if mean residual is high, favor bins below mean
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small nonzero gaps are hard to fill later.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 20 {
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: prefer existing bins when many are open;
    // allow opening a new bin when few bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize slightly so it only wins when
        // all open bins are poor fits; reduce penalty late in stream.
        score += 18.0 + 12.0 * (1.0 - progress);
    } else {
        score -= bin_pressure.min(20.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: if this bin's residual is far below average,
    // it is an outlier; packing it normalizes the residual distribution.
    let res_diff = mean_residual - bin_residual as f64;
    score += 0.08 * res_diff;

    // Lookahead: if next item could use the post residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless current bin fits badly.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Reward opening a new bin if no other bin fits or fit is terrible.
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
        return score;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to tightness of chain fit.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving residual that blocks it.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative-to-mean residual adjustment: prefer bins with residual close to item.
    let diff = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.3 * diff;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Slight bias toward tighter fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good, but emphasize closeness).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that nothing useful can fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < item_size.min(80) {
        // residual could still fit some future item — mild bonus
        score -= 8.0;
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    // unless the fit is terrible (post_residual huge relative to capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        if waste < 0.4 {
            score -= 40.0;
        } else {
            score += 15.0 * waste; // poor fit in only bin -> maybe open new bin instead
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is expensive; penalize unless current alternatives are bad.
        score += 12.0;
        // But if next item is large and this item is small, deferring is good:
        if next_item_size > 0 && next_item_size > item_size && item_size < 30 {
            score -= 10.0;
        }
        // Late in the stream, avoid opening bins that will stay nearly empty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    } else {
        // Existing bin: reward filling bins that are already partially used,
        // especially bins with low residual (consolidation).
        let closeness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * closeness;
    }

    // Lookahead coupling: if the post-residual exactly accommodates the next item,
    // this is a great chaining placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual > 0 {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        }
        // If placing here leaves residual that cannot fit next item but other bins could take next,
        // slight penalty for fragmenting.
        if post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
    }

    // Global state: many open bins -> prefer consolidation (reward using existing bins).
    let open_norm = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    if !is_new_bin {
        score -= 5.0 * open_norm.min(2.0);
    }

    // Mean residual coupling: if mean residual is large, bins are loose —
    // be pickier about tight fits; if mean residual is small, take any decent fit.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.05 * mean_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic coupling of post_residual with stream progress.
    // Early on, larger residuals are more acceptable (future items can fill them);
    // late in the stream, dead space is penalized more heavily.
    let mut score = pr * (1.0 + 0.9 * progress) + 0.004 * pr * pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating term.
    score -= 8.0 * (-pr / 12.0).exp();

    // Lookahead: if the next item fits the resulting residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (pr - nxt) / cap).max(0.0);
        } else {
            // Next item won't fit: penalize creating a bin that strands the lookahead.
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many open bins
    // could have fit and how much residual capacity would be wasted elsewhere.
    if bin_residual == bin_capacity {
        let waste = mean_residual / cap;
        score += 12.0 + 6.0 * (1.0 - waste) * (1.0 - progress);
    } else {
        // Slight preference for bins with residual close to the item (best-fit flavor)
        // via smooth deviation term.
        let dev = (bin_residual as f64 - item_size as f64) / cap;
        score += 2.0 * dev * dev;
    }

    // Mild diversity pressure: many open bins -> prefer consolidating into fuller bins.
    score += 0.15 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small residue" classes are more likely to be closed out usefully.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals that are tiny but unusable are bad.
    if post_residual > 0 {
        // Modulo-10 harmonic class: residuals in [1..9] are hard to fill.
        let class = post_residual % 10;
        if class > 0 {
            score += (10 - class) as f64 * 0.8; // penalize awkward residues
        } else {
            score -= 3.0; // residual divisible by 10 is a "harmonic" slot
        }
    } else {
        score -= 8.0; // perfect fill
    }

    // Reward tight fits: post_residual small relative to capacity.
    score -= (1.0 - post / cap) * 15.0;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain harmonic).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // integer-division threshold: how many next-items fit
            let k = (post_residual / next_item_size.max(1)) as f64;
            score -= k * 2.5;
            // penalize leaving a residue awkward for the next item
            let after = post_residual - next_item_size;
            if after > 0 && after < 10 {
                score += 4.0;
            }
        } else {
            score += 5.0; // next item won't fit here; residual may be stranded
        }
    } else {
        // last item: just close bins tightly
        score -= post * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, prefer it strongly
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when open
    // bins fit poorly. Penalize the fresh bin by its (large) residual,
    // but relax the penalty when many bins are open and mean residual is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (open_bins_count as f64) * (mean_residual / cap);
        score += 30.0 - congestion * 2.0 - progress * 5.0;
        // If next item is large, a fresh bin is attractive
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference to spread load when many bins are open with high residual.
    if post > mean_residual {
        score += (post - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - post) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead space is the worst outcome
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making the new-bin candidate less attractive.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: fresh bin has full residual, but penalize
        // opening new bins, more so when many bins are already open.
        score += 35.0 + 4.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // If next item would fit nicely in the leftover, opening is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Existing bin: mild bonus to keep bin count low.
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins with residual close to what we consume (avoid wasting big bins on small items).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), best-fit style.

    if next_item_size > 0 {
        // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Post residual can still hold the next item: mild reward proportional to slack.
        else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        }
        // Next item cannot follow: penalize dead space, worse if post_residual is small-but-nonzero.
        else {
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.35 * gap;
        }

        // Coupling with mean residual: bins already crowded relative to the mean
        // are good consolidation targets; sparse bins are penalized.
        let resid_f = bin_residual as f64;
        if resid_f < mean_residual {
            score -= 0.10 * (mean_residual - resid_f);
        } else {
            score += 0.05 * (resid_f - mean_residual);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (residual == capacity): discourage unless it looks genuinely better.
    // Its raw post_residual is already high; add a fixed opening penalty.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Late in the stream, tighten up: favor closing bins out (small post_residual matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual close to 0 is good.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score += tight * tight * 60.0;

    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Penalize large dead space that small future items could still use poorly.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0; // awkward sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 45.0 * (1.0 - next_tight);
    }
    // If next item cannot fit in post residual but could fit current residual,
    // mildly penalize consuming space the next item needs.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 25.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Default penalty: prefer existing bins when they fit reasonably.
        score += 120.0;
        // But if no open bin fits (this is the only fitting candidate), opening
        // is necessary: remove penalty.
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
        // Late in the stream, avoid leaving many scattered open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && open_bins_count > 3 {
            score += 30.0;
        }
    }

    // Global state: when mean residual is high, prefer bins that reduce spread
    // (place into bins with residual near item_size).
    let dev = (bin_residual as f64 - item_size as f64).abs();
    score += dev * 0.15;

    // Mild preference for bins with residual below mean (consolidate fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Early stream: be slightly exploratory, keep bins flexible (prefer larger post residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_post = post / cap;

    // Base: prefer minimal post residual, with a smooth convex (quadratic) coupling
    // so small dead space is only mildly penalized but large dead space heavily so.
    let mut score = post * (1.0 + norm_post * norm_post * 2.0);

    // Smooth stream-progress coupling: late in the stream, tighten up on waste.
    score *= 1.0 + 0.5 * progress * norm_post;

    // Tight-fit reward: smooth gaussian-like bump when post residual is small.
    let tightness = (-norm_post * norm_post / 0.02).exp();
    score -= 8.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward leaving a residual that can still host the next item,
    // penalize residuals that strand the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 4.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate handling: make an empty bin moderately attractive only when
    // the item would leave a lot of dead space everywhere (high mean residual spread).
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item).max(0.0) / cap;
        // Opening a new bin is favored if existing bins would waste a lot and
        // this placement yields a large, reusable residual.
        score = post * (1.0 + 0.3 * progress) - 6.0 * mean_gap;
        // Slight inertia against proliferating bins.
        score += 0.4 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid near-zero useless slivers
    if post_residual > 0 {
        // harmonic-style penalty on residual classes
        let cls = post_residual / 10; // integer division threshold classes
        score -= 8.0 / (cls as f64 + 1.0);
        // dead space penalty for very small unusable residuals
        if post_residual < 10 {
            score += 6.0;
        }
    } else {
        score -= 12.0; // perfect fit
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 4.0; // dead space can't host next item
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should be penalized unless
    // no open bin fits well (large mean residual spread or many open bins)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 30.0 + 20.0 * (1.0 - progress);
        // penalize new bin more when many bins are open and mean residual is high
        let pressure = open_bins_count as f64 * 0.5 + mean_residual * 0.2;
        score = base + pressure;
        // if next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 12.0;
        }
    }

    // Mild penalty for leaving residual far from modular-friendly values (multiples of 10)
    let mod_pen = (post_residual % 10) as f64;
    if mod_pen > 0.0 && post_residual < 40 {
        score += mod_pen * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post_residual gaps are nearly unusable
    // (items are >= 10 in the classic regime, so gaps < 10 are pure waste).
    let min_item = 10u32;
    if post_residual < min_item && post_residual > 0 {
        score += 120.0 + (min_item - post_residual) as f64 * 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin size: small residual fraction preferred.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // If the next item fits exactly in the post-residual, big reward
    // (perfect chaining), otherwise penalize leaving a gap the next item
    // barely misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item cannot use this gap: dead space likely
            score += 25.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; mild linear + quadratic pressure.
    let ob = open_bins_count as f64;
    score += ob * 1.5 + ob * ob * 0.05;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // in existing bins is poor. Penalize the empty-bin candidate moderately;
    // the dead-space penalties above can override it.
    if bin_residual == bin_capacity {
        score += 35.0;
        // but if item is large relative to capacity, new bin is natural
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier worth filling; if far above, deprioritize slightly.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.4;

    // Slight late-stream conservatism: as the stream progresses, tighten
    // packing to avoid accumulating many half-empty bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but cap the raw signal.
    score = post_residual as f64 * 0.6;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 {
        let exact = (post_residual as i64 - next_item_size as i64).abs();
        if exact == 0 {
            score -= 40.0;
        } else {
            // Graduated lookahead penalty: the further next_item_size is from
            // post_residual, the worse this bin looks as a 2-step partner.
            let mismatch = if (post_residual as i64) < (next_item_size as i64) {
                // next item cannot fit here -> dead space risk
                (next_item_size as f64 - post_residual as f64)
            } else {
                (post_residual as f64 - next_item_size as f64) * 0.5
            };
            score += mismatch * 0.35;
        }
    }

    // Reward bins whose residual is close to the mean (keep pool balanced),
    // penalize outliers that create fragmented dead space.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item fits very poorly everywhere else (huge post_residual elsewhere)
    // or no lookahead match exists. Make the empty bin moderately expensive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 45.0 + 20.0 * progress;
        // If the next item is large, a fresh bin has good future pairing value.
        let lookahead_discount = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64) * 18.0
        } else {
            0.0
        };
        score = base - lookahead_discount;
    }

    // Small tie-breaker favoring fuller bins (less total residual waste).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: penalize opening a new bin unless
    // the item fits badly everywhere else.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If several bins can fit the item, strongly discourage a new bin.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // Large lookahead item: a fresh bin preserves flexibility, small relief.
        if next_item_size >= 60 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferation of bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        return score;
    }

    // Reward tight fits: small post-residual is already the base; add a
    // superlinear bonus when the bin becomes nearly full.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Penalize creating dead space that no typical item could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // perfect waste (nothing fits in <10 anyway)
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for stranding capacity.
        score += 2.0;
    } else if next_item_size > 0 {
        // Next item fits: prefer leaving a residual close to next_item_size.
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if mean_residual > 0.0 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * spread;
    }

    // Time horizon: early in the stream, be more conservative (favor filling
    // existing bins well); late, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled by smooth progress-dependent polynomial
    let mut score = pr * (0.5 + 0.9 * progress * progress);

    // Non-linear coupling of normalized post-residual with progress
    score += 30.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 25.0 * norm_pr * progress * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / (cap * cap) * 100.0;

    // Lookahead coupling: reward residual that can still fit next item, smoothly
    let ns = next_item_size as f64;
    if ns > 0.0 {
        let fits_next = if pr >= ns { 1.0 } else { 0.0 };
        let tight = (ns / cap).powi(2);
        score -= 18.0 * fits_next * (1.0 - tight) * (0.4 + 0.6 * progress);
        score += 10.0 * (1.0 - fits_next) * (pr - ns + 1.0).max(0.0) / cap;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - norm_pr * norm_pr);
    }

    // New-bin candidate: penalize opening a new bin, more so early and when open bins exist
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 45.0 + 12.0 * openness * (1.0 - progress) + 20.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 5 bands.
    let band = post_residual / (bin_capacity / 5).max(1);
    let band_bonus: f64 = match band {
        0 => -12.0, // near-perfect fit, tiny dead space
        1 => -6.0,  // small but plausibly usable gap
        2 => 0.0,
        3 => 3.0,
        _ => 6.0,   // large leftover: wasteful unless bin was fresh
    };
    score += band_bonus;

    // Exact-fill harmony: post_residual exactly divisible by common size classes.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual < 10 {
        score += 5.0; // dead space too small for any item
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic pairing: next item slots exactly (or class-aligned)
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: it is only attractive when no open bin fits
    // well or the open-bin pool is empty/congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // Penalty keeps new bins from stealing good fits...
        let mut new_bin_penalty = 10.0 + mean_residual * 0.3;
        // ...but relax it when congestion is high or mean residual is tiny
        // (open bins are nearly full, so a fresh bin is genuinely useful).
        if mean_residual < 15.0 {
            new_bin_penalty -= 10.0;
        }
        if open_bins_count > 20 {
            new_bin_penalty -= 3.0;
        }
        // Late in the stream, avoid spawning bins that will never fill.
        new_bin_penalty += progress * 8.0;
        score += new_bin_penalty.max(-5.0);
    } else {
        // Mild preference for tighter existing bins as the stream progresses.
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Tie-break: prefer bins whose residual is in the same harmonic class
    // as the item size (modular affinity).
    if bin_residual % item_size.max(1) == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (min size 1, but practically < 10) are wasted space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit: fully packed bin, strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: how much of the bin the item consumes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Dead-space relative to capacity: penalize leaving awkward gaps.
    let gap_ratio = post_residual as f64 / bin_capacity as f64;
    if gap_ratio > 0.0 && gap_ratio < 0.15 {
        score += 30.0 * (0.15 - gap_ratio) / 0.15;
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item could use the post_residual, reward preserving it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 6.0; // next item won't fit here; residual likely dead
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make opening a new bin unattractive by default,
    // unless current bin would leave severe dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        if bin_residual < item_size {
            score -= 1000.0; // impossible anyway (safety)
        }
        // If no open bin gives a good fit, allow new bin more readily early on.
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to mean residual (balanced packing).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: post residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Dead space: leftover that cannot fit the next item is wasted (unless ~0).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let tightness = (next_item_size - post_residual) as f64;
        score += 12.0 + tightness * 0.6;
    }

    // Reward tight fits relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.35;
    } else {
        score += (pr - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Progress-based pressure: late in the stream, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    } else {
        // New-bin candidate: penalize more when many bins are already open.
        score += 5.0 + open_bins_count as f64 * 0.5;
    }

    // Mild penalty for very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed — late items favor consolidation into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining: residual exactly matches next item -> strong reward.
            if next_item_size == post_residual {
                score -= 10.0;
            } else {
                score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
            }
        } else {
            // Dead space: residual too small for lookahead item.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 4.0 * (1.0 - waste / 10.0);
            }
        }
    } else {
        // Last item: simply prefer tightest fit (smallest post_residual already does this).
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // New-bin candidate: add a fixed opening cost so a new bin is only chosen
    // when existing bins fit poorly. Discount slightly late in the stream
    // (fewer future items to justify a fresh bin).
    if bin_residual == bin_capacity {
        score += 14.0 - 6.0 * progress;
        // A fresh bin that can host the next item is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 3.0;
        }
    }

    // Prefer bins whose residual is already below average (they are "used up",
    // finishing them off is good); penalize draining bins far above mean residual.
    if open_bins_count > 0 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Mild penalty for very tight remaining capacity that risks fragmentation
    // when it doesn't match the lookahead.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 2.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits (low post residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + progress) * 15.0;

    // Penalize dead space that cannot fit the next item (smooth coupling)
    let waste = (pr as f64 - next_item_size as f64).max(0.0) / cap;
    score += 25.0 * waste * waste * (0.5 + 0.5 * progress);

    // Reward bins whose residual exactly accommodates the lookahead item
    if next_item_size > 0 {
        let fit_gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (1.0 - fit_gap / cap) * (1.0 - norm_item);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open relative to stream progress
    score += open_bins_count as f64 * (1.0 - progress) * 2.0;

    // Coupling with mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // Penalize the brand-new empty bin candidate smoothly, unless item is large
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - norm_item) * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover space: residues divisible into nice
    // chunks (multiples of 10) are more reusable than odd dead space.
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 8.0; // clean residue, likely reusable
    } else {
        // Penalize awkward residues; worst are just above a "useful" size.
        score += (residue_class as f64) * 1.5;
    }

    // Dead space: post_residual too small for the smallest plausible item (1..100 range).
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Lookahead: strongly reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportionally to how well the next item uses the leftover.
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.2 * fill_after;
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0; // chain of clean splits
            }
        } else {
            // Leftover can't host the next item: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current residuals are badly fragmented relative to the item.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: full residual, minus a bonus that
        // grows when open bins are crowded (low mean residual) or few fit.
        score -= 15.0;
        let pressure = mean_residual / bin_capacity as f64;
        score -= 30.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Progress: late in the stream, consolidation matters more; slightly
    // prefer bins with larger residuals (they stay flexible).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to host future items
    // (items are 1..=100, but typical min useful gap ~ smallest plausible item).
    // Penalize gaps in the "dead zone" (1..=10) very harshly, tapering up to ~30.
    let dead = if post_residual == 0 {
        -6.0 // perfect fit: strong reward
    } else if post_residual <= 10 {
        40.0
    } else if post_residual <= 20 {
        18.0
    } else if post_residual <= 30 {
        6.0
    } else {
        0.0
    };
    score += dead;

    // Reward tight fits: fill ratio of the placement.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill;

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; make new bins less attractive.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 0.6 * open_bins_count as f64;
        // If this is the last fitting bin, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Early stream: allow opening bins more freely to build a good pool.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
    } else {
        // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 4.0; // next item can still use leftover space
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0; // leftover becomes dead space for the lookahead
    }

    // Mean residual coupling: if this bin's residual is well below the mean,
    // using it up is good (balances bins); if above mean, slight penalty.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small slack left.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward proportional to how tight the fit is (slack small = good).
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit in the leftover: penalize dead space proportionally.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Coupling with mean residual: prefer bins whose post residual is close to the
    // mean residual (keeps the fleet homogeneous and future-flexible).
    let mr = mean_residual;
    if mr > 0.0 {
        let dev = (post_residual as f64 - mr).abs();
        score += 0.2 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin, but less so early in the stream when flexibility
    // is cheap; scale penalty with stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 40.0 * (0.5 + 0.5 * progress);
        // Opening a new bin is more acceptable when many bins are open and mean
        // residual is fragmented (low mean residual => poor fits everywhere).
        if mr < 20.0 {
            score -= 20.0;
        }
    }

    // Mild preference for tighter fits overall (best-fit baseline sharpening).
    score += 0.05 * post_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // New-bin candidate: base cost of opening a bin, softened when existing
        // fits are poor (high mean residual waste) and few bins fit the item.
        let mut nb = 45.0 + 0.35 * post_residual as f64;
        if fitting_bins_count <= 1 {
            nb -= 18.0;
        }
        nb -= 0.25 * mean_residual;
        if next_item_size > 0 && next_item_size <= post_residual {
            nb -= 6.0;
        }
        // Late in stream, avoid opening bins for marginal gains.
        nb += 25.0 * progress;
        return nb;
    }

    // Dead-space penalty: strongly penalize leaving tiny unusable residuals.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 0.6 * (item_size as f64 / bin_capacity as f64) * 40.0;

    // Lookahead: reward if the next item can use the leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Leftover too small for next item -> dead space risk.
            score += 4.0;
        }
    } else {
        // Last item: prefer emptiest possible remainder.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (concentrate waste in fewer bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Early in stream: be picky about fits; late: just pack.
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight fit), non-linearly scaled.
    let mut score = post * (1.0 + 0.9 * post / cap);

    // Quadratic coupling of post_residual with stream progress:
    // late in the stream, dead space matters more.
    score += 2.0 * (post / cap).powi(2) * (0.5 + progress);

    // Smooth interaction: residual fill ratio vs progress.
    let fill = 1.0 - resid / cap;
    score -= 3.0 * fill * fill * (1.0 - progress);

    // Reward tight fits (post_residual near zero) more strongly as stream advances.
    let tight = 1.0 - post / cap;
    score -= 4.0 * tight * tight * tight * (0.3 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else {
        // Crowding penalty: many fitting bins -> keep flexibility, mild penalty.
        score += 0.35 * ((fitting_bins_count as f64 - 1.0).min(6.0));
    }

    // Lookahead coupling: if next item fits the post residual, reward leaving
    // exactly that space; penalize post residual slightly larger than next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 2.5 * (1.0 - gap / cap);
        } else {
            score += 0.6 * (-gap) / cap;
        }
    }

    // Mean-residual context: when open bins are generally loose, prefer
    // consolidating into tight bins (penalize above-mean post residual).
    score += 0.8 * (post - mean_residual) / cap;

    // New-bin candidate handling: opening a new bin wastes the residual of
    // existing bins; penalize smoothly unless current bins are nearly full.
    let is_new_bin = (resid - cap).abs() < 1e-9;
    if is_new_bin {
        let avg_waste = mean_residual / cap;
        // If open bins are mostly full, opening a new bin is fine (low penalty);
        // if there is lots of slack, strongly discourage.
        score += 10.0 * (1.0 - avg_waste).powi(2);
        // Late in stream, slightly more tolerant of new bins.
        score -= 2.0 * progress;
    }

    // Mild penalty for proliferation of open bins.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues near "dead space"
    // values (small nonzero) are the worst, exact 0 is perfect.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Modulo-10 class: residuals that are multiples of 10 pair well
        // with typical item sizes (items are multiples of 5/10 in many streams).
        if r % 10 == 0 {
            score -= 12.0;
        }
        // Integer-division thresholds: very small residual is dead space.
        if r < 10 {
            score += 45.0; // unusable sliver
        } else if r < 20 {
            score += 18.0;
        }
        // Fraction of capacity remaining, non-linear penalty on waste.
        let frac = r as f64 / bin_capacity as f64;
        score += 25.0 * frac * frac;
    }

    // Lookahead: reward leaving room for the next item (harmonic pairing).
    if next_item_size > 0 {
        if r >= next_item_size {
            let gap = (r - next_item_size) as f64;
            if gap == 0.0 {
                score -= 40.0; // next item closes this bin exactly
            } else if gap < 10.0 {
                score += 10.0; // next item would leave a sliver
            } else {
                score -= 8.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow into this bin: mild penalty unless
            // this placement itself was a near-perfect fit.
            if r > 0 && r < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current
    // item is large relative to capacity or open bins are congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut penalty = 70.0;
        // Large items are fine to start fresh bins with.
        penalty -= 45.0 * item_frac;
        // Many open bins with low mean residual => fragmentation; a fresh
        // bin is more attractive then.
        penalty -= 0.5 * open_bins_count as f64;
        penalty += 0.3 * mean_residual;
        // Early in the stream, be slightly more willing to open bins.
        penalty -= 10.0 * (1.0 - progress);
        score += penalty.max(0.0);
    }

    // Prefer filling fuller bins (best-fit bias) when several bins fit.
    if fitting_bins_count > 1 {
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Items range 1..100; a gap < 10 is nearly always dead space.
    if post_residual < 10 {
        score += 60.0; // severe penalty for creating unusable slivers
    } else if post_residual <= 25 {
        // small gaps are only usable by small items: mild penalty scaled by gap smallness
        score += 12.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward tight fits: post_residual near zero relative to residual.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 25.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine for large items or when no good fit exists,
        // but add pressure so we prefer existing bins with decent fits.
        score += 30.0;
        // Pressure grows with number of open bins (avoid bin proliferation).
        score += open_bins_count as f64 * 1.5;
        // If the item is large relative to capacity, a fresh bin is attractive.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // If next item is large and this bin's post-fit residual can't hold it,
        // opening a fresh bin that can hold both is valuable.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight preference for bins with lower residual already
        // (keep large gaps available for large future items).
        score += 0.1 * (bin_residual as f64 - post_residual as f64).max(0.0);
        // If this bin's post-residual exactly accommodates the lookahead item,
        // reward chaining the next item here.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize placing a large item into a bin with a large residual when
        // the next item could use that residual better.
        if next_item_size > post_residual && post_residual >= 10 {
            score += 8.0;
        }
        // Open-bin pressure: mildly prefer reusing bins as count grows.
        score -= open_bins_count.min(10) as f64 * 0.5;
    }

    // Stream progression: early on, be more conservative about tight fits in
    // bins (future variety unknown); late in stream, squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Mean-residual coupling: if mean residual across bins is high, we have
    // slack; tolerate imperfect fits. If low, be strict about dead space.
    let strictness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += strictness * (post_residual as f64 * 0.3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Dead space: post_residual too small for the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Post-residual can still hold the next item (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Exact fit now is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Small leftover waste penalty (non-linear dead-space cost).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin has a good fit.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 40.0;
        // But if the new bin would perfectly chain the next item, soften it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0;
        }
        // Fewer alternatives make opening a bin more acceptable.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit), with super-linear penalty
    // for small-but-unusable leftover space (dead space below min item size).
    let min_item = 1u32; // items can be as small as 1 per interface note
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 50.0; // unreachable sliver
    }
    // General dead-space pressure: residual that is hard to fill later
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: bonus proportional to fill ratio of this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Reward near-perfect fits strongly (post_residual close to 0).
    let pr = post_residual as f64;
    score -= 30.0 * (-pr / 10.0).exp();

    // Penalize leaving a residual that is awkward: large residual is fine only
    // if it can plausibly host the next item; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin stays useful for the lookahead item: reward.
            score -= 6.0;
        } else {
            // Post-residual can't fit next item: penalize proportionally.
            score += 4.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when: many open bins already exist
        // with fragmented space, or current fit is bad, or stream is early
        // (long horizon to amortize the bin).
        let fit_quality = if bin_residual >= item_size { 1.0 } else { 0.0 };
        let _ = fit_quality;
        let fragmentation = mean_residual / bin_capacity as f64;
        let new_bin_bias = 18.0
            - 8.0 * fragmentation.min(1.0)      // fragmented open bins -> new bin ok
            - 10.0 * (1.0 - t)                  // early stream -> new bins amortize
            + 6.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)); // slight crowding penalty
        score += new_bin_bias;
    } else {
        // Using an existing bin: reward reuse, especially when mean residual
        // across bins is high (we should consolidate).
        score -= 5.0 * fragmentation_like(mean_residual, bin_capacity);
    }

    // Mild penalty for spreading across many bins when residuals are large.
    if open_bins_count > 2 && mean_residual > 0.5 * bin_capacity as f64 {
        score += 2.0;
    }

    // Small exploration noise-free coupling: time-horizon scaling of tightness.
    // Late in the stream, prioritize closing bins out (minimize post-residual more).
    score *= 1.0 + 0.5 * t * (pr / bin_capacity as f64);

    score
}

#[inline]
fn fragmentation_like(mean_residual: f64, bin_capacity: u32) -> f64 {
    (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: normalized post residual, polynomially shaped
    let x = post / cap;
    let mut score = 2.0 * x - 1.6 * x * x + 0.9 * x * x * x;

    // Coupling: large post residual is more acceptable early (bins stay flexible),
    // less acceptable late (we want tight packing as stream ends)
    score += (0.5 - progress) * (post * post) / (cap * cap) * 1.2;

    // Penalize new empty bin when other bins could fit the item
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 3.0 + 2.0 * (1.0 - progress);
        } else {
            score -= 1.0;
        }
    }

    // Reward last-chance bin (only fitting bin) strongly
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 2.5;
    }

    // Lookahead: prefer leaving residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.8 * (nxt / cap);
        } else {
            score += 0.4 * (1.0 - post / cap);
        }
    }

    // Mild preference for bins tighter than mean residual
    score += 0.3 * ((post - mean_residual) / cap);

    // Diversification: slight penalty when many bins already open
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic classes of post_residual
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr % 10 == 0 {
        score -= 12.0; // aligned class, likely reusable
    } else if pr < 20 {
        score += 8.0; // dead-space risk zone
    }

    // Fractional capacity coupling
    let frac = post_residual as f64 / cap;
    score += 30.0 * frac * frac; // quadratic penalty for leftover fraction

    // Lookahead: does the residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            let slack = post_residual - next_item_size;
            if slack <= 10 { score -= 10.0; } // near-perfect chain
        } else {
            score += 10.0; // residual unusable by next item
        }
    } else {
        // last item: prefer any fit, penalize leftover less
        score -= 20.0;
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only open new bin if item is large
    if bin_residual == bin_capacity {
        if item_size > 60 && post_residual < 40 {
            score -= 10.0; // big item, fresh bin reasonable
        } else {
            score += 25.0 + 0.5 * open_bins_count as f64; // prefer existing bins
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / cap);

    // Mean-residual divergence penalty: avoid bins far from mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate (bin_residual == bin_capacity) gets a penalty
    // proportional to open_bins_count.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
        // But if no open bin fits well, opening a new bin is fine:
        // small item in a fresh bin keeps residual large and usable.
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        // Dead space for the known next item: penalize.
        if post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (fill the emptier-trending bins first to consolidate).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (fewer chances to fill them).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits here later; mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the leftover space: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Compare post_residual relative to mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize wasting a nearly-full bin on a tiny item
    if item_size < 20 && post_residual > 60 {
        score += 50.0;
    }

    // New-bin candidate: make empty bin moderately attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 100.0; // two identical items pair well in a fresh bin
        }
    }

    // Late-stream consolidation: prefer tighter fits as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual relative to capacity).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead space too small for typical items is nearly as good.
        score -= 15.0;
    }

    // Penalize creating residuals that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // bin stays useful for next item
        } else {
            score += 4.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
        // If this bin could fit both current and next item, reward that.
        if bin_residual >= item_size + next_item_size {
            score -= 5.0;
        }
    }

    // Last chance: only this bin can fit the item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's only chosen when fits are bad.
        score += 18.0;
        if fitting_bins_count > 0 {
            // Scale penalty with how many alternatives exist.
            score += 6.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        // If open bins have lots of residual, prefer using them.
        score += 0.3 * mean_residual;
    } else {
        // Slight preference for fuller (lower-residual) existing bins.
        score += 0.05 * (bin_residual as f64);
        // If many bins fit, prefer the one with least residual (implicit in score),
        // but dampen over-fragmentation: mild penalty per open bin.
        score += 0.02 * open_bins_count as f64;
    }

    // Late-stream consolidation: push toward filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap; // 0..1 post residual fraction

    // Base: prefer tight fits (low post residual), non-linearly
    let mut score = 6.0 * fit_norm + 24.0 * fit_norm * fit_norm;

    // Stream-progress coupling: early on, tolerate larger residuals (future items
    // may fill them); late in stream, strongly penalize leftover dead space.
    let late = progress * progress;
    score += 30.0 * late * fit_norm;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = fit_norm * (1.0 - fit_norm);
    score -= 8.0 * coupling * (1.0 - progress);

    // Next-item lookahead: if the next item fits into post_residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 6.0 * snug;
    } else if next_item_size > 0 {
        // next item won't fit: penalize wasted residual proportional to its size
        score += 3.0 * (pr / cap) * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowd penalty: many open bins with slack -> avoid adding more slack there
    score += 2.0 * (mean_residual / cap) * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin, more so early in the stream when open bins exist.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 40.0 + 60.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64);
        // but if no existing bin could fit, fitting_bins_count == 1 refers to this
        // empty candidate, so soften the penalty to allow opening when forced.
        if fitting_bins_count == 1 {
            score = 10.0 * fit_norm + 5.0;
        } else {
            score += new_bin_penalty;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that create "dead zones"
    // (small unusable leftovers) are penalized, near-zero residues rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity filled after placement
    let fill_frac = 1.0 - pr / cap;

    // Reward high fill fraction non-linearly (super-linear squeeze)
    score -= 40.0 * fill_frac * fill_frac;

    // Modulo classes on post_residual: leftovers in (0..=10] are near-perfect;
    // leftovers in 11..=30 are the worst dead space band.
    let r = post_residual % 100;
    if r == 0 {
        score -= 25.0; // perfect closure
    } else if r <= 10 {
        score -= 15.0;
    } else if r <= 30 {
        score += 18.0; // dead-space band penalty
    } else if r <= 60 {
        score -= 4.0; // moderate residual, still usable
    }

    // Integer-division threshold: post_residual quarters
    let quarter = post_residual / 25;
    score -= match quarter {
        0 => 12.0,
        1 => 0.0,
        2 => 3.0,
        _ => 8.0,
    } as f64;

    // Harmonic coupling with next item (k=2 lookahead):
    // if next item exactly consumes post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after pair should be small or large, not middle
            let pr2 = post_residual - next_item_size;
            if pr2 <= 10 {
                score -= 20.0;
            } else if pr2 <= 30 {
                score += 10.0;
            }
        } else {
            // next item cannot use this bin's residue: mild penalty scaled by gap
            score += (next_item_size - post_residual).min(50) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are
    // congested (low mean residual) or no real alternatives exist.
    if bin_residual == bin_capacity {
        let congestion = (mean_residual / cap).clamp(0.0, 1.0);
        // base penalty so we prefer existing bins; relax when mean residual is tiny
        score += 55.0 * congestion + 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        if next_item_size >= 70 {
            score -= 10.0; // big next item: keep fresh bins
        }
    }

    // Late-stream tightening: drive toward tight packing as stream ends
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_frac;

    // Slight preference to keep open-bin count from exploding
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // Dead-space avoidance: penalize unusable small gaps.
    // Gaps below the smallest plausible item threshold are wasted capacity.
    let min_item = 1u32;
    let dead_threshold = 20u32; // gaps <= 20 are hard to fill for typical streams
    if post_residual > 0 && post_residual < dead_threshold {
        // The smaller and more "orphaned" the gap, the worse.
        score += (dead_threshold - post_residual) as f64 * 3.0;
        // Extra penalty if no future item could ever fit (post_residual < min possible size).
        if post_residual < min_item.max(1) {
            score += 100.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size > post_residual {
            // Next item cannot use this bin's leftover; leftover is likely dead space.
            score += post_residual as f64 * 0.5;
        } else {
            // Next item fits, but penalize proportional leftover after that hypothetical placement.
            let next_leftover = post_residual - next_item_size;
            if next_leftover < dead_threshold {
                score += (dead_threshold - next_leftover) as f64 * 1.5;
            }
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones and
    // encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are already open.
        score += 30.0 + 8.0 * bin_pressure;
        // But if existing bins would leave very tight/awkward fits, allow new bin:
        // i.e., if this item fits poorly everywhere, the fit_ratio bonus already helps.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Slight reward for packing into bins whose residual is near mean (balanced closing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // 2-step lookahead: reward if next item fits the post-residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 120.0;
            } else {
                score -= 40.0 / slack;
            }
        } else {
            // Next item cannot fit here: penalize small post-residuals that become dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative
    // to capacity or existing bins are poor fits.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill >= 0.6 {
            score -= 100.0 * fill;
        } else {
            score += 150.0 * (0.6 - fill);
        }
        // Discourage opening new bins when many bins already fit the item.
        if fitting_bins_count > 2 {
            score += 80.0;
        }
    }

    // Late-stream consolidation: tighten bin selection as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight fit).
    let mut score = post;

    // Strong reward for near-perfect fits (post residual <= 5% of capacity).
    if post <= cap * 0.05 {
        score -= cap * 0.35;
    } else if post <= cap * 0.12 {
        score -= cap * 0.15;
    }

    // Penalize creating dead space that few future items could use.
    // Dead-space severity grows for small unusable-but-not-tiny leftovers.
    if post > 0.0 {
        let waste = 1.0 - (post / cap);
        // small residuals are unusable; scale penalty by how "awkward" the gap is
        let awkwardness = (post / cap).powf(0.5) * (1.0 - waste);
        score += awkwardness * cap * 0.08;
    }

    // Lookahead (k=2): if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            if gap <= cap * 0.03 {
                score -= cap * 0.30; // perfect chain
            } else if gap <= cap * 0.15 {
                score -= cap * 0.12; // good chain
            } else {
                score -= cap * 0.03; // mild chain benefit
            }
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += (nxt - post) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.40;
    }

    // Congestion: many open bins with large mean residual -> prefer consolidating
    // into fuller bins rather than spreading.
    if open_bins_count > 2 {
        let spread = (mean_residual - post).abs();
        score += spread * 0.02;
        // reward choosing bins below mean residual (filler bins)
        if (post as f64) < mean_residual {
            score -= mean_residual * 0.05;
        }
    }

    // Time horizon: late in the stream, be more conservative — prefer tight fits
    // even more and penalize opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * t;

    // New-bin candidate handling: empty bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Baseline penalty so a new bin is only chosen when all fits are bad.
        score += cap * 0.55;
        // Early in stream, new bins are cheaper; late in stream, expensive.
        score += cap * 0.35 * (1.0 - t);
        // If next item is large and would need a fresh bin anyway, opening now
        // is less painful.
        if next_item_size > 0 && (next_item_size as f64) > cap * 0.6 {
            score -= cap * 0.10;
        }
        // If many bins are open and fragmented, slightly discourage another.
        score += open_bins_count as f64 * 0.5;
    }

    // Tiny structural bonus for filling more than half the bin.
    if item >= cap * 0.5 {
        score -= cap * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.5 * fill * fill);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; later, demand tighter packing.
    let slack_penalty = post * post / cap * (0.3 + 1.2 * progress * progress);
    score += slack_penalty;

    // Penalize the brand-new empty bin candidate smoothly; the penalty decays
    // as the stream progresses (less value in hoarding capacity late).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += cap * (0.35 + 0.35 * (1.0 - progress) * (1.0 - progress));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead coupling: reward leaving post_residual that the next item can use,
    // penalize post_residual that is small but nonzero (dead space for next item).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else if post > 0.0 {
            score += 10.0 * (1.0 - post / nxt);
        }
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * fill;

    // Deviation from mean residual: prefer bins whose residual is close to mean
    // (balanced packing), penalize outliers smoothly.
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual (mod-10 residue classes) ----
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residue = (post_residual % 10) as f64;

    // Dead-space penalty: residuals that are small but not zero are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }
    // Reward exact fills and harmonically "friendly" residuals (multiples of 10).
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Mid-range residues (4..7) leave awkward gaps: penalize.
    if residue >= 4.0 && residue <= 7.0 {
        score += 3.0;
    }

    // ---- Capacity fraction thresholds on post_residual ----
    let frac = pr / cap;
    if frac < 0.10 && post_residual > 0 {
        score += 8.0; // near-full but wasted remainder
    } else if frac > 0.45 {
        score += 4.0; // leaving nearly half a bin empty is bad
    } else if frac > 0.25 {
        score -= 2.0; // sweet spot: half-ish filled bin
    }

    // ---- Lookahead coupling with next_item_size ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect harmonic continuation: next item exactly fills post_residual.
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward tighter co-fit, mod-class match bonus.
            score -= 5.0;
            if (next_item_size % 10) == (post_residual % 10) {
                score -= 3.0;
            }
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 10 {
                score += 4.0; // creates a sliver for the step after next
            }
        } else {
            // Next item will NOT fit here: this bin's residual becomes dead space.
            let wasted = pr.min(nxt);
            score += 2.0 + 0.05 * wasted;
        }
    }

    // ---- Last-chance bin pressure ----
    if fitting_bins_count == 1 {
        // This is the only bin that fits; strongly prefer using it over new bin.
        score -= 20.0;
    } else if fitting_bins_count > 4 {
        score += 1.0; // plenty of alternatives; be pickier about fit quality
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 25.0;
        // Open a new bin only for large items that would wreck an open bin's structure,
        // or when no open bin fits anyway (fitting_bins_count==0 handled by selection).
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && item_size <= 30 {
            score += 15.0;
        }
        // If many open bins with large mean residual exist, new bin is less attractive.
        if mean_residual > 40.0 {
            score += 10.0;
        }
    }

    // ---- Mild occupancy preference: fuller bins (smaller residual) preferred ----
    score += 0.02 * (bin_residual as f64 - post_residual as f64).signum() as f64 * 0.0;
    score += 0.01 * (open_bins_count as f64);

    // Tie-break with tightness: prefer minimal post_residual via quadratic shaping.
    score += 0.05 * pr * pr / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item (<= 10) are essentially wasted -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-ish gaps that few future items could use.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // next item would leave a dead gap -> mild penalty
        score += 8.0;
    }

    // New-bin candidate: only attractive when no good fit exists, i.e.
    // when the best open fit would leave a dead gap or item barely fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Slightly cheaper to open a bin early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // If current bin would leave a dead gap, new bin becomes attractive.
        if bin_residual >= item_size && bin_residual - item_size < 10 {
            score -= 45.0;
        }
    }

    // Prefer bins with residual close to the item (tighter fits) mildly.
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // item fits after placing current item
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit in leftover: dead-space penalty grows as leftover shrinks
            let tiny = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * (1.0 - tiny);
        }
    }

    // Reward tight fits relative to mean residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when plenty of bins fit the item
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 30.0 + 5.0 * fitting_bins_count as f64;
        } else {
            score -= 10.0;
        }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins with residual below mean (consolidating waste)
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Avoid leaving residuals too small for any future item (min size 1)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty dominates.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless it enables a great lookahead fit.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 45.0;
        }
    }

    // Lookahead: reward leaving post_residual that exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Global pressure: when many bins are open, encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * (1.0 - progress);
    score -= open_bins_count as f64 * 0.3;

    // Late stream: bias toward closing bins tightly.
    if progress > 0.8 {
        score += post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score -= progress_weight * (pr - norm_post * pr * 0.5) * 0.05;

    // Cubic penalty on normalized dead space, modulated by progress.
    score += progress * norm_post * norm_post * norm_post * 40.0;

    // Coupling with mean residual: prefer bins whose residual deviates favorably.
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev * (1.0 + progress);

    // Last-chance bonus (smoothly scaled by progress).
    if fitting_bins_count == 1 {
        score -= 3.0 + 4.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0 + 3.0 * (1.0 - norm_post);
    } else if next_item_size > 0 {
        // penalize leaving a gap that blocks the next item, worse late in stream
        score += 1.0 + 2.0 * progress;
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals in "dead" bands
    // (very small, unusable slivers) are heavily penalized.
    let dead = post_residual < 10;
    if dead {
        score -= 40.0; // perfect fit: dead space is fine
    } else {
        // Harmonic class via integer division: classify residual into bands of 10
        let band = post_residual / 10;
        // Mid-size residuals (bands 3..=6, i.e. 30..70) are most reusable
        let band_bonus: f64 = match band {
            0 => 25.0,  // 1..9 handled above; band 0 = 0 -> perfect
            1 => 15.0,  // 10..19: small but usable by tiny items
            2 => 5.0,   // 20..29
            3 => -12.0, // 30..39: sweet spot
            4 => -14.0, // 40..49
            5 => -12.0, // 50..59
            6 => -6.0,  // 60..69
            7 => 4.0,   // 70..79
            8 => 10.0,  // 80..89
            _ => 18.0,  // 90..99: nearly empty, wasteful
        };
        score += band_bonus;

        // Modulo-5 harmonic coupling: residuals divisible by 5 pair well with
        // common item sizes; small odd remainder adds slight penalty.
        if post_residual % 5 != 0 {
            score += 2.0;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Extra reward when the next item fills this bin nearly exactly
        let gap = post_residual - next_item_size;
        if gap < 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Post-residual too small for next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate detection: prefer keeping items in open bins unless
    // the fit would create large dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, scaled by stream progress and
        // number of open bins (more open bins => consolidation is better).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut penalty = 55.0 + 0.35 * open_bins_count as f64 + 20.0 * progress;
        // If the item is huge relative to capacity, a fresh bin is fine
        if item_size * 4 >= bin_capacity * 3 {
            penalty -= 30.0;
        }
        // If next item is small, new bin remains flexible
        if next_item_size > 0 && next_item_size <= 20 {
            penalty -= 10.0;
        }
        score += penalty;
    }

    // Slight global preference for tighter bins (smaller bin_residual)
    score += bin_residual as f64 * 0.05;

    // Mean-residual coupling: if this bin is much tighter than average,
    // filling it now is valuable (reduces fragmentation).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead space is nearly worthless
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item (good packing chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // gap too small for next item: likely dead space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.5;
    }

    // Relative tightness bonus: favor bins where item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_frac;

    // New-bin candidate: only attractive when no good fit exists
    // (large residual elsewhere or many open bins with slack).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Attractive if mean residual is large (existing bins too full/wasteful)
        // or this bin is the only fitting option.
        if mean_residual < 20.0 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 40.0 * (1.0 - match_gap * 4.0).max(0.0);
    }

    // Penalize post_residual that cannot host the next item (dead space risk)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Compare against mean residual: prefer bins whose post residual deviates toward tight fits
    let post_f = post_residual as f64;
    let dev = (post_f - mean_residual).abs();
    score -= 6.0 * (1.0 - dev / bin_capacity as f64).max(0.0);

    // Last chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving very small unusable residuals (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: only attractive when current bin would be badly fragmented
    // or no good lookahead match exists elsewhere. Default: slightly discourage new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_base = 30.0 + 20.0 * progress;
        if next_item_size > 0 && item_size <= next_item_size {
            // opening a fresh bin lets the next item pair nicely
            score = new_bin_base - 18.0;
        } else {
            score = new_bin_base + 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= (item_size as f64) * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);
    }

    // Penalize leaving dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 3.0; // usable pocket for small items
    }

    // Lookahead: if next item fits in the post-residual, reward; otherwise penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0;
        } else if next_item_size <= bin_residual {
            score += 1.5; // this bin could have taken the next item instead
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 0.5; // plenty of alternatives, be picky
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere or open bins are nearly full.
    if bin_residual == bin_capacity {
        let tightness = if bin_residual as f64 >= item_size as f64 { 1.0 } else { 0.0 };
        let _ = tightness;
        // Base cost of a fresh bin: moderate penalty, offset when alternatives are bad
        let mut nb = 14.0;
        if fitting_bins_count == 0 {
            nb -= 20.0; // no alternative at all
        } else if fitting_bins_count == 1 {
            nb += 10.0; // there is a last-chance bin, prefer it
        }
        if mean_residual > (item_size as f64) + 5.0 {
            nb += 6.0; // open bins have plenty of room; don't open new
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb *= 1.0 - 0.3 * progress; // later in stream, slightly less eager to open
        score += nb;
    }

    // Global state coupling: high mean residual means space is abundant; be choosy
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // Slight preference for filling fuller bins early (best-fit flavor)
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * 2.0;

    // Time-horizon modulation: early on, keep bins balanced; late, pack greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tight fit reward: quadratic coupling of post_residual with stream progress.
    // Later in the stream, small residuals are increasingly valuable (smooth amplification).
    let tightness = 1.0 - (post / cap).clamp(0.0, 1.0);
    score -= 18.0 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: bonus if the next item fits into the post residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // reward proportional to how well next item nests in the remaining space
            let nest = 1.0 - ((post - nxt) / cap).clamp(0.0, 1.0);
            score -= 14.0 * nest;
        } else {
            // penalize residuals that neither fit next item nor are near zero (dead space)
            let dead = (post - nxt) / cap;
            score += 6.0 * dead * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins vs. consolidating near mean residual.
    let mean_gap = (post - mean_residual).abs() / cap;
    score += 3.0 * mean_gap * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize opening a new bin unless residuals of open bins are poor.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 30.0 * (1.0 - avg_fill) + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands on
    // "usable" residue classes (divisible by small harmonic steps) are
    // more valuable, since future items are more likely to fit exactly.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if pr % 10 == 0 {
        score -= 12.0; // aligns with the coarse harmonic grid
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else {
        // Dead-space penalty grows for odd/awkward leftovers.
        score += (pr % 5) as f64 * 1.5;
    }

    // Integer-division thresholds: classify how "deep" the fill is.
    let fill_quarter = (bin_capacity - bin_residual) / (bin_capacity / 4).max(1);
    match fill_quarter {
        3 => score -= 8.0, // nearly full bin: excellent
        2 => score -= 3.0,
        _ => {}
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a two-item chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // Next item fits but leaves a residue: mild reward scaled by
            // how harmonically clean the resulting residue is.
            let nr = pr - next_item_size;
            if nr % 10 == 0 {
                score -= 8.0;
            } else if nr % 5 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize large
            // unusable leftovers a bit more.
            score += (pr as f64 / 20.0).min(5.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are
    // crowded or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fill = 1.0 - (mean_residual / bin_capacity as f64);
        // Base penalty keeps new bins from winning cheaply.
        score += 30.0;
        // As bins fill up on average, opening a fresh bin becomes better.
        score -= avg_open_fill * 25.0;
        // Late in the stream, consolidation matters more.
        score += progress * 10.0;
        // If many bins are open, a new bin dilutes future choices less.
        score -= (open_bins_count.min(20) as f64) * 0.5;
        // Small items are cheap to start fresh with.
        if item_size <= 30 {
            score -= 10.0;
        }
    }

    // Mild preference for balancing residual mass across bins.
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item are almost pure waste. Penalize them heavily.
    let min_useful_gap = 10.0f64.min(item_size as f64);
    if (post_residual as f64) < min_useful_gap {
        score += 60.0;
    } else if post_residual <= 15 {
        // Small but potentially usable gaps: moderate penalty to prefer
        // placements leaving larger, more flexible residuals.
        score += 12.0;
    }

    // Reward tight fits (small but usable post_residual).
    if post_residual > 0 && post_residual <= 20 {
        score -= 8.0;
    }

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading into
    // new bins; favor consolidating into existing ones.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when current
    // fits are poor. Base it slightly above a good fit, and scale with stream
    // progression (late in the stream, prefer closing out open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * progress;
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // If many bins are open, opening a new bin is less attractive.
        score += 0.5 * open_bins_count as f64;
    }

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // reward creating that residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }

    // Mean-residual coupling: if this bin's post-residual is far below the
    // mean residual, it is becoming an outlier of dead space; penalize.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 200.0 };
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        score += desperation + if poor_fit { 0.0 } else { 150.0 };
        // Slight bonus late in stream to consolidate
        score -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
        return score;
    }

    // 2-step lookahead: reward post_residual matching next_item_size exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap); // exact match gets full bonus
        // Perfect two-item fill is ideal
        if post_residual as i64 == next_item_size as i64 {
            score -= 25.0;
        }
        // Penalize leaving residual that next item can't use at all
        if next_item_size > post_residual {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize leftover hard
        score += 0.5 * post_residual as f64;
    }

    // Dead space penalty: tiny residuals are hard to fill later
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, use it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins slightly
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;

    let mut score = pr;

    // Penalize deviation from the fleet's mean residual: prefer bins whose
    // post placement keeps the global residual profile balanced.
    score += 0.35 * (mean_residual - pr).abs();

    // Reward near-perfect fills (dead space below smallest item class).
    if post_residual < 10 {
        score -= 6.0;
    } else if post_residual < 20 {
        score -= 2.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: reward if the next item can also fit here after
    // this placement (chaining), penalize if this placement strands space
    // that the next item almost fits.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 7.0;
        } else if (next_item_size as f64) <= pr + 10.0 {
            score += 4.0;
        }
    } else {
        // End of stream: waste matters most, squeeze bins hard.
        score -= 4.0;
    }

    // Brand-new empty bin candidate: keep it expensive unless the stream is
    // early (investing in bins pays off later) or many bins are open.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / 8.0).min(1.0);
        score += 18.0 - 10.0 * t - 6.0 * openness;
    }

    // Mild time pressure: late in the stream, prefer tighter placements.
    score += 2.0 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual

    // Base: prefer filling bins tightly (lower post residual = lower score)
    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, waste is cheap (many items coming can fill gaps);
    // later, dead space is costly, so amplify residual penalty super-linearly.
    let late = progress * progress;
    score *= 1.0 + 1.7 * late * (1.0 + pr);

    // Reward near-perfect fits with a smooth non-linear bonus.
    let fit_quality = 1.0 - pr;
    score -= 22.0 * fit_quality * fit_quality * fit_quality * (1.0 + 0.8 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // (avoid opening a new bin) unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 * (1.0 - 0.5 * pr);
    }

    // Penalize creating residuals that are too small to be useful for typical items,
    // with a smooth bump around small post residuals.
    let small_gap = (pr - 0.05).abs();
    score += 14.0 * (-small_gap * small_gap / 0.004).exp() * (0.4 + 0.6 * late);

    // Lookahead: if the next item fits exactly into the resulting residual, reward it.
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        score -= 10.0 * (-diff * diff / 18.0).exp();
        // If next item cannot fit, the residual is a potential dead end; mild penalty.
        if post < next_item_size as f64 {
            score += 5.0 * (next_item_size as f64 - post) / cap;
        }
    }

    // Context coupling: many open bins with low mean residual -> encourage consolidation
    let mean_r = mean_residual / cap;
    score += 6.0 * (open_bins_count as f64 / 8.0).tanh() * mean_r * (1.0 - fit_quality);

    // New-bin candidate: keep it attractive only when it beats a bad fit;
    // its post residual is large, and base term already scores it high.
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Residues divisible by common item sizes (multiples of 5/10) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else {
        // modulo arithmetic on residual usability
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        // dead-space penalty: small unusable leftovers
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 8.0; }

        // integer-division threshold: can next item fit in the post residual?
        if next_item_size > 0 {
            if next_item_size <= pr {
                score -= 10.0;
                // harmonic bonus: next item leaves a residue in a "good class"
                if (pr - next_item_size) % 10 == 0 { score -= 5.0; }
            } else {
                score += 4.0; // next item won't chain here
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only good when existing bins are crowded or mean residual is tiny
        let pressure = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 - post_residual as f64; // baseline = full empty
        if pressure < 0.25 || fitting_bins_count == 0 {
            score -= 15.0; // open fresh bin when nothing fits well
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // big follower: keep current bins free
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    // Slight preference for fuller bins (small residual before placement)
    score += bin_residual as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 {
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if !next_fits {
            // Dead space: gap too small for the lookahead item.
            score += 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // Very tiny gaps are almost certainly waste.
        if post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: penalize spreading across many bins slightly.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is large relative to capacity, new bin may be fine.
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
        // Late in stream with many open bins: opening new bin is worse.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * progress;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (smaller residual than average means tighter packing).
    score -= 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space (non-linear to punish tiny residuals).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // 2-step lookahead: reward exact/near match of post_residual with next_item_size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let diff = (post_residual as f64 - nr).abs();
        if post_residual as f64 >= nr {
            // Next item can follow into this bin: reward closeness of fit.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 60.0; // perfect 2-step packing
            }
        } else {
            // Next item cannot fit here; penalize leaving a gap just below next size.
            score += 15.0 * (1.0 - diff / bin_capacity as f64);
        }
    }

    // Prefer tight fits relative to the bin's original residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Relative-to-mean coupling: bins with below-average residual are precious;
    // placing into them tightly is good, wasting them is bad.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item is huge
    // or the fit into open bins would be terrible.
    if bin_residual == bin_capacity {
        score += 50.0;
        if item_size >= 60 {
            score -= 45.0; // big items justify a fresh bin
        }
        if post_residual as f64 > 0.7 * bin_capacity as f64 && item_size < 40 {
            score += 30.0; // small item into a fresh bin wastes it
        }
    }

    // Late in the stream, consolidate: discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fill_ratio * fill_ratio;

    // Exact or near-exact fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Chain bonus: next item would also leave a small remainder.
        let chain_post = post_residual - next_item_size;
        if chain_post < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use: mild penalty scaled by waste.
        score += 0.15 * post_residual as f64;
    }

    // Last chance: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across many open bins when residuals are healthy.
    if bin_residual != bin_capacity {
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate logic: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 25.0;
        // If current item is large relative to capacity, opening fresh is safer.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // If the next item is large and this bin's post-residual would be tiny,
        // a fresh bin handles the pair better.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score -= 10.0;
        }
        // Late in the stream, consolidate rather than open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins are already open and mean residual is high, discourage new bins.
        score += 0.05 * mean_residual;
    } else {
        // Prefer bins whose residual is closest above the item (best-fit flavor),
        // modulated by mean residual context.
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.05 * gap;
        if (bin_residual as f64) < mean_residual {
            score -= 3.0; // below-average residual bins: use them up first
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; later, dead space is more costly.
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;
    score += pr * (0.6 * prog_sq + 0.9 * prog_cu);

    // Non-linear fill-ratio reward: reward high utilization with smooth saturation.
    let fill = 1.0 - pr / cap;
    score -= 18.0 * fill * fill * fill;

    // Penalize large post_residual that cannot fit the lookahead item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap > 0.0 {
            // wasted space above next item: mild smooth penalty
            score += 0.35 * (gap / cap) * (gap / cap) * cap;
        } else {
            // post_residual too small for next item: penalize proportionally
            score += 2.5 * ((-gap) / cap) * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a smooth penalty that decays
    // with stream progress (late in stream, opening a bin is less costly relative
    // to scattering items), but early on we prefer filling existing bins.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
        // penalize new bin if lookahead fits comfortably elsewhere implicitly via pr=cap
        score += 0.5 * it;
    }

    // Mild penalty for proliferation of open bins with large mean residual spread.
    let spread = (mean_residual - pr).abs() / cap;
    score += 1.5 * spread * spread;

    // Smooth preference for bins tighter than the mean (compact packing).
    score += 0.8 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it decomposes into
    // "nice" sizes (divisors of capacity). Class 0 = perfectly reusable.
    let nice = [0u32, 10, 20, 25, 33, 50, 66, 75, 80, 100];
    let mut best_nice_gap: u32 = 100;
    for &n in nice.iter() {
        if n <= post_residual {
            let gap = post_residual - n;
            if gap < best_nice_gap {
                best_nice_gap = gap;
            }
        }
    }
    score += best_nice_gap as f64 * 0.6;

    // Reward leaving residuals that are multiples of common item classes
    // (integer division thresholds on post_residual).
    let class = post_residual / 10;
    let class_bonus = match class {
        0 => 0.0,                       // near-full bin, excellent
        1 => 2.0,                       // 10-19: fits small items
        2 => 3.0,                       // 20-29
        3 => 1.5,                       // 30-39: sweet spot for medium items
        4 => 4.0,
        5 => 2.5,                       // 50-59: fits half-capacity items
        _ => 5.0,                       // large leftover: poor
    };
    score -= class_bonus;

    // Modulo coupling: post_residual divisible by 25 or 10 is highly reusable
    if post_residual % 25 == 0 {
        score -= 4.0;
    } else if post_residual % 10 == 0 {
        score -= 3.0;
    }

    // Lookahead: penalize if next item cannot fit the post residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.25;
        } else {
            score -= 1.5; // next item fits here: chain placement
        }
        // Harmonic pair: item + next_item near a capacity fraction
        let pair = item_size + next_item_size;
        if pair <= bin_capacity && (bin_capacity - pair) <= 5 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 2 {
        // Many options: prefer tighter fits
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Tightness reward: relative fill of the bin
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 6.0;

    // Mean-residual coupling: placing in a bin below mean residual
    // preserves large residual bins for harder items
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item is huge and fits nowhere well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / 8.0;
        let big_item = item_size as f64 / bin_capacity as f64;
        let mut nb = 18.0; // default penalty: prefer existing bins
        nb -= crowded * 3.0;
        nb -= big_item * 12.0;
        nb -= progress * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            nb -= 2.0; // stream of large items: fresh bin useful
        }
        if fitting_bins_count == 0 {
            nb -= 30.0; // no alternative anyway
        }
        score += nb.max(0.0);
    }

    // Small progressive jitter-free tie-breaker on exact fit
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a leftover gap that cannot hold the next
    // item is wasted capacity. Penalize it super-linearly.
    let gap_usable = next_item_size > 0 && post_residual >= next_item_size;
    if !gap_usable && post_residual > 0 {
        let dead = post_residual as f64;
        score += 25.0 + dead * dead / (bin_capacity as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Mild preference toward tighter competition among fitting bins.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // slightly favor consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 40.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Prefer bins whose residual is close to what is being consumed
    // (avoid cannibalizing large residual bins with tiny items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive when the current bin would leave an
    // unusable dead gap and the next item could use a fresh bin well.
    if bin_residual == bin_capacity {
        if !gap_usable && post_residual > 0 {
            score -= 30.0; // open new bin rather than create dead space
        } else {
            score += 20.0; // keep using existing bins when fit is decent
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            // Perfect two-item fill: this bin becomes exactly full after next item.
            score -= 60.0;
        } else if diff > 0 && (diff as u32) < 10 {
            // Next item fits with tiny waste left.
            score -= 40.0 - diff as f64 * 2.0;
        } else if diff < 0 {
            // Next item won't fit; penalize proportionally to shortfall.
            score += (-diff as f64) * 0.5;
        } else {
            // Large leftover after next item: dead-space penalty.
            score += diff as f64 * 0.3;
        }
        // Coupling with mean residual: prefer bins whose post state tracks the fleet mean.
        score += (post_residual as f64 - mean_residual).abs() * 0.15;
    } else {
        // Last item: simply minimize leftover.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Discourage opening new bins when a decent fit exists among open bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty, relaxed if item is large relative to capacity.
        score += 20.0 - (item_size as f64 / bin_capacity as f64) * 30.0;
        // If many open bins are congested, opening a new bin is more acceptable.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Small penalty for leaving very tight residuals that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Mild stream-progression pressure: later in stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize tiny unusable dead space (nonzero but nearly full).
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    // Detect brand-new empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so open bins with decent fits win.
        score += 15.0;
        // Opening a bin is more attractive early in the stream and when
        // few bins are open; less attractive late / with many open bins.
        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };
        score += 10.0 * progress;
        score += 0.4 * open_bins_count as f64;
        // If the next item could chain into this fresh bin's residual,
        // opening is slightly more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0;
        }
    } else {
        // Lookahead: reward bins whose residual can host the next item.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 3.0;
            } else {
                // Residual too small for next item: mild penalty scaled by waste.
                score += 0.05 * (next_item_size - post_residual) as f64;
            }
        }

        // Last-chance bin: strongly favor using it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 8.0;
            // Extra reward if the fit is snug.
            score -= 0.1 * item_size as f64;
        }

        // Prefer bins below the mean residual (tighter bins first),
        // keeping larger residuals available for future large items.
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = fitting_bins_count as f64;
    let mut score = x * x * (1.0 + 2.0 * t) + 0.6 * x;

    // Smooth coupling: prefer tight fits more strongly as stream progresses.
    score += (1.0 - t) * (x - 0.5) * (x - 0.5) * 1.5;

    // Reward scarcity of fitting bins (last-chance placement).
    if fitting_bins_count <= 1 {
        score -= 3.0;
    } else {
        score -= 1.0 / fit;
    }

    // Lookahead: bonus if next item fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 1.2 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 0.8 * (nxt / cap);
        }
    }

    // Deviation from mean residual: penalize creating outliers (dead space).
    score += 0.5 * (x - mean_residual / cap).abs();

    // New-bin candidate (empty bin): post_residual = capacity - item_size.
    if bin_residual == bin_capacity {
        // Discourage opening a new bin unless it yields a very tight fit.
        score += 2.5 + 2.0 * (1.0 - item_size as f64 / cap);
        if open_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "awkward" residue classes (dead space) are penalized.
    let pr = post_residual;
    let class = pr / 10; // integer division: decile class of leftover
    let class_penalty = match class {
        0 => 12.0,                 // near-perfect fit, but tiny leftover -> dead space
        1 => -2.0,                 // 10..19 leftover: often reusable for small items
        2 => 1.5,
        3 => 3.0,
        4 => 4.5,                  // 40..49: classic awkward zone
        5 => 0.0,
        6 => -1.0,
        7 => 2.0,
        8 => 3.5,
        _ => 1.0,
    };
    score += class_penalty;

    // Modulo-3 / modulo-4 harmonic coupling: leftover divisible by common
    // item sizes is more likely reusable.
    if pr > 0 {
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 5 == 0 { score -= 1.5; }
        if pr % 3 == 0 { score -= 0.5; }
        if pr % 7 == 0 { score += 1.0; }
    }

    // Lookahead: reward leftovers that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + (next_item_size as f64) / 20.0;
    } else if next_item_size > 0 {
        // leftover cannot host next item: mild penalty scaled by gap
        let gap = (next_item_size - post_residual) as f64;
        score += 0.05 * gap.min(30.0);
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // With many alternatives, prefer tighter fills (lower post_residual already does this)
        score += 0.5 * ((fitting_bins_count as f64).ln().max(0.0));
    }

    // New-bin candidate handling: empty bin gets a base score near capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fits are bad.
        // Base penalty so a fresh bin usually loses to a decent fit:
        score = cap * 0.85 + (item_size as f64) * 0.1;
        // But if the item is huge relative to capacity, opening a bin keeps
        // future flexibility (large item leaves little waste anywhere anyway):
        if (item_size as f64) / cap > 0.7 {
            score -= 10.0;
        }
        // Early in the stream, having multiple bins helps flexibility:
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress) * (1.0 - progress);
        // If open bins are already crowded on average, new bin more attractive:
        score -= (mean_residual - cap * 0.2).max(0.0) * 0.3;
    }

    // Tight-fill bonus: reward near-exact fills.
    if post_residual <= 5 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Small global tie-breaker preferring bins with residual close to mean
    // (keeps population balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // for any realistic item (items >= 1, but tiny slivers under ~10 are
    // nearly dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Medium gaps (10..25) are risky: only small items can use them.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: small post_residual relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Pressure from number of open bins: prefer consolidating into
    // existing bins rather than spreading out.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean (they are the "fuller"
    // bins); leave emptier bins for larger future items.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // item is large (poor fit anywhere) or late in the stream where
    // spreading is safe.
    if bin_residual == bin_capacity {
        // Base handicap: opening a new bin is usually worse than using
        // an existing one.
        score += 35.0;
        // Large items justify a fresh bin (they leave big residuals anyway).
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // Early stream: opening bins early is cheap; late stream: consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If next item is large too, a fresh bin keeps a big contiguous space.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of next item into post-residual is gold.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0); // reward tight 2-step fits up to 60
        if post_residual == next_item_size {
            score -= 80.0; // exact two-item completion
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: dead space unless post_residual is tiny
        let dead = post_residual as f64;
        if dead > 0.0 && dead < 10.0 {
            score -= 15.0; // negligible waste is fine
        } else {
            score += dead * 0.35; // penalize stranded mid-size gaps
        }
    }

    // Reward filling bins tightly relative to mean residual.
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let rel = post_residual as f64 - mr;
    score += rel * 0.5; // prefer bins whose leftover is below average

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when this
    // item fits terribly anywhere (large post_residual waste avoided) or
    // stream is early (future flexibility valuable).
    if bin_residual == bin_capacity {
        let waste_here = post_residual as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let flexibility = (1.0 - progress) * 45.0;
        // A fresh bin is good if the item is huge (little waste) or many open bins
        let new_bin_bonus = 100.0 - waste_here * 0.9 + flexibility
            - (open_bins_count as f64) * 3.0;
        score = new_bin_bonus.min(score) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual relative to item size is better.
    if item_size > 0 {
        let tightness = (bin_residual - post_residual) as f64 / bin_residual as f64;
        score -= 18.0 * tightness;
    }

    // Penalize dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item cannot fit in the post residual,
    // this residual is likely dead space -> penalize proportionally.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
        } else {
            // Next item fits here: reward keeping this residual usable.
            score -= 4.0;
        }
    }

    // Last chance: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // When many bins are open, encourage consolidation into existing bins.
    score += 0.4 * open_bins_count as f64;

    // Global residual pressure: high mean residual means space is plentiful,
    // slightly favor reusing bins; low mean residual means scarcity.
    score -= 0.05 * mean_residual;

    // Early in the stream, be more willing to open bins (exploration);
    // later, consolidate (exploitation).
    if is_new_bin {
        let exploration = 1.0 - progress;
        score -= 20.0 * exploration;
        score += 8.0 * progress;
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Slight preference for bins whose residual is close to mean
    // (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;

    // Base: reward tight fits via smooth polynomial in post_residual
    let mut score = pr + 40.0 * (pr / cap).powi(2) + 60.0 * (pr / cap).powi(4);

    // Non-linear coupling of tightness with stream progress:
    // late in the stream, tight fits matter more (consolidate dead space)
    score -= 25.0 * fit_ratio * (1.0 - (pr / cap)) * (0.5 + progress);

    // Penalize creating dead space unusable by typical items (smooth barrier near small residuals)
    score += 10.0 * (-(pr / 10.0).powi(2)).exp() * (1.0 - fit_ratio);

    // Lookahead: penalize if next item cannot use the resulting residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0);
        score += 0.35 * waste * (1.0 - progress);
        // bonus if residual after placement exactly accommodates lookahead
        score -= 12.0 * (1.0 - ((pr - nx).abs() / cap).min(1.0)) * ((pr >= nx) as i32 as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * fit_ratio;
    } else {
        // mild penalty per competing bin to keep spread controlled
        score += 0.5 * (fitting_bins_count.min(20) as f64).ln().max(0.0);
    }

    // New-bin candidate: residual == capacity. Make it attractive only when
    // current residuals are large relative to the item (poor fits everywhere).
    if bin_residual == bin_capacity {
        let scarcity = ((mean_residual - item_size as f64) / cap).clamp(0.0, 1.0);
        score = cap + 20.0 - 60.0 * scarcity.powi(2) - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but heavily penalize unusable dead space.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    // Residuals in [1..=9] are "dead" (items are >= 10 in classic streams, but
    // interface allows 1..100, so treat < 5 as dead and small bands as classes).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    } else {
        // Classify post_residual by integer division into harmonic bands of capacity.
        let band = post_residual / 10; // 0..=10
        // Reward bands that align with common item-size classes (multiples of 10/25/50).
        let harmonic_bonus = match band {
            0 => 0.0,
            1 => 8.0,          // 10..19
            2 => 2.0,          // 20..29
            3 => 5.0,          // 30..39
            4 => 1.0,          // 40..49
            5 => 6.0,          // 50..59
            6 => 2.0,
            7 => 3.0,
            8 => 1.0,
            9 => 4.0,
            _ => 0.0,
        };
        score -= harmonic_bonus;

        // Exact-fill reward: item perfectly closes the bin.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Lookahead: does next_item_size fit in the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: this bin can host the next item too.
            let slack = post_residual - next_item_size;
            score -= 15.0 + (slack as f64).min(20.0) * 0.3;
        } else {
            // Next item won't fit here; penalize more if we're wasting a big residual.
            score += (post_f - next_item_size as f64).max(0.0) * 0.0; // handled by base
            score += 5.0 * ((post_residual as f64) / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        if post_residual >= 10 || post_residual == 0 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate (empty bin): only attractive when open bins are crowded
    // or the item leaves a very awkward residual in existing bins.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let mean_r = mean_residual;
        // Open a new bin if existing mean residual is small (bins nearly full)
        // or many bins are open (avoid fragmentation).
        if mean_r < 20.0 || crowd > 8.0 {
            score -= 30.0;
        } else {
            score += 15.0 + mean_r * 0.2;
        }
        // Never prefer a fresh bin when the item would fill it substantially
        // and other bins are loose.
        score += post_f * 0.1;
    }

    // Slight preference for filling fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (cap - post_f) * 0.05 * (0.5 + progress);

    // Mean-residual coupling: penalize bins far below mean residual
    // (keeps a spread of usable residuals across bins).
    score += (mean_residual - post_f).max(0.0) * 0.1;

    // Tie-break: prefer bins with larger current residual consumed ratio.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead space is wasted capacity
    }

    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host typical future items (>=10).
    if post_residual >= 10 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use this gap: dead space risk
        score += 12.0;
    }

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins, but allow
    // opening a new bin when current bins would create dead space.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate (empty bin): default slightly penalized so it is chosen
    // only when all open bins would produce poor fits (dead space).
    if bin_residual == bin_capacity {
        score += 20.0;
        // If no open bin fits, opening new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the next item is large and current mean residual is small,
        // reserving a fresh bin may help.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 8.0;
        }
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter packing).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Stream progression: early on, be more willing to open bins (flexibility);
    // late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // New-bin candidate: neutral baseline, mildly penalized so we only open
    // when existing bins look bad.
    if bin_residual == bin_capacity {
        score = cap * 0.75;
        // If the next item fits perfectly in the leftover of a fresh bin
        // pairing, encourage opening.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        return score;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Reward proportional to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit: penalize dead space that is small-but-unusable.
            let dead = next_item_size - post_residual;
            if dead <= 20 {
                score += 60.0 + dead as f64;
            }
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are precious,
    // prefer filling them; bins looser than mean can absorb waste.
    let diff = mean_residual - post;
    score -= 0.5 * diff;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize leaving very small unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mild preference for bins with larger residual generally (waste big bins first).
    score += 0.1 * (bin_residual as f64 - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic decay of score as post_residual shrinks.
    score -= (bin_capacity as f64 - post_residual as f64).sqrt() * 4.0;

    // Penalize large dead space relative to typical item size.
    if post_residual > 0 {
        score += (post_residual as f64 / 20.0).powi(2) * 0.5;
    }

    // Lookahead: reward if the next item exactly or nearly fits the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + gap);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // (poor chance of a better existing fit) or many bins are already open.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 8.0 * tightness;
        score += 6.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, discourage proliferation of barely-used bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += mean_residual * 0.15;
    }

    // Mild preference for filling bins that are already heavily loaded.
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Small time-varying jitter-free modulation to break ties toward diversity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (progress * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual with non-linear shaping (quartic)
    let mut score = x * x * (3.0 - 2.0 * x) * 100.0;

    // Polynomial coupling of post_residual with stream progress
    let coupling = (1.0 - progress) * (x * x * 40.0) - progress * (x * x * x * 30.0);
    score += coupling;

    // Penalize large post-residual early (wasted space), reward tight fits
    score += (1.0 - x).powi(3) * 25.0;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 18.0 * (1.0 - ((pr - nxt) / cap));
        } else {
            score += 8.0;
        }
    }

    // Mean-residual deviation penalty: prefer bins near the mean (balance)
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * 20.0;

    // Slight penalty for many open bins to discourage fragmentation
    score += (open_bins_count as f64) * 0.05 * progress;

    // New-bin candidate: make it moderately attractive only when open bins give bad fits
    if bin_residual == bin_capacity {
        score = 45.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the residual gap (dead-space analysis) ---
    // Residual gaps that cannot fit typical items are "dead space".
    // Class the post_residual into harmonic buckets via integer division.
    let gap_class = post_residual / 10; // harmonic decade class 0..=9
    // Small gaps (class 0-2) are near-perfect fits -> strong reward.
    match gap_class {
        0 => score -= 30.0,
        1 => score -= 22.0,
        2 => score -= 14.0,
        3 => score -= 6.0,
        4 => score -= 1.0,
        _ => {} // large gaps: no reward, baseline residual already penalizes
    }

    // --- Perfect fit bonus (modulo arithmetic on capacity fractions) ---
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        // gap is a multiple of 10 -> likely reusable by future items
        score -= 8.0;
    } else if post_residual < 10 {
        // tiny unusable sliver: dead space penalty
        score += 12.0;
    }

    // --- Lookahead: does next_item_size fit into the resulting gap? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain placement possible: reward proportionally to tightness
            let chain_waste = post_residual - next_item_size;
            score -= (20.0 - chain_waste as f64 * 0.25).max(4.0);
            // extra reward if the chained fit is exact
            if chain_waste == 0 {
                score -= 15.0;
            }
        } else if post_residual < next_item_size && post_residual > 0 {
            // gap blocks the known next item -> penalize if gap is small
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh empty bin: baseline score = full capacity worth of residual.
        // Prefer it only when no existing bin offers a decent fit.
        // Reward opening a new bin when the current item is large and
        // fitting options are scarce.
        score = bin_capacity as f64 * 0.9; // 90.0 baseline
        if fitting_bins_count <= 1 {
            score -= 25.0; // last chance: opening new bin is attractive
        }
        if item_size >= bin_capacity / 2 {
            score -= 10.0; // big items go well into fresh bins
        }
        // Early in stream, favor consolidation less; late, favor new bins
        // only if open bins are crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        // If mean residual across open bins is small, new bin is better
        score -= (mean_residual * 0.15).min(15.0);
    } else {
        // --- Existing bin: scarcity pressure ---
        if fitting_bins_count == 1 {
            // This is the only bin that can fit: strong reward to use it
            // rather than open a new bin.
            score -= 20.0;
        }
        // Prefer filling bins whose residual is closest to item (best fit
        // is implicit in post_residual, but reward using bins that are
        // already committed).
        score -= (bin_residual - post_residual) as f64 * 0.05;
        // Slight penalty for spreading across too many open bins
        score += open_bins_count as f64 * 0.3;
        // Reward bins below mean residual (more filled bins get priority)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any post_residual that is too small to be
    // usable by future items (typical items are >= 10, but be conservative)
    // is heavily penalized. Only exact fits (0) escape the penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver -> dead space
        } else if post_residual < 20 {
            score += 15.0; // marginal gap
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Make it attractive only when the current bin would leave a bad fit or
    // the item perfectly matches what an empty bin would give.
    if bin_residual == bin_capacity {
        // Neutral-ish base for a fresh bin; slightly discourage unless needed.
        score += 8.0;
        // If the next item is large, opening a fresh bin now is fine.
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Lookahead: if post_residual would exactly fit the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 10.0; // next item would create dead space here
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if next item exactly fits post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward scaled by tightness
            score -= 50.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: penalize leaving medium dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(60.0);
        }
    }

    // Compare post_residual relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new bin when decent fits exist, but allow it for large items
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus penalty proportional to wasted capacity of open bins
        score += 120.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // stacking large items together in a fresh bin
        }
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste of 0..10 is very desirable.
    if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 25 {
        score -= 6.0;
    }

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slightly penalize leaving a mid-size gap.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed
    // (no good existing option) or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 55.0;
        // Early in the stream, opening bins is cheaper.
        new_bin_score -= 35.0 * (1.0 - progress);
        // If many bins are open with slack, discourage new bins.
        new_bin_score += (open_bins_count as f64).ln().max(0.0) * 6.0;
        // If mean residual is large, existing bins likely suffice.
        new_bin_score += mean_residual * 0.3;
        // If only this bin can fit the item, opening a new bin is fine.
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        score += new_bin_score;
    }

    // Mild preference for filling fuller bins relative to the fleet average.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 2.0 * t * t - 2.0 * t + 1.0; // parabola in [0.5, 1.0]
    let mut score = base * (0.7 + 0.6 * poly);

    // Reward tight fits, more strongly early in the stream
    let tightness = 1.0 - pr / cap;
    score -= tightness * (1.0 - t) * 12.0 + tightness * t * 6.0;

    // Penalize dead space: unusable residual relative to smallest possible item
    let dead = pr / cap;
    score += dead * dead * 20.0;

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: prefer bins leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 4.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 6.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - tightness);

    // New-bin candidate: penalize slightly so it wins only on poor fits
    if (bin_residual as f64 - cap).abs() < 0.5 {
        score += 10.0 - 6.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class analysis of post_residual ---
    // Items create "dead space classes" based on post_residual mod small integers.
    // Residuals that divide evenly into common item sizes (harmonic residuals) are
    // more likely to be filled by future items, so reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        // Harmonic divisors: residuals divisible by these sizes are reusable.
        for d in [10u32, 20, 25, 50, 100] {
            if pr % d == 0 {
                harmony += 8.0;
            }
        }
        // Exact harmonic residual: subtract to favor bins leaving reusable space.
        score -= harmony;
        // Non-harmonic awkward residuals (prime-ish, odd chunks) get penalized.
        if pr % 10 != 0 && pr % 2 == 1 {
            score += 4.0;
        }
        // Very small dead space (< 10, minimum item) is pure waste.
        if pr < 10 {
            score += 15.0; // penalize, but base term already prefers small pr
        }
    } else {
        // Perfect fill is the ideal outcome.
        score -= 40.0;
    }

    // --- Integer-division threshold classes on post_residual ---
    let quarter = bin_capacity / 4;      // 25
    let half = bin_capacity / 2;         // 50
    if pr > half {
        score -= 6.0;  // bin still half-empty: flexible, keep it attractive
    } else if pr > quarter {
        score += 2.0;  // moderate leftover
    }

    // --- Lookahead coupling (k=2): does this bin also fit the next item? ---
    if next_item_size > 0 && pr >= next_item_size {
        // Chain fit: this placement keeps the bin usable for the next item.
        score -= 12.0;
        // Extra reward if next item exactly consumes the post-residual class.
        if pr == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > pr && next_item_size <= 100 {
        // Next item won't fit here; residual likely becomes dead space.
        score += 6.0;
    }

    // --- Last-chance logic: only one bin fits; strongly prefer using it ---
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many candidates: prefer tighter fits, mild competition penalty.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is good for large items that would waste an open bin,
        // bad for small items that should fill existing gaps.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score -= 10.0;   // large item: fresh bin is fine
        } else {
            score += 30.0;   // small item: must use existing space
        }
        // Early in stream, many bins will be needed anyway.
        if (step_index as f64) / (total_items.max(1) as f64) < 0.2 {
            score -= 5.0;
        }
    }

    // --- Mean residual coupling: if open bins are already loose, prefer
    //     consolidating into the emptiest-feeling viable bin ---
    if (post_residual as f64) > mean_residual {
        score += 1.0;
    } else {
        score -= 1.0;
    }

    // --- Stream progression: late in the stream, avoid opening bins and
    //     squeeze into anything that fits ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }
    // Unusable tiny dead space (1..10): heavy penalty
    else if post_residual < 10 {
        score += 45.0;
    }
    // Marginal gap (10..20): mild penalty
    else if post_residual < 20 {
        score += 12.0;
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer bins that stay useful (large post_residual)
    // so they can absorb future items; with few bins, tight fits are fine.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += open_bins_count as f64 * 1.5 * frac;

    // Lookahead: reward bins that can also host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a gap just below the next item's size (stranded dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }

    // Slight bias against opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leftover after hypothetically serving the next item too.
        let two_step_leftover = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.35 * two_step_leftover.min(60.0);
    } else if next_item_size > 0 {
        // Cannot serve the next item: penalize proportionally to how close we came (dead space).
        let gap = (next_item_size - post_residual) as f64;
        score += 0.8 * gap.min(80.0);
    }

    // Last-chance bin bonus: only bin that fits; avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when this bin would leave a tiny unusable sliver
    // or the bin is already very full and next item won't fit here anyway.
    if bin_residual == bin_capacity {
        let tight_fit = next_item_size > 0 && post_residual < next_item_size && post_residual < 10;
        let no_fitting_alt = fitting_bins_count == 0;
        if tight_fit || no_fitting_alt {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Slightly prefer bins below the mean residual (keeps residuals balanced).
    score -= 0.1 * (mean_residual - post_residual as f64);

    // Late in the stream, compactness matters more: reward fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 0.15 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: post_residual near 0 is ideal.
    score -= (1.0 - post / cap) * 20.0;

    // Penalize dead space that can't fit typical future items.
    if post > 0.0 && post < 10.0 {
        score -= 15.0; // nearly perfect fill
    } else if post >= 10.0 {
        // residual usability: penalize residuals that no small item (>=10) fits well
        let waste = post / cap;
        score += waste * waste * 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - ((post - nxt) / cap));
        } else {
            score += 6.0; // this placement strands the lookahead item
        }
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // spread load when many bins fit: prefer fuller bins
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Global state: prefer bins below mean residual (fill emptier bins) slightly,
    // but prefer keeping some slack diversity.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 8.0;

    // New-bin candidate handling: empty bin gets a base penalty so we only open
    // a new bin when fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // open new bin early in stream is cheaper (more items to fill it later)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
        // if current fit would leave large waste, new bin becomes attractive
        if post > 40.0 && item_size >= 10 {
            score -= (post - 40.0) as f64 * 0.5;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: reward tight fit via strongly convex penalty on post_residual.
    let norm_post = post / cap;
    let mut score = 2.0 * norm_post + 3.0 * norm_post * norm_post;

    // Non-linear coupling: tight fits matter more as the stream progresses.
    score += progress * 4.0 * norm_post * (1.0 - progress + 0.5);

    // Reward filling a bin nearly completely, amplified late in the stream.
    let fill_ratio = item / cap;
    score -= 1.5 * fill_ratio * fill_ratio * (0.5 + progress);

    // Penalize leaving dead space relative to the mean residual of open bins.
    score += 0.6 * ((post - mean_residual) / cap).abs() * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin, especially when the fit is decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.0 + 2.0 * (1.0 - norm_post);
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline neutral score; penalize opening new bins when many are already open.
        score = 1.2 + 0.05 * (open_bins_count as f64);
        // If next item is large, a fresh bin is more valuable.
        let next = next_item_size as f64;
        if next > 0.0 {
            score -= 0.8 * (next / cap) * (next / cap);
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 1.5 * progress * progress;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 1.0 * (1.0 - slack) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common small item sizes) are rewarded.
    let post = post_residual;
    if post > 0 {
        // Reward leftovers that are exactly reusable by typical item sizes.
        if post % 10 == 0 {
            score -= 6.0;
        } else if post % 5 == 0 {
            score -= 3.0;
        }
        // Penalize awkward dead zones: very small leftovers are wasted space.
        if post < 10 {
            score += (10 - post) as f64 * 0.8;
        }
        // Sweet spot: leftover in [15, 35] can host most incoming items.
        if post >= 15 && post <= 35 {
            score -= 4.0;
        } else if post > 60 {
            score += 2.0; // large leftover means this bin was underfilled
        }
    } else {
        // Perfect fill: strongly reward closing a bin exactly.
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement creates a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 10.0;
        } else if post > next_item_size {
            let gap = (post - next_item_size) as f64;
            score -= 3.0 * (1.0 - gap / cap).min(1.0);
        } else {
            // next item cannot follow here; mild penalty scaled by overflow
            score += ((next_item_size - post) as f64) * 0.05;
        }
        // Integer-division threshold: if next item shares a harmonic class
        // with post_residual (both multiples of 10), encourage the pairing.
        if next_item_size % 10 == post % 10 && post >= next_item_size {
            score -= 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the
    // stream is early (room to consolidate later) or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0; // base cost of consuming a fresh bin
        score -= 6.0 * (1.0 - progress); // cheaper to open bins early
        if open_bins_count == 0 {
            score -= 20.0; // must open when nothing is open
        }
        // If mean residual across open bins is small, packing is tight;
        // a new bin is more acceptable then.
        if mean_residual < item_size as f64 {
            score -= 4.0;
        }
    } else {
        // Prefer tighter fits generally: reward small post_residual relative
        // to bin capacity (best-fit flavor with harmonic shaping).
        let frac = post as f64 / cap;
        score += frac * frac * 4.0;
    }

    // Mild consolidation pressure: with many open bins, favor reusing them.
    if bin_residual != bin_capacity {
        score -= (open_bins_count.min(20) as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fill, extremely rare but best case
    } else if post_residual <= 10 {
        // unusable tiny gap: penalize proportionally to how wasteful it is
        score += 40.0 + 3.0 * (10 - post_residual) as f64;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        // or when the current bin could hold the next item too.
        let mut nb = 30.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            nb += 10.0;
        }
        // Late in the stream, opening new bins is cheaper to avoid
        // fragmenting; slightly reduce the penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb -= 10.0 * progress;
        score += nb;
    } else {
        // Existing bin that can also host the next item is very attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // This placement would strand a gap the next item can't use.
            score += 8.0;
        }
    }

    // Coupling with mean residual: prefer bins below the mean residual
    // (tighter bins) to consolidate fullness.
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect match reward: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match reward: next item fits tightly into remaining space.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - tightness / cap);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize, scaled by how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 8.0 * (miss / cap).min(1.0);
    }

    // Penalize dead space that is too small to hold typical future items.
    if post > 0 && post < 12.0 {
        score += 20.0;
    }

    // Reward bins whose residual is already below the mean (tight bins first).
    score += 0.15 * (mean_residual - post).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, avoid opening new bins: penalize the fresh-bin option.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * progress;
        // But a fresh bin is fine if it enables a perfect next-item match.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0;
        }
    } else {
        // Mild preference for filling existing bins as stream progresses.
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Superlinear penalty on wasted dead space
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * waste_frac * waste_frac * 25.0;

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys room for the next item
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Many open bins: prefer consolidating into existing space
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let mut new_bin_score = cap * 0.6 + post_residual as f64;

        // No open bin can fit the item -> must open a new bin
        if fitting_bins_count == 0 {
            new_bin_score -= 200.0;
        }

        // Large items justify fresh bins
        if item_size as f64 > cap * 0.6 {
            new_bin_score -= 25.0;
        }

        // Early in the stream: keep options open, mild new-bin bias
        let t = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += (1.0 - t) * 12.0;

        // If open bins already hold lots of residual space, avoid fragmentation
        new_bin_score += mean_residual * 0.25;

        // Lookahead: fresh bin accommodates next item comfortably
        if next_item_size > 0 && cap >= next_item_size {
            new_bin_score -= 6.0;
        }

        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: penalize remaining space, with polynomial coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear interaction: tight fits (small post_residual) rewarded more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize very small dead space that can't fit typical items (smooth polynomial)
    let dead = (pr_norm * (1.0 - pr_norm)).sqrt();
    score += 8.0 * (1.0 - dead) * (1.0 - dead);

    // Lookahead coupling: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let fit_next = (pr as f64 - next_norm * cap) / cap;
        let kernel = (fit_next * std::f64::consts::PI).cos();
        score -= 6.0 * kernel.max(-1.0) * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.3);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize slightly unless open bins are scarce or fit is bad
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 10.0 - 8.0 * scarcity - 5.0 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residues in (0,10) are unusable since items >= 1 but
    // tiny slivers waste capacity; harmonic class 0 (post_residual % 10 == 0)
    // is the most valuable residue class.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 3.0 * (10 - post_residual) as f64;
    }

    // Reward residues in harmonic class 0 (multiples of 10) — these align with
    // common item-size increments.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead reward: if the next item fits exactly into the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial lookahead bonus, stronger the tighter the chain.
        score -= 6.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Penalize leaving a residue that cannot host the next item when it is small.
    if next_item_size > post_residual {
        score += 4.0;
    }

    // New-bin candidate handling: opening a bin should be discouraged when
    // existing bins can fit, unless the existing fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for opening a new bin; grows with number of alternatives.
        let mut penalty = 15.0 + 4.0 * fitting_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        penalty += 10.0 * progress;
        // But if this bin would be the ONLY fitting option, opening a fresh bin
        // is fine — remove the alternatives penalty.
        if fitting_bins_count == 0 {
            penalty = 0.0;
        }
        // If the item fills the new bin nearly perfectly, encourage it.
        if post_residual <= 5 {
            penalty -= 20.0;
        }
        score += penalty;
    } else {
        // Last-chance bonus: if this is the only open bin that fits, strongly
        // prefer using it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Reward using bins whose residual is below mean (tighter bins first),
        // which consolidates small leftovers into fewer bins.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Mild bonus for very full bins (small residual relative to capacity).
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size
    // under classic assumption; use 1..10 band as dead zone) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 15.0;
    }

    // Penalize moderate dead space that is unlikely to fit the lookahead item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual > 0 && (post_residual as f64) < ni {
            score += 0.5 * (ni - post_residual as f64);
        } else if post_residual >= next_item_size {
            // Reward bins that can still host the next item.
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via open_bins_count term).
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate handling: empty bin gets a mild penalty so it is only
    // chosen when all open bins score badly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score += 6.0;
        // Early in the stream or when open bins are congested, new bins are cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (1.0 - progress);
    }

    // Slight preference for bins tighter than average (good consolidation).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // exact match: big reward
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // penalize leftover that next item cannot use well
            score += 0.35 * diff;
            // if next item fits exactly into post_residual region, mild bonus scaled
            if next_item_size <= post_residual {
                score -= 8.0 * (1.0 - diff / (bin_capacity as f64));
            } else {
                // dead space the next item can't use
                score += 0.25 * (post_residual as f64);
            }
        }
    }

    // Penalize tiny unusable residuals (dead space) below minimum plausible item size
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Tight fit bonus: small post_residual relative to item size is good
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Prefer bins with below-mean residual (concentrate filling)
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.15 * (mean_residual - res);
    } else {
        score += 0.10 * (res - mean_residual);
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let good_open = open_bins_count > 0 && fitting_bins_count > 0;
        if good_open {
            // discourage opening a new bin when existing bins can fit
            score += 30.0 + 0.5 * (post_residual as f64);
        } else {
            score -= 15.0;
        }
    }

    // Slight preference for filling bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
