    let mut score = post * (1.0 + norm_post * norm_post * (1.0 - progress));

    // Tight-fit reward: smooth quadratic coupling of post_residual with item size
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * item_size as f64 * 0.5;

    // Last-chance bonus: only one bin fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * 0.75;
    } else {
        // Smooth scarcity penalty
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += scarcity * post * 0.25;
    }

    // Mean residual coupling: penalize bins whose residual deviates above the mean
    score += (post - mean_residual).abs() * 0.3 * (1.0 - progress);

    // Lookahead: reward if next item can fit the post residual
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= fits_next * next_item_size as f64 * 0.4;
    }

    // New-bin candidate: mildly penalize opening a new bin early, more later
    if bin_residual == bin_capacity {
        score += cap * (0.5 + 0.5 * progress);
    }

    // Open-bin count pressure: many open bins -> encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: mod classes determine dead-space quality
    let pr = post_residual;
    // Residuals that are exact multiples of small item-friendly classes (mod 10) are reusable
    let mod10 = (pr % 10) as f64;
    score += 2.0 * mod10; // penalize non-aligned residuals

    // Perfect zero residual is ideal
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        // tiny residual: near-perfect fill, but wastes little
        score -= 20.0;
    } else if pr < item_size {
        // residual smaller than current item: dead space unless future small item fits
        score += 8.0;
    }

    // Harmonic threshold classes on post_residual via integer division
    let class = pr / 25; // 0,1,2,3 classes
    score += match class {
        0 => -5.0,  // 0..24: very tight
        1 => 0.0,   // 25..49
        2 => 5.0,   // 50..74
        _ => 12.0,  // 75..99: wasteful
    };

    // Lookahead: does next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chainability reward, stronger when it's a good chain fit
            let chain_waste = (pr - next_item_size) as f64;
            score -= 25.0 - 0.3 * chain_waste;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current open bins are very full
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // default penalty for new bin
        score += 55.0;
        // if open bins are nearly full (low mean residual), new bin is fine
        score -= 40.0 * (1.0 - pressure);
        // early stream: be more willing to open bins
        score -= 10.0 * (1.0 - progress);
        // if next item is large and no bin can chain, new bin attractive
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 15.0;
        }
    }

    // Slight preference to consolidate: fewer open bins is better when fits exist
    if bin_residual < bin_capacity {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 2.0 * pressure;

    // Prefer bins with below-average residual (fill emptier bins first).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Lookahead: if next item could use the post-residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item almost fills the bin afterwards.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Reward decays with distance to the lookahead size.
        score -= 40.0 / (1.0 + gap * 0.15);
        // Penalize leaving a sliver that the next item can't use (dead space).
        if gap < next_item_size as f64 {
            score += gap * 0.3;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Residual too small for the lookahead: mild penalty proportional to wasted space.
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Compare post_residual against the mean residual of open bins.
    // Prefer bins whose post-residual stays near/below the mean (tight packing).
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.35;

    // Last chance: this is the only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer reusing tight ones rather than spreading out.
    if open_bins_count > 3 {
        score += 0.1 * open_bins_count as f64;
    }

    // New-bin candidate: neutral-ish baseline, but acceptable for large items
    // that would otherwise leave poor fits in existing bins.
    if bin_residual == bin_capacity {
        // Opening a new bin: score = capacity minus item, i.e. the space it locks up.
        score = (bin_capacity - item_size) as f64;
        // If lookahead fits exactly in a fresh bin, opening is attractive.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 30.0;
        }
        // Late in the stream with many bins, avoid unnecessary new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.5 && fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to relax/tighten behavior over time.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead reward: if the next item can fit into the post residual,
    // reward this placement (keeps chains of fits alive).
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 8.0 + 12.0 * tightness;
    }

    // Lookahead penalty: if next item does NOT fit in post residual but would
    // fit in a fresh bin, penalize leaving a large awkward residual.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Penalize placing small items into bins with large residuals when other
    // options exist (waste of a big residual on a small item).
    if item_size < 30 && post_residual > 50 && fitting_bins_count > 1 {
        score += 10.0;
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (fill the tightest bins first), scaled by number of open bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= residual_gap * 0.3;

    // Mild penalty for opening new bins when several bins already fit the item.
    if bin_residual == bin_capacity {
        let new_bin_penalty = if fitting_bins_count > 1 { 15.0 + 10.0 * (fitting_bins_count as f64).ln() } else { 5.0 };
        score += new_bin_penalty;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 20.0 * (1.0 - progress);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Dead space threshold: residuals below 10 are nearly useless.
        score -= 15.0;
    }

    // Tie-break: prefer bins with lower index effect via open_bins_count
    // (slightly prefer consolidating into fewer bins).
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: quadratic bonus shrinking post_residual.
    score -= (pr / cap) * (pr / cap) * 8.0;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (1.0 + progress);
        } else {
            // Slack that leaves room for next item is mildly rewarded.
            score -= (pr - ni).min(20.0) * 0.3;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin late in stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize early, allow late when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 12.0 * (1.0 - progress) - 10.0 * fragmentation * progress;
    }

    // Non-linear coupling: residual spread vs mean residual interaction.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 4.0 * (1.0 - progress);

    // Mild open-bin pressure: fewer open bins favored as stream progresses.
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // leaves a "harmonically useful" residual that pairs well with small items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Dead-space classes: residuals that are hard to fill (mod 10 residue 1..3)
        let dead = post_residual % 10;
        let dead_penalty = if post_residual > 0 && dead <= 3 { 12.0 } else { 0.0 };
        score += 8.0 + progress * 6.0 + dead_penalty;
        // Slightly favor opening new bin when the item is large (tight fit expected)
        score -= (item_size / 20) as f64;
        return score;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    }

    // Harmonic class of post_residual modulo 10: residues 0 and 5 are the most
    // reusable (items commonly sized in multiples of 5/10).
    let residue = post_residual % 10;
    match residue {
        0 => score -= 10.0,
        5 => score -= 7.0,
        1 | 2 | 3 => score += 6.0, // awkward slivers -> penalize
        _ => {}
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual
    // (or leaves a good class again), reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nr = (post_residual - next_item_size) % 10;
            if nr == 0 { score -= 12.0; }
            else if nr == 5 { score -= 8.0; }
            else if nr <= 3 { score += 5.0; }
        } else {
            // Next item cannot follow in this bin: mild penalty if bin would be stranded
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fills (lower post_residual dominates anyway).
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Prefer bins with residual far below the mean (denser bins first).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Integer-division thresholds: bins whose residual is in the "large-item
    // band" (>= 80) are valuable; penalize wasting them on small items.
    if bin_residual >= 80 && item_size < 30 {
        score += 10.0;
    }
    if bin_residual / 2 >= item_size && post_residual >= 40 {
        score += 4.0; // keeps half-capacity usable, mild preference to not overfill dense bins
    }

    // Late-stream tightening: as the stream progresses, prefer exact-class fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (20.0 - post_residual.min(20) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residual that can still host a typical future item.
    if post_residual >= 10 {
        score -= 6.0;
    }
    // Penalize residuals that are too small for the lookahead item if lookahead exists.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward residuals that can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: default mild preference; only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 2.0 - mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score = 10.0; // forced new bin anyway
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Late-stream tightening: as stream progresses, prefer tighter fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tightest fit (smallest post_residual).
    let progress: f64 = step_index as f64 / total_items.max(1) as f64;

    // --- 2-step lookahead: reward bins whose post_residual matches next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            // Perfect chain: next item fits exactly in the leftover space.
            let gap = (pr - nxt).abs();
            let chain_bonus = if gap < 1.0 {
                45.0
            } else {
                30.0 * (1.0 - gap / bin_capacity as f64)
            };
            score -= chain_bonus;
            // Extra reward if next item exactly consumes the residual (bin closes).
            if gap < 1.0 {
                score -= 10.0;
            }
        } else if post_residual == 0 {
            // Bin perfectly closed: excellent.
            score -= 25.0;
        } else {
            // Next item does NOT fit: leftover may be dead space; penalize
            // proportionally to how small/awkward the residual is.
            let waste = pr / bin_capacity as f64;
            if pr < 10.0 {
                score += 18.0 * (1.0 - pr / 10.0); // tiny sliver = dead space
            } else {
                score += 6.0 * waste;
            }
        }
    } else {
        // Last item: just close bins as tightly as possible.
        score -= 20.0 * (1.0 - pr_safe(post_residual, bin_capacity));
    }

    // --- Relative-to-mean coupling: prefer bins tighter than the average ---
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res_f - mean_residual) / mean_residual.max(1.0);
        // A bin with residual below mean is already tight; using it keeps
        // big-residual bins flexible. Reward using tighter-than-average bins.
        score -= 8.0 * (-rel).max(0.0);
        score += 5.0 * rel.max(0.0);
    }

    // --- Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin (avoid bin proliferation). ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // --- New-bin candidate handling: empty bin should only win when no
    // open bin offers a decent fit. Make the empty bin moderately
    // unattractive so tight fits in existing bins dominate. ---
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
        // But if many open bins exist and none fits well, allow new bin:
        // (fitting_bins_count == 0 case is handled by caller loop; here we
        // soften penalty late in the stream when mean residual is large).
        if mean_residual > 0.5 * bin_capacity as f64 && open_bins_count > 3 {
            score -= 25.0;
        }
    }

    // --- Late-stream consolidation: favor reusing bins as stream ends. ---
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for leaving residuals that are hard-to-fill odd sizes.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 4.0;
    }

    score
}

#[inline]
fn pr_safe(post_residual: u32, cap: u32) -> f64 {
    1.0 - post_residual as f64 / cap.max(1) as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        let fit_ratio = post_residual as f64 / bin_capacity as f64;
        score -= 25.0 * (1.0 - fit_ratio * fit_ratio);
    }

    // Penalize creating dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_tightness = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - lookahead_tightness / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here after placement; slight penalty unless this is a near-perfect fit now.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: penalize opening a new bin, more so early in the stream
    // or when many bins are already open (fragmentation risk).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 20.0 + 15.0 * (1.0 - progress);
        if open_bins_count > 0 {
            new_bin_penalty += 5.0 * (open_bins_count as f64).ln();
        }
        // Allow new bin only when the item is large relative to capacity (poor fit anywhere).
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item {
            new_bin_penalty -= 18.0;
        }
        score += new_bin_penalty;
    }

    // Prefer bins whose residual is below the mean residual (filling fuller bins first).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 4.0 * (mean_residual - residual_f) / bin_capacity as f64;
    } else {
        score += 3.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Mild pressure to keep the number of open bins from exploding.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer tight fits, penalized non-linearly with progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial coupling: small post-residuals are increasingly valuable
    // as the stream progresses (dead space costs compound late).
    let tight = 1.0 - prn;
    score -= 30.0 * tight * tight * (0.5 + progress);

    // Interaction of post_residual with mean residual: avoid bins far from mean.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item can use the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: smooth penalty that relaxes when open bins are poor fits.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 + 15.0 * (1.0 - progress) + crowding;
    }

    // Mild penalty for many open bins, smoothed by progress.
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity fractions (C=100)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual % (bin_capacity / 4); // quarter-capacity harmonic class
    let class_bonus = match class {
        0 => 12.0,                 // perfectly aligned quarter: great dead-space profile
        1..=4 => 6.0,              // near-aligned
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: tiny unusable residue is dead space
    if post_residual > 0 && post_residual < bin_capacity / 20 {
        score += 15.0; // 1..5 residue is nearly worthless
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Waste fraction coupling (non-linear)
    let waste_frac = pr / cap;
    score += 10.0 * waste_frac * waste_frac;

    // Last chance: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        }
        // If next item cannot fit here anyway, mild penalty for leaving medium gap
        if next_item_size > post_residual && post_residual > bin_capacity / 2 {
            score += 5.0;
        }
    }

    // New-bin candidate logic: only open a new bin when fit is poor or item huge
    if bin_residual == bin_capacity {
        let fit_tightness = item_size as f64 / cap;
        let pressure = open_bins_count as f64 / (mean_residual / cap).max(0.5);
        let late = step_index as f64 / (total_items.max(1) as f64);
        // opening is attractive when item is large and mean residual is fragmented
        let open_bonus = 10.0 * fit_tightness * pressure + 5.0 * late;
        if item_size >= bin_capacity / 2 && mean_residual < item_size as f64 * 0.6 {
            score -= open_bonus;
        } else {
            score += 30.0; // discourage opening when existing bins can absorb
        }
    }

    // Prefer fuller bins (small residual before placement)
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals that are too small to be useful later
    // (typical items are >= 1..=100, so tiny gaps waste capacity).
    if post_residual > 0 {
        let usable_threshold = 10.0_f64.max(next_item_size as f64);
        if (post_residual as f64) < usable_threshold {
            score += 60.0 * (1.0 - (post_residual as f64) / usable_threshold);
        }
        // Non-linear penalty for medium-tight gaps (awkward to fill)
        if post_residual <= 30 {
            score += 0.5 * (30.0 - post_residual as f64).powf(1.2);
        }
    }

    // Reward tight fits: filling a bin almost exactly is excellent
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should be costly unless the
    // current item fits poorly everywhere (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are already open
        score += 35.0 + 2.0 * open_bins_count as f64;
        // But a new bin is attractive if the item is large and would leave a bad gap
        if item_size >= 60 {
            score -= 30.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 20.0;
        }
        // Early in the stream, cheap to open bins (more freedom later)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Open-bins pressure: prefer denser packing when many bins are open
    if bin_residual != bin_capacity {
        score -= 1.5 * mean_residual.min(50.0) / 10.0;
    }

    // Lookahead synergy: reward leaving a gap that exactly fits the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (tight packing).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item fits the post-residual,
    // this placement chains perfectly — heavily reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual that is just barely too small for next item
        // (unusable dead space relative to the lookahead).
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 80.0;
        }
    }

    // Relative-to-mean coupling: bins with residual above mean can absorb
    // slack more safely; bins below mean should be filled tightly.
    let res = post_residual as f64;
    if res > mean_residual {
        score -= (res - mean_residual).min(50.0) * 0.5;
    } else {
        score += (mean_residual - res) * 0.3;
    }

    // Last chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fit win; relax late in stream
        // or when many bins are open and mean residual is small.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let relax = 60.0 * progress + 0.4 * (open_bins_count as f64);
        score += 250.0 - relax;
        // If next item is huge and current item is small, a fresh bin is fine.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 50.0;
        }
    }

    // Discard splitting a bin that could hold the next item almost exactly.
    if next_item_size > 0 && post_residual < next_item_size && bin_residual >= next_item_size + item_size {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward snug fits: bins whose residual is mostly consumed.
    let fill_ratio = 1.0 - post / cap;
    score -= 2.5 * fill_ratio * item;

    // Lookahead (k=2): penalize residuals that cannot host the next item,
    // reward residuals that can (keeps the bin reusable).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            score += 1.5 * (nxt - post);
        } else {
            score -= 4.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 0.5 * item;
    }

    // Penalize candidate new bins, unless the item is very large relative to
    // the mean residual of open bins (poor fit everywhere -> better to open).
    if bin_residual == bin_capacity {
        let mismatch = (item - mean_residual).max(0.0);
        score += 12.0 + 0.3 * open_bins_count as f64 - 0.2 * mismatch;
    }

    // Late in the stream, prioritize consolidation: shrink scores of existing
    // bins slightly so filling them beats opening new ones.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill_ratio = item / cap;
    let post_norm = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, keep bins flexible (penalize tiny leftovers);
    // late in the stream, packing tightly matters more.
    let tightness = 1.0 - post_norm;
    let flexibility_cost = 4.0 * post_norm * (1.0 - post_norm) * (1.0 - progress);
    score += flexibility_cost;

    // Reward high fill ratio, scaled smoothly by progress.
    score -= 6.0 * fill_ratio * fill_ratio * (0.5 + progress);

    // Dead-space penalty: very small leftovers are wasted unless the bin is nearly full.
    let dead_threshold = 10.0;
    if post > 0.0 && post < dead_threshold {
        let sev = (dead_threshold - post) / dead_threshold;
        score += 8.0 * sev * sev * (1.0 - tightness * tightness);
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 5.0 * (1.0 - (nxt / post.max(1.0) - 0.5) * (nxt / post.max(1.0) - 0.5)) * (0.4 + 0.6 * progress);
        } else {
            // Next item won't fit here; mild penalty proportional to gap.
            score += 2.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so it is only
    // chosen when all open bins score poorly (e.g. would leave large dead space).
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
        // Opening a new bin is more attractive when many bins are open and mean residual is low.
        score -= (open_bins_count as f64).sqrt() * 1.5;
        score -= mean_residual / cap * 4.0;
    }

    // Mild penalty for spreading across many bins early (encourages consolidation).
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // residual fraction of capacity

    // Dead-space classes: tiny unusable residuals are good (perfect fit),
    // mid-range residuals are wasteful unless they can host a future item.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 35.0; // near-perfect, likely dead space is small
    } else {
        // Harmonic penalty: residual in (10, 20) is a "bad band" — too small
        // for most items but wastefully large.
        if post_residual < 20 {
            score += 25.0;
        }
        // Classify residual by which item-size harmonic class it can host.
        // Items 1..=100; key thresholds at 25, 34, 50, 67, 100.
        let hostable = if post_residual >= 80 { 4.0 }
            else if post_residual >= 67 { 3.0 }
            else if post_residual >= 50 { 2.0 }
            else if post_residual >= 34 { 1.0 }
            else if post_residual >= 25 { 0.5 }
            else { 0.0 };
        score -= 12.0 * hostable;
    }

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match bonus scaled by tightness of the future fit.
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 20.0 + 15.0 * tight;
        } else {
            // Next item won't fit here; penalize if we leave a wide gap.
            let gap = (post_residual - next_item_size) as f64;
            if gap > 0.0 {
                score += 0.15 * gap;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // badly everywhere (high post_residual elsewhere means bad fit).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: roughly the wasted space implied.
        score += 55.0 + 0.3 * (open_bins_count as f64);
        // If item exactly fills a large chunk, a fresh bin is attractive.
        let f = item_size as f64 / cap;
        if f > 0.85 {
            score -= 45.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Prefer tighter bins overall: reward placing into below-mean-residual bins.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 8.0 * (mean_residual - bin_res_f) / cap;
    } else {
        score += 4.0 * (bin_res_f - mean_residual) / cap;
    }

    // Modulo harmonic on post_residual: residuals congruent to small
    // multiples of 10 are reusable by common item sizes.
    let m = post_residual % 10;
    score -= 3.0 * (m as f64) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 0.4 * open_bins_count as f64;

    // Prefer bins with below-average residual (concentrate filling).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits in the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would NOT fit in post-residual but post-residual is small, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // New-bin candidate: baseline attractiveness so it's chosen only when
    // open bins offer poor fits (their scores lowered by bonuses above).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // Opening early in the stream is cheaper long-term.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 2.0 * tightness * (bin_capacity as f64);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: bin fully consumed by next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how close next item gets to filling the bin
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize dead space more strongly
            let waste = post_residual as f64;
            score += 0.5 * waste * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Compare against mean residual: bins tighter than average are more valuable
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 5.0 * (rel - 1.0).min(3.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin, especially early in the stream or when
    // open bins have plenty of residual space
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 + 20.0 * (1.0 - progress);
        if open_bins_count > 0 {
            score += 15.0;
        }
        // still allow new bin if current item is large and would leave bad residue elsewhere
        if item_size >= 60 {
            score -= 25.0;
        }
    }

    // Mild penalty for very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Tight-fit reward: heavily favor small post residuals (non-linear).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
