        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    if is_new_bin {
        // Penalize opening a new bin, more so when alternatives exist.
        score += 15.0 + 10.0 * (fitting_bins_count as f64).min(4.0);
        // Early in the stream, allow new bins more freely (future packing potential).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 12.0 * (1.0 - progress);
