        score += 0.05 * mean_residual;
    } else {
        // Lookahead: penalize leaving a residual that barely fails to fit the next item,
        // reward residuals that can accommodate it.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if (post_residual as f64) >= nxt {
                score -= 6.0;
            } else if (post_residual as f64) >= nxt * 0.6 {
                score += 3.0; // awkward leftover that nearly fits
            }
        }
        // Prefer placing into bins with more residual (consolidate slack) mildly.
        score -= 0.02 * (bin_residual as f64);
    }

    // Mild preference to spread across bins when many are open and mean slack is high.
    if mean_residual > (item_size as f64) * 1.5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: prefer bins that end with small post_residual (tight fit).
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Later in the stream, dead space becomes more costly (fewer chances to fill it),
    // so weight post_residual quadratically with progress.
    let p2 = progress * progress;
    score += 0.35 * p2 * post * (post / cap);
    score += 0.15 * p2 * post;

    // Reward very tight fits (post_residual near zero) with a smooth saturating term.
    let tightness = 1.0 - (post / cap);
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize leaving a residual that is awkwardly large relative to the mean residual
    // of open bins (smooth interaction).
    let dev = (post - mean_residual) / cap;
    score += 2.0 * dev * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, strongly encourage using it
    // rather than opening a new bin (smooth in fitting_bins_count).
    if fitting_bins_count >= 1 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 6.0 * scarcity * (1.0 + p2);
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fits_next = (post >= nxt) as i32 as f64;
        score -= 5.0 * fits_next * (1.0 - gap / cap).max(0.0);
        // Penalize post_residual just barely below next item (blocking lookahead).
        let block = ((nxt - post) / cap).max(0.0);
        score += 3.0 * block * (block > 0.0) as i32 as f64 * (1.0 - p2);
    }

    // New-bin candidate handling: brand-new empty bin (residual == capacity).
    // Prefer opening a new bin only when no open bin offers a decent fit,
    // i.e. when the best alternative would leave large dead space. Encode by
    // penalizing the new bin mildly, more so early in the stream.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 10.0 * (1.0 - p2) + 4.0;
        // If many bins are already open and mean residual is large, discourage new bin further.
        score += 0.05 * open_bins_count as f64 * (mean_residual / cap);
    } else {
        // Mild reward for keeping bins balanced (avoid many nearly-empty bins).
        score -= 1.5 * (1.0 - (residual - mean_residual).abs() / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual (mod 10 buckets): prefer residuals
    // that fall in "usable" classes (>=10 chunks align with typical item sizes).
    let class = (post_residual % 10) as f64;
    score += class * 0.6; // penalize ragged remainders

    // Reward large aligned residuals (multiples of 10) strongly.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Tight fit reward: small post residual is good, but not dead space.
    if post_residual <= 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residual too small for any future item (min size 1).
    if post_residual > 0 && post_residual < 4 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits: mild reward scaled by leftover after next.
        let post2 = post_residual as i64 - next_item_size as i64;
        score -= 6.0 + (post2 % 10) as f64 * 0.3;
    } else {
        // next item won't fit here: penalize a bit more if residual is large.
        score += 4.0 + post_residual as f64 * 0.02;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only when fit is terrible (huge leftover) or no real alternative.
        let leftover = post_residual as f64;
        score += 18.0 + leftover * 0.5;
        if fitting_bins_count <= 1 {
            // only this new bin fits -> it's forced anyway
            score -= 30.0;
        }
        // early in stream, opening bins is cheaper; late, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Slight preference for bins below mean residual (spread load evenly).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: residual equals capacity means an empty bin.
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Prefer opening a new bin only when no good fit exists elsewhere.
        // If other bins fit, make the new bin mildly unattractive so tight
        // fits win; if this is the only fitting option, make it attractive.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        } else {
            score += 25.0;
        }
        return score;
    }

    // Strict dead-space avoidance: small leftover gaps are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger residuals are reusable; reward them.
        score -= 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // If the next item would fit exactly into the post-residual, reward it
    // (chain packing), otherwise penalize leaving a gap the next item
    // cannot use.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage scattering items across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Early in the stream, allow slightly more bin spreading; later, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0;

    // Relative tightness against mean residual of open bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= next {
            let slack = pr - next;
            // Perfect handoff to next item.
            if slack < 5.0 {
                score -= 150.0 - slack * 10.0;
            } else {
                // Proportional reward decaying with slack.
                score -= 60.0 * (1.0 - slack / (bin_capacity as f64)).max(0.0);
            }
        } else {
            // Next item can't fit here; penalize slightly to prefer bins
            // that keep future flexibility, scaled by stream progress.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 20.0 * (0.5 + 0.5 * progress);
        }
    }

    // Relative-to-mean adjustment: prefer bins tighter than average residual
    // (packing into fuller bins preserves open capacity elsewhere).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // among open bins (penalize by default, discount late in stream or
    // when item is large relative to capacity).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 30.0 - 25.0 * item_frac + 5.0 * pressure;
        // Late in stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Mild preference for filling already-open bins over proliferation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual), superlinear.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: penalize if post_residual cannot fit the next item but is
    // still large enough to be "wasted" dead space; reward if next item fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual >= 10 {
            // dead space too small for next item (min item size 10)
            score += 0.8 * post_residual as f64;
        }
        // Reward chain: post_residual fits next item AND next residual then fits nothing (good compaction)
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 18.0;
        }
    }

    // Last chance: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only prefer opening a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with reasonable fit win.
        score = bin_capacity as f64 * 0.9 + 25.0;
        // If current fit is terrible (post_residual tiny but nonzero dead space)
        // relative to item, opening a fresh bin becomes attractive.
        let waste_ratio = if post_residual < 10 { 1.0 } else { 0.0 };
        if waste_ratio > 0.0 {
            score -= 30.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If many open bins with big mean residual, new bin less needed.
        score += 0.15 * open_bins_count as f64 + 0.05 * mean_residual;
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild global pressure: when many bins are open, discourage spreading.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight time decay: early on, be a bit more tolerant of imperfect fits
    // (exploration), later be strict.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling: tighter fits (low post_residual) rewarded more later in stream.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 40.0 * progress) * (item_size as f64 / cap);

    // Penalize large dead space superlinearly, scaled by stream progress.
    score += norm_pr * norm_pr * 25.0 * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when other bins fit.
    if bin_residual == bin_capacity {
        let penalty = 15.0 + 25.0 * (1.0 - progress);
        score += penalty + (fitting_bins_count as f64) * 8.0;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - progress);
    }

    // Mild dispersion penalty: prefer bins near mean residual to keep options balanced.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (mean_residual + 1.0);

    // Crowding: slight penalty when many bins are open and fit is loose.
    if open_bins_count > 2 {
        score += 0.02 * (open_bins_count as f64) * norm_pr * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space non-linearly.
    let frac = post_residual as f64 / cap;
    score += 12.0 * frac * frac;

    // Harmonic class: how well post_residual decomposes into small "friendly" chunks.
    // Residuals divisible by small sizes (5,10,20,25) are more reusable.
    let pr = post_residual;
    let harmony_bonus: f64 = if pr == 0 {
        -20.0
    } else {
        let mut h = 0.0;
        if pr % 5 == 0 { h += 2.0; }
        if pr % 10 == 0 { h += 2.5; }
        if pr % 20 == 0 { h += 3.0; }
        if pr % 25 == 0 { h += 3.5; }
        if pr % 50 == 0 { h += 4.0; }
        // Small residuals (< 10) are dead space unless exactly 0.
        if pr < 10 { h -= 15.0; }
        else if pr < 20 { h -= 5.0; }
        h
    };
    score -= harmony_bonus;

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // Partial credit, scaled by how much slack remains after next item.
            let after2 = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - after2 / cap);
        } else {
            // Next item cannot use this residual: penalize large wasted residuals.
            score += 3.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New empty bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - item_size as f64 / cap);
        // But if item is huge and mean residual is small, opening a bin is fine.
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 22.0;
        }
    }

    // Mild preference for bins below mean residual (pack fuller bins together).
    score += 1.5 * (bin_residual as f64 - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space avoidance: residuals too small for the smallest plausible item
    // (items in 1..=100, but tiny scraps are rarely useful) are penalized hard.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Mid-range dead space (10..=25) is moderately wasteful.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // If the lookahead item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap < 10 {
            score -= 15.0;
        }
    }
    // Lookahead cannot use the leftover: penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above using an existing bin,
        // rising with open_bins_count pressure but easing late in the stream.
        score = 100.0 + 2.0 * open_bins_count as f64 - 30.0 * progress;
        // If the item is large relative to residual, new bin is natural.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // If existing bins are fragmented (high mean residual but many bins),
        // opening fresh is less costly.
        if mean_residual > 40.0 && open_bins_count > 4 {
            score -= 25.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> very strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still fit the next item: mild reward proportional to fit quality.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead: penalize unusable leftovers.
        score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Compare bin residual against mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Small post-residuals are good (dense packing) unless they are dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    // Late in the stream, be more conservative: penalize very small leftovers harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && post_residual < next_item_size {
        score += 10.0 * progress;
    }

    // New-bin candidate: keep its score near baseline so it only wins when open bins
    // would create large dead space relative to the lookahead.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.3 * mean_residual - 0.2 * next_item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (low post_residual) is good.
    // Penalize very small post_residual that becomes unusable dead space
    // unless the next item can use it (lookahead).
    let dead_threshold = 9u32; // min item size is 1..100, but keep flexible
    if post_residual > 0 && post_residual <= dead_threshold {
        let usable = next_item_size > 0 && next_item_size <= post_residual;
        if !usable {
            score += 40.0; // unusable sliver
        }
    }

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if (post_residual as f64) < 0.08 * bin_capacity as f64 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use this bin's remainder; slight penalty
            // proportional to wasted potential.
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many fitting bins: we can afford to be choosy; add small penalty
    // to bins with average residuals to encourage spread of tight fits.
    if fitting_bins_count > 1 {
        let fit_bonus = ((fitting_bins_count as f64) - 1.0).min(5.0);
        score += fit_bonus * 0.5 * (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized by default so we prefer existing bins,
        // but if the item is large and existing fits are poor, allow it.
        let mut open_penalty = 55.0;
        // If item is large relative to capacity and would leave awkward residue
        // in typical bins, reduce penalty.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            open_penalty -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        open_penalty += progress * 15.0;
        // If only one fitting bin exists, avoid opening new bins.
        if fitting_bins_count <= 1 {
            open_penalty += 40.0;
        }
        score += open_penalty;
    }

    // Global state: if mean residual is high, bins are loose; prefer bins
    // whose residual is below mean (tighter bins) to keep loose bins available.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 0.15;
    }

    // Mild penalty for placing into nearly-full bins when many bins are open,
    // to preserve bin-count minimization pressure via tighter packing.
    let load = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += load * load * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual (lower is better fit)
    let mut score = pr;

    // Non-linear polynomial shaping of residual: strongly penalize mid-range waste,
    // mildly reward near-full packing.
    let x = pr / cap;
    score += 18.0 * x * (1.0 - x) * (1.0 - x);

    // Smooth interaction: residual waste penalty grows with stream progress.
    score += pr * progress * 0.35;

    // Coupling with mean residual: prefer bins deviating below mean (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64).abs() * 0.25;
    score -= 0.3 * (bin_residual as f64 - mean_residual).max(0.0) * (1.0 - progress);

    // Lookahead: reward residual that can fit the next item (smooth, not piecewise).
    let nis = next_item_size as f64;
    if nis > 0.0 {
        let fit_margin = (pr - nis) / cap;
        score -= 6.0 * (fit_margin.max(-1.0).min(1.0) + 1.0) * 0.5 * (1.0 - fit_margin.abs().min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Slight penalty for opening new bins when many are open and progress is high.
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small residues are "dead space".
    let class = (post_residual / 10).min(9) as f64;
    score += class * class * 0.6;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits into the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap).max(0.0);
        } else {
            score += 4.0; // next item cannot use this bin's remainder
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Penalize opening a new bin unless the current bin fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin is attractive only if no tight fit exists elsewhere or
        // item is large relative to capacity.
        let tight_elsewhere = fitting_bins_count > 0 && (post_residual as f64) < 0.5 * cap;
        if tight_elsewhere {
            score += 22.0;
        }
        // Large items pack better into fresh bins.
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 10.0 * (frac - 0.5);
        }
        // Late in the stream, avoid proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress * (open_bins_count as f64 / 10.0).min(3.0);
    } else {
        // Favor bins whose residual is close to the item (min waste) —
        // extra coupling with mean residual: prefer below-mean-residual bins.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Harmonic integer-division threshold: residues in [50,99] are reusable.
        if post_residual >= 50 {
            score -= 5.0;
        } else if post_residual % 2 == 1 {
            score += 1.0; // odd small residues slightly worse for integer streams
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize unusable "dead" gaps: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Penalize gaps that cannot fit the lookahead item (k=2) when it's real.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also serve the next item.
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.7 {
        score -= 40.0 * (fill_ratio - 0.7);
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading into new bins.
    score += 4.0 * open_bins_count as f64;

    // Prefer bins with residual below mean (consolidating small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // New empty bin candidate: neutral baseline, slightly above good fits,
    // below bad fits, so it is chosen only when all open fits are poor.
    if bin_residual == bin_capacity {
        score = 180.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is less costly (fewer future items to serve).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 80.0 * progress;
        // If next item is large and this item is small, a fresh bin keeps flexibility.
        if next_item_size > item_size + 20 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual that can't fit anything useful.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward bins where the NEXT item also fits (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportional to how snugly the next item fits after this one.
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 12.0 + 0.25 * (100.0 - chain_waste.min(100.0));
        // Extra reward if chain leaves a still-usable residual (>= 10).
        if post_residual - next_item_size >= 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here after placing current item: mild penalty,
        // stronger if this bin was the only option (last-chance bin).
        score += 4.0 + if fitting_bins_count == 1 { 8.0 } else { 0.0 };
    }

    // Reward tight fits for the current item (low post_residual relative to item).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize bins whose residual deviates strongly from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else. Make the empty bin moderately expensive
    // so it's chosen only when open bins score badly.
    if bin_residual == bin_capacity && bin_capacity >= item_size {
        // Base cost of a fresh bin, reduced when many items remain (amortization)
        // and when current fit is bad (large post_residual on other bins is
        // already penalized, so this mostly gates frivolous openings).
        score += 40.0 - 10.0 * progress;
        // If next item is large and wouldn't fit typical residual, a fresh bin
        // with room for both is attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Slight preference for using bins early in the stream (keep residual pool diverse).
    score += 0.01 * (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post-residual) with a non-linear bonus.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness;

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, favor it strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Next item still fits here: mild reward for leaving usable space.
            score -= 6.0 * (1.0 - ((post_residual as f64 - nxt) / cap));
        } else {
            // Next item won't fit after this placement: penalize unless we have alternatives.
            score += 8.0;
        }
        // If next item would exactly fill post_residual, big reward.
        if post_residual as f64 == nxt {
            score -= 20.0;
        }
    }

    // Last-chance bin: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer reusing existing bins, discourage spreading.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Penalize bins whose residual is far above the mean (hoarding space in rich bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev;

    // Time-horizon factor: early in the stream, be conservative with new bins;
    // late in the stream, allow looser fits since fewer items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: opening a new bin is expensive; only attractive when
    // the item is large relative to capacity (poor fit elsewhere is likely).
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / cap;
        let mut new_bin_score = cap as f64 - item_size as f64; // waste of fresh bin
        new_bin_score -= 40.0 * item_ratio;
        // If few fitting bins exist and item is large, new bin becomes competitive.
        if fitting_bins_count <= 1 {
            new_bin_score -= 20.0;
        }
        // Late in stream, slightly discourage new bins (fewer future items to fill them).
        new_bin_score += 15.0 * progress;
        score = score.min(new_bin_score + 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Smooth non-linear waste penalty: dead space grows quadratically when very small.
    let tightness = 1.0 - post / cap; // 1 = perfect fit
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Penalize large leftover space that is unlikely reusable: smooth logistic coupling
    let waste_risk = post / cap;
    score += 18.0 * waste_risk * waste_risk * waste_risk * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits, scaled by stream progress.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New empty bin candidate: penalize unless current fit is poor and stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = (post / cap - 1.0).abs(); // = item/cap, large items => poor fit elsewhere
        let pressure = if open_bins_count > 0 { (mean_residual / cap).max(0.0) } else { 1.0 };
        score += 30.0 - 25.0 * poor_fit * (1.0 - progress) - 10.0 * (1.0 - pressure);
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let snug = 1.0 - ((post - nxt) / cap).min(1.0);
            score -= 8.0 * snug * (1.0 - progress);
        } else {
            // Post-residual too small for next item: mild penalty for stranded space.
            score += 5.0 * (1.0 - post / cap) * progress;
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual (harmonized packing).
    score += 0.15 * (resid - mean_residual).abs();

    // Mild preference to fill bins with more residual early on (keep many small bins open).
    score -= 0.05 * resid * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual by integer division thresholds
    let cls = post_residual / 10; // class of dead space
    score += (cls as f64) * 3.0;

    // Small post-residuals (<10) are nearly dead space; penalize mildly unless zero
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; prefer small post_residual anyway
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (mean_residual / bin_capacity as f64) * open_bins_count as f64;
        // open new bin only if no bin offers a decent fit and pressure is low
        if item_size <= bin_residual {
            score += 40.0 - 30.0 * progress + pressure * 10.0;
            if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
                // pairing potential in a fresh bin
                score -= 25.0;
            }
        }
    }

    // Prefer tighter existing bins: reward low bin_residual relative to item
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    // Modulo harmonic coupling: post_residual divisible by common item classes is reusable
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 10.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1, but
    // practically >= 10 in classic streams) can use are pure waste.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 8.0;
    }

    // Penalize gaps too small for the lookahead item if that item would
    // otherwise need a fresh bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive; penalize it,
    // especially when many bins are already open (open_bins_count pressure),
    // unless the current item would leave a bad gap elsewhere.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 35.0 + pressure * 2.0;
        // If item fits poorly anywhere (large item), new bin may still win
        // because fitting bins get the dead-space penalty above.
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0;
        }
    }

    // Slight preference for bins with residuals near mean (balance load).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, consolidate harder to avoid trailing open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step fit: chain both items
        }
        // penalize dead space too small for likely future items
        if post_residual < 10 {
            score += 25.0;
        }
    } else {
        // last item: strongly prefer filling existing bins
        score -= 15.0;
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: default to existing bins unless they fit poorly
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0; // new bin can still host the lookahead item
        }
        if fitting_bins_count == 0 {
            score = 5.0; // no open bin fits: opening a new bin is required
        }
    }

    // Prefer bins tighter than the average residual
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity.
    let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * tight;

    // Penalize dead space that no future item can plausibly use.
    // Small residuals (< 10) are essentially dead weight; large residuals are fine.
    if post_residual < 10 {
        score += 25.0;
    } else {
        // Fraction of residual unusable by typical small items grows with residual
        // if it's in the awkward middle band (e.g. 51..60 leaves nothing for <=50 items).
        if post_residual > bin_capacity / 2 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item would fit in the post residual, reward keeping it;
    // if next item is large and this bin is the only one that could chain-fit, be careful.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // good chaining potential
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // placing here destroys the only fit for the next item
            score += 10.0;
        }
    }

    // New-bin candidate handling: opening a new bin is wasteful when a decent
    // fit exists; make the empty bin attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 55.0;
        // But if open bins are all nearly full (low mean residual), a new bin is fine.
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score -= 60.0 * mean_tightness;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If many bins already fit the item, opening a new one is clearly worse.
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    // Slight preference for bins whose residual is close to the item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * fit_gap;

    // Mild penalty for spreading across too many open bins late in stream.
    if open_bins_count > 8 {
        score += 0.3 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_norm = mean_residual / cap;

    // Base: prefer small post residual (tight fit), non-linearly.
    let mut score = 100.0 * (norm_pr * norm_pr) + 60.0 * norm_pr;

    // Smooth coupling with stream progress: later in the stream, tolerate
    // larger post residual less (dead space becomes costlier to ever recover).
    let late_penalty = 80.0 * progress * (norm_pr * (1.0 - norm_pr) * 4.0);
    score += late_penalty;

    // Interaction: if this bin's residual is far above mean residual,
    // it is a "loose" bin; using it for a small item wastes its flexibility.
    let residual_gap = (bin_residual as f64 - mean_residual) / cap;
    score += 40.0 * residual_gap * norm_pr;

    // Last-chance bonus: only this open bin fits the item.
    if fitting_bins_count == 1 {
        score -= 150.0 + 50.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item can fit into the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 30.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    }

    // New-bin candidate handling: an empty bin has norm_pr == 1.
    // Make it unattractive early (prefer filling open bins), attractive only
    // when the fit into existing bins would leave a very large dead space,
    // or when no open bin fits (fitting_bins_count small among open bins).
    let is_new_bin = (bin_residual as u64 == bin_capacity as u64) && post_residual == bin_residual;
    if is_new_bin {
        // Smooth gate: openness grows with progress and with mean residual tightness.
        let openness = 0.5 + 0.5 * progress;
        let tight = 1.0 - (mean_norm.min(1.0));
        score = 120.0 * openness * openness - 100.0 * tight * progress;
        // If truly last chance (no other fitting bin), strongly allow new bin.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Harmonic classes: classify post_residual into residue classes mod 10
    // (items are multiples of 10 in classic streams; dead space < 10 is nearly useless).
    let dead = (post_residual % 10) as f64;
    score += 8.0 * (dead / 10.0); // penalize non-aligned dead space

    // Integer-division thresholds: how many "typical item slots" fit in post_residual
    let slots = post_residual / 20; // coarse slot count
    score += 6.0 * (1.0 / (slots as f64 + 1.0));

    // Next-item lookahead: big reward if next item still fits in this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (slack / (bin_capacity as f64)).min(1.0);
            // harmonic pairing: post_residual mod next_item_size small => chained fits
            let chain = (post_residual % next_item_size) as f64;
            score -= 10.0 * (1.0 - chain / (next_item_size.max(1) as f64));
        } else {
            // next item cannot follow here: penalize proportionally to wasted pairing
            score += 12.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) / (open_bins_count as f64 + 4.0);
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.35;
        if fitting_bins_count == 0 || (poor_fit && mean_residual < 15.0) {
            score -= 45.0;
        } else {
            score += 20.0 + 25.0 * crowded;
        }
    }

    // Stream progression: late in stream, consolidate harder (avoid opening bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a good dump.
    let dev = (mean_residual - post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * dev.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0; // dead space of 1..9 is nearly unusable
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 6.0;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: prefer bins with residuals below mean (compact them),
    // leave larger-residual bins flexible.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && next_item_size >= bin_residual {
        // next item won't fit here anyway; this bin is a good dump target
        score -= 2.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; penalize it
    // unless the current placement would create severe dead space or no bin fits well.
    if bin_residual == bin_capacity {
        score += 14.0;
        // If placing here (in some open bin) would leave tiny dead space, opening
        // a fresh bin becomes attractive instead.
        if post_residual > 0 && post_residual < 10 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect match with the next item (2-step lookahead).
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let rel = diff / (post_residual as f64);
        score -= (1.0 - rel.min(1.0)) * 12.0;
    } else if post_residual == 0 {
        // Perfect closure of the bin is highly desirable.
        score -= 20.0;
    }

    // Penalize post residuals that are small but not zero (dead space),
    // unless they closely match the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Prefer bins with residuals below the mean (tighter bins first),
    // keeping larger residual bins available for future large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        let below_mean = mean_residual - bin_residual as f64;
        score += below_mean * (0.15 + 0.2 * progress);
    } else {
        // New-bin candidate: penalize moderately so it's only chosen when
        // all open bins are poor fits, more so late in the stream.
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    // Mild preference for using already-open bins to limit bin proliferation.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: low post_residual is good, but dead space
    // below a "useful threshold" is even worse. Penalize small-but-nonzero
    // post_residual (unusable slivers) super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let useless = if pr < 10.0 { (10.0 - pr) * 2.5 } else { 0.0 };
        score += useless;
        score += pr * pr / (bin_capacity as f64 * 4.0);
    } else {
        // Perfect fit: big reward.
        score -= 30.0;
    }

    // Lookahead: if the next item can fit into post_residual, reward this bin
    // (chaining two placements is valuable). If next item is larger than
    // post_residual but post_residual is small, this is fine (little waste).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if ni <= pr {
            // next item chains nicely; stronger reward the tighter the chain
            score -= 12.0 * (1.0 - (pr - ni) / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to leftover
            score += 0.15 * pr;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with below-average residual (pack tight bins first,
    // keep loose bins flexible for future large items).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Slight preference for reusing bins over opening new ones as the stream
    // progresses (late in stream, consolidation matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late
        // in the stream, unless the current fit is terrible elsewhere.
        score += 8.0 + 25.0 * progress + 1.5 * open_bins_count as f64;
    } else {
        score -= 3.0 * progress;
    }

    // Mild penalty for leaving residuals that match common item sizes
    // (keep residual "compatible" with typical future demand).
    let pr = post_residual as f64;
    if pr >= 10.0 && pr <= 80.0 {
        score += 0.05 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual (larger leftover = worse score... actually lower score for tighter fits)
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress:
    // as the stream matures, dead space becomes costlier (quadratic in progress).
    let norm_pr = pr / cap;
    let tightness = 1.0 - norm_pr; // fraction of bin filled
    score -= progress * tightness * tightness * 30.0;
    score -= progress * progress * tightness * 20.0;

    // Penalize large residuals that are unusable: smooth penalty when post_residual
    // is small but nonzero (dead space), coupling with progress.
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0);
    score += (1.0 - 4.0 * dead) * 5.0 * (1.0 - progress);

    // Reward exact fit strongly.
    if pr == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        let next_fits = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= next_fits * (1.0 - gap) * 15.0;
        // Smooth partial reward when next item nearly fits.
        score += (next_item_size as f64 / cap) * (1.0 - next_fits) * 10.0 * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin (residual == capacity) gets a mild
    // penalty that grows with available fitting bins, but shrinks when the item
    // fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let fit_pressure = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 12.0 - 10.0 * fit_pressure;
        // Late in stream, prefer filling existing bins even harder.
        score += 8.0 * progress;
    }

    // Mild coupling with mean residual: prefer bins deviating from mean fill
    // (place into tighter-than-average bins).
    let mean_norm = mean_residual / cap;
    let dev = (norm_pr - mean_norm).abs();
    score += dev * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: mild baseline preference; override only when current bin is a poor fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 18.0;
        // Prefer opening a new bin early in the stream when many bins are open with slack.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0).min(1.0);
        // If next item is large, a fresh bin is attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        return score;
    }

    // Harmonic class of post_residual: how "complete" the bin is.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Reward near-full closures strongly.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 22.0;
    } else if post_residual <= quarter / 2 {
        score -= 14.0;
    } else if post_residual <= quarter {
        score -= 8.0;
    } else if post_residual <= half {
        score -= 3.0;
    }

    // Modulo-class penalty: residuals that are awkward (not multiples of common item sizes)
    let awkward = |r: u32| -> f64 {
        let m10 = r % 10;
        let m20 = r % 20;
        let mut pen = 0.0;
        if m10 != 0 { pen += 2.0; }
        if m20 == 5 || m20 == 15 { pen += 1.5; }
        pen
    };
    score += awkward(post_residual);

    // Lookahead coupling: if next item fits the post residual exactly or well, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack <= 10 {
            score -= 16.0;
        } else if slack <= quarter {
            score -= 7.0;
        } else {
            score -= 2.0;
        }
        // If next item is huge and this bin is its only chance, prioritize.
        if next_item_size > half && slack <= 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving large dead space.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual <= 15 {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: when average slack is high, prefer filling the emptiest-fit
    // (largest fill => smallest post_residual already in base); add pressure when mean is high.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    // Late-stream pressure: close bins tightly as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.1 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that still leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // gap that cannot host the next item
    }

    // Last-chance bin before opening a new one: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.6;

    // Pull score toward mean residual to prefer bins with typical slack.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when item is large relative to a
    // fresh bin and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let decent_fit_exists = fitting_bins_count > 1
            || (fitting_bins_count == 1 && bin_residual != bin_capacity);
        if decent_fit_exists {
            score += 55.0; // keep item in an existing bin
        } else {
            score -= 10.0 * tightness; // fresh bin for large awkward items
        }
    }

    // Late in the stream, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (small post_residual) is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let match_diff = (pr - nxt).abs();
        if pr >= nxt {
            // Next item can follow: reward closeness of the match.
            score -= (bin_capacity as f64 - match_diff) * 0.3;
            // Perfect chaining bonus (post_residual == next_item_size).
            if match_diff == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit here: penalize proportionally to wasted gap.
            score += (nxt - pr) * 0.4;
            // Very small unusable residue penalized more (dead space).
            if pr < 10.0 && pr > 0.0 {
                score += 15.0;
            }
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than the mean is good (consolidating space).
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when placement in
    // existing bins would be poor. Penalize opening a new bin mildly, more so
    // when other fitting bins exist.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Avoid spreading across too many bins: prefer bins when many are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 40.0;

    // Penalize leaving dead space that no typical item could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // perfect-ish fill
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead: bonus if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual: mild penalty proportional to waste
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // many options: prefer the bin with best fit (already captured), slight spread penalty
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Global state: if mean residual is low, bins are scarce -> conserve open bins.
    let mean_res_ratio = mean_residual / bin_capacity as f64;
    if mean_res_ratio < item_size as f64 / bin_capacity as f64 {
        score -= 15.0; // reuse bins when residuals are scarce
    }

    // New-bin candidate handling: empty bin gets base score = capacity, which is high,
    // but allow opening a new bin when fits are terrible or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early stream: opening fresh bins is cheap (more future flexibility).
        score -= 45.0 * (1.0 - progress);
        // If current bin fit is bad (large post residual waste), new bin more attractive.
        if !fitting_bins_count == false && fitting_bins_count == 0 {
            score -= 50.0;
        }
        // If mean residual across bins is large, prefer reusing existing bins.
        score += mean_res_ratio * 30.0;
    }

    // Time horizon: late in stream, consolidate; slightly penalize new bins implicitly
    // by boosting existing-bin usage.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if !is_new_bin {
            score -= 20.0 * progress;
        }
    }

    // Mild penalty for very large items in nearly full bins causing fragmentation.
    if item_size as f64 > 0.7 * bin_capacity as f64 && post_residual > 0 && post_residual < 30 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: prefer tight fits (low post_residual), with smooth non-linear shaping.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth coupling of residual waste with stream progress:
    // late in the stream, waste becomes more costly (compaction pressure).
    score += 12.0 * progress * (pr / cap) * (1.0 - progress + 0.25);

    // Reward filling a bin nearly completely (smooth quadratic reward).
    let fill = 1.0 - pr / cap;
    score -= 8.0 * fill * fill;

    // Last-chance bonus: strongly favor the only bin that fits, smoothly scaled by tightness.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * fill;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) == (next_item_size as i64) {
        score -= 5.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= pr {
        // mild reward if next item can still fit afterwards
        score -= 1.5 * (1.0 - pr / (next_item_size as f64 + pr)).abs().min(1.0);
    }

    // Penalize bins whose residual deviates from the mean (avoid fragmentation outliers),
    // smoothly via squared deviation.
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev / (1.0 + open_bins_count as f64);

    // New-bin candidate handling: it has pr = cap - item_size (large).
    // Add a smooth opening penalty that shrinks as the stream progresses,
    // so late-stage placements prefer compacting into open bins.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 10.0 * (1.0 - 0.5 * progress) + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (1/4, 1/3, 1/2) via integer division thresholds.
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;

    // Reward tight fits: post residual in the "dead zone" (< quarter) is fine.
    if post_residual < quarter {
        score -= 8.0;
    } else if post_residual < third {
        // Awkward sliver: penalize mildly.
        score += 3.0;
    } else if post_residual < half {
        score += 1.5;
    }

    // Modulo arithmetic: post_residual divisible by common item classes (10, 20, 25)
    // is more reusable by future items.
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 2.0; }
        if pr % 25 == 0 { score -= 2.0; }
        // Small odd leftovers are hard to reuse.
        if pr < 10 { score += 6.0; }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            // Next item fits: leftover after next placement matters.
            let post2 = post_residual - next_item_size;
            if post2 < quarter { score -= 5.0; } else { score += (post2 as f64) * 0.05; }
        } else {
            // Next item cannot use this bin's leftover: penalize large leftovers.
            score += (post_residual as f64) * 0.08;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the stream
    // is early, few bins are open, or the current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin, reduced late in the stream
        // or when many bins are open (consolidation less valuable).
        let mut penalty = 20.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
        // If the current fit would leave a big awkward leftover, allow opening.
        if post_residual >= half { penalty -= 10.0; }
        // If next item is large and would not fit leftover, new bin more attractive.
        if next_item_size > post_residual && next_item_size > half as u32 { penalty -= 6.0; }
        score += penalty;
    }

    // Small tie-breaker toward bins with below-average residual (fill fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Mid-range dead space (10..20) is also risky: few future items fit.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discouraging proliferation of bins with scattered residuals.
    score += open_bins_count as f64 * 0.8;

    // If this is a brand-new empty bin candidate, make it moderately
    // attractive only when the fit into open bins would be bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Next item lookahead: if next item is large, opening a fresh bin
        // now for a small item is wasteful.
        if next_item_size > item_size {
            score += 10.0;
        }
    } else {
        // Favor bins whose residual is close to what the next item needs.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Penalize bins whose post-residual cannot hold the next item
        // but is too big to be dead space comfortably.
        if next_item_size > post_residual && post_residual > 0 {
            score += 4.0;
        }
    }

    // Prefer bins that are already well-filled (low residual relative to mean).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, tighten packing (fewer chances left to fix gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);

        // If next item fits exactly after this placement, strongly favor.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // If next item cannot fit anywhere else after this placement, penalize blocking.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor),
    // penalize consuming space from bins already below average residual.
    let mr = mean_residual.max(0.0);
    if (bin_residual as f64) < mr {
        score -= 5.0;
    } else {
        score += (bin_residual as f64 - mr) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving tiny unusable dead space (waste fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // New-bin candidate: only attractive when the item is large and would leave
    // a well-usable residual, or when fits elsewhere are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= 50 && post_residual >= 20 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Late in the stream, consolidate into existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small-but-nonzero dead space (unusable slivers)
        let t = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * (1.0 - t) * (1.0 - t) * t;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty proportional to wasted opportunity
        score += 5.0;
    }

    // Prefer filling bins with larger residual when many bins are open (bin consolidation)
    score += 0.15 * (open_bins_count as f64 - 3.0).max(0.0) * (bin_residual as f64 / bin_capacity as f64);

    // Global residual pressure: if mean residual is low, be greedy with tight fits
    score += 0.1 * mean_residual;

    // Early in stream: be more exploratory toward opening bins (mild new-bin friendliness)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize normally, but discount penalty early
        let base_pen = 25.0 + 0.5 * item_size as f64;
        score += base_pen * (0.4 + 0.6 * progress);
        // Opening a new bin is good if item is huge and no tight option exists
        if item_size >= 60 && bin_residual != bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize post_residual, with a super-linear penalty so small
    // post-residuals are strongly preferred (tight packing).
    let mut score = pr * (1.0 + 2.0 * (pr / cap).powi(2));

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter fits matter more (dead space is harder to fix).
    let coupling = pr * (pr / cap) * (progress * (1.0 - progress) * 4.0);
    score += 0.5 * coupling;

    // Reward bins whose residual matches the next item (lookahead synergy),
    // smoothly via normalized difference.
    if next_item_size > 0 && post_residual > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs() / cap;
        score -= 4.0 * (1.0 - (diff * 2.0).min(1.0)).powi(2);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: mildly penalize opening a new bin unless residuals
    // of open bins are large (poor fits everywhere).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual / cap;
        score += 3.0 - 6.0 * mean_r * (1.0 - progress);
    }

    // Slight preference for bins tighter than the mean residual.
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "waste class".
    // Residuals that are multiples of 10 are highly reusable (harmonic alignment).
    let pr = post_residual as i64;
    let class = (pr % 10) as f64;
    score += class * 1.5;                       // penalize off-grid residuals
    if pr % 10 == 0 {
        score -= 6.0;                           // reward perfectly harmonic residuals
    }
    if pr % 20 == 0 {
        score -= 4.0;                           // extra reward for 20-aligned residuals
    }

    // Integer-division thresholds on post_residual: dead-space zones.
    if pr > 0 && pr < 10 {
        score += 25.0;                          // tiny sliver: near-dead space
    }
    if pr >= 10 && pr <= 20 {
        score += 8.0;                           // awkward small zone
    }

    // Coupling with next item (lookahead harmonic match).
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if pr >= nxt {
            let gap = pr - nxt;
            score += (gap % 10) as f64 * 0.8;   // prefer post_residual that exactly/near fits next item
            if gap == 0 {
                score -= 10.0;                  // perfect chain fit
            } else if gap < 5 {
                score -= 5.0;
            }
        } else {
            score += 6.0;                       // next item cannot use this bin's remainder
        }
        // Harmonic divisibility: next item divides residual cleanly
        if nxt > 0 && pr % nxt.max(1) == 0 && pr > 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish base, penalize opening when
    // good fitting bins exist and stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 20.0;                      // discourage opening when alternatives exist
        }
        if post_residual as f64 >= mean_residual {
            score -= 5.0;                       // fresh bin keeps high residual, mildly good
        }
    }

    // Small tight-fit bonus: reward filling bins nearly exactly.
    if pr == 0 {
        score -= 12.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (pack tighter bins first, keep loose bins for future large items).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.15;
    } else {
        score += (res - mean_residual) * 0.05;
    }

    // Late-stream tightening: as stream ends, prefer zero/low post residuals more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (10.0 - class * 0.5).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 {
        // Dead space threshold: gaps below ~15 are nearly unusable.
        if post_residual < 15 {
            score += 60.0 - (post_residual as f64) * 3.0; // worse the smaller the gap
        } else if post_residual < 30 {
            score += 12.0 - (post_residual as f64) * 0.2;
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 100.0;
        }
    } else {
        score -= 100.0;
    }

    // Tight fit reward: fraction of residual consumed.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading onto fresh bins,
    // encourage consolidating into existing ones.
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin should only win when the fit
    // elsewhere would be terrible. Give it a moderate standing penalty.
    if bin_residual == bin_capacity {
        score += 55.0 + mean_residual * 0.1;
        // If nothing else fits well (few fitting bins) and stream is late,
        // relax the penalty so a fresh bin can be preferred.
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
    }

    // Lookahead coupling: if the next item can exactly use the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits in the gap: mild reward proportional to how well.
        score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Gap cannot host the next item: penalize if it becomes dead space.
        if post_residual < next_item_size.min(15) {
            score += 25.0;
        }
    }

    // Stream progression: early on, allow looser packing; late, be strict
    // about waste since future recovery is less likely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., closer to being closed out) when residuals are plentiful.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward bins whose post-fit residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0 + 0.5 * next_item_size as f64;
        } else {
            // penalize creating dead space that cannot fit the next item
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fit only
        score += 0.0;
    }

    // Tightness reward relative to mean residual across open bins
    if (post_residual as f64) < mean_residual {
        score -= 0.35 * (mean_residual - post_residual as f64);
    } else {
        score += 0.35 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: make empty bin attractive only when nothing fits well
    if bin_residual == bin_capacity {
        let empty_penalty = if fitting_bins_count <= 1 { 0.0 } else { 55.0 };
        score += 20.0 + empty_penalty;
        // toward the end, discourage opening extra bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight early-stream bias to consolidate items into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize very small unusable residuals
    if post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer bins that leave less space wasted overall.
    let mut score = post;

    // Tightness reward (quadratic): filling a bin deeply is very desirable.
    let tightness = 1.0 - post / cap;
    score -= 40.0 * tightness * tightness;

    // Penalize tiny unusable dead space (fragments < 10 can never host min item).
    if post > 0.0 && post < 10.0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only open bin that can fit the item,
    // strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Default: opening a new bin wastes potential; make it unattractive.
        score += 90.0;
        // Large items deserve fresh bins (they leave little residue anyway).
        if item >= 60.0 {
            score -= 70.0;
        }
        // If NO open bin can fit the item, the new bin is mandatory.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Lookahead (k=2): reward leaving room for the next item, punish otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - post / cap);
        } else {
            score += 6.0;
            // If next item would fit this bin exactly after current item fails,
            // slight extra penalty for blocking a good two-item sequence.
            if nxt <= bin_residual as f64 {
                score += 4.0;
            }
        }
    }

    // Global state coupling: if mean residual is high, prefer consuming
    // existing slack rather than spreading items into fresh bins.
    score += 0.08 * (mean_residual - post).abs();
    if mean_residual > 40.0 && !is_new_bin {
        score -= 10.0;
    }

    // Time horizon: early in the stream, be slightly more willing to open
    // bins (flexibility); late in the stream, consolidate aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * t;
    if is_new_bin {
        score -= 20.0 * (1.0 - t);
    }

    // Crowding effect: many open bins -> consolidate into existing ones.
    if open_bins_count > 4 {
        score += if is_new_bin { 30.0 } else { -3.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: reward small post-residual with a non-linear (quadratic) coupling.
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth stream-progress coupling: later in the stream, tighten fits more aggressively.
    let prog_term = 0.6 * progress * (pr / cap) * (1.0 - progress);
    score += prog_term * cap;

    // Penalize bins whose residual is far from the mean (fragmentation signal).
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 0.3 * item_size as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.2 * gap - 8.0 * (1.0 - gap / cap).max(0.0);
    } else {
        // Last item: maximize fill, strongly reward minimal post-residual.
        score += 0.5 * pr;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Prefer opening a new bin only when the item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        // Penalize opening a new bin generally, but less for large items.
        score += 40.0 - 35.0 * fill_ratio * fill_ratio;
    }

    // Mild penalty for spreading across too many open bins (encourages consolidation).
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: minimize post_residual relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes on post_residual: small residues that are "hard" to reuse get penalized.
    // Residues in awkward classes (e.g. < 10, or odd small values) are dead space.
    let dead = if post_residual < 10 { 40.0 } else { 0.0 };
    score += dead;

    // Modulo class of residual vs common item sizes: reward residuals that are multiples
    // of small harmonics (5, 10, 20) which future items can tile well.
    let harmonic_bonus = if post_residual % 20 == 0 && post_residual > 0 {
        -15.0
    } else if post_residual % 10 == 0 && post_residual > 0 {
        -8.0
    } else if post_residual % 5 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for wasting the lookahead opportunity.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item
    // (avoids opening a new bin when this one would otherwise be abandoned).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when good
    // fitting bins exist or many bins are already open.
    if bin_residual == bin_capacity {
        score += 60.0 + 5.0 * (open_bins_count as f64);
        if fitting_bins_count > 0 {
            score += 40.0;
        }
        // Late in the stream, prefer filling existing bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If item is small, a new bin is very wasteful.
        if item_size < 30 {
            score += 25.0;
        }
    }

    // Slight preference for bins below mean residual (keeps balance, avoids
    // stranding large-residual bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap <= 10.0 {
            // Tiny gaps are dead space: big penalty, tighter gap = worse.
            score += (11.0 - gap) * 12.0;
        } else if gap < 20.0 {
            score += (20.0 - gap) * 2.5;
        }
        // Reward usable residual chunks that can still host plausible items.
        if gap >= 20.0 {
            score -= 8.0;
        }
        if gap >= 50.0 {
            score -= 10.0;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 40.0;
    }

    // Reward tightness relative to bin capacity (best-fit core).
    let tightness = (bin_capacity - bin_residual.min(bin_capacity)) as f64 / bin_capacity as f64;
    score -= tightness * 6.0;

    // Open-bins pressure: with many open bins, prefer reusing existing bins;
    // with few open bins, allow new bins more readily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.35;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or mean residual is very low.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        let desperation = if fitting_bins_count == 0 {
            25.0
        } else {
            (mean_gap / 10.0).min(20.0)
        };
        // Base new-bin cost plus desperation discount.
        score = 55.0 - desperation + open_bins_count as f64 * 0.15;
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Lookahead synergy: placing here leaves room for the next item.
        if post_residual as i64 >= next_item_size as i64 {
            score -= 5.0;
        } else if (post_residual as i64) > 0 && (post_residual as i64) < next_item_size as i64 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * tightness * tightness;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        // Perfect chaining: post_residual exactly equals next item size.
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Post-residual can host the next item: reward closeness of fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // Extra reward if next item then leaves another usable chunk.
            if slack >= 10.0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize leftover dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * (gap / bin_capacity as f64);
        }
        // Reward if next item fits even better elsewhere-vs-mean comparison.
        if (post_residual as f64) >= next && (post_residual as f64) <= mean_residual + next {
            score -= 8.0;
        }
    } else {
        // Last item: minimize waste only.
        score += 10.0 * tightness;
    }

    // Penalize bins whose residual is far below the mean (they are nearly full anyway,
    // keep them for future small items rather than fragmenting).
    let res = bin_residual as f64;
    if res < mean_residual * 0.5 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the item
    // is large relative to typical residuals or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64) > mean_residual;
        let mut bias = 18.0;
        if big_item {
            bias -= 12.0;
        }
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            // Fresh bin gives perfect chain for next item.
            bias -= 20.0;
        }
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            // Fresh bin leaves residual that may not host next item.
            bias += 10.0 * (1.0 - progress);
        }
        // Late in stream, prefer closing out open bins instead of spawning.
        bias += 15.0 * progress;
        score += bias;
    }

    // Mild preference for filling more-opened bins (bin-count control).
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space, normalized by capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin;
    // if next item would be blocked by too-large post-residual, penalize dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > bin_residual {
            // next item can't fit here anyway; residual waste matters less
            score -= 4.0;
        } else {
            // next item fits now but won't fit after placement -> bad choice
            score += 18.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is poor. Penalize the empty bin moderately.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in the stream, prefer closing out open bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // More open bins -> opening new ones is costlier.
        score += open_bins_count as f64 * 3.0;
    }

    // Global state coupling: if this bin's residual is far below the mean residual,
    // it is a "small hole" — placing items there is valuable.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f).min(40.0) * 0.5;
    } else {
        score += (resid_f - mean_residual) * 0.15;
    }

    // Prefer filling nearly-full bins completely.
    if post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: strongly favor small post_residual (non-linear polynomial)
    let mut score = pr * pr / cap + 2.0 * pr;

    // Smooth coupling: as stream progresses, waste becomes costlier
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits when the next item could use the leftover space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // post_residual is reusable by next item: reward
            score -= 6.0 * (1.0 - (pr - nxt) / cap) * (0.5 + progress);
        } else {
            // post_residual too small for next item: penalize dead space
            score += 4.0 * (1.0 - pr / nxt) * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when other bins fit, smoothly scaled by
    // how many bins fit and how much mean residual is available
    if bin_residual == bin_capacity {
        let fit_factor = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let mean_usable = (mean_residual - item_size as f64).max(0.0) / cap;
        score += 20.0 + 10.0 / fit_factor + 8.0 * mean_usable;
    } else {
        // Mild preference for fuller bins among open candidates
        score -= 3.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Non-linear interaction between post_residual and open bin count:
    // many open bins -> prefer consolidating into tight fits
    let consolidation = (open_bins_count as f64).ln_1p();
    score += pr_norm * pr_norm * 4.0 * consolidation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the item: which capacity fraction does it live in? ---
    // Classes: (0,25], (25,50], (50,75], (75,100]
    let item_class = ((item_size - 1) * 4 / bin_capacity) as i64; // 0..3
    let next_class = if next_item_size == 0 { -1 } else { ((next_item_size - 1) * 4 / bin_capacity) as i64 };

    // --- Reward tight fits, scaled by post-residual harmonic class ---
    // post_residual in small "dead" classes is bad unless it's exactly 0.
    if post_residual == 0 {
        score -= 60.0; // perfect fill is always best
    } else {
        let post_class = ((post_residual - 1) * 4 / bin_capacity) as i64; // 0..3
        // Penalize dead space quadratically within its harmonic class
        score += (post_residual as f64) * (1.0 + 0.25 * post_class as f64);
        // Dead space in the lowest class (1..25) is nearly unusable
        if post_class == 0 {
            score += 18.0;
        }
        // Mid-class residual (25..50) is moderately useful
        if post_class == 1 {
            score -= 6.0;
        }
    }

    // --- Modulo pairing logic: does the next item fit the post-residual exactly or near-exactly? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 45.0; // sets up a perfect follow-up fill
        } else if gap <= 10 {
            score -= 20.0;
        } else if gap <= 25 {
            score -= 8.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: residual becomes pure waste
        score += 12.0;
    }

    // --- Harmonic complementarity: item class + next class summing near capacity ---
    if next_item_size > 0 {
        let pair_sum = item_size + next_item_size;
        if pair_sum == bin_capacity {
            score -= 30.0; // ideal harmonic pair
        } else if pair_sum > bin_capacity {
            score += 5.0; // pair overflows capacity, less attractive
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0; // strongly prefer using the only fitting bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: attractive early in the stream or when open bins are all tight,
        // but never free — must be worse than a genuinely good fit.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 22.0 + 10.0 * progress;
        // If the item is large (top harmonic class), a fresh bin is natural
        if item_class >= 2 {
            score = base - 6.0;
        } else {
            score = base;
        }
        // Many open bins with slack: discourage adding another
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 14.0;
        }
    }

    // --- Mild preference to keep bin count low ---
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += (11 - pr) as f64 * 12.0; // gap of 1 is worst
    } else if pr > 10 && pr <= 25 {
        score += (pr as f64 - 10.0) * 0.8; // mild penalty for medium waste
    }

    // Reward very tight fits (near-perfect packing).
    if pr == 0 {
        score -= 40.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; allow opening new bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 1.5 * progress);
    score += pressure * 0.6;

    // Last-chance bin: strongly favor filling it rather than leaving it dangling.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if item is large and would
    // leave a big useful residual, or if existing bins are all nearly full.
    if bin_residual == bin_capacity {
        score += 15.0; // base cost of opening a new bin
        let large_item = item_size as f64 >= 0.5 * bin_capacity as f64;
        let all_tight = mean_residual < 12.0 && open_bins_count > 0;
        if large_item || all_tight {
            score -= 55.0;
        }
        // Don't open a new bin for tiny items when open bins exist.
        if item_size <= 20 && open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 60.0;
        }
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && pr > 0 && (pr as u32) < next_item_size {
        score += 6.0; // residual too small for lookahead item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
        if lookahead_waste == 0 {
            score -= 800.0;
        } else if lookahead_waste < 10 {
            score -= 100.0;
        } else {
            score += lookahead_waste as f64 * 0.3;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot fit here afterwards; penalize small dead space
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare against mean residual: prefer bins tighter than mean
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins exist with decent fit
    if bin_residual == bin_capacity {
        score += 120.0 + (open_bins_count as f64) * 5.0;
        // But allow new bin for large items that would leave big dead space
        if item_size >= 60 && post_residual < 20 && next_item_size > post_residual {
            score -= 200.0;
        }
    }

    // Late in stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer minimal post residual (tight fit)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness;

    // Lookahead: reward if next item can fit into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let combo_slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.08 * combo_slack;
    } else if next_item_size > 0 && next_item_size <= item_size {
        // next item too big for this bin's leftover; mild penalty for wasting space
        score += 4.0;
    }

    // Last chance: this is the only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
        // extra reward if residual is small (item nearly fills bin)
        if post_residual <= 5 {
            score -= 12.0;
        }
    }

    // Penalize creating small unusable dead space (1..=9) unless it's zero
    if post_residual > 0 && post_residual < 10 {
        score += 14.0 - 1.2 * post_residual as f64;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // New-bin candidate logic: opening a new bin is attractive only when
    // existing bins fit poorly (large post_residual) or few bins are open
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // early stream: opening bins is cheap; late stream: prefer filling existing
        let open_penalty = 6.0 + 22.0 * progress + 1.5 * (open_bins_count as f64).sqrt();
        score += open_penalty;
        // if the item is large relative to capacity, a fresh bin is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        // if mean residual of open bins is small, new bin is justified
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // reward using existing bins, more so when mean residual is high (bins are loose)
        score -= 2.0 * (mean_residual / bin_capacity as f64);
    }

    // Global state: when many bins are open, prefer consolidating into them
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, tighten up (avoid leaving many loose bins)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize wasted residual with a non-linear (quadratic) coupling
    let norm_post = post / cap;
    let mut score = post * (1.0 + norm_post * norm_post);

    // Stream-progress coupling: early on, prefer tight fits less aggressively;
    // late in the stream, strongly prefer minimizing post_residual (polynomial ramp).
    let ramp = 0.5 + 1.5 * progress * progress;
    score *= ramp;

    // Smooth interaction between post_residual and mean residual:
    // if this bin's post-residual is far below the mean residual of open bins,
    // it creates a low-utility fragment; penalize smoothly.
    let mean_coupling = (post - mean_residual) / cap;
    score += 20.0 * mean_coupling * mean_coupling - 8.0 * mean_coupling;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    // (avoid opening a new bin) with a smooth discount proportional to fill ratio.
    if fitting_bins_count <= 1 {
        let fill_ratio = item_size as f64 / cap;
        score -= 30.0 * (1.0 - norm_post) * (0.5 + fill_ratio);
    }

    // Lookahead coupling: reward leaving residual that can fit the next item,
    // smoothly via a saturating quadratic term.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let deficit = (nxt - post) / cap;
            score += 10.0 * deficit * deficit;
        }
    }

    // Penalize fragmenting a nearly-full bin into tiny unusable residue
    // (smooth cubic penalty on very small post_residual).
    let tiny = (1.0 - norm_post).min(0.0).abs();
    let _ = tiny;
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (10.0 - post) * 0.5;
    }

    // Mild penalty for spreading across many open bins vs consolidating
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Harmonic class of post_residual: prefer residuals in "usable" classes
    // (multiples of 10 or 20 are more likely to host future items).
    let class10 = post_residual % 10;
    let class20 = post_residual % 20;
    if class10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if class20 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Odd/awkward residuals get a mild penalty.
    if class10 >= 7 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 300.0;
        } else if gap < 10 {
            score -= 40.0;
        } else {
            score -= (gap as f64).ln() * 5.0;
        }
    }
    // If next item cannot fit here, mild penalty (chain break) unless residual still large.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
        if next_item_size > 0 && post_residual < 25 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin wastes the remaining capacity
    // of all open bins. Penalize proportionally to mean residual, scaled by progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual * (open_bins_count as f64).sqrt();
        score += 45.0 + waste * 0.35 + progress * 30.0;
        // But if no open bin fits at all, opening is inevitable: soften.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Perfect fit in a fresh bin (item == capacity) is fine.
        if post_residual == 0 {
            score -= 500.0;
        }
    }

    // Prefer filling bins that are already low on space (tight packing).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 20.0;

    // Mild preference for bins below the mean residual (balance avoidance of
    // many half-empty bins).
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for small unusable gaps (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (exact fill is ideal)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward good relative fill of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open bins pressure: prefer denser packing when many bins are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Prefer bins with residual below mean residual (fill the emptier-ish bins,
    // keeping large residuals available for large future items)
    if bin_residual as f64 > mean_residual {
        score += 6.0;
    } else {
        score -= 6.0;
    }

    // Lookahead: if next item fits into the post_residual, reward saving that space
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 12.0;
        }
        // Penalize leaving a gap just slightly smaller than the next item (near-miss waste)
        if next_item_size > post_residual && post_residual > 0 {
            let waste = (next_item_size - post_residual) as f64;
            if waste < 10.0 {
                score += 20.0;
            }
        }
    }

    // New-bin candidate: opening a new bin is only attractive when this is an
    // empty bin call and current fits are poor. Make the empty bin moderately
    // unattractive so it only wins when open-bin scores are heavily penalized.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to typical residuals, opening fresh is fine
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Post-residual close to next item size (near-perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 12.0 * (-gap / 8.0).exp();
    }

    // Dead space: post_residual too small for the next item (likely wasted).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Penalize bins whose residual deviates strongly below mean (fragmented bins).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.12;
    }

    // Last-chance bin bonus: avoid opening a new bin when only this bin fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Late in the stream, prefer consolidating into fewer bins.
    if total_items > 0 && step_index as f64 / total_items as f64 > 0.7 {
        score -= 4.0;
    }

    // Slight penalty for opening new bins when several bins already fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on leftover space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - (slack / bin_capacity as f64) * 8.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that cannot hold the next item: penalize proportionally.
        score += (post_residual as f64) * 0.35;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins fit decently.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in the stream, new bins are more acceptable (fewer future regrets).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If the item is large and nothing tight is available, new bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild preference for bins below mean residual (keeps balance, avoids fragmenting one bin).
    score += ((mean_residual - bin_residual as f64) / bin_capacity as f64) * 4.0;

    // Slight preference for more-filled bins early on.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual) mildly; later, penalize waste harder.
    let progress_weight = 0.5 + 2.5 * t * t;
    score += progress_weight * norm_pr * cap * 0.5;

    // Non-linear dead-space term: residuals too small to matter are penalized super-linearly.
    let dead = norm_pr * norm_pr;
    score += 40.0 * dead * (1.0 - t);

    // Reward exactness of fit: item filling bin residual well lowers score.
    let fill_ratio = 1.0 - norm_pr;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: bonus if next item fits in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (1.0 - nxt.abs() - 0.0) * (0.5 + 0.5 * t);
    }
    // Penalize if post_residual is small but nonzero and next item won't fit (dead space risk).
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 15.0 * (1.0 - norm_pr) * (0.3 + 0.7 * t);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // More competing bins: slight preference for tighter ones.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual context: prefer bins below mean residual (tighter than average).
    let mean_norm = mean_residual / cap;
    score += 10.0 * (norm_pr - mean_norm);

    // New-bin candidate handling: make empty bin attractive only when fits are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = cap * 0.8 + 20.0 * scarcity * (1.0 - t)
            - 10.0 * scarcity * fit
            + 30.0 * (1.0 - scarcity);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover lands in
    // "reusable" classes (multiples of small denominators) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible by 10 or 20 -> highly reusable leftover.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Class B: tiny dead space (1..=5) is actually fine (near-perfect fit).
    if post_residual <= 5 {
        score -= 8.0;
    }
    // Class C: awkward mid residuals (6..=9, 11..=19 non-divisible) are dead space.
    if (6..10).contains(&post_residual) {
        score += 5.0;
    }
    if (11..20).contains(&post_residual) && post_residual % 10 != 0 {
        score += 3.0;
    }

    // Exact fill is best.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Fraction-of-capacity coupling: prefer residuals that are small fractions.
    let frac = pr / cap;
    score += 10.0 * frac * frac; // convex penalty on wasted fraction

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 2.0;
        }
        // Harmonic pairing: next item exactly fills post residual.
        if next_item_size == post_residual {
            score -= 10.0;
        }
    }

    // New-bin candidate: only attractive when open bins are nearly full or crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = cap * 0.9 + 15.0 * progress + crowd;
        // Opening a new bin is good if mean residual is small (bins nearly full).
        if mean_residual < 15.0 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size + item_size > bin_capacity {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but tiny dead space
    // (< 5) is nearly unusable, so penalize it extra.
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    // Fill-ratio reward: prefer bins where the item fills a large fraction
    // of the current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into more bins; consolidate instead.
    score += (open_bins_count as f64).min(10.0) * 0.8;

    // Lookahead coupling: if the next item fits in the post-residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item almost fits (small shortfall), penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // New-bin candidate: empty bin has large post_residual; make it lose
    // against any reasonable existing bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early in the stream, opening bins is cheaper (more future items
        // to fill them); relax the penalty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for bins with residuals below the mean (consolidate
    // large residuals for future big items).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect or near-perfect match for the next item is strongly preferred.
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
            // Chain fit bonus scaled by how much of post_residual the next item consumes.
            let consume = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 10.0 * consume;
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    } else {
        // Last item: only immediate tightness matters.
        score -= 5.0 * tightness;
    }

    // Relative to mean residual: prefer bins whose residual deviates usefully.
    let dev = (post_residual as f64) - mean_residual;
    score += 0.08 * dev; // prefer below-mean residual bins (tighter than average)

    // Last-chance bonus: if this is the only bin that can fit, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when fits are poor or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Default penalty: reusing open bins is generally better.
        score += 15.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = (step_index as f64) / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If many bins fit the item, opening a new one is wasteful.
        score += 3.0 * (fitting_bins_count as f64);
        // If the next item is large and this item leaves a bad fit, opening a fresh bin
        // keeps flexibility for the future.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 18.0;
        }
        // If mean residual across open bins is very small, open bins are nearly full anyway.
        if mean_residual < 20.0 {
            score -= 10.0;
        }
    } else {
        // Mild penalty per extra open bin to discourage bin sprawl.
        score += 0.5 * (open_bins_count as f64);
    }

    // Dead-space penalty: residuals too small for any item (min size 1) are fine,
    // but residuals just below typical item sizes are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // small crumbs are effectively full bins, that's good
    } else if post_residual >= 10 && post_residual <= 25 {
        score += 2.0; // awkward dead zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small dead space that nothing can use
        if post_residual < 10 {
            score += 20.0;
        }
        // Reward tight fits proportionally
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 15.0;
    }

    // Lookahead: if next item fits into the post residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is large and would not fit, mildly penalize wasting the tight slot
    if next_item_size > post_residual && post_residual > 0 && next_item_size >= 40 {
        score += 6.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New empty bin candidate: penalize opening a new bin unless it's genuinely needed
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if no open bin fits well (post_residual here is large by definition),
        // allow opening when existing bins are nearly full
        let mean_fill = mean_residual / bin_capacity as f64;
        if mean_fill < 0.15 {
            score -= 30.0;
        }
    }

    // Time horizon: early in the stream, prefer consolidating into few bins;
    // late in the stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Slight preference for bins with residual above mean (keeps spread balanced)
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // base: post residual
    let mut score = pr;

    // non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = pr_norm * (0.5 + 1.5 * p2 + 2.0 * p3);
    score += 40.0 * coupling;

    // penalize large dead space relative to next item (smooth interaction)
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = pr - nxt;
        if gap > 0.0 {
            let g = gap / cap;
            score -= 25.0 * g * g * (1.0 - progress);
        } else {
            let g = (-gap) / cap;
            score += 30.0 * g * (0.5 + 0.5 * p2);
        }
    }

    // last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * p2;
    }

    // new-bin candidate penalty: discourage opening new bins unless residual is unusable
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    // smooth deviation from mean residual: prefer bins below mean (tighter fit)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev - 8.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: buckets of capacity/10.
    let class = (post_residual * 10 / bin_capacity.max(1)) as f64;

    // Dead-space penalty: residuals in the awkward mid-range (10..=25)
    // are hard to fill later; push them into a penalized harmonic band.
    if post_residual >= 10 && post_residual <= 25 {
        score += 45.0 - class * 2.0;
    }

    // Near-perfect fill: residual below the smallest plausible item
    // is effectively zero waste — reward strongly.
    if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead chain bonus: if the next item also fits in the
    // remaining space, this bin stays productive — reward it.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 6.0 + (next_item_size as f64) * 0.05;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // using it avoids opening a new bin — strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (bin_residual == bin_capacity, post == cap).
    // Baseline slightly below cap so only genuinely poor fits in all
    // open bins (large penalized residuals) can beat it; a mild
    // congestion term grows with the number of open bins.
    if bin_residual == bin_capacity {
        score = cap - 20.0 + (open_bins_count as f64).sqrt() * 1.5;
        if fitting_bins_count == 0 {
            // No open bin fits at all: new bin is the only option.
            score = 0.0;
        }
    }

    // Slight global drift: late in the stream, tighten packing
    // (waste matters more since fewer chances to recover).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += post * 0.1 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual as i32) as f64 * 6.0;
    }

    // Reward very tight fits (small usable leftover).
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // If next item could combine with current item in a fresh bin, allow it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0;
        }
    }

    // Favor bins whose residual is close to the item (relative tightness).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Mild open-bin pressure: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Prefer bins below the mean residual (more packed bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Next item fits into the post residual (2-step lookahead success)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use what remains
        score += 8.0 + 0.25 * (post_residual as f64);
    }

    // Perfect 1-step fit: item exactly fills the bin
    if post_residual == 0 {
        score -= 12.0;
    }

    // Penalize leaving tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: only attractive when current item is large
    if bin_residual == bin_capacity {
        score += 30.0 - 0.2 * (item_size as f64);
        // But if next item is also large and this bin would chain-fill, ease penalty
        if next_item_size > 0 && item_size >= 50 && next_item_size >= 50 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early in stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (open_bins_count as f64).recip().min(0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post residual relative to capacity, the better.
    score -= 12.0 * (1.0 - post_residual as f64 / cap);

    // Lookahead (k=2): strongly reward if the next item chains into the leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize leaving a gap that the next item cannot use (dead space risk).
            score += 0.3 * (post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier, penalize mediocre fits.
        score += 3.0;
    }

    // Mild global pressure: when mean residual across open bins is low, be thrifty.
    score += 0.05 * mean_residual * (0.5 + 0.5 * t);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score = cap * 1.2 - 2.0 * (open_bins_count as f64).min(8.0);
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is necessary.
            score -= 40.0;
        }
        // If the next item is large, keeping flexibility helps slightly.
        if next_item_size > item_size {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * (1.0 - progress) * 2.0;
    score += poly * cap * 0.1;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 6.0 * (0.3 + progress);

    // Penalize if next item cannot fit in post residual (smooth quadratic)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let rel_gap = gap / cap;
        score += rel_gap * rel_gap * cap * 0.4;
        // Reward leaving room for next item
        let slack = (pr - next_item_size as f64).max(0.0) / cap;
        score -= slack * slack * 8.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 * (1.0 - norm_pr);
    }

    // Slight preference for bins below mean residual (balancing)
    score += ((mean_residual - bin_residual as f64) / cap).max(0.0) * 2.0 * progress;

    // Mild new-bin penalty to prefer filling existing bins unless very poor fit
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress) + norm_pr * 0.0;
        if fitting_bins_count > 0 {
            score += 6.0 * (1.0 - norm_pr);
        }
    }

    // Open bins pressure: prefer using many bins when few open
    score -= (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // integer division into capacity-eighth buckets; small classes are dead space.
    let cap = bin_capacity as f64;
    let eighth = cap / 8.0;
    let post = post_residual as f64;
    let class = (post / eighth).floor(); // 0..=8

    // Penalize dead-space classes heavily (very small leftovers are unusable).
    if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    } else if post_residual <= 5 {
        score += 25.0; // nearly-dead space: penalize
    } else if post_residual <= 10 {
        score += 12.0;
    } else {
        // reward mid-range classes that can still host typical items
        score -= (class.min(6.0)) * 2.0;
    }

    // Modulo arithmetic on post_residual: leftovers congruent to small
    // residues mod 10 pair well with common item granularities.
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0;
    } else if m <= 3 {
        score += 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 15.0 - (chain_waste as f64).min(15.0);
        } else {
            // next item cannot follow here: slight penalty proportional to overshoot
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: make empty bins attractive only when open bins are
    // fragmented (high mean residual spread) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post).abs();
        // Empty bin baseline: score = capacity residual, adjusted.
        score = cap - 8.0 + fragmentation * 0.3 - progress * 5.0;
        if open_bins_count == 0 {
            score = -100.0; // must use a bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps quadratically.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual) as f64 * (13 - post_residual) as f64 * 2.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual <= 12 {
        score += 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 4.0;
        // But allow a new bin when open bins would leave terrible dead space.
        if post_residual > 0 && post_residual <= 12 {
            score -= 15.0;
        }
    } else {
        // Mild reward for filling bins tighter than the current mean residual.
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Early-stream exploration: prefer compacting into few bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when the next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            // Perfect chain (post_residual == next_item_size) is heavily rewarded.
            score -= 25.0 * (1.0 - chain_waste / cap);
            if post_residual == next_item_size {
                score -= 15.0; // exact 2-item fill
            }
        } else {
            // Next item cannot follow into this bin: penalize leftover dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
    } else {
        // Last item: just minimize final waste.
        score += 10.0;
    }

    // Compare post_residual relative to mean residual: leaving less than average
    // residual is good (we concentrated waste), leaving more than average is bad.
    let mean_post = mean_residual - item_size as f64;
    score += 0.5 * ((post_residual as f64) - mean_post);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large relative to typical residuals (poor fit elsewhere is likely).
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / cap;
        let crowded = (open_bins_count as f64) / (1.0 + mean_residual.max(1.0) / cap);
        // Reward new bin for big items or many crowded bins with small residuals.
        score -= 20.0 * large_item * large_item + 5.0 * crowded;
        // Penalize new bins when a good chain exists with the next item.
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score += 10.0; // an open bin could chain too; discourage needless opening
        }
    }

    // Mild preference to keep the number of open bins low early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.3 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (nonlinear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving very small unusable residuals (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate handling: default penalty so it is only chosen on poor fits.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If the next item is large and this item nearly fills a bin, new bin is fine.
        if next_item_size >= item_size && item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Prefer bins below mean residual (spread load evenly, keep big holes alive).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual (tight fit)
    let mut score = post;

    // Non-linear waste penalty: dead space grows super-linearly
    let waste_frac = post / cap;
    score += 60.0 * waste_frac * waste_frac * (1.0 + progress);

    // Fit quality: item size relative to residual, smooth coupling
    let fit_ratio = item_size as f64 / res.max(1.0);
    score -= 30.0 * fit_ratio * (1.0 - fit_ratio).max(0.0);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - waste_frac);
    }

    // New-bin candidate: penalize opening a new bin, more as stream progresses
    if bin_residual == bin_capacity {
        let urgency = (open_bins_count as f64).ln().max(0.0);
        score += 15.0 + 10.0 * urgency * (0.5 + progress);
        // But if current item is large and next item is also large, allow new bin
        if next_item_size > 0 && (next_item_size as f64) > 0.5 * cap {
            score -= 8.0;
        }
    }

    // Lookahead coupling: reward leaving space compatible with next item
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score += 0.15 * gap * (1.0 - progress);
        if post >= next_item_size as f64 && post < next_item_size as f64 + 10.0 {
            score -= 6.0; // near-perfect follow-up fit
        }
    }

    // Mean residual deviation: prefer bins deviating from mean to consolidate
    score += 0.05 * (res - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: partition residual space into
    // capacity-fraction classes (0, (0,10], (10,25], (25,50], (50,100]).
    // Small-but-nonzero residuals are the classic "dead space" trap.
    let post = post_residual;
    let class_penalty: f64 = if post == 0 {
        -40.0 // perfect closure: strongest reward
    } else if post <= 5 {
        -18.0 // near-perfect, likely closable by a tiny future item
    } else if post <= 10 {
        -8.0 // smallest standard item class can still seal it
    } else if post <= 25 {
        12.0 // awkward mid-class dead space
    } else if post <= 50 {
        4.0 // half-bin: still broadly reusable
    } else {
        0.0 // large residual: fine, plenty of room
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item-size atoms (10, 20, 25, 50) are "harmonic" — future items
    // drawn from typical distributions can tile them exactly.
    if post > 0 {
        if post % 10 == 0 {
            score -= 6.0;
        }
        if post % 25 == 0 {
            score -= 4.0;
        }
        if post % 50 == 0 {
            score -= 3.0;
        }
        // Odd, non-harmonic residuals are hard to fill: penalize.
        if post % 10 != 0 && post % 25 != 0 && post < 30 {
            score += 8.0;
        }
    }

    // Lookahead coupling (k=2): reward a residual that exactly or nearly
    // admits the next item; penalize when the next item cannot use this bin.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0; // perfect chain
        } else if next_item_size < post && post - next_item_size <= 10 {
            score -= 10.0; // near chain
        } else if next_item_size > post {
            score += 5.0; // next item can't go here anyway
        }
    }

    // Last-chance logic: if this is the only bin that fits the item, prefer
    // placing here over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post == 0 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large (would leave a bad class of dead space elsewhere) or
    // no open bin is a good harmonic match.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 20.0; // base cost of opening a new bin
        if item_frac > 0.5 {
            new_bin_score -= 12.0; // large items pair well with fresh bins
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // forced: no open bin fits
        }
        // Late in the stream, avoid proliferating bins with large residuals.
        new_bin_score += progress * 10.0;
        // If mean residual across open bins is large, reuse is cheap: discourage new bin.
        new_bin_score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 15.0;
        score = new_bin_score + post as f64;
    }

    // Mild global pressure: many open bins -> favor consolidation into
    // existing bins (already encoded via post_residual), tiny tie-breaker
    // preferring tighter bins when scores are otherwise equal.
    score += (open_bins_count as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that can't fit anything useful are heavily penalized.
    // Define "unusable" as post_residual below the minimum plausible item size (10),
    // or below the lookahead item size when it could otherwise pair with this bin.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead gap: worst outcome
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0; // gap can't host the next item
        } else {
            // Usable gap: reward proportionally (subtract) but keep exact-fit best.
            score -= 8.0;
        }
    } else {
        score -= 25.0; // perfect fill: strongly preferred
    }

    // Exact fit detection relative to next item: gap exactly fits next item -> great pairing.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless dead space would be terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
        if post_residual < 10 && post_residual > 0 {
            score += 20.0; // undo bonus if it creates a tiny dead gap
        }
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer compacting into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.35 + 0.4 * progress);

    // Mean-residual coupling: if mean residual is large, prefer bins below mean (tighter bins)
    // to consolidate waste; if mean residual is small, mild neutralization.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: brand-new empty bin should only win when placements
    // into open bins would create severe dead space. Give it a moderate baseline penalty.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the current item is large relative to capacity, a fresh bin is fine
        // (large items pair poorly anyway).
        if item_size >= bin_capacity / 2 {
            score -= 22.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but with a twist:
    // dead space below the smallest useful size is worthless.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: perfect match => strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-step match: place next item here too
        } else if post_residual >= next_item_size {
            // next item still fits here: reward proportional to closeness
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item won't fit here: penalize wasted remainder
            score += 8.0 + 0.35 * post_residual as f64;
        }
    }

    // Penalize residuals that are small but nonzero (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: placing in a bin that keeps residuals
    // balanced avoids accumulating many half-empty bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among multiple candidates, tie-break toward fuller bins
        score += 0.05 * (post_residual as f64);
    }

    // New-bin candidate logic: only attractive when the item fits poorly
    // everywhere else (large post_residual relative to capacity) or stream
    // is early and we can afford spreading.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // A fresh bin has huge post_residual; make it unattractive unless
        // the alternative would leave terrible fragments.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.85 {
            // big item in fresh bin is fine (post_residual small anyway)
            score -= 10.0;
        } else {
            score += 15.0 + 30.0 * (1.0 - fill_ratio) * (1.0 - progress);
        }
    }

    // Late in the stream: consolidate aggressively, discourage new bins.
    if progress > 0.8 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary tightness term: reward low post-residual with a convex penalty.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * bin_capacity as f64;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more dead space: mild reward proportional to fit quality.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize slightly if it would have fit well otherwise.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.15 * overshoot.min(30.0);
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
        if post_residual <= 10 {
            score -= 10.0;
        }
    }

    // Many fitting bins: competition exists, reward tighter fits more aggressively.
    if fitting_bins_count > 2 {
        score -= 0.5 * pr; // extra pressure toward minimal post-residual
    }

    // Fragmentation guard: penalize leaving residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny dead space is nearly unusable
    }

    // Global state coupling: high mean residual means bins are loose; prefer using fuller bins.
    let mr_frac = mean_residual / bin_capacity as f64;
    score += 10.0 * mr_frac * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Time horizon: early in the stream, be conservative about filling bins unevenly;
    // late in the stream, prioritize immediate tightness.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * (1.0 - pr / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is good when current bins fit poorly or are scarce.
        let poor_fits = if bin_residual >= item_size && fitting_bins_count <= 1 { 0.0 } else { 0.0 };
        let _ = poor_fits;
        // Base new-bin cost: discourage unless item is large relative to capacity
        // or the item would leave awkward residue in existing bins.
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let awkward = post_residual == 0; // empty bin always leaves residual == cap - item
        let _ = awkward;
        let mut new_bin_penalty = 25.0;
        if large_item {
            new_bin_penalty -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            new_bin_penalty -= 12.0; // new bin can also host the next item
        }
        if open_bins_count == 0 {
            new_bin_penalty = -100.0; // must open a bin
        }
        // If the only fitting open bin is a near-perfect fit, strongly discourage a new bin.
        if fitting_bins_count == 1 && post_residual <= 10 {
            new_bin_penalty += 30.0;
        }
        // Late in stream: keep new bins cheap to open since leftover space matters less.
        new_bin_penalty -= progress * 10.0;
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Smooth non-linear polynomial coupling between post_residual and stream progress
    let t = progress * (1.0 - progress) * 4.0; // peaks mid-stream, 0 at ends
    score -= 8.0 * t * pr_norm * (1.0 - pr_norm);
    score += 4.0 * pr_norm * pr_norm * progress;

    // Reward tight fits, more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (1.0 + 6.0 * progress) * 5.0;

    // Lookahead: penalize residual that fits next item (wasted pairing), reward otherwise
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score += 3.0 * (1.0 - ni / cap) * (0.5 + progress);
        } else {
            score -= 2.0 * (ni / cap);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize new-bin candidate unless residuals across open bins are large
    if bin_residual == bin_capacity {
        let mr = mean_residual / cap;
        score += 15.0 * (1.0 - mr) * (0.5 + progress);
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit reward: harmonic class of post_residual via modulo arithmetic.
    // Residuals that are multiples of the smallest item granularity (or zero) are "usable".
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always best
    } else if post_residual % 10 == 0 {
        score -= 8.0; // clean class residual, likely reusable by future small items
    } else if post_residual < 10 {
        score += 25.0; // dead space: unusable for items >= 10
    }

    // Fractional-capacity classes: reward leaving residuals in "attractive" quarters.
    let quarter = cap / 4.0;
    let pr = post_residual as f64;
    let class = (pr / quarter).floor(); // 0..4
    score += match class as u32 {
        0 => 6.0,   // tiny leftover, poor
        1 => 0.0,   // quarter left, okay
        2 => -3.0,  // half left, good
        3 => -2.0,  // three-quarters left, decent
        _ => -4.0,  // nearly full residual (small item in empty-ish bin)
    };

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to overshoot
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly everywhere else. Penalize the fresh bin normally; relax penalty
    // when the item is large relative to capacity (little to gain from squeezing).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 30.0 - 25.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: must open new bin
        }
        // Avoid opening new bins late in the stream when consolidation is possible
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Encourage balancing: prefer bins whose residual is below the mean
    // (packing big items into emptier bins keeps small-item flexibility).
    score += 0.3 * (pr - mean_residual).max(0.0);

    // Mild pressure to close bins: prefer fullest bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }

    // Penalize small but not-quite-zero gaps proportionally harder (dead space risk).
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap <= 10.0 {
            score += (10.0 - gap) * 3.0; // tiny gaps are nearly unusable
        } else if gap <= 20.0 {
            score += (20.0 - gap) * 1.0; // moderate dead-space risk
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual != bin_capacity {
        score -= open_pressure;
    } else {
        // New-bin candidate: penalize unless it would be a near-perfect fit
        // or existing bins have bad residuals relative to the item.
        score += 40.0;
        let tight_fit = (bin_capacity as f64 - item_size as f64) <= 5.0;
        if tight_fit {
            score -= 60.0;
        }
        // If mean residual across open bins barely exceeds the item, opening fresh is fine.
        if mean_residual < item_size as f64 + 3.0 {
            score -= 45.0;
        }
    }

    // Lookahead: if next item fits into the post-residual, reward leaving that space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover space can't serve next item: extra dead-space penalty
        score += 8.0;
    }

    // Late in the stream, waste matters more; early on, keep bins open flexibly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when post_residual exactly matches next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward.
        if gap == 0.0 {
            score -= 40.0;
        } else {
            score += gap * 0.35;
        }
        // Penalize leaving dead space too small for the next item.
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: just prefer tightest packing.
        score -= 5.0;
    }

    // Prefer bins already below mean residual (nearly-full bins absorb items,
    // keeping roomy bins flexible).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits terribly everywhere (item near capacity or huge relative to residuals).
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (fitting_bins_count == 1 && bin_residual.saturating_sub(item_size) > bin_capacity / 2);
        if poor_fit_elsewhere && fit_ratio > 0.5 {
            score -= 10.0; // open fresh bin for big items with no good home
        } else {
            score += 25.0; // discourage wasting a fresh bin on small/easy items
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (0..1).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Reward high fill (tight fits) with a non-linear boost.
    score -= fill * fill * 30.0;

    // Penalize dead space that is too small to hold typical items:
    // post_residual in 1..10 is nearly unusable -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward heavily; if it almost fits, mild penalty for wasting the space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fill would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: opening a new bin should be rare.
    if bin_residual == bin_capacity {
        // Base reluctance grows with number of open bins and progress.
        score += 20.0 + 3.0 * open_bins_count as f64 + 15.0 * progress;
        // If the item fills the new bin well (>= 70%), allow it more readily.
        if fill >= 0.7 {
            score -= 25.0;
        }
        // If existing bins fit poorly (high mean residual spread) and item is
        // large, a fresh bin can be sensible; soften reluctance.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 10.0;
        }
    } else {
        // Reward using bins that are already partially filled when mean
        // residual is high (consolidation of fragmented space).
        if mean_residual > 30.0 {
            score -= (mean_residual - 30.0).min(20.0) * 0.3;
        }
    }

    // Mild pressure to reduce total open bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress + 0.4 * progress * norm_pr);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * fit * (1.0 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) / cap;
        score += waste * waste * 2.0;
        // Reward leaving room exactly for next item
        score -= (1.0 - ((pr - nx).abs() / cap).min(1.0)) * 0.5;
    }

    // Last-chance bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.5 + progress;
    }

    // Mild penalty for spreading across many bins when mean residual is high
    score += 0.1 * (open_bins_count as f64).ln() * (mean_residual / cap);

    // New-bin candidate: penalize slightly unless current bin would be near-perfectly filled
    if bin_residual == bin_capacity {
        score += 0.6 - 1.2 * fit * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are "dead" (too small
    // for any plausible item, i.e. < 10) are pure waste; residues that are
    // exact capacity fractions are reusable slots.
    let dead = if post_residual < 10 { 1.0 } else { 0.0 };

    // Modulo-class coupling: post_residual mod 10 classifies the leftover into
    // decade harmonics. Small non-zero residues are penalized extra.
    let residue_class = (post_residual % 10) as f64;
    let harmonic_penalty = if post_residual > 0 { residue_class / 10.0 } else { -0.5 };

    // Integer-division threshold: how many "average items" still fit.
    let slots = post_residual / 20;

    // Tight fit reward: post_residual near zero is excellent.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space strongly.
    score += 60.0 * dead;

    // Penalize awkward harmonic leftovers (1..9 residue).
    score += 6.0 * harmonic_penalty;

    // Reward bins that retain at least one usable slot.
    score -= 8.0 * slots as f64;

    // Lookahead: if the next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if next item fills the bin completely (perfect chain).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't chain: penalize proportionally to wasted potential.
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // (i.e. consuming a large residual) is good; bins above mean are hoarders.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: an empty bin is only attractive when the
    // current bin landscape is poor (many open bins with scattered residuals)
    // or when this bin would leave a dead harmonic leftover.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 55.0;
        // If the item would leave dead space in any existing bin, opening fresh
        // is better.
        if dead == 1.0 {
            new_bin_score -= 70.0;
        }
        // If the next item also fits a fresh bin alongside this one nicely.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_bin_score -= 15.0;
        }
        // Fewer open bins => cheaper to open a new one (less fragmentation risk).
        new_bin_score -= 2.0 * (10usize.min(open_bins_count)) as f64;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 25.0 * progress;
        // Compare against this bin's placement quality: only override when the
        // existing placement is bad.
        if new_bin_score < score {
            score = new_bin_score;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: strongly reward zero post_residual.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize small unusable gaps (dead space) heavily.
    // A residual gap is "dead" if it can't fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    } else if post_residual < 25 {
        // Semi-dead space: mild penalty proportional to closeness to dead zone.
        score += (25.0 - post_residual as f64) * 2.0;
    }

    // Reward leaving a gap that exactly fits the next item (lookahead k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Favor bins that can also serve the next item.
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Pressure to fill existing bins when many are open: scale penalty on new bins.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // Opening a new bin is penalized more when many bins are already open.
        score += 40.0 + open_bins_count as f64 * 3.0;
        // But if all open bins would create dead space, opening may win anyway.
        if post_residual == bin_capacity - item_size {
            // neutral-ish: still penalized via the terms above.
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) to
    // consolidate space and keep looser bins available for larger future items.
    if !new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += (bin_residual as f64 - mean_residual) * 0.15;
        }
    }

    // Late in the stream, be extra conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the remaining space: good chaining
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual as f64 - next_item_size as f64).min(20.0) * 0.15;
    }
    // Dead space below the smallest plausible item is wasted
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: avoid opening a new bin when only this one fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Compare post_residual against mean residual: leaving more than average is worse
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, be more liberal about using open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // New-bin candidate: penalize moderately so it is chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that nothing can use (min item size 1, but
    // typical items are larger; treat small slivers as waste).
    if post_residual < item_size.min(10) {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // Base cost of opening a bin; grows with number of open bins.
        score += 55.0 + 3.0 * pressure;
        // Lookahead: if next item fits perfectly with current item in a fresh bin,
        // make new bin more attractive.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            let pair_waste = bin_capacity - item_size - next_item_size;
            score -= (pair_waste as f64).max(0.0) * 0.5;
        }
        // Early in stream, opening bins is cheaper (need spread).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead synergy in existing bins: if next item fits exactly into
    // post_residual, reward strongly.
    if next_item_size > 0 && bin_residual != bin_capacity {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Prefer bins with residual below mean (filling down the average).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: penalize leftover space, with non-linear growth for large dead space
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftovers; late, squeeze bins harder
    let progress_coupling = 0.35 * progress * (1.0 - progress) * 4.0; // hump mid-stream
    score += post * progress_coupling;

    // Reward tight fits (small post_residual) with a non-linear bonus
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.1 * item_size as f64;
    }

    // Penalize bins far from the mean residual (keeps residual profile balanced)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: if next item fits into the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack = (post - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: mild penalty for stranded space
        score += 3.0 * norm_post;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Discourage opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            // No alternative: opening a new bin is fine, remove the penalty
            score -= 20.0;
        }
    }

    // Mild penalty for proliferating open bins, smoothed by progress
    score += 0.02 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let prog = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity && item_size <= bin_capacity;

    // Perfect fill: strongest reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Harmonic class logic: residuals aligned to decade boundaries are
    // more likely to host future items drawn from coarse-grained streams.
    score += (post_residual % 10) as f64 * 0.6;
    score += ((post_residual / 10) % 3) as f64 * 1.5;

    // Lookahead coupling: if the next item fits into the post residual,
    // this placement chains well; otherwise the leftover is likely dead.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Extra reward when next item exactly consumes the remainder.
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only open bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins could fit,
    // with the penalty relaxing late in the stream when consolidation matters less.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 55.0 - 30.0 * prog;
        } else {
            // No alternative: opening is fine, small progress-aware bonus.
            score -= 5.0 + 10.0 * prog;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (placing into tighter-than-average bins preserves large residuals elsewhere).
    if !is_new_bin && mean_residual > 0.0 {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.15;
    }

    // Late-stream tightening: discourage leaving mid-size residuals near the end.
    if prog > 0.8 && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strongly reward (zero dead space).
    if post_residual == 0 {
        score -= 500.0;
    }

    // Unusable dead space: gaps smaller than the smallest plausible item are worthless.
    let dead_threshold: u32 = 8;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 300.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Reward leaving room for the lookahead item if it fits in the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Extra reward when the next item would fill the bin completely afterwards.
        if post_residual - next_item_size == 0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize wasting space the known next item cannot use.
        score += 20.0;
    }

    // Open-bins pressure: when many bins are open, favor packing into existing bins
    // (penalize the new-bin candidate, whose residual equals capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 15.0 * open_bins_count as f64 + 50.0 * progress;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer bins tighter than the mean residual (better global balance).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Slight preference for high fill ratio.
    score -= 0.3 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = (post_residual as f64) * 1.0;

    // 2-step lookahead: reward when post_residual matches next_item_size exactly,
    // penalize when the next item cannot fit into post_residual.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (pr - ni).abs();
            // Perfect match: strong reward.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
            // Slight bonus if next item fits at all.
            score -= 5.0;
        } else {
            // Next item won't fit here: penalize proportional to overflow.
            let overflow = ni - pr;
            score += 10.0 + 0.5 * overflow;
        }
    }

    // Penalize dead space that is too small for the minimum item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins that are already below-average residual
    // (filling the emptiest bins first keeps many usable bins open).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(-50.0).min(50.0);

    // Last-chance bin: if this is the only bin that can fit the item, prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (i.e., all fits would leave large unusable residuals relative to item sizes).
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a good fit's score.
        score = bin_capacity as f64 * 0.5;
        if next_item_size > 0 && next_item_size <= item_size {
            // A fresh bin can pair current + next item well.
            score -= 15.0;
        }
        if fitting_bins_count > 0 {
            // Discourage opening new bin when decent fits exist.
            score += 10.0;
        }
        // Early in stream, slightly favor consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Many open bins: encourage using existing ones rather than growing the pool.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize wasted residual non-linearly: dead space that can never be
    // filled by typical items (1..=100, but small residuals are hard to use)
    let dead_zone = 15.0f64;
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 2.5;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // post residual is dead for the next item: mild penalty scaled by gap
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.3;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible)
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it unattractive by default; it wins only when all fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But early in the stream or when few bins are open, allow growth
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        if open_bins_count < 2 {
            score -= 20.0;
        }
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is reasonable
        if mean_residual < 20.0 {
            score -= 15.0;
        }
    } else {
        // Prefer tighter existing bins: reward small post_residual relative to mean
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Mild preference for keeping more slack in the system later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = (r / cap).clamp(0.0, 1.0);

    // Base: prefer small post residual, with smooth polynomial shaping.
    let mut score = r * (1.0 + 0.5 * fit_norm * fit_norm);

    // Non-linear coupling of residual with stream progress:
    // late in the stream, dead space becomes more costly.
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * (r * r) / cap;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * (1.0 + late) * 8.0;

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + late);
    }

    // Penalty for opening a new bin when open bins fit well.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 10.0 + 20.0 * late
            + 5.0 * (fitting_bins_count as f64).ln().max(0.0);
        // Less penalty if item is large (would leave big residual elsewhere).
        let size_relief = (item_size as f64 / cap) * 8.0;
        score += new_bin_penalty - size_relief;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let gap = r as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - (gap / cap).clamp(0.0, 1.0));
        } else {
            score += 4.0;
        }
    }

    // Mild diversity term: avoid fragmenting when many bins are open.
    score += (open_bins_count as f64).ln() * (r / cap) * 2.0;

    // Mean residual coupling: prefer bins near the mean (keeps spread small).
    score += ((r - mean_residual) / cap).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small nonzero post_residual is the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Harmonic classes: post_residual buckets by integer division of capacity.
    // Residuals in the "half-capacity" class (40..=60) are highly reusable.
    let post_class = post_residual / 20; // 0..=5
    match post_class {
        0 => score += 40.0,                       // 0..19: nearly dead space
        1 => score += 10.0,                       // 20..39: moderate
        2 => score -= 30.0,                       // 40..59: golden zone
        3 => score -= 20.0,                       // 60..79: good
        4 => score -= 5.0,                        // 80..99: fine
        _ => {}                                   // empty/new bin class
    }

    // Lookahead coupling: reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic bonus scaled by how well next item divides into residual.
            let k = post_residual / next_item_size.max(1);
            score -= 15.0 + 5.0 * (k.min(4) as f64);
        } else {
            // Next item won't fit here: mild penalty if we leave a mid residual.
            if post_residual >= 10 && post_residual < next_item_size {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a bin is usually wasteful unless
    // the item fits poorly everywhere or the stream is early with few bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 150.0;
        // Cheaper to open a bin early in the stream (bins amortize longer).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 80.0 * (1.0 - progress);
        // If many bins are open with slack, opening another is worse.
        score += (open_bins_count as f64).min(20.0) * 2.0;
        // If mean residual across open bins is large, opening a new bin is bad.
        score += (mean_residual / 10.0).min(15.0);
        // If this is the only fitting option anyway, new-bin cost is irrelevant.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild preference for tighter existing bins when residuals are close.
    score += (bin_residual as f64 - post_residual as f64) * 0.0; // no-op guard
    score -= mean_residual * 0.05 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest future item (size >= 1) are worthless; residuals that cannot
    // hold a "typical" item are heavily penalized.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // unusable dead space
    } else if post_residual < 20 {
        score += 18.0; // nearly unusable
    } else if post_residual < 35 {
        score += 6.0; // marginal gap
    } else {
        // Larger usable gaps get a mild reward scaled by usefulness
        score -= (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Reward tight fits: small post_residual relative to residual capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.8 {
        score -= 12.0;
    } else if fit_ratio > 0.6 {
        score -= 5.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow.
        score += 25.0 + 6.0 * pressure;
        // But if no existing bin fits well, opening may be justified:
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Early in stream, new bins are cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    } else {
        // Existing bin: reward being one of few fitting options (last chance).
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Reward bins tighter than average (they're scarce capacity).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Lookahead: if next item would fit the post-residual, this placement
    // chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Perfect chain: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // If next item is large and this bin would leave a big gap, slight penalty.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size && post_residual < 30 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 150.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize wasting a good residual
        score += 30.0;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    let rel = post_residual as f64 - mean_residual;
    score += 0.5 * rel;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin unless the item is large relative to residual
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 60.0 * (1.0 - fill_ratio);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin serves the next item too
        }
    }

    // Late-stream tightening: fewer open bins pressure toward consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small dead-space penalty (nonlinear): residuals in awkward mid-range
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0; // tiny unusable sliver
        } else {
            score += 0.15 * pr;
        }
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if we leave awkward gap.
        score += 0.1 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only open a new bin when current bin fit is bad
    // and many bins are already open (fragmentation risk) or early stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = item_size as f64 / cap; // small item into fresh bin = wasteful
        let mut new_bin_score = cap - item_size as f64; // residual baseline
        // Opening new bin is attractive if item is large (good fill) or few bins open.
        new_bin_score -= 20.0 * fit_quality;
        if open_bins_count == 0 {
            new_bin_score -= 50.0;
        }
        // Late in stream, prefer consolidating into open bins.
        new_bin_score += 15.0 * progress;
        // If existing open bins are fragmented (high mean residual), fresh bin ok.
        new_bin_score -= 0.05 * mean_residual;
        score = new_bin_score;
    }

    // Mild preference for filling bins with lower residual among equals.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on wasted space, weighted by stream progress
    let mut score = norm_post * (1.0 + 1.5 * norm_post) * (0.6 + 0.8 * progress);

    // Smooth coupling: waste hurts more when few bins remain open relative to items seen
    let density = (open_bins_count as f64 / (total_items as f64).max(1.0)).clamp(0.0, 1.0);
    score *= 1.0 + 0.5 * (1.0 - density);

    // Reward tight fits via smooth saturation of post_residual
    let tightness = 1.0 - (post / (cap * 0.5)).min(1.0);
    score -= 2.0 * tightness * tightness;

    // Lookahead coupling: reward if next item fits smoothly in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 0.8 * (1.0 - 2.0 * slack).max(0.0);
        } else {
            score += 0.4 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current item is huge
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        score += 2.5 * (1.0 - big_item) * (1.0 - 0.5 * progress);
        // allow new bin late in stream when open bins are mostly full
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 1.5 * mean_fill * mean_fill * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual via integer division thresholds.
    // Classes: [0], [1..10] (dead space, unusable for min item), [10..33], [33..50], [50..75], [75..100].
    let cls = if post_residual == 0 { 0u32 }
        else if post_residual < 10 { 1 }
        else if post_residual < 33 { 2 }
        else if post_residual < 50 { 3 }
        else if post_residual < 75 { 4 }
        else { 5 };

    match cls {
        1 => { score += 120.0; } // tiny dead space: worse than a mid gap
        2 => { score -= 20.0; }  // usable small gap
        3 => { score -= 10.0; }
        4 => { score -= 25.0; }  // large gaps are valuable, keep them
        5 => { score -= 40.0; }
        _ => {}
    }

    // Lookahead coupling: if the next item fits in the resulting gap, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 60.0 - tightness * 0.8; // tight follow-up fit rewarded most
    }
    // If next item almost fits (within 10), slight penalty: gap is tantalizing but likely wasted.
    else if next_item_size > 0 && next_item_size <= post_residual + 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        let mut penalty = 150.0;
        if fitting_bins_count <= 2 {
            penalty = 30.0; // few alternatives: opening a bin is reasonable
        }
        if post_residual < 20 {
            penalty += 100.0; // big item in fresh bin leaves little room: fine, don't over-penalize
        }
        score += penalty;
    }

    // Mild stream-phase adaptation: early on, be frugal with bins.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += (1.0 - phase) * 40.0;
    }

    // Prefer filling bins that deviate below the mean residual (balance consolidation).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit even the
    // smallest plausible item are pure waste — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is the ideal placement.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize residuals that can only fit a narrow slice of future items
    // (small but not dead gaps are still mostly wasted capacity).
    if post_residual > 0 && post_residual < 25 {
        score += 0.8 * (25.0 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // tighter bins; with few open bins, filling is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.15;

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward creating that chain; if post-residual is smaller than the
    // next item (likely dead for it), penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else if post_residual > next_item_size {
            score -= 5.0;
        }
    }

    // New-bin candidate: an empty bin should only win when no open bin offers
    // a decent fit. Base it on mean residual: if mean residual is large,
    // open bins are roomy, so discourage opening a new one.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 20.0;
        if mean_residual < item_size as f64 + 15.0 {
            // Open bins are tight; allow new bin by lowering score.
            score -= 30.0;
        }
        // Late in the stream, opening a new bin is less costly in the long run.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after hypothetical second placement
            let second_left = post_residual - next_item_size;
            score += second_left as f64 * 0.6;
        } else {
            // next item doesn't fit here: mild bonus for keeping space free? penalize waste
            score += 15.0;
        }
    } else {
        // last item: prefer minimal post_residual
        score += 5.0;
    }

    // Prefer bins tighter than mean residual (good fillers)
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let base = 120.0 + post_residual as f64;
        // cheaper to open new bin only if all fits are bad (high post_residual elsewhere)
        score = base - (fitting_bins_count as f64) * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0; // fresh bin can host next item too
        }
    }

    // Late stream: consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    // Slight penalty per open bin to discourage sprawl
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward small post-residual relative to item size (tight fit)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 / (1.0 + tightness);

    // Penalize large dead space: post residual too small to ever fit typical items
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (1.0 - progress * 0.5);
        } else {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many fitting bins: mild penalty for hoarding space in this one if it's already tight
    if fitting_bins_count > 2 {
        score += 3.0;
    }

    // Global state: penalize bins whose residual deviates below mean (wasting space unevenly)
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate handling: empty bin gets a baseline cost, so it only wins
    // when open bins are genuinely bad fits (high post_residual or big dead space).
    if bin_residual == bin_capacity {
        score += 55.0;
        // Opening a new bin is cheaper early in the stream or when item is large
        score -= 30.0 * progress;
        if item_size >= 70 {
            score -= 25.0;
        }
        // If next item is huge, a fresh bin is attractive
        if next_item_size >= 70 {
            score -= 15.0;
        }
    }

    // Mild penalty for very loose fits (item much smaller than residual)
    if (item_size as f64) < 0.35 * bin_residual as f64 && bin_residual < bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: prefer tight fits, with a smooth non-linear (quadratic) coupling
    // that penalizes large post-residuals progressively harder over time.
    let mut score = pr + 0.9 * (pr / cap) * pr * (0.5 + progress);

    // Reward filling bins almost exactly (dead-space aversion, super-linear).
    if post_residual <= 5 {
        score -= 12.0 + 10.0 * progress;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward it;
    // smooth polynomial interaction between leftover and next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).abs();
        score -= 8.0 * (1.0 - gap / cap).powi(2) * (1.0 - 0.5 * progress);
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin, scaled by stream progress.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the
    // current item is large relative to capacity or many bins already fit.
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * (item / cap) - 5.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Mild preference for bins already below mean residual (balance avoidance
        // of many half-empty bins) via smooth coupling.
        score += 0.05 * (mean_residual - bin_residual as f64).abs();
    }

    // Smooth progress-driven tightening: as stream advances, demand tighter fits.
    score *= 1.0 + 0.3 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near capacity fractions
    // create "dead space" classes. Classify post_residual into harmonic bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals that are too small to ever fit a plausible item (1..100),
    // i.e. post_residual == 0 is perfect, but tiny residuals (1..=9) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward exact fit strongly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic classes: post_residual divisible by common item sizes (10,20,25,50)
    // tends to remain reusable; reward those residues.
    if post_residual % 10 == 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 {
        score -= 10.0;
    }
    if post_residual % 50 == 0 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Prefer leaving a well-structured residual for the next item.
            if next_post % 10 == 0 {
                score -= 25.0;
            }
            if next_post == 0 {
                score -= 60.0;
            }
            // Penalize leaving a residual barely larger than next item (fragmentation).
            let slack = (post_residual - next_item_size) as f64;
            if slack > 0.0 && slack < 10.0 {
                score += 30.0;
            }
        } else {
            // Next item cannot follow into this bin: mild penalty unless residual is 0.
            if post_residual > 0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer open bins with decent fits; only choose a new bin when all open fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a new bin early in the stream (long horizon amortizes),
        // or when many bins are open (dispersion is fine).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        if open_bins_count > 3 {
            score -= 10.0;
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    } else {
        // For open bins: prefer bins whose residual is close to item (tight fit)
        // beyond the raw post_residual ordering.
        let tightness = (bin_residual - item_size) as f64 / cap;
        score += 20.0 * tightness * tightness;
        // Prefer filling bins that deviate below mean residual (consolidate fuller bins).
        score += 0.3 * (mean_residual - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful later
    // are heavily penalized. Treat residual <= 10 as pure dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 25.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score += 8.0;
    }

    // Reward very tight fits (small gaps that are still "clean").
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(20.0);
    }
    // If next item would NOT fit in the residual, and residual is dead space, penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new bins,
    // encourage filling existing ones (except the brand-new candidate).
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        score -= (open_bins_count as f64).sqrt() * 3.0;
    } else {
        // New bin candidate: penalize when open-bin pressure is high or item fits well elsewhere.
        score += (open_bins_count as f64) * 2.5;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Opening a new bin is attractive if the current mean residual is large and
        // fragmented (item would leave big dead space everywhere).
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= progress * 10.0;
    } else {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: residual zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fits post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits after this placement; mild reward scaled by tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * tightness;
        } else {
            // Next item won't fit here: penalize leaving large dead space.
            score += 0.5 * (post_residual as f64 - 1.0);
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize new-bin candidate unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        let good_fit_exists = post_residual < 20 || (next_item_size > 0 && next_item_size == post_residual);
        if good_fit_exists {
            score += 500.0;
        } else {
            score += 50.0;
        }
    }

    // Slight preference early in stream to consolidate bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on leftover space.
    score += (post_residual as f64 / cap) * (post_residual as f64) * 0.6;

    // Last chance: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Mild preference for bins among many candidates by tightness.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            let combo = post_residual as u32 - next_item_size;
            if combo == 0 {
                score -= 30.0;
            } else {
                score -= 8.0 * (1.0 - combo as f64 / cap);
            }
        } else if next_item_size <= bin_residual {
            // Next item fits this bin but current item blocks a perfect combo elsewhere;
            // penalize leaving a residual that wastes the slot.
            score += 6.0;
        }
    }

    // New-bin candidate logic: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 / cap) > 0.25;
        if fitting_bins_count == 0 || poor_fit {
            score -= 15.0 + 10.0 * progress;
        } else {
            // Penalize opening bins when open bins fit reasonably well.
            score += 25.0 + 3.0 * open_bins_count as f64;
        }
        // Early stream: slightly favor consolidation, avoid bin explosion.
        if progress < 0.3 {
            score += 10.0;
        }
    }

    // Global residual balance: prefer bins below mean residual (denser bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Late stream: squeeze harder, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: post-residual, smoothly warped by a polynomial in progress.
    let warp = 1.0 + 0.6 * progress * (1.0 - progress) * 4.0;
    let mut score = post * warp;

    // Non-linear coupling: dead-space penalty grows quadratically as residual shrinks.
    let tightness = 1.0 - post / cap;
    score += 0.5 * post * tightness * tightness;

    // Reward near-perfect fits (small post_residual) with a smooth exponential bonus.
    score -= 6.0 * (-post / 6.0).exp() * (1.0 + 0.3 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let diff = post - next_item_size as f64;
        score -= 4.0 * (-diff / 10.0).exp();
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving large unusable gaps.
        score += 0.3 * post * (item / cap);
    }

    // New-bin candidate: penalize mildly so open bins are preferred unless fit is poor,
    // penalty decays as stream progresses (late stream: consolidation matters more).
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress + 0.05 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (balance the pool smoothly).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Harmonic class analysis of post_residual: dead space that no future item
    // (sizes 1..=100) can pair with is worse. Classes mod 10 as capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / bin_capacity as f64;
    // Penalize residuals in "awkward" bands: too big to waste, too small to reuse.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -6.0,                      // round residual, highly reusable
        1 | 2 | 3 => 4.0,               // sliver, nearly dead space
        8 | 9 => 2.0,                   // almost a full slot, slightly awkward
        _ => 0.0,
    };
    score += class_penalty + 10.0 * frac;

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills what remains.
            if next_item_size == post_residual {
                score -= 25.0;
            } else {
                score -= 8.0 * (next_item_size as f64 / post_residual as f64);
            }
        } else {
            // Next item cannot use this bin's remainder; dead space risk grows.
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * gap.sqrt();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are congested
    // (mean residual low) or the fit here is terrible.
    if bin_residual == bin_capacity {
        let congestion = (mean_residual / bin_capacity as f64) - 0.5; // >0 means roomy bins
        let fit_quality = (post_residual as f64) / bin_capacity as f64; // = 1 - item/C for new bin
        // Opening a bin costs a lot unless existing bins are nearly full.
        score += 45.0 - 40.0 * congestion.max(-1.0);
        // Large items prefer fresh bins when current fits are poor.
        if item_size >= 60 && mean_residual < item_size as f64 * 0.6 {
            score -= 25.0;
        }
        let _ = fit_quality;
    }

    // Stream progression: late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Mild pressure to keep bin count low: favor existing bins when many are open.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln() * 0.5;
    }

    // Small coupling with mean residual: prefer bins below mean residual (fill emptier
    // bins first keeps fuller bins available for large items? inverse: prefer filling
    // fuller bins to close them out).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits proportionally to fill ratio.
        let fill = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fill * fill;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap just below the next item size (near-miss dead space).
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(3) && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it unattractive unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But allow a fresh bin for large items that would leave tiny gaps anywhere.
        if item_size >= bin_capacity - 10 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), normalized against capacity.
    score *= 1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: reward if the next item fits into post_residual exactly or snugly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: item + next item fills bin exactly.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snug the chain is.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 + 30.0 * snug;
        } else {
            // Next item does NOT fit: post_residual becomes dead space for the lookahead.
            let waste = (next_item_size - post_residual) as f64;
            // Penalize more when waste is small-but-nonzero (awkward dead space),
            // and when the leftover is below the minimum item size.
            score += 8.0 + 0.4 * waste;
            if post_residual < 10 {
                score += 15.0; // unusable sliver
            }
        }
    }

    // Relative-to-mean coupling: placing in a bin with residual far below mean
    // concentrates waste into few bins (good); avoid draining already-small bins
    // into slivers unless the fit is tight.
    if (bin_residual as f64) < mean_residual {
        score += 0.15 * (mean_residual - bin_residual as f64);
    } else {
        score -= 0.10 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing bins
    // offer poor fits. Penalize opening a new bin mildly, more so when many bins
    // are already open (fragmentation cost) and early in the stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 0.5 * open_bins_count as f64 + 10.0 * (1.0 - progress);
        // But if the next item is huge and won't fit anywhere useful anyway,
        // a fresh bin is fine for chaining large items.
        if next_item_size >= item_size && next_item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Mild preference for keeping bin count stable: reward filling bins that
    // are already well-utilized.
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * used;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: very small post-residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // mild reward proportional to how well next item fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fill;
        } else {
            // next item won't fit here; slight penalty scaled by leftover size
            score += 0.1 * (post_residual as f64).sqrt();
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: base cost of opening a fresh bin.
    if bin_residual == bin_capacity {
        // Opening a new bin costs roughly the wasted space it starts with
        // relative to the item; make it unattractive unless fits are poor.
        score = cap - item_size as f64 + 30.0;
        if fitting_bins_count <= 1 {
            // no real alternative: new bin is fine
            score -= 25.0;
        }
        // Late in the stream, slightly cheaper to open new bins to keep options open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins (penalize this bin less if it's tight).
    if open_bins_count > 0 {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 5.0 * tightness * (mean_residual / cap).min(1.0);
    }

    // Prefer filling fuller bins: reward small post_residual relative to capacity.
    score -= 15.0 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual, with smooth polynomial sharpening
    let x = pr / cap; // normalized post-residual in [0,1]
    let mut score = pr as f64 * (1.0 + 2.0 * x * x) - 8.0 * x * (1.0 - x);

    // Tight-fit reward: strongly favor bins where the item fills most of the residual
    let fill_ratio = it / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio * (1.0 - fill_ratio);

    // Lookahead coupling: penalize leaving residuals that can't host the next item,
    // reward residuals that can exactly-ish accommodate it
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = pr - ni;
            score -= 6.0 * (1.0 - slack / cap); // next item fits: bonus, tighter is better
        } else {
            let waste = ni - pr;
            score += 5.0 * (waste / cap) * (waste / cap); // dead space for next item
        }
    }

    // Last-chance bin: reward using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // allow it late in the stream or when mean residual is large (poor spread)
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 6.0 * (1.0 - progress) - 10.0 * mean_norm * mean_norm;
    }

    // Smooth stream-progress coupling: later in stream, be greedier about tight fits
    score *= 1.0 - 0.25 * progress * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer small post-residual (tight fit), but not zero waste blindly.
    let mut score = post;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable"
    // class (divisible into common item sizes) are better than dead-space classes.
    let usable = post_residual % 10 == 0 || post_residual % 20 == 0
        || (post_residual >= 10 && post_residual % 15 == 0);
    if usable { score -= 6.0; } else { score += 4.0; }

    // Dead space penalty: leftover too small for the minimum item (1..100 interface,
    // but tiny slivers below 10 are classic dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect closure
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next > 0.0 && post_residual as f64 >= next {
        let slack = (post_residual as f64 - next) / cap;
        score -= 12.0 * (1.0 - slack);
    } else if next > 0.0 {
        // Next item won't fit here: mild penalty scaled by how close it was.
        let miss = (next - post as f64) / cap;
        score += 5.0 * miss;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    // Opening a new bin is attractive only when the current fit is poor (large post)
    // or the item is small enough to leave a versatile residual.
    if bin_residual == bin_capacity {
        // Penalize opening new bins when many are open and mean residual is high.
        score += open_bins_count as f64 * 1.5 + mean_residual * 0.3;
        // Reward opening a new bin if item is large (keeps open bins for small items).
        score -= (item / cap) * 20.0;
        // If item is small and would waste an almost-empty bin's versatility, penalize.
        if item < 0.4 * cap {
            score += 8.0;
        }
    } else {
        // Reward using existing bins, especially when they are relatively full.
        let fill = (bin_residual as f64) / cap;
        score -= 5.0 * fill;
        // Congestion: many open bins -> prefer filling existing ones.
        score -= open_bins_count as f64 * 0.2;
    }

    // Stream progression: late in the stream, avoid opening new bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    // Integer-division threshold class on item size: big items want tight bins.
    let item_class = item_size / 20; // 0..4
    score -= item_class as f64 * (1.0 - fill_of(bin_residual, bin_capacity));

    score
}

#[inline(always)]
fn fill_of(residual: u32, capacity: u32) -> f64 {
    1.0 - (residual as f64 / capacity as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1..100 unknown,
    // but typical min ~10) can ever use are pure waste.
    if post_residual < 10 {
        // Unusable sliver: heavy penalty proportional to how "locked" the gap is.
        score += 60.0;
    } else if post_residual <= 15 {
        score += 18.0;
    } else if post_residual <= 25 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual that is still usable).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the resulting residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            // Next item would create dead space here — mild penalty.
            score += 8.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            // Residual becomes unusable for the known next item.
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).powf(1.2) * 0.35;

    // Mean-residual coupling: if open bins are already loose (high mean residual),
    // penalize placements that leave this bin much looser than average.
    if post_residual as f64 > mean_residual * 1.5 {
        score += 5.0;
    } else if (post_residual as f64) < mean_residual * 0.5 {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when open bins are congested or fit is hopeless.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, growing with stream progress.
        score += 20.0 + 25.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin fits
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Empty bin keeps full flexibility for the next item.
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Strong reward: post-residual exactly matches the next item (perfect 2-step chain)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // post-residual can still host the next item: reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 * (waste / 100.0).min(1.0);
        }
    }

    // Reward tight fits overall (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Penalize new-bin opening, softened when existing bins have poor residuals
    if is_new_bin {
        let mean_r = mean_residual.max(0.0);
        // opening a new bin is attractive only if mean residual is very small
        let open_penalty = 30.0 - 0.4 * mean_r;
        score += open_penalty.max(5.0);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin is a good host for the next item
        }
    }

    // Slight preference for consolidating into bins with larger residuals
    score += 0.05 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Late-stream tie-break: favor filling bins nearly full
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer minimal post residual (tight fit).
    let mut score = post;

    // Fractional tightness: reward filling the bin well.
    let fill_frac = item / cap;
    score -= 30.0 * fill_frac;

    // Dead space penalty: small post residual is good, but a tiny unusable
    // sliver (< 10) is dead weight; mildly penalize slivers to prefer
    // placements leaving either zero or usable residue.
    if post > 0.0 && post < 10.0 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement.
    if next > 0.0 && (post_residual as u32) == (next_item_size as u32) {
        score -= 25.0;
    } else if next > 0.0 && next <= post {
        // next item fits here too: good, mild reward proportional to fit
        score -= 5.0 * (next / post.max(1.0));
    } else if next > 0.0 && next > post {
        // next item won't fit here: slightly penalize leaving large residue
        // that will likely be wasted.
        score += 3.0 * (post / cap);
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins with high mean residual: encourage consolidation into
    // existing bins rather than spreading.
    if open_bins_count > 2 {
        let consolidation_bonus = ((open_bins_count as f64).ln()) * 4.0;
        score -= consolidation_bonus * (1.0 - (post / cap));
    }

    // Penalize bins that are outliers far above the mean residual when
    // placing a large item (keep big items in already-loose bins? No—
    // actually prefer placing into bins with residual close to item size).
    let diff = (bin_residual as f64 - item).abs();
    score += 0.15 * diff;

    // New-bin candidate handling: brand-new empty bin. Only attractive when
    // the item is huge (fits poorly everywhere) or no other bin fits well.
    if bin_residual == bin_capacity {
        let huge = item > 0.75 * cap;
        let poor_options = fitting_bins_count == 0
            || (mean_residual < item * 0.9 && fitting_bins_count <= 1);
        if huge || poor_options {
            score -= 45.0; // open a new bin for a clean placement
        } else {
            score += 60.0; // discourage opening bins when fits exist
        }
    }

    // Time horizon: early in the stream, be slightly more conservative
    // (favor new bins for structure); late, squeeze everything in.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 10.0 * progress * (1.0 - (post / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let norm_residual = bin_residual as f64 / cap;

    // Base: prefer small post residual (tight fit), non-linear coupling with progress
    let mut score = post * (1.0 + 0.6 * progress * progress);

    // Reward tight fits more strongly as stream progresses (smooth polynomial term)
    let tightness = 1.0 - post / cap;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving dead space that can't fit typical future items
    let dead = (post - norm_next * cap).max(0.0) / cap;
    score += 30.0 * dead * dead;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate penalty: opening a bin wastes the complement unless item is large
    let is_new_bin = (bin_residual as u32 == bin_capacity);
    if is_new_bin {
        let waste = post / cap;
        score += 35.0 * (1.0 - waste) * (1.0 - waste) + 10.0 * (1.0 - progress);
        // If next item can't fit anywhere else well, opening may be fine
        if next_item_size > post_residual {
            score -= 8.0 * norm_next;
        }
    } else {
        // Reward using bins whose residual aligns with mean residual (balance open bins)
        let dev = (norm_residual - mean_residual / cap).abs();
        score += 12.0 * dev * dev;
        // Mild reward for keeping many open bins consolidated
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0) / (1.0 + progress);
    }

    // Smooth lookahead coupling: favor placements that leave room for the next item
    if next_item_size > 0 {
        let gap = (post as f64 - next_item_size as f64).abs();
        score += 0.15 * gap;
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - progress) * norm_next;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer smallest post_residual (tight fit).
    let cap = bin_capacity as f64;

    // Harmonic class bonus: post_residual in "nice" residue classes
    // (multiples of 10 / 20) are more reusable by future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fill
    } else if pr % 20 == 0 {
        score -= 12.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else if pr < 10 {
        // dead space below minimum item size (interface: items >= 1, but small)
        score += 15.0;
    }

    // Integer-division thresholds: classify residual tier.
    let tier = pr / 25; // 0..=4
    score += tier as f64 * 2.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 6.0 + 10.0 * (1.0 - slack / cap);
        if (pr - next_item_size) % 10 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here; mild penalty for stranding
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets baseline so it's chosen
    // only when all open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // planning a pair into a fresh bin
        }
    }

    // Mean residual coupling: avoid worsening an already-fragmented fleet.
    score += 0.3 * (mean_residual - post_residual as f64).abs() / cap;

    // Slight pressure to consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps (dead space below minimum item size 1..100).
    // Treat gaps below 10 as fully wasted; scale quadratically for tightness.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 6.0;
    } else if pr == 0.0 {
        // Perfect fit: heavily reward closing the bin.
        score -= 25.0;
    } else {
        // Mild reward for leaving room that can still fit typical items.
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: penalize placements that leave a bin open with
    // awkward residual while many bins are open; encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (pr / bin_capacity as f64) * 3.0;

    // Coupling with mean residual: if this bin's post-residual is far below
    // the mean, it's a good consolidation target.
    score -= (mean_residual - pr) * 0.5;

    // Lookahead: if the next item fits exactly into post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < dead_threshold {
            score -= 12.0; // next item will nearly close this bin
        } else {
            score -= 3.0;
        }
    }

    // New-bin candidate: neutral baseline slightly above good fits so we only
    // open a new bin when existing bins score poorly.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Late in the stream, opening fresh bins is less attractive.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // partial fit: reward proportional to how much of the leftover is used
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * usage;
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 25.0;
        }
    } else {
        // last item: only exact fit matters
        if post_residual == 0 {
            score -= 80.0;
        } else {
            score += 20.0;
        }
    }

    // Exact fill now is always great.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Compare against mean residual: bins with residual below mean are "tight" -> prefer filling them.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 8.0;
    }

    // Early in stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // penalize opening a new bin unless item is large relative to capacity
        score += 45.0 - 40.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // reward proportional to how much of the residual the next item consumes
            let use_ratio = (next_item_size as f64) / (post_residual as f64);
            score -= 12.0 * use_ratio;
        } else {
            // next item won't fit here: penalize leaving large dead space
            score += 0.08 * (post_residual as f64 - next_item_size as f64).abs().min(50.0);
        }
    } else {
        // Last item: strongly prefer filling an existing bin completely.
        score -= 25.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize placements into bins with large residual when mean residual is small
    // (i.e., wasting a "good" bin on a poor fit).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Dead-space penalty for residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    }

    // New-bin candidate: penalize opening a new bin, more strongly later in the stream
    // and when other bins fit; but allow it early or when fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_penalty = 10.0 + 20.0 * progress;
        if fitting_bins_count > 2 {
            new_penalty += 8.0;
        }
        if post_residual > 40 {
            new_penalty -= 5.0; // opening a fresh bin is fine if item is small
        }
        score += new_penalty;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
