    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual as u32 == bin_capacity) && item_size as u32 != 0;

    // Base: reward tight fills (small post_residual), non-linearly.
    let mut score = pr * pr / cap; // quadratic dead-space penalty

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early, flexibility is fine.
    let tightness = pr / cap;
    score += 12.0 * progress * tightness * (1.0 - tightness) * (1.0 - tightness);

    // Penalize leaving a residual that is awkwardly close to but below the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
