    if fitting_bins_count == 1 && is_new_bin == false {
        score -= 15.0;
    }

    // New-bin candidate: penalize by default, scaled by how many bins exist
    // and how loose the average residual already is.
    if is_new_bin {
        score += 20.0 + 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // Late in stream, opening new bins is even worse (waste carries forward).
        score += 10.0 * progress;
        // But if the item is huge relative to capacity, a new bin may be fine.
        score -= 0.2 * item_size as f64;
    }

    // Mild preference for bins below mean residual (balance load smoothly).
    score += 0.05 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
