        let nxt = next_item_size as f64;
        if (post_residual as u32) >= next_item_size {
            let chain = (post_residual - next_item_size) as f64;
            score -= (1.0 - chain / cap).powi(4) * 15.0;
        } else if (post_residual as u32) + 10 > next_item_size && (post_residual as u32) < next_item_size {
            // post residual nearly useless for the next item: penalize
            score += 10.0;
        }
        // If next item is huge and this bin can't chain it, prefer leaving big residuals elsewhere.
        if nxt > post {
            score += (nxt - post) * 0.05;
        }
    }

    // Time horizon: early in the stream, be more conservative (favor new bins less);
    // late in the stream, pack aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - tight);

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        let pressure = mean_residual / cap;
        score -= pressure * 6.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks when
    // the item fits poorly everywhere else (few fitting bins) or the item is huge.
    if bin_residual == bin_capacity {
        let waste = cap - item;
        score = cap * 0.6 + waste * 0.3;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if fitting_bins_count == 1 {
            score += 20.0; // keep the last-chance bin preferred over new bin
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            // big item followed by another big item: opening a fresh bin is fine
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space, with a non-linear (quadratic) coupling to progress.
    // Late in the stream, wasted space is costlier (less opportunity to fill it).
    let mut score = x * (1.0 + 1.5 * progress) + 2.0 * x * x * (0.5 + progress);

    // Reward tight fits: small post_residual gets a discount that grows with progress.
    let tight = (1.0 - x).powi(3);
    score -= 3.0 * tight * (0.4 + 0.8 * progress);

    // Dead-space hazard: residuals too small for typical future items are bad,
    // especially mid/late stream. Smooth penalty around small-but-nonzero x.
    let dead = (-(x / 0.12).powi(2)).exp() * (1.0 - (-(x / 0.35).powi(2)).exp());
    score += 4.0 * dead * (0.3 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 2.5 * fit_quality * (0.5 + progress);
        } else {
            // Next item can't use this residual: mild penalty scaled by gap.
            score += 1.5 * ((nx - pr) / cap).min(1.0) * (0.3 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 * (1.0 - x) * (0.5 + progress);
    }

    // Crowding: many open bins with high mean residual -> prefer consolidation
    // into existing bins rather than opening new ones.
    if bin_residual != bin_capacity {
        let consolidation = (mean_residual / cap - x).abs();
        score += 0.5 * consolidation;
        score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - x);
    } else {
        // New-bin candidate: penalize when open bins are underutilized,
        // reward when the stream is late and existing bins are fragmented.
        score += 1.0 * (1.0 - progress) + 0.4 * (mean_residual / cap);
        score -= 0.6 * progress * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by residue class mod 10
    let class = post_residual % 10;
    let harmonic_penalty = match class {
        0 => -12.0, // perfect alignment: residual is a multiple of 10, highly reusable
        1 | 9 => 4.0,
        2 | 8 => 2.0,
        3 | 7 => 0.5,
        4 | 6 => -1.0,
        _ => 3.0, // class 5: half-capacity sliver, moderately awkward
    };
    score += harmonic_penalty;

    // Reward near-full packing (small post_residual is good unless unusable)
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    } else if post_residual < 10 {
        score += 15.0; // dead space below min item size: unusable
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward if next item exactly fills the remainder
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else if post_residual < 10 {
            score -= 3.0; // residual is dead anyway; using this bin frees nothing worse
        }
    }

    // New-bin candidate handling: prefer opening a new bin only when the fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tight_fit = item_size * 100 / bin_capacity; // capacity fraction percent
        if tight_fit >= 60 && post_residual <= 40 {
            score -= 8.0; // large item into fresh bin is fine
        } else {
            score += 30.0; // discourage wasting a fresh bin on small items
        }
        // early in stream: more bins may be needed anyway
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 5.0;
        }
    }

    // Prefer filling bins that are already below mean residual (balance avoidance)
    if !is_new_bin {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff * 0.15; // favor emptier-than-average bins
        }
    }

    // Mild penalty per open bin to encourage consolidation
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste. Penalize them hard,
    // with a super-linear ramp as the gap shrinks toward zero.
    if post_residual > 0 && post_residual < 10 {
        let waste = (10 - post_residual) as f64;
        score += 40.0 + 8.0 * waste;
    }
    // Gaps too small for the lookahead item are also dead weight.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large relative to typical residuals, otherwise keep it unattractive
    // so existing bins get used. An empty bin scores its full residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when few bins are open
        // or the item is big.
        score += 18.0 - 0.15 * open_bins_count as f64
                       - 0.08 * item_size as f64;
        // If no open bin fits well (post_residual of this empty call is
        // capacity - item, always fine), but many bins are open, add cost.
        if open_bins_count > 0 && fitting_bins_count > 1 {
            score += 10.0;
        }
        // Late in the stream, opening new bins is worse (cleanup pressure).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for bins whose residual deviates from the mean in
    // the "large residual" direction gets filled by big items.
    if (bin_residual as f64) > mean_residual && item_size > 40 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins where the next item fits exactly
    // into the post residual (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves slack: mild reward proportional to
            // how small the remaining slack after the next item would be.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a residual that is
            // too small to be useful (dead space), worse the closer it is
            // to being usable without being usable.
            let waste = next_item_size - post_residual;
            if waste <= 10 {
                score += 60.0;
            } else {
                score += 15.0;
            }
        }
    }

    // Reward tight fits relative to bin residual (small wasted fraction).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 50.0 * fill_ratio;

    // Relative-to-mean coupling: prefer bins whose residual is below the mean
    // (consolidate into fuller bins), penalize dipping into emptier bins.
    score += (bin_residual as f64 - mean_residual) * 0.6;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: it is an empty bin (residual == capacity).
    // Only attractive when the item is large enough that placement elsewhere
    // would leave badly fragmented space, or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty: discourage opening new bins by default.
        score += 120.0;
        // But if the item is huge relative to capacity and few bins fit it,
        // opening fresh is reasonable.
        if item_size >= 70 && fitting_bins_count <= 1 {
            score -= 200.0;
        }
        // If the next item is large and would pair well with the remainder,
        // opening a new bin gains value.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 10 {
            score -= 150.0;
        }
    }

    // Mild pressure to reduce open-bin sprawl as the stream progresses.
    score += open_bins_count as f64 * 0.05;
    score += (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best; amplify small residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness * tightness;

    // Penalize unusable dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize mildly, but allow when it enables
    // a perfect fit for the current or next item, or when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size == bin_capacity {
            score -= 100.0; // perfect fill, always open
        }
        if post_residual as f64 <= bin_capacity as f64 * 0.2 {
            score -= 12.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && next_item_size as f64 >= post_residual as f64 * 0.8 {
            score -= 10.0; // new bin pairs well with the lookahead item
        }
        if open_bins_count > 0 {
            let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
            score -= 6.0 * frag; // if open bins are full-ish, opening fresh is fine
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * (1.0 - progress); // early on, prefer consolidating into open bins
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack < 10 {
            score -= 10.0;
        }
        // Penalize leaving a gap that only barely fits the next item but wastes the rest.
        if slack >= 10 && slack < 25 {
            score += 3.0;
        }
    }

    // Prefer bins whose residual is close to the mean (keep bin states balanced),
    // but only when many bins compete.
    if open_bins_count > 2 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
    }

    // Mild preference for filling larger-residual bins when few bins are open.
    if open_bins_count <= 2 {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) coupling
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth interaction: post-residual weighted by stream progress
    score += 20.0 * norm_post * (progress * (1.0 - progress) * 4.0);

    // Penalize dead space relative to mean residual (smooth coupling)
    score += 0.35 * (post - mean_residual).abs() + 0.15 * (post - mean_residual);

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 25.0 * (1.0 - norm_post);
    }

    // Deter new-bin candidate unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 45.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Slight preference for filling bins tighter when many bins open
    score += 0.05 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by modulo classes.
    // Residuals <= 10 are nearly unusable dead space (items >= 10 in original spec,
    // but sizes 1..100 here, so use finer granularity).
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit, best possible outcome
    } else if pr <= 2 {
        score -= 20.0; // near-perfect, tiny dead space
    } else if pr <= 10 {
        score -= 8.0; // small residual, still usable for small items
    } else if pr <= 25 {
        score += 2.0; // awkward middle zone
    } else if pr <= 50 {
        score += 5.0; // large residual, moderate penalty
    } else {
        score += 10.0; // huge residual means item was small in a big bin
    }

    // Harmonic coupling: does next_item_size fit into the post_residual exactly or well?
    if next_item_size > 0 && pr > 0 {
        let gap = pr as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // next item exactly fills this bin: chain fit
        } else if gap > 0 && gap <= 5 {
            score -= 12.0; // next item nearly fills it
        } else if gap > 0 && gap <= 15 {
            score -= 6.0; // next item fits reasonably
        } else if gap < 0 && (-gap) as u32 <= 3 {
            score += 8.0; // next item just barely won't fit: bad dead space lock-in
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: residual == capacity means empty bin. Only open a new
    // bin when the current item is large and would leave a big awkward residual
    // in any existing bin.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // Large items benefit from a fresh bin (less likely to find good fits).
        if item_size >= 60 {
            score -= 20.0;
        }
        // If few bins are open and stream is early, opening is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count <= 2 && progress < 0.5 {
            score -= 10.0;
        }
        // If many bins are open, prefer packing into them.
        if open_bins_count > 6 {
            score += 10.0;
        }
    }

    // Prefer tighter bins generally: reward low residual relative to mean.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Modulo harmonic classes on post_residual: multiples of common item sizes
    // are more likely to be filled by future items.
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0; // round residual more likely reusable
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Slight preference for bins with less absolute residual when item is small.
    if item_size <= 20 {
        score += post_residual as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space that no item (min size 1..10 band) can reliably use.
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits generally: smaller post_residual relative to capacity.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Mean residual coupling: if mean residual is large, prefer bins below it
    // (fill the emptier-biased ones less; prefer tighter bins).
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0;
    }

    // New-bin candidate handling: a fresh empty bin is a fallback; make it
    // attractive only when this placement would waste a nearly-full bin badly.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened unless open bins score badly.
        score += 30.0 + 1.5 * open_bins_count as f64;
        // But if the item is huge relative to typical residual, opening fresh
        // is reasonable: soften penalty for large items.
        score -= 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect match with the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // exact match: item+next fill this bin perfectly
        } else if post_residual > next_item_size {
            score -= 20.0 - diff.min(20.0); // next item still fits: mild reward, decaying with gap
        } else {
            score += diff * 0.5; // next item won't fit: penalize proportionally to mismatch
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Penalize small unusable dead space (fragmentation), reward large usable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit bias relative to fleet state)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Discard opening a new bin when good open bins exist and item is small
    if bin_residual == bin_capacity {
        score += 10.0 + item_size as f64 * 0.1;
        // But allow new bin if it would create a perfect lookahead match
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0;
        }
        // Late in stream, discourage opening new bins even more
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many alternatives, prefer the bin that keeps more useful space.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement; if post-residual is too small for next item, penalize
    // creating dead space unless it was a near-perfect fit.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when the
    // current bin's fit is poor and the stream is not near its end.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Relative fit quality of this item into a fresh bin.
        let fill = item_size as f64 / bin_capacity as f64;
        // Penalize new bins early (keep bins tight), reward late when open
        // bins are fragmented.
        score += 30.0 * (1.0 - progress);
        score -= 20.0 * fill;
        if fitting_bins_count == 1 {
            // Even so, avoid opening a new bin when an existing bin fits.
            score += 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; prefer consolidating into existing bins.
    if mean_residual > item_size as f64 * 1.5 {
        score -= 5.0;
    }
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is close to item size (best-fit core).
    score += 0.2 * ((bin_residual as f64 - item_size as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (low post_residual), smoothed by polynomial coupling
    let mut score = pr;

    // Non-linear coupling: post_residual squared normalized, modulated by progress.
    // Late in the stream, dead space is more costly (fewer chances to fill it).
    let prn = pr / cap;
    let dead_penalty = prn * prn * (0.5 + 1.5 * progress);
    score += 20.0 * dead_penalty;

    // Exact-fill bonus: strongly reward zero post residual
    if post_residual == 0 {
        score -= 30.0;
    } else {
        // Smooth small-residual reward
        score -= 15.0 * (1.0 - prn).powi(6);
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus;
    // if next item can't fit into post_residual, mildly penalize wasting it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let fit_quality = 1.0 - ((pr - ni) / cap).abs();
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            score += 6.0 * progress * (ni - pr) / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling: discourage opening a new bin early / when
    // mean residual across open bins is still large.
    if bin_residual == bin_capacity {
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 + 8.0 * open_bonus + 0.3 * mean_residual - 20.0 * progress;
    }

    // Mild dispersion penalty: bins far from mean residual create fragmentation
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // 0..1

    // Integer-division thresholds on post_residual (harmonic classes of C/4).
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..=8 harmonic class

    // Reward tight fits: small post_residual, especially in low classes.
    score -= 8.0 * (1.0 - frac) * (1.0 - frac);

    // Penalize mid-class dead space (hard to fill later): classes 1..=2 (residual 12..37)
    if post_residual > 0 && class >= 1 && class <= 2 {
        score += 6.0;
    }
    // Very small residual (class 0..1) is near-perfect: strong reward
    if post_residual < eighth {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
            // modulo harmony: next item divides residual cleanly
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += 0.05 * post_f;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred unless they score badly
        score += 20.0;
        // late in stream or many open bins: opening fresh is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0; // big next item: fresh bin useful
        }
    }

    // Prefer bins below mean residual (consolidate fullness).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    // Slight preference for fewer open bins being consolidated.
    score += 0.01 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are almost unusable.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny sliver = pure waste
        } else if post_residual <= 20 {
            score += 25.0; // small gap, usable only by smallest items
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fill
    }

    // Reward tight fits (small post_residual relative to item size)
    score += 0.35 * (item_size as f64 - post_residual as f64).abs();

    // Lookahead: if the next item fits exactly in the resulting gap, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // gap too small for next item
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading; keep score higher
    // so selection prefers consolidating unless fit is genuinely good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: penalize placing into bins deviating from mean residual
    // (prefer balanced residual portfolio, avoid creating extreme outliers).
    score += 0.10 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: make it unattractive unless current bin would be left with
    // a truly unusable tiny gap or the item barely fits.
    if bin_residual == bin_capacity {
        let waste_if_forced = (post_residual < 10) as i32 as f64;
        score = 100.0 + waste_if_forced * 80.0 - (item_size as f64 * 0.1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item size (perfect chain placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Exact match gets a big bonus; near match gets a graded bonus.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score -= (30.0 / diff).min(20.0);
        }

        // Penalize leaving dead space that the next item cannot use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: just minimize waste.
        score += post_residual as f64 * 0.1;
    }

    // Penalize bins whose residual deviates strongly from the mean residual
    // (prefer balanced residual landscape unless lookahead match is good).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Discourage wasting a nearly-full bin on a tiny item (dead space penalty).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Slight preference to fill existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Penalize leaving awkward dead space that likely can't fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // very small dead space is nearly useless
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 6.0; // still usable for small items
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if this placement blocks the next item while other bins exist, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && bin_residual != bin_capacity {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Pairing bonus: item + next item perfectly filling the bin.
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // or open-bin pool is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > mean_residual * 0.6;
        if fitting_bins_count > 0 && !poor_fit {
            score += 55.0 + 30.0 * (1.0 - progress); // discourage new bins early
        } else {
            score -= 10.0; // allow new bin when fits are bad
        }
        if open_bins_count > 12 {
            score += 15.0; // too many open bins, consolidate
        }
    }

    // Mild pressure toward fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.05;

    // Slight preference for bins below mean residual (balance load).
    score += (bin_residual as f64 - mean_residual) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.35 * progress * (pr / cap));

    // Polynomial coupling of post-residual with stream progress:
    // tight packing matters more as the stream advances
    let tightness = (pr / cap).powi(2);
    score += progress * tightness * 12.0;
    score += progress * progress * (pr / cap) * 6.0;

    // Penalize leaving residuals that no typical item can use (dead space)
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 2.5;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: reward residuals that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 2.0 + 3.0 * (nx / cap);
        } else {
            score += 1.5 * (nx - pr) / cap;
        }
    }

    // Mild preference for consolidating into bins below mean residual
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: prefer it only when it beats a clearly poor fit.
    // Empty bin has full residual; make it unattractive early, acceptable late.
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of the dead space: waste in low residue classes
        // (1..=9) is nearly unusable since items >= 10... but sizes can be 1..100 here.
        let pr = post_residual;
        // Modulo-classes of post_residual w.r.t. capacity fractions.
        let class = pr % 10;
        // Penalize tiny dead space that can't fit typical small items.
        if pr < 10 {
            score += 120.0 - (pr as f64) * 4.0;
        }
        // Harmonic tier: quantize residual into capacity eighths.
        let eighth = (cap / 8.0) as u32;
        let tier = pr / eighth;
        score += (tier as f64) * 6.0;

        // Reward leaving space exactly matching the next item (chaining).
        if next_item_size > 0 {
            if pr == next_item_size {
                score -= 200.0;
            } else if pr > next_item_size {
                // reward leaving room for next item with some slack
                score -= 30.0 * (1.0 - ((pr - next_item_size) as f64) / cap);
            } else {
                // next item won't fit here; slight penalty scaled by class
                score += 15.0 + (class as f64);
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a bin.
        if fitting_bins_count == 1 {
            score -= 80.0;
        }

        // Many open bins: discourage spreading into already-crowded state,
        // favor tighter fills (lower post_residual relative to mean).
        if open_bins_count > 4 {
            score += (mean_residual - post_residual as f64) * 0.3;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin would be left with a bad harmonic class of waste, or when
    // existing bins are nearly full.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin is not chosen over decent fits.
        score += 90.0;
        // But if the item is large relative to capacity and current mean
        // residual is small (all bins nearly full), opening is fine.
        let fill_frac = item_size as f64 / cap;
        if fill_frac > 0.5 {
            score -= 40.0 * fill_frac;
        }
        if mean_residual < fill_frac * cap * 0.5 {
            score -= 60.0;
        }
        // If next item is small, a fresh big residual is useful.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 25.0;
        }
    }

    // Late in the stream: consolidate aggressively, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 80.0 * progress;
    } else {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: post-placement residual (lower is better => lower score)
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap that cannot fit the
    // minimum plausible next item (or the actual lookahead item) is waste.
    let min_item = if next_item_size > 0 && next_item_size < 10 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < min_item {
        score += 60.0 + (min_item - post_residual) as f64 * 4.0;
    }

    // If the lookahead item would NOT fit this residual, the gap is likely dead.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 8.0 + dead * 0.9;
    } else if next_item_size > 0 {
        // Reward leaving exactly the space the next item needs (perfect chaining).
        let chain = (next_item_size - post_residual) as f64;
        score -= 6.0 - chain.abs() * 0.4;
    }

    // Reward tight fits (small post_residual that is still usable).
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading across many open bins slightly,
    // encouraging consolidation into existing bins.
    score += open_bins_count as f64 * 0.6;

    // Mean-residual coupling: bins far below mean residual are "dregs";
    // prefer filling bins with large residuals first (keeps small holes together).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // unattractive unless every open bin would leave a truly dead gap.
    if bin_residual == bin_capacity {
        let early = (step_index as f64 / total_items.max(1) as f64) * 10.0;
        score += 45.0 - early * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild non-linear bonus.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Aggressive 2-step lookahead: reward bins whose post_residual can exactly
    // or nearly fit the next item (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        let exact = if diff == 0.0 { 45.0 } else { 22.0 * (1.0 - diff / cap) };
        score -= exact;
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize leaving awkward dead space.
        score += 6.0;
    }

    // Relative-to-mean-residual coupling: bins already below average residual
    // (i.e. fuller than average) are preferred to consolidate fill.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.5 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist and fit reasonably;
    // the empty-bin candidate gets a handicap unless stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_penalty = 40.0 + 25.0 * (1.0 - progress);
        score += if open_bins_count == 0 { 0.0 } else { new_bin_penalty };
        // Still allow a new bin if the lookahead suggests a perfect pairing
        // with the next item in a fresh bin.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 35.0;
        }
    }

    // Late-stream pressure: tighten up as the stream ends to avoid waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional tightness of the fit: small post_residual relative to capacity is good
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize post-residuals that are too small to be useful for typical items.
    // Dead space: 1 <= post_residual < some usable threshold.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + gap);
    }
    // If next item cannot fit here but a small residual would be wasted anyway, mild penalty
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: discourage fragmenting space further; favor consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // If this bin's residual is far from mean residual, slight penalty (prefer typical bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate handling: brand-new empty bin gets baseline cost.
    // It should win only when fits are poor (high post_residual waste) or late in stream.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Late in the stream, opening new bins is cheaper than fragmenting
        score -= 30.0 * progress;
        // If many bins already open, new bin is more acceptable
        score -= 3.0 * (open_bins_count as f64).min(10.0);
        // If next item is large, a fresh bin is valuable
        if next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit = item_size as f64 / cap;
    let nf = next_item_size as f64 / cap;
    let mean_r = mean_residual / cap;

    // Base: penalize post_residual, but with a smooth non-linear twist:
    // residual that is "just below" the next item's size is dead space -> extra penalty.
    let mut score = pr as f64;

    // Non-linear dead-space coupling: smooth bump when post_residual is small
    // relative to the next item (can't fit next item) but not tiny.
    let gap = (nf - pr / cap).max(0.0);
    score += 12.0 * gap * gap * (1.0 - progress);

    // Reward tight fits (post_residual near zero) with smooth saturating term.
    score -= 8.0 * (1.0 - pr / cap).powi(3);

    // Polynomial coupling with stream progress: early on, prefer filling bins
    // deeply (keep many bins open); late, prefer minimal post_residual.
    let poly = (1.0 - progress) * (progress - 1.0); // negative, smooth
    score += 6.0 * poly * (pr / cap - 0.5);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mean-residual awareness: penalize bins far below the mean residual
    // (fragmenting small leftovers) with a smooth quadratic.
    let dev = pr / cap - mean_r;
    score += 3.0 * dev * dev;

    // Next-item synergy: reward leaving exactly-enough space for the next item.
    let diff = pr / cap - nf;
    score -= 5.0 * (-(diff * diff) / 0.02).exp();

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual as f64 == cap {
        score += 4.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact / near-exact fits get strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0 - pr * 4.0;
    }

    // Harmonic class penalty: residual divisible by common item sizes is reusable.
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
    if reusable {
        score -= 30.0;
    }

    // Coupling with lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to lookahead: penalize proportionally.
        score += (next_item_size as f64 - pr).min(60.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny unusable slivers (below min item size 10... be lenient: < 5).
    if post_residual > 0 && post_residual < 5 {
        score += 35.0;
    }

    // New-bin candidate: base preference against opening new bins, unless
    // the item is huge and no open bin fits well (tight fit in fresh bin).
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        if item_size >= 60 && fitting_bins_count == 1 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host item + next item
        }
    }

    // Mild spread penalty: prefer bins with residual below mean (denser bins).
    score += (mean_residual - pr) * 0.15;

    // Stream progression: late in stream, tighten packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<=10) are unusable for the
    // smallest possible item (1..100 interface), so penalize them heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Medium-small gaps (11..=25) are likely dead space too.
    if post_residual > 10 && post_residual <= 25 {
        score += 15.0;
    }

    // Reward tight fits (post_residual near zero handled by base score already).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 8.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: when many bins are open, prefer
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in post_residual, reward this
    // placement strongly; if next item cannot fit post_residual, penalize
    // leaving a gap that wastes the space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // Gap cannot serve next item; penalize proportionally to gap size.
            score += (post_residual as f64) * 0.6;
        } else {
            // Next item fits but leaves another residual: mild penalty.
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 {
                score += 6.0;
            } else {
                score -= 3.0;
            }
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // item is large relative to residual (poor fit) or residual is tiny.
    if bin_residual == bin_capacity {
        let poor_fit = fill_ratio < 0.55;
        if poor_fit || post_residual <= 10 {
            score -= 20.0; // attractive to open a new bin
        } else {
            score += 35.0; // discourage wasting an existing partial bin
        }
    }

    // Slight nudge toward bins with above-mean residual when fit is loose.
    if (bin_residual as f64) > mean_residual && fill_ratio < 0.7 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let residual_f = bin_residual as f64;
    let item_f = item_size as f64;
    let cap_f = bin_capacity as f64;

    // Tightness reward: strongly reward near-exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else {
        // Penalize post residuals that are too small to ever be useful
        // (dead space trap): residual < minimum plausible item size.
        if post_residual < 10 {
            score += 40.0; // item sizes >= 10 in classic regime; small dead space is waste
        }
        // Non-linear waste penalty: quadratic in post_residual relative to capacity.
        score += (post_residual as f64 / cap_f) * (post_residual as f64) * 0.25;
    }

    // 2-step lookahead: reward bins whose post_residual can host next_item_size exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = post_residual as f64 - nxt;
            // Perfect chain match is highly desirable.
            if slack == 0.0 {
                score -= 45.0;
            } else if slack <= 10.0 {
                score -= 25.0;
            } else {
                score -= 15.0 * (1.0 - slack / cap_f);
            }
        } else {
            // Next item cannot fit here after this placement; mild penalty,
            // stronger if the bin becomes a dead-space trap.
            score += 8.0 + 0.1 * (nxt - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already
    // "cramped"; placing there consolidates waste — reward that.
    let dev = residual_f - mean_residual;
    if dev < 0.0 {
        score -= 0.15 * (-dev);
    } else {
        // Bins with above-mean residual: penalize slightly unless fit is very tight.
        score += 0.05 * dev;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when open bins are genuinely bad options.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large and would pair well with a fresh bin, soften penalty.
        if next_item_size > 0 && (next_item_size as f64) >= 0.5 * cap_f {
            score -= 10.0;
        }
    }

    // Slight preference for bins that are already well-utilized (fewer open bins kept alive).
    score -= 0.02 * (cap_f - residual_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving awkward small dead space (waste zones).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item cannot use leftover; penalize proportionally to waste.
            score += 4.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 30.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // More attractive early in the stream (plenty of future items to fill it)
        // and when many bins are already open (fragmentation risk).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If mean residual of open bins is small (all bins nearly full), new bin is fine.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 10.0;
        // If nothing else fits well, allow opening.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight preference for filling fuller bins first when several fit.
    let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fullness;

    // Mild penalty when bin count is large: encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr_norm = post / cap;

    // Base: prefer small post_residual, with non-linear (quadratic) sharpening.
    let mut score = post + 40.0 * pr_norm * pr_norm * cap;

    // Smooth coupling: waste penalty grows with stream progress (late items should pack tighter).
    score += 30.0 * progress * pr_norm * pr_norm * cap;

    // Exact fit reward (post_residual == 0).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving room for the next item, penalize awkward leftovers.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Next item fits: reward proportionally to how well the leftover matches it.
            let slack = (post as f64 - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            // Dead space relative to next item: penalize smoothly.
            let waste = (nxt - post) / cap;
            score += 20.0 * waste * waste * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in the stream
    // and when the current fit is decent.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = 1.0 - (item_size as f64 / cap);
        score += 60.0 + 80.0 * (1.0 - progress) * fit_quality;
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Crowding pressure: mildly discourage spreading across many bins when mean residual is high.
    score += 5.0 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: coarse residue classes via integer division.
    // Residuals in [0,10) are near-perfect fits (dead space ~ zero) -> strong reward.
    let cls = post_residual / 10; // 0..=10 harmonic class
    score -= (10 - cls as i32 as f64) * 3.0; // lower class => bigger reward

    // Modulo coupling: residuals that are multiples of 5 pair well with common item sizes.
    if post_residual % 5 == 0 {
        score -= 4.0;
    }
    // Odd tiny leftovers (< 5) are almost unusable: penalize.
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward proportional to how tight the next fit is
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 8.0 * tight;
        } else {
            // next item cannot use this residual: penalize large stranded space
            score += 0.05 * post_residual as f64;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Discourage spreading across many open bins when residuals are small on average.
    score += 0.02 * open_bins_count as f64;

    // Slight preference for tighter bins overall (best-fit flavor).
    score += 0.1 * (mean_residual - bin_residual as f64).abs() * 0.0
        + 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: an empty bin should only win when the fit into
    // existing bins would be poor. Give it a mid-range score based on the space
    // it would leave, with a bonus if the item is large (hard to place later).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 45.0 + 0.15 * post_residual as f64 - 20.0 * progress;
        // large items justify a fresh bin more
        if item_size >= 60 { nb -= 10.0; }
        if item_size >= 80 { nb -= 10.0; }
        // if next item chains perfectly into the fresh bin's residual
        if next_item_size > 0 && next_item_size == post_residual { nb -= 12.0; }
        // if many bins already fit the item, opening a new one is wasteful
        if fitting_bins_count >= 2 { nb += 20.0; }
        score = score.max(0.0).min(cap) * 0.0 + nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver of waste
    }
    // If the leftover can't fit the next item, it's likely dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open,
    // but allow opening a new bin when existing residuals are small and fragmented.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 * (0.05 + 0.1 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if open bins are crowded / fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += open_pressure - 5.0 + fragmentation * 0.1;
    } else {
        score -= open_pressure * 0.5;
    }

    // Mild preference for bins whose residual is close to mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits snugly into the leftover space
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use the leftover: dead-space penalty scaled by tightness
        let waste = post_residual as f64 / bin_capacity as f64;
        if post_residual > 0 {
            score += 15.0 * waste;
        }
        if post_residual > 0 && post_residual < 10 {
            score += 20.0; // tiny unusable sliver
        }
    }

    // Relative to mean residual: prefer bins tighter than average when fill is good
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last chance: only this bin can fit the item -> strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer fuller bins overall
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let good_open = next_item_size > 0 && next_item_size <= post_residual;
        if fitting_bins_count > 0 && !good_open {
            score += 30.0; // keep using open bins when they can host the item
        } else if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: new bin is right choice
        }
    }

    // Early stream: be more liberal opening bins (keep flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: minimize wasted space (tight fit reward).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize post-residual dead space that is too small to be useful later.
    // Small post-residuals (< 10) are excellent; mid-range residuals are risky.
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score += 4.0;
    } else if post_residual > 60 {
        score += 6.0; // very loose fit, big remaining gap
    }

    // Lookahead: reward if the next item exactly fits the post-residual,
    // penalize if next item cannot fit and we're leaving a moderate gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining
        } else if next_item_size < post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 5.0; // next item won't chain here
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With many options, be pickier about fit quality.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
        score -= 8.0 * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin has huge post_residual.
    // Only attractive when no good existing option exists (approximated by
    // high post_residual here) and stream is early or item is large.
    if bin_residual == bin_capacity {
        score += 30.0; // default: prefer existing bins
        if item_size > 60 {
            score -= 20.0; // large items are fine in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 45.0; // nothing else fits, must open
        }
        if progress > 0.8 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild time-horizon shaping: late in the stream, tighten aggressively.
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual (tight fit)
    let mut score = pr;

    // Non-linear tightness reward: strongly favor near-zero post residual
    let tight = (pr / cap).powi(2);
    score -= 18.0 * (1.0 - tight) * (pr / cap);

    // Smooth stream-progress coupling: later in stream, value tight fits more,
    // and penalize leaving medium dead space.
    let prog_term = progress * progress;
    score += prog_term * (pr * (1.0 - (pr / cap).powi(3))) * 0.35;

    // Lookahead: reward post_residual that can still host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            // small bonus if next item fits nicely; smooth gaussian-like coupling
            score -= 6.0 * (-((slack - 0.1) / 0.25).powi(2)).exp();
        } else {
            // post residual too small for next item: penalize proportionally to wasted space
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Mild penalty when this bin is much fuller than average (keeps many bins balanced)
    let mean_dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * mean_dev * mean_dev;

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    // Penalize the fresh bin mildly, scaled by how badly current fits are.
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
        // if the item is large relative to capacity, opening a fresh bin is more acceptable
        score -= 6.0 * (item / cap);
    }

    // Slight preference to fill already-open bins when many are open
    score += 0.15 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity left over

    // Integer-division thresholds on post_residual: residuals <= 10 are essentially dead.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if post_residual <= 10 {
        score += 25.0; // unusable dead space (min item size 10 in classic, small here)
    } else if post_residual <= 20 {
        score += 8.0;
    } else if post_residual <= 30 {
        score += 2.0;
    }

    // Modulo-arithmetic harmonic classes: residuals congruent to small multiples of
    // common item sizes (10..80) are more reusable than odd leftovers.
    let harmonics: [u32; 8] = [10, 20, 25, 30, 40, 50, 60, 80];
    let mut reusable = false;
    for &h in harmonics.iter() {
        if post_residual >= h && (post_residual % h == 0 || post_residual % 10 == 0) {
            reusable = true;
            break;
        }
    }
    if reusable {
        score -= 6.0; // residual aligns with a harmonic class, likely reusable
    } else if post_residual % 10 != 0 {
        score += 3.0; // off-grid residual less likely to be filled exactly
    }

    // Reward tight fits relative to item size: waste ratio coupling.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Lookahead coupling: if next item fits the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // extra bonus if next item exactly fills the bin afterwards
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this residual: penalize proportionally
        score += 0.05 * (next_item_size as f64 - pr);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only when the item fits poorly everywhere.
        // Base cost of a new bin, modulated by stream progress and open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 + 20.0 * (1.0 - progress) + 1.5 * open_bins_count as f64;
        // If the item perfectly harmonizes with the empty bin's capacity classes,
        // opening is cheaper (e.g., item is a divisor-friendly size).
        if item_size % 10 == 0 && item_size >= 50 {
            score -= 10.0;
        }
        // If next item is huge, avoid fragmenting: slight penalty to new bin.
        if next_item_size >= 60 {
            score += 10.0;
        }
    }

    // Mild penalty when this bin's residual is far from the mean residual
    // (keeps bin population homogeneous in leftover structure).
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // gap too small for any item (min size 1..100 assumption -> use small threshold)
    }
    // Penalize gaps that no plausible future item can use relative to item size scale
    if post_residual > 0 && post_residual < item_size / 2 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) super-linearly
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // discourage new bin when other bins can fit the item
            score += 45.0 + 3.0 * open_bins_count as f64;
        } else {
            // forced to open; slight reward so it beats bad fits
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // post_residual becomes dead space for the next item
        score += 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing ones
    score += 0.5 * open_bins_count as f64;

    // Last-chance bonus: this is the only bin that fits -> avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Slight preference for bins below mean residual (keep residuals balanced)
    score -= 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits relative to mean residual
    let tightness = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * tightness;

    // Perfect fill is ideal
    if post_residual == 0 {
        score -= 30.0;
    }

    // 2-step lookahead: reward bins where post_residual matches next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize small dead space
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 8.0;
            }
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: prefer only if it's early or current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Mild penalty for many open bins to discourage bin proliferation
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 {
        let dead = (post_residual as f64) / cap;
        if dead < 0.10 {
            score += 18.0 * (0.10 - dead);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item can use the post residual, reward leaving useful space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 8.0 * (nxt / cap);
        } else if post_residual > 0 {
            // residual too small for next item: penalize proportionally to wasted space
            score += 6.0 * ((post_residual as f64) / cap);
        }
        // If next item fits exactly in post residual, big reward.
        if post_residual as f64 == nxt {
            score -= 20.0;
        }
    }

    // Global state coupling: prefer filling bins when many bins are open (bin consolidation).
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * tight;

    // Mean residual coupling: when mean residual is high, prefer bins below mean (balance).
    let dev = mean_residual - (post_residual as f64);
    score += 0.15 * dev;

    // Time horizon: early in stream, be conservative (favor new bins for big items);
    // late in stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 40.0 * progress;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += new_bin_penalty;
        // Opening a new bin is fine if item is large and leaves big residual? penalize small leftovers
        score += (post_residual as f64) * 0.05;
    } else {
        // Late stream: reward using existing bins more aggressively.
        score -= 10.0 * progress;
    }

    // Slight preference for bins with larger residual among ties (use fullest bins first).
    score -= 0.03 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual, with non-linear emphasis on tiny dead space.
    let mut score = pr + (pr / cap).powi(3) * 40.0;

    // Tightness reward: how well the item fills the bin (non-linear coupling).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= (fill_ratio * fill_ratio) * 30.0;

    // Lookahead: reward if the post-residual can fit the next item exactly-ish.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let look = 1.0 - (gap / cap).powi(2);
        score -= look * 12.0 * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize mildly, more so early in the stream and
    // when plenty of open bins exist; relax late when fragmentation accumulates.
    if bin_residual == bin_capacity {
        let mean_r = if mean_residual.is_finite() { mean_residual } else { cap };
        let frag = (mean_r / cap).clamp(0.0, 1.0);
        score += 15.0 + 30.0 * (1.0 - progress) - 20.0 * frag * progress;
    }

    // Slight preference for bins whose residual is far below mean (consolidation).
    score += ((bin_residual as f64 - mean_residual) / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction remaining

    // Penalize small-but-unusable residuals (dead space) more than large residuals.
    // A residual is "dead" if it cannot fit the smallest plausible item (<= ~10% of capacity).
    if pr > 0.0 && pr < 0.1 * cap {
        score += 18.0 * (1.0 - pr / (0.1 * cap));
    }

    // Reward near-perfect fits strongly (harmonic class 0: post_residual divisible by 10).
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 4.0 + 0.05 * slack;
        // Extra reward if post residual also lands in the next item's harmonic class.
        if (post_residual % next_item_size.max(1)) == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to how much we "waste".
        score += 2.0 + 0.03 * (next_item_size as f64 - pr).min(20.0);
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so new bins are not chosen casually; reduced when mean residual is low.
        score += 10.0 + 8.0 * (1.0 - progress);
        score -= 0.15 * (mean_residual - frac * cap).max(0.0);
        if mean_residual < 0.15 * cap && next_item_size > 0 {
            score -= 8.0; // open bins nearly full -> opening a new bin is fine
        }
    }

    // Mild preference for filling fuller bins (smaller residual before placement).
    score += 0.02 * (bin_residual as f64 - post_residual as f64).signum() * (item_size as f64 / cap);

    // Slight global pressure: with many open bins, favor compacting into existing ones.
    score += 0.01 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: penalize using bins when many are open, to avoid fragmentation.
    score += 0.4 * open_bins_count as f64;

    // Prefer bins with residual below mean (fill the emptiest relative space first keeps spread tight).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit in post_residual and post_residual is small, mild penalty for stranding space.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 15.0;
    }

    // New-bin candidate: only allow opening a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count == 1 {
            score += 50.0; // keep using the last fitting bin instead of opening new
        }
    }

    // Late-stream: consolidate, avoid opening new bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer minimal post_residual (tight fit).
    // Tightness ratio: fraction of the item's size recovered as used space.
    let tight = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tight;

    // 2-step lookahead: perfect match where post_residual == next_item_size
    // is gold — subtract strongly so this bin wins.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // bin can host the next item too: reward proportionally to closeness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here: dead space penalty grows with tightness
            score += 8.0 * tight * (1.0 - diff / bin_capacity as f64);
        }
    } else {
        // last item: just minimize post_residual
        score -= 10.0 * tight;
    }

    // Relative-to-mean coupling: bins below mean residual are "dirtier";
    // filling them is good if fit is tight, bad if it creates crumbs.
    let rel = bin_residual as f64 - mean_residual;
    score += 0.05 * rel * (1.0 - tight);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * tight;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // the item is large (would leave big unusable residue elsewhere) or
    // stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_if_forced = (bin_capacity - item_size) as f64;
        let mut new_bin_score = 40.0 + waste_if_forced * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score += 10.0; // fresh bin also fits next item
        }
        if open_bins_count == 0 {
            new_bin_score -= 100.0; // must open
        }
        if progress < 0.15 && open_bins_count < 3 {
            new_bin_score -= 15.0;
        }
        score = score.min(new_bin_score);
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post-residual waste.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Strong reward for exact or near-exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual that no plausible item can use
    // (items >= 1, but tiny residuals under 10 are hard to fill for large-item streams).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is excellent; if next item needs almost all of post_residual, good too.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() <= 2.0 && post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; penalize leaving awkward remainder.
            score += 0.15 * (nxt - post_residual as f64);
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is large relative to capacity and few bins fit it,
    // or when open bins are nearly full on average.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 30.0;
        // Large items into a fresh bin are fine early.
        penalty -= 25.0 * fill_ratio;
        // If mean residual across open bins is small, opening fresh is reasonable.
        penalty -= 0.25 * (mean_residual - 20.0).max(0.0);
        // Late in the stream, avoid proliferating bins.
        penalty += 15.0 * progress;
        // Many fitting bins means we don't need a new one.
        penalty += 6.0 * (fitting_bins_count as f64).min(4.0);
        score += penalty.max(0.0);
    } else {
        // Prefer using existing bins, more so when many are open.
        score -= 2.0 * (open_bins_count as f64).sqrt().min(6.0);
    }

    // Mild preference for bins whose residual is above mean (balance preservation).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Time-horizon modulation: early on, be greedy about tight fits; later, conservative.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fits), with non-linear emphasis.
    let mut score = post + 0.35 * (post * post) / cap;

    // Reward filling the bin deeply: interaction between fill ratio and post-residual.
    let fill = (bin_residual as f64 - post) / cap;
    score -= 12.0 * fill * fill * (1.0 - post / cap);

    // Perfect fit bonus (smooth, continuous).
    if post == 0.0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits into the resulting residual,
    // penalize if the residual is just barely too small (dead space trap).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (-gap / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    score -= 5.0 * progress * (post / cap);

    // Penalize spreading residual far above the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.5 * dev * dev;

    // New-bin candidate: post_residual is large here; add calibrated penalty so a
    // new bin only wins when no open bin gives a reasonably tight fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - item / cap) + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by 10 are
    // "friendly" because item sizes are multiples of 10 in the classic regime.
    let class = post_residual % 10;
    score += (class as f64) * 1.5;

    // Quotient-class reward: large clean leftovers (>= 50) are reusable.
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 6.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 4.0; // tiny dead space
    }

    // Perfect fit is king.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the next item fit the post-residual class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item leaves another clean residue?
            let next_left = post_residual - next_item_size;
            score -= 3.0 + (next_left % 10) as f64 * 0.8;
        } else {
            score += 2.0; // bin becomes dead for the lookahead item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or the stream is early and many bins will be needed anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (fitting_bins_count as f64).recip();
        score += 15.0                      // base cost of a fresh bin
               - congestion * 8.0          // reward when few bins fit
               + mean_residual * 0.25      // crowded open bins -> open new
               + progress * 5.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0; // next item needs a fresh bin anyway
        }
    }

    // Mild preference for tighter (more filled) bins as stream matures.
    score -= (1.0 - post_residual as f64 / cap) * (step_index.min(total_items) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold the minimum item (size >= 1, practically < 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading across
    // bins with large leftover space; consolidate into tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that create fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 12.0; // would leave a dead gap after next item
    }

    // New-bin candidate: penalize opening a fresh bin when decent fits exist,
    // unless current open bins are all badly fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate baseline: slightly above a perfect fit to prefer
    // existing bins unless they leave unusable dead space.
    if bin_residual == bin_capacity {
        return bin_capacity as f64 + 0.5;
    }

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: strongly reward when the next item fits exactly
    // into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item closure
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64); // next fits well
        } else {
            // next item does not fit: penalize dead space more heavily
            // as it approaches the smallest item size.
            let waste = post_residual as f64;
            score += 20.0 * (1.0 - waste / bin_capacity as f64);
        }
    }

    // Reward closing the bin entirely now (zero residual ideal).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean absorb items well.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.3 * mean_gap;

    // Late in the stream, prefer tighter packing (smaller post residual).
    score *= 1.0 + 0.2 * progress;

    // Penalize leaving residuals below ~10 (likely dead space), since
    // min item size is 10 in classic streams; mild penalty otherwise.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity as f64 > 0.0 {
        bin_capacity as f64
    } else {
        1.0
    };
    let s = item_size as f64;
    let r_before = bin_residual as f64;
    let r_after = post_residual as f64;
    let nxt = next_item_size as f64;
    let mean_res = if mean_residual.is_finite() { mean_residual } else { 0.0 };

    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let horizon = (1.0 - progress).clamp(0.03, 1.0).powf(0.78);
    let space = (mean_res / cap).clamp(0.0, 1.4);
    let scarcity = (1.45 - space).clamp(0.55, 1.8);

    let open_f = open_bins_count as f64;
    let fitting_f = fitting_bins_count as f64;
    let is_new = bin_residual == bin_capacity;
    let new_room = (cap - s).max(0.0);

    let mut eff = r_after;
    if nxt > 0.0 && nxt <= r_after {
        eff = r_after - nxt;
    }

    let mut score = eff + 0.14 * eff * eff / cap;

    if !is_new {
        let opens_help_next = nxt > 0.0
            && nxt > r_after
            && (nxt <= r_before || nxt <= new_room);

        if opens_help_next {
            let lost = (nxt - r_after).max(0.0);
            let large_share = ((r_before - mean_res) / cap).clamp(0.0, 1.0);
            let alt_factor = if fitting_bins_count <= 1 {
                0.8
            } else {
                1.0 + 0.08 * (fitting_bins_count.saturating_sub(1).min(8) as f64)
            };

            let preserve = 2.0
                + lost * (0.25 + 0.65 * horizon) * scarcity
                + large_share * (8.0 + 22.0 * horizon)
                + 3.0 * horizon;

            score += (preserve * alt_factor).min(82.0);
        } else if nxt > 0.0 && nxt > r_after {
            score -= 3.0 + 0.10 * s * horizon + 6.0 * progress;
        }

        if fitting_bins_count == 1 {
            let last_chance = 10.0 + 10.0 * progress + 0.12 * s * horizon;
            score -= if opens_help_next {
                last_chance * 0.6
            } else {
                last_chance
            };
        }
    } else {
        let mut open_cost = 18.0
            + 20.0 * progress
            + 2.8 * open_f.sqrt()
            + 6.0 * space;

        if fitting_bins_count > 0 {
            open_cost += 1.5 + 2.5 * fitting_f.sqrt();
        }

        if nxt > 0.0 && nxt <= new_room {
            open_cost -= 3.0 + 0.07 * nxt * horizon;
        }

        score += open_cost.max(4.0);
    }

    score += 0.03 * open_f.sqrt() * eff * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with non-linear emphasis.
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Smooth quadratic coupling of tightness with stream progress:
    // late in the stream, tight fits matter more.
    let tightness = 1.0 - post / cap; // 1 = perfect fit
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Reward filling bins deeply relative to the average open-bin state.
    let fill_deficit = (mean_residual - post).max(-cap) / cap;
    score -= 10.0 * fill_deficit;

    // Lookahead: if the next item can use the post-residual, reward leaving it.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (1.0 - (next_item_size as f64 - post).abs() / cap);
    } else if next_item_size > 0 {
        // Post-residual likely dead space for the next item; penalize mildly.
        score += 5.0 * (post / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: make empty bins less attractive unless residuals are tight.
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - mean_residual / cap;
        score += 40.0 - 35.0 * avg_tightness * avg_tightness + 20.0 * progress;
        // If nothing currently open can fit, opening a bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for bin sprawl late in the stream.
    score += 0.3 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction does it fall into?
    // Classes via integer division thresholds on post_residual (capacity = 100).
    let post_class = post_residual / 10; // 0..=10 harmonic class
    score -= match post_class {
        0 => 40.0,          // near-perfect fit, tiny dead space
        1 => 30.0,          // excellent
        2 => 20.0,
        3 => 10.0,
        4 => 5.0,
        5 => 0.0,           // half-empty bin: neutral
        6 => 3.0,
        7 => 6.0,
        8 => 10.0,
        9 => 15.0,
        _ => 0.0,           // full bin class
    };

    // Dead-space penalty: residuals that nothing (min size 1..10 typical) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Modulo arithmetic: residual in harmonic resonance with common item sizes.
    let r = post_residual % 10;
    if r == 0 && post_residual > 0 {
        score -= 8.0; // residual is a multiple of 10: likely reusable
    } else if r >= 7 {
        score += 4.0; // awkward remainder
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // bonus scaled by how well next item nests
            let nest = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.15 * nest;
        } else {
            score += 6.0; // next item won't fit here: bin likely closes
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has no scarcity value early on,
    // but late in the stream prefer using existing bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 20.0 * progress; // new bins cost more as stream advances
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // next big item: fresh bin has room
        }
    }

    // Mild preference for tighter bins overall (relative to mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Crowd control: many open bins -> favor consolidation into existing ones.
    if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it cannot fit even the smallest plausible item (1..=100 range),
    // but treat small gaps (< 10) as pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that cannot fit the lookahead item but could otherwise be useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 25.0;
    }
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Reward using bins that are tight fits relative to mean residual (consolidation).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.5;
    } else {
        score += (residual_f - mean_residual) * 0.25;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, mild preference to fill best-fit.
    let pressure = open_bins_count as f64;
    score += pressure * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity and the fit would leave big dead space anyway.
    if bin_residual == bin_capacity {
        score += 70.0;
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Late-stream tightening: as the stream progresses, avoid creating
    // medium dead space that can never be reused.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 15 && post_residual < 40 {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual)
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // dead space penalty relative to next item
            score += 8.0 * (next_item_size as f64 - post_residual as f64).max(0.0) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize bins with residual far from the pack's mean residual (fragmentation)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Prefer fuller bins when many bins are open
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: penalize mildly, but allow if it would be a near-perfect
    // future home for the next item (pure lookahead opening)
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0 * (item_size as f64 / bin_capacity as f64);
        }
    }

    // Slight late-stream tightening: waste less as stream progresses
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual dominates).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 1.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when current bins are crowded (low mean residual) or item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = 1.0 - (mean_residual / bin_capacity as f64);
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let load_pressure = (item_size as f64 / bin_capacity as f64) * 30.0;
        score += 20.0
            - 18.0 * crowding
            - 6.0 * progress
            - load_pressure;
        // Penalize new bins more when many bins already exist (bin count economy).
        score += 0.05 * open_bins_count as f64;
    }

    // Mild preference for bins with residuals below the mean (consolidate space).
    let delta = bin_residual as f64 - mean_residual;
    score += 0.08 * delta;

    // Slight time-varying exploration: later in stream, tighten more.
    let horizon = step_index as f64 / (total_items as f64).max(1.0);
    score += 3.0 * (1.0 - horizon) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_it = it / cap;
    let norm_mean = mean_residual / cap;

    // Base: tight fits preferred (low post residual)
    let mut score = pr as f64;

    // Smooth polynomial coupling: small post-residuals rewarded extra via quadratic dip
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.1;

    // Penalize dead space that is too small to be useful later (non-linear in progress)
    let dead = (norm_pr * (1.0 - norm_pr) * 4.0).powi(2); // peaks at norm_pr = 0.5
    score += 6.0 * dead * (0.5 + progress);

    // Lookahead coupling: reward residual that can still fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as i32 as f64;
        let slack = (pr - nx).max(0.0) / cap;
        score -= 8.0 * fits_next * (1.0 - slack * slack);
        // Penalize wasting a bin whose residual barely misses the next item
        let miss = ((pr - nx) as f64).abs() / cap;
        score += 5.0 * (1.0 - fits_next) * (1.0 - miss) * (1.0 - miss);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + norm_it);
    } else if fitting_bins_count > 2 {
        // Plenty of alternatives: slight penalty keeps fragmentation low
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Mean residual coupling: prefer bins with residual near the mean (smooth balance)
    let dev = norm_pr - norm_mean;
    score += 4.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: only attractive when current fit is poor
    let is_new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let fit_quality = norm_pr; // small = good fit
    score += is_new_bin * (10.0 + 30.0 * (1.0 - fit_quality).powi(3) * 0.0 + 20.0 * (1.0 - norm_it));
    // Make new bin unattractive for good fits, attractive for bad fits:
    score -= is_new_bin * 18.0 * fit_quality * fit_quality;

    // Late stream: consolidate, penalize opening bins
    score += is_new_bin * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // sizes (10..80 multiples) are "usable" future space; prime/dead residues
    // are penalized.
    let pr = post_residual;
    if pr > 0 {
        let mut usable = 0u32;
        for k in 10u32..=80 {
            if pr >= k && pr % k == 0 { usable += 1; }
        }
        // reward residual that is an exact multiple of small item classes
        score -= (usable as f64) * 3.0;
        // dead-space penalty: small leftover that fits nothing common
        if pr < 10 {
            score += (10 - pr) as f64 * 6.0;
        } else if usable == 0 && pr < 40 {
            score += (pr as f64) * 0.5;
        }
    }

    // Perfect fit: zero post residual is ideal
    if pr == 0 { score -= 50.0; }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving exactly next_item_size after placement
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 35.0;
        } else if pr > next_item_size && (pr - next_item_size) < 10 {
            score += 10.0; // leaves an unusable sliver for the lookahead
        }
        // harmonic pairing: post residual divisible jointly with next item class
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 12.0;
        }
    }

    // Integer-division threshold on bin fill fraction
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    let quartile = (fill * 4.0).floor() as i32;
    score -= quartile as f64 * 4.0;

    // Stream progression: later in stream, prefer tightening existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Many open bins: discourage spreading; few open bins: mild new-bin tolerance
    if open_bins_count > 8 {
        score += 6.0;
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New empty bin candidate: must not be chosen unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 45.0;
        // allow new bin early when few bins open and item is large
        if open_bins_count == 0 || (item_size > 60 && fitting_bins_count <= 1) {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap that the next item cannot use: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are ample.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.5 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.2;

    // New-bin candidate: penalize mildly so it only wins when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream with high open-bin count, new bins are even less attractive.
        if open_bins_count > 6 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size
    // means the next item exactly fills this bin -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match: next item leaves only a tiny sliver.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= (10 - slack) as f64 * 3.0;
        }
    }

    // Penalize post_residuals that are too small to ever fit the smallest
    // plausible next item (dead space), scaled by how dead they are.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Relative to mean residual: prefer tightening bins that are already
    // below-average residual (compacting), avoid wasting a roomy bin.
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.5;
    } else {
        score += (res_f - mean_residual) * 0.25;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin just to keep fragmentation low.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no
    // good fit exists. Penalize it moderately; the lookahead rewards above
    // (perfect fit) can override this when an existing bin is ideal.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheap and useful.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress < 0.2 {
            score -= 15.0;
        }
        // If many bins are open with large mean residual, discourage new bin.
        score += mean_residual * 0.15;
    }

    // Slight preference for tighter fits overall.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinearity
    score += (post_residual as f64 / bin_capacity as f64).powf(1.7) * 40.0;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward for a near-perfect chain (next item fills almost exactly)
            let chain_gap = post_residual - next_item_size;
            score -= (1.0 - chain_gap as f64 / bin_capacity as f64) * 8.0;
        } else {
            // post_residual too small for lookahead item: penalize dead space
            score += 6.0;
        }
    } else {
        // last item: pure tightness matters most
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize bins far below mean residual (fragmented outliers) mildly
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 3.0;

    // Time horizon: early in stream, be picky (favor new bins for bad fits);
    // late in stream, consolidate into open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 8.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // brand-new bin candidate: baseline cost, adjusted by bias and open-bin count
        score = 45.0 + new_bin_bias + (open_bins_count as f64) * 1.5 - (item_size as f64 / bin_capacity as f64) * 10.0;
        // opening a bin when next item is large is fine
        if next_item_size >= 50 { score -= 5.0; }
    } else {
        // existing bin: late-stage consolidation bonus
        score -= progress * 6.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let nz = next_item_size as f64;

    // Quadratic penalty on wasted space, scaled by stream progress
    score += 4.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic coupling: residual^3 relative to capacity grows penalty late in stream
    score += 8.0 * norm_pr * norm_pr * norm_pr * progress * progress;

    // Reward tight fits: small post_residual relative to item size
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 6.0 * tightness * (1.0 - progress) * (1.0 - progress);

    // Lookahead: penalize post_residual that cannot fit next item
    if nz > 0.0 && nz <= pr {
        score -= 3.0 * (nz / cap) * (1.0 + progress);
    } else if nz > pr {
        score += 5.0 * (nz - pr) / cap;
    }

    // Last-chance bonus: only fitting bin gets strong reward
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + 2.0 * progress);
    }

    // Mean residual coupling: prefer bins near the mean to keep balance
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 + progress);

    // Open bins pressure: many open bins -> favor filling existing ones
    let open_norm = open_bins_count as f64 / (1.0 + total_items as f64);
    score -= 4.0 * open_norm * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a fresh bin unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * (1.0 - progress) + 3.0 * (mean_residual / cap);
        if fitting_bins_count <= 1 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post-residuals (< 10) are unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward good tightness relative to residual used.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open with scattered residuals.
    score += 0.15 * open_bins_count as f64;

    // Penalize bins whose residual deviates badly from the mean residual (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for next item: mild dead-space penalty.
        score += 10.0;
    }

    // New-bin candidate handling: prefer a fresh bin only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base neutral score for a new bin; slightly above a perfect fit, below wasteful fits.
        score = bin_capacity as f64 * 0.5 + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post == next {
            // Perfect match: this bin's leftover exactly fits the next item
            score -= 60.0;
        } else if post > next {
            // Leftover still usable by the next item; closer match is better
            let slack = (post - next) / cap;
            score -= 18.0 * (1.0 - slack);
        } else {
            // Dead space for the next item: penalize proportionally to the gap
            score += 22.0 + (next - post);
        }
    }

    // --- Relative-to-mean coupling: prefer bins tighter than average ---
    score -= 0.35 * (post - mean_residual);

    // --- Last-chance bonus: only open bin that fits, avoid wasting it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin: high so it loses to decent fits
        score = cap + 40.0;
        if fitting_bins_count == 1 {
            // No open bin can fit the item -> opening a new bin is necessary
            score -= 200.0;
        } else if next_item_size > 0 {
            let next = next_item_size as f64;
            // A fresh bin gives a perfect post-fit for the next item
            if post == next {
                score -= 90.0;
            } else if (item_size as f64 + next) <= cap {
                score -= 45.0;
            }
        }
        // Late in the stream, avoid spawning extra bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space that few item sizes could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver is wasted capacity
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= item_size {
        // next item larger than current: prefer keeping a bigger residual elsewhere
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.5;
        // Opening a bin is costly; make it unattractive by default, cheaper late in stream
        // when open bins are fragmented.
        let mut new_bin_score = 45.0 - 20.0 * progress;
        if poor_fit && fitting_bins_count <= 2 {
            new_bin_score -= 35.0;
        }
        // If many open bins with high mean residual, prefer spreading load into them.
        new_bin_score += (open_bins_count as f64).sqrt() * 2.0 + mean_residual * 0.15;
        // Perfect fit on a fresh bin (item == capacity) is ideal.
        if item_size == bin_capacity {
            new_bin_score -= 100.0;
        }
        score = new_bin_score;
    } else {
        // Mild penalty for hoarding too many open bins; reward consolidation.
        score += 0.5 * open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        // Prefer bins below mean residual (using up emptier bins first keeps options open).
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: reward tight fits with non-linear coupling to stream progress.
    // Early on, moderate residuals are acceptable; late, demand tightness.
    let mut score = pr * (0.6 + 0.9 * progress * progress);

    // Smooth penalty for residual that is too small to ever be useful
    // (dead space), amplified as the stream progresses.
    let dead = (cap * 0.2 - pr).max(0.0) / cap;
    score += 40.0 * dead * dead * (0.5 + progress);

    // Lookahead coupling: if the next item can use the post-residual,
    // reward leaving exactly that much space (smooth quadratic match).
    if next_item_size > 0 {
        let mismatch = (pr - next_item_size as f64).abs() / cap;
        score -= 25.0 * (1.0 - mismatch.min(1.0)) * (1.0 - fit_frac);
    }

    // Last-chance bonus: strongly prefer filling the only fitting bin
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild pressure to prefer bins with less residual than the mean
    // (consolidation), smoothed by a tanh-like term.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 10.0 * dev / (1.0 + dev.abs());

    // New-bin candidate: penalize opening a new bin, more so when other
    // bins fit and early in the stream; relax late when consolidation
    // has run its course.
    if bin_residual == bin_capacity {
        let rel = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += (35.0 + 25.0 * (1.0 - progress)) * rel + pr * 0.3;
        // But if the item is large and would leave a bad remainder anyway,
        // a fresh bin is comparatively fine.
        score -= 30.0 * fit_frac * fit_frac * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 10 are
    // more reusable (typical item sizes cluster on decade boundaries).
    let r = post_residual % 10;
    let class_bonus = match r {
        0 => 8.0,
        1 | 9 => 4.0,
        2 | 8 => 2.0,
        3 | 7 => 0.0,
        _ => -1.5, // awkward residues 4..6 leave dead space
    };
    score -= class_bonus;

    // Strong reward for a near-perfect fit.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize leaving large dead space relative to capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score += 10.0;
    } else if frac > 0.3 {
        score += 4.0;
    }

    // Lookahead coupling: reward a bin whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.1 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Post-residual useless for the next item: mild penalty.
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fits = (post_residual as f64) < 10.0; // n/a for empty bin; use item fit logic
        let _ = poor_fits;
        // Base cost of opening a bin, discounted by stream progress and scarcity.
        score += 25.0 - 15.0 * scarcity - 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // Opening a bin is better if mean residual across open bins is tiny.
        score += 0.2 * mean_residual;
    }

    // Slight preference for tighter existing bins when many are open.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to residual (small waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins;
    // make the new-bin candidate less attractive as open_bins_count is low.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -1.5;
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item could use the post-residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        if post_residual - next_item_size < 5 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual {
        // Gap won't serve the next item; mild penalty proportional to waste.
        score += (post_residual as f64) * 0.3;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's already
    // fragmented; prefer bins with larger residuals for big items.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // Late in the stream, tighten up: avoid leaving many near-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress > 0.8 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual can fit the next item: reward proportionally to how snugly.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(20.0);
    }
    // Next item cannot fit here: penalize, worse for very small dead space.
    else if next_item_size > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += 5.0 + 0.5 * gap.min(40.0);
    }

    // Penalize leaving tiny unusable dead space (< 10, smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward near-perfect fills (small residual but usable).
    if post_residual >= 1 && post_residual <= 15 {
        score -= 8.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    // Progress-based tightening: later in stream, prefer tighter fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.2;

    // Discard preference for opening a new bin unless current bin is a bad host.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: reward if the next item can fit into the post-residual space.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        // Prefer chains that keep future leftovers small.
        let chain_quality = 1.0 - (leftover_after_next as f64 / bin_capacity as f64);
        score -= 10.0 * chain_quality;
    } else if next_item_size > 0 {
        // Penalize leaving space that the next item cannot use (dead space risk).
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate (bin_residual == bin_capacity) more when open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 10.0 * (1.0 - progress);
        // But if this is the only option, the last-chance logic above doesn't apply; soften a bit.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidate large holes),
    // penalize drawing from bins already much emptier than average.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff;

    // Mild preference for keeping the number of open bins stable when stream is late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t2 = t * t;
    let t3 = t2 * t;

    // Normalized post-residual and fill ratio
    let pr = post_residual as f64 / cap;
    let fill = 1.0 - pr;

    // Non-linear coupling: reward high fill more strongly as stream progresses
    score -= (post_residual as f64) * (0.5 + 1.5 * t2) * fill;

    // Polynomial dead-space penalty: small residuals are wasted space
    let dead = pr * pr * (1.0 - pr);
    score += 60.0 * dead * (1.0 + t3);

    // Last-chance bonus: smooth reward when this bin is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Lookahead coupling: if next item fits into post_residual, reward it smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let slack = pr * cap - ns;
        if slack >= 0.0 {
            let fit_q = 1.0 - (slack / cap);
            score -= 30.0 * fit_q * fit_q;
        } else {
            score += 10.0 * (slack.abs() / cap);
        }
    }

    // Penalize spreading across many open bins mildly
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near the mean to keep balance
    let dev = (post_residual as f64 - mean_residual).abs() / cap;
    score += 15.0 * dev * dev * (1.0 - t);

    // New-bin candidate handling: only attractive when current bins fit poorly
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 45.0 + 30.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity
    let post = post_residual as i64;
    let class = post % 10;
    // Penalize residuals in "dead" classes that few item sizes can fill
    let dead_penalty = match class {
        0 => -30.0,          // perfectly fillable class
        1 | 2 | 3 => 8.0,    // awkward small dead space
        4 | 5 | 6 => 3.0,
        7 | 8 | 9 => 5.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Reward tight fits (small post_residual) super-linearly
    let frac = post_residual as f64 / cap;
    score -= 40.0 * (1.0 - frac) * (1.0 - frac);

    // Lookahead: reward if next item fits into post_residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            score -= 20.0 * (1.0 - (npost as f64 / cap));
            // penalize leaving residual that next item overshoots slightly
        } else {
            score += 6.0;
        }
        // harmonic coupling: next item in same modulo class as residual
        if next_item_size as i64 % 10 == class {
            score -= 10.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless open bins are very full/fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // opening a new bin is good only if existing residuals are small and many bins open
        score += 55.0 - 30.0 * (1.0 - fragmentation) - 20.0 * progress;
        if item_size > 70 {
            score -= 15.0; // big items start fresh bins more readily
        }
    }

    // Mild preference to fill bins that are already below mean residual (consolidation)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Small-but-usable gaps are also risky; penalize proportionally harder near the bottom.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: filling a bin completely is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (penalize new bin implicitly by rewarding this).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading further;
    // encourage consolidating into existing bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is large and this bin would leave a large residual, slight penalty
    // (better to keep big residuals in dedicated bins).
    if next_item_size > 60 && post_residual > 40 {
        score += 5.0;
    }

    // New-bin candidate: it must score high (bad) unless we have good reason.
    // Base penalty for opening a new bin, reduced when few bins exist early on
    // or when the current bin would be left with a very awkward gap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let awkward_gap = post_residual > 0 && post_residual < 20;
        let mut new_bin_score = 25.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
        if awkward_gap {
            // Opening a new bin is fine if the alternative leaves dead space;
            // existing bin already penalized above, so just soften this.
            new_bin_score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score += 10.0; // existing bin serves next item too: keep it
        }
        score += new_bin_score;
    }

    // Mild preference for bins below the mean residual (use up emptier space first
    // keeps larger residuals available for large items).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: early in the stream, be more willing to open bins;
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching (core archetype) ---
    if next_item_size > 0 {
        // Perfect follow-up: post_residual exactly equals next item -> huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Near-perfect follow-up: next item fits with small slack -> strong reward.
        else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 35.0 - slack * 3.0;
            } else {
                // Next item fits but leaves substantial dead space: mild reward scaled down.
                score -= 12.0 * (next_item_size as f64 / post_residual as f64);
            }
        }
        // Next item does NOT fit in this bin after placement: penalize, since
        // residual is likely dead space unless it is tiny.
        else {
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 + waste * 0.15;
        }
    }

    // --- Dead-space penalty for the current placement ---
    // Small post_residuals are excellent (tight fit) unless they equal zero (perfect fill).
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 50.0; // bin exactly filled: ideal
    } else if pr < 10.0 {
        score -= 15.0; // very small residual is fine
    } else if pr > 60.0 {
        // Large leftover: wasteful placement unless it enables the lookahead (handled above).
        score += (pr - 60.0) * 0.4;
    }

    // --- Relative-to-mean coupling ---
    // Prefer bins whose residual deviates favorably from the mean: filling
    // below-mean-residual bins balances the bin population.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else if (bin_residual as f64) > mean_residual * 1.5 {
        score += 4.0;
    }

    // --- Last-chance bonus ---
    // If this is the only bin that can fit the item, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable early, or when the item is large and
        // would leave existing bins with awkward residuals.
        let early_bonus = (1.0 - progress) * 10.0;
        let large_item_bonus = if item_size >= 50 { 8.0 } else { 0.0 };
        score += 20.0 - early_bonus - large_item_bonus;
        // If lookahead says next item pairs perfectly with residual capacity 100 - item,
        // opening is more attractive.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // --- Late-stream tightening ---
    score += progress * 6.0;

    // Slight penalty proportional to number of open bins to discourage sprawl.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if is_new_bin {
        // Opening a new bin wastes capacity; penalize, but relax late in stream
        // or when the item is huge and would leave an awkward gap elsewhere.
        let waste = (bin_capacity as f64 - item_size as f64).max(0.0);
        let mut open_penalty = waste * 0.35;
        // Large items pack cleanly into fresh bins; small discount for them.
        if item_size >= 60 {
            open_penalty -= 8.0;
        }
        // Late in the stream, leftover consolidation matters less.
        open_penalty *= 1.0 - 0.4 * progress;
        // If many bins are open, prefer reusing them rather than growing the fleet.
        open_penalty += open_bins_count as f64 * 0.8;
        score += open_penalty;
    } else {
        // Reward tight fits in existing bins: small post_residual already favored.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 6.0;

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        } else {
            // With many fitting options, prefer the one closest to fullness.
            score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
        }

        // Prefer bins with below-average residual (they are "nearly full").
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.0;
        }

        // Lookahead: if the post-residual cannot host the next item but other
        // placements might, mildly penalize; if it can host it exactly, reward.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 2.0;
                if (post_residual - next_item_size) <= 5 {
                    score -= 3.0; // near-perfect two-item chain
                }
            } else {
                score += (next_item_size - post_residual) as f64 * 0.05;
            }
        }

        // Dead-space penalty: residuals below the minimum item size are unusable.
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space squared, amplified by stream progress
    let waste_frac = post / cap;
    score += 40.0 * waste_frac * waste_frac * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / residual.max(1.0);
    score -= 25.0 * tightness * tightness * (1.0 - progress);

    // Smooth coupling of post_residual with mean residual: prefer bins below mean residual
    let dev = (post - mean_residual) / cap;
    score += 15.0 * dev * dev - 10.0 * dev;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space for the next item smoothly
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (post - nxt) / cap;
        let fit_next = 1.0 / (1.0 + (-20.0 * gap).exp());
        score -= 18.0 * fit_next;
    }

    // Mild penalty for many open bins, encouraging consolidation early
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: penalize slightly so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 defines how "usable" the dead space is.
    let post_class = post_residual % 10;
    let post_quot = post_residual / 10;

    // Penalize residuals whose harmonic class is small (1..9 are awkward dead spaces).
    if post_residual > 0 && post_class != 0 {
        score += (10 - post_class) as f64 * 0.9;
    }

    // Reward exact fills and multiples-of-10 post residuals (harmonic with typical sizes).
    if post_class == 0 {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Integer-division thresholds: small quotients mean tiny unusable slivers.
    if post_quot == 0 && post_residual > 0 {
        score += 5.0; // residual < 10 is nearly dead space
    }

    // Coupling with next item: reward a post residual that harmonically hosts the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit_class = (post_residual - next_item_size) % 10;
            score -= 4.0;
            if next_fit_class == 0 {
                score -= 4.0;
            }
            if post_residual == next_item_size {
                score -= 6.0;
            }
        } else {
            score += 3.0; // lookahead won't fit here; bin likely closes
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Tightness preference among multiple candidates.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 8.0;
    }

    // New-bin candidate: only attractive when no good fit exists (few fitting bins or bad harmonics).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let penalty = 20.0 + 10.0 * (1.0 - progress) + (fitting_bins_count as f64) * 4.0;
        score += penalty;
        // Opening a bin is better if the item is large relative to mean residual space.
        if (mean_residual < item_size as f64) && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference for tighter existing bins (waste-aware).
    score += (bin_residual as f64 - post_residual as f64 - item_size as f64).abs() * 0.01;
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone_max = 10.0f64;
    if post_residual > 0 && (post_residual as f64) <= dead_zone_max {
        score += (dead_zone_max - post_residual as f64 + 1.0) * 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving space usable for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * (post_residual as f64 - next_item_size as f64).min(30.0);
        } else if post_residual > 0 {
            // Post-residual too small for next item: dead space penalty scaled by tightness.
            score += 10.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (makes new-bin candidate less attractive when open_bins_count is high).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // New-bin candidate adjustment: empty bin gets residual == capacity, which is
    // naturally a high score; add extra penalty so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
    } else {
        // Reward tight fits relative to bin residual.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powi(6);

    // Strong penalty if the leftover space is too small for the next item
    // (dead space that likely can never be used).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 + (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving exactly usable space for the lookahead item.
            score -= 15.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64)).powi(3);
        }
    }

    // Penalize bins far above mean residual (they are the "loosest" fits).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // would leave a very small residual in existing bins (poor fits) or
    // early in the stream when many items remain to fill fresh bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_pressure = (post_residual as f64 / bin_capacity as f64).powi(2);
        score = 20.0 + 60.0 * poor_fit_pressure + 40.0 * progress;

        // Opening a new bin is good if the next item is large and would
        // benefit from a fresh full bin.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild quadratic shaping.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 0.05 * (post_residual as f64 - next_item_size as f64);
        } else {
            // Dead space for the next item: penalize proportionally to waste.
            score += 0.03 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is truly terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
        // Extra reward if the fit is decent (post_residual small).
        if post_residual < 10 {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded (mean residual low) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Default penalty for opening a new bin.
        score += 6.0;
        // Relax penalty when bins are crowded and we're mid/late stream.
        score -= 10.0 * crowding * (0.3 + 0.7 * progress);
        // A fresh bin is great for very large items.
        if item_size > bin_capacity / 2 {
            score -= 2.0;
        }
    }

    // Prefer bins with residual already below half capacity (consolidation).
    if bin_residual < bin_capacity / 2 && bin_residual >= item_size {
        score -= 1.5;
    }

    // Slight preference for bins whose residual deviates from mean in the
    // "smaller" direction (use up the tightest bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with mild non-linear decay
    let mut score = pr * (1.0 + 0.35 * pr / cap) - 0.25 * (pr * pr) / cap;

    // Reward tight fits (small post_residual relative to item) smoothly
    let tightness = 1.0 - pr / cap;
    score -= 18.0 * tightness * tightness * (it / cap);

    // Smooth stream-progress coupling: tighter packing valued more later
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 10.0 * tightness * prog_term;

    // Reward bins whose post_residual can host the next item (lookahead)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack) * (nx / cap);
        } else {
            // penalize blocking the next item, worse as gap shrinks
            let gap = (nx - pr) / cap;
            score += 6.0 * gap * gap * 10.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (it / cap);
    } else {
        // mild dilution when many bins fit (choice is easy)
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: penalize heavily, but relax when no good fit exists
    let is_new = (bin_residual as f64 - cap).abs() < 0.5 && item_size > 0 && post_residual == bin_residual - item_size && bin_residual == bin_capacity;
    if is_new {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { (mean_residual / cap).min(1.0) };
        score += 40.0 - 25.0 * desperation * desperation;
        // opening early in stream is cheaper than late
        score -= 5.0 * (1.0 - progress);
    }

    // Slight pull toward bins near mean residual (balanced packing)
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual modulo small divisors
    // captures "dead space" classes that rarely accept future items.
    let r = post_residual;
    let m4 = (r % 4) as f64;
    let m10 = (r % 10) as f64;
    let m25 = (r % 25) as f64;

    // Penalize residuals that fall into awkward harmonic classes (nonzero
    // remainders waste space), reward exact harmonic alignment.
    score += 0.8 * m4;
    score += 0.5 * m10;
    score += 0.3 * m25;

    // Integer-division thresholds: residuals in (0, 10] are nearly dead space.
    let dead = (r <= 10 && r > 0) as i32;
    score += 12.0 * dead as f64;

    // Perfect fit is best.
    if r == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly or well,
    // strongly reward this bin.
    if next_item_size > 0 && next_item_size <= r {
        let fit_gap = (r - next_item_size) as f64;
        score -= 25.0 * (1.0 - fit_gap / bin_capacity as f64);
        // Harmonic bonus: next item leaves another aligned residual
        if (r % next_item_size.max(1)) == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > r {
        // Next item cannot use this bin's leftover: mild penalty scaled by waste.
        score += 0.1 * (next_item_size - r) as f64;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when the item
    // is large relative to capacity or open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 * 0.55 - 20.0 * item_frac + 5.0 * crowding + 10.0 * progress;
        // Prefer new bin when existing residuals are small and item is big.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Spread pressure: when many bins are open, favor filling existing ones.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that cannot hold even the smallest plausible item (<= ~10)
    // is pure waste; a residual that could fit the next item is valuable.
    if post_residual < 10 {
        score += 60.0; // hard dead space penalty
    } else if post_residual > 0 {
        // smooth penalty for small gaps that are unlikely to be filled
        let gap_usefulness = (post_residual as f64 / bin_capacity as f64).sqrt();
        score -= 25.0 * gap_usefulness;
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Next-item lookahead: if the next item fits in the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual blocks the next item but is not usable dead space
        score += 10.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // (consolidation) rather than spreading; penalize lightly per open bin.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make the empty bin attractive only when existing bins
    // would leave bad dead space. Base new-bin score anchored to capacity.
    if bin_residual == bin_capacity {
        // neutral anchor: slightly worse than a good fit, better than dead space
        score = 0.55 * bin_capacity as f64
            - 15.0 * (next_item_size as f64 / bin_capacity as f64)
            + 0.15 * open_bins_count as f64;
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            // large item into fresh bin is fine
            score -= 20.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0 is ideal).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this is a perfect chain placement -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills remainder.
            let fill = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 25.0 * fill;
        } else {
            // Next item cannot use this residual: penalize leftover dead space.
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 15.0 * waste;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins with residual below
    // average (denser bins) when the fit is good.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.15 * rel;

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin unless it is genuinely needed (no good fit
    // exists). New-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base penalty for wasting a fresh bin; reduced when many bins are open
        // and stream is early (room to consolidate later).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 10.0 * progress;
        // If next item is large and current item is small, a fresh bin may
        // still be reasonable: slight discount.
        if next_item_size >= 50 && item_size <= 30 {
            score -= 8.0;
        }
    }

    // Mild penalty for leaving residuals in the awkward 1..=9 range
    // (unusable by items >= 10 in classic setting, but items can be >= 1,
    // so weight small dead space less).
    if post_residual >= 1 && post_residual <= 5 {
        score += 12.0;
    }

    // Encourage consolidation when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (tight fit).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Exact fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on dead space, stronger for small leftovers that are hard to reuse.
        let dead = post / cap;
        if post < 10.0 {
            score += 40.0 * dead; // tiny slivers are nearly useless
        }
        score += 20.0 * dead * dead;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_bonus = 30.0 + 0.5 * (next_item_size as f64);
        score -= chain_bonus * (1.0 - post / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize creating residual just below next item size (near-miss waste).
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap < 8 {
            score += 15.0 - 1.5 * gap as f64;
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, to keep options open.
        score += 2.0 * (fitting_bins_count as f64).min(10.0);
    }

    // New-bin candidate handling: only attractive when item is large relative to capacity
    // or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item / cap;
        // New bin score ~ remaining space; discount it if item is big (good use of fresh bin).
        score -= 220.0 * fill_ratio * fill_ratio;
        // Penalize opening new bins when plenty of open bins have room.
        if fitting_bins_count >= 1 {
            score += 60.0 + 5.0 * (open_bins_count as f64).min(20.0);
        }
        // Early in stream, opening bins is cheaper (build diversity of residuals).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 80.0 * (1.0 - progress);
    }

    // Global state coupling: if mean residual is high, avoid worsening fragmentation
    // by leaving small leftovers in already-fragmented bins.
    if mean_residual > 0.0 {
        let frag = (post - mean_residual).abs();
        score += 0.05 * frag;
    }

    // Slight preference for bins with lower initial residual among equal post-residuals
    // (consolidates fullness).
    score += 0.1 * (bin_capacity.saturating_sub(bin_residual)) as f64 * 0.0
        + 0.02 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress.
    // Late in the stream, compacting residual space matters more: reward low
    // post-residual super-linearly as progress increases.
    let tightness = 1.0 - norm_pr; // high when item nearly fills the bin
    let coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 18.0 * coupling * tightness * tightness;
    score -= 30.0 * progress * progress * tightness;

    // Penalize large unusable dead space with a cubic term.
    if norm_pr > 0.0 {
        score += 25.0 * norm_pr * norm_pr * norm_pr;
    }

    // Reward exact or near-perfect fits smoothly.
    if pr == 0 {
        score -= 50.0;
    } else {
        score -= 15.0 * (-norm_pr * 12.0).exp();
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let slack = (pr as f64 - nx) / cap;
            score -= 20.0 * (1.0 - slack) * (1.0 + progress);
        } else {
            score += 8.0 * (nx / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 + progress);
    }

    // New empty bin candidate: penalize mildly so it is chosen only when
    // no open bin offers a decent fit, with a smooth decay over the stream.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Discourage placements far from the mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it divides into capacity
    let pr = post_residual;
    let class = pr % 10; // residue class mod 10
    let div_class = if pr == 0 { 10 } else if pr % 20 == 0 { 0 } else if pr % 5 == 0 { 1 } else if pr % 3 == 0 { 2 } else { 3 };

    // Reward residuals in "good" harmonic classes (divisible, reusable chunks)
    match div_class {
        0 => score -= 6.0,        // exact halves/quarters of capacity
        1 => score -= 3.0,        // multiple of 5
        2 => score -= 1.5,        // multiple of 3
        _ => {}
    }
    if pr == 0 { score -= 12.0; } // perfect fit

    // Penalize awkward dead space: small non-classed remainders
    if pr > 0 && pr < 10 {
        score += 8.0 + (10 - pr) as f64;
    }

    // Lookahead coupling: does next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // bonus scaled by how well next item harmonizes with post residual
            let harmony = (pr % next_item_size.max(1) == 0) as f64 * 4.0;
            score -= 5.0 + harmony + (next_item_size as f64 / cap) * 4.0;
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).sqrt() * 0.8;
        // prefer new bin only if best existing fit leaves tiny dead space
        let waste = (bin_residual - item_size) as f64;
        score += 14.0 + pressure - progress * 4.0 - (waste / cap) * 6.0;
        if item_size >= 70 { score -= 6.0; } // big items pair well with fresh bins
    }

    // Mild preference for tighter bins overall
    score += (bin_residual as f64 / cap) * 2.0;
    score += (mean_residual - bin_residual as f64) * 0.02;

    // Tie-break with harmonic class of item itself
    score += (item_size % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps.
    // A residual that is too small to hold even the smallest plausible item is waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 0.0; // perfect fit, no dead space possible
    } else {
        // Dead space severity: gaps that cannot fit the next item are worse.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // General small-gap penalty: residuals in (0, 10) are near-useless.
        if post_residual > 0 && post_residual < 10 {
            score += (10 - post_residual) as f64 * 2.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= tightness * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing bins
    // over opening new ones; the empty-bin candidate gets penalized implicitly
    // through post_residual == bin_capacity - item_size, but add explicit pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more when many bins are open.
        score += bin_pressure * 8.0;
        // But if no open bin fits well (post_residual here would be large),
        // a new bin is fine; counteract when item is large relative to residual gap.
        let gap = (bin_capacity - item_size) as f64;
        if gap > 30.0 {
            score -= gap * 0.5;
        }
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter bins)
    // when many bins are open, to consolidate waste.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff * 0.3;
        } else {
            score += (-diff) * 0.3;
        }
    }

    // Lookahead: if the next item exactly fits the post residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fit (item exactly fills the bin).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward leaving space exactly matching next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            // next item can still fit here; mild bonus proportional to tightness
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize proportionally to waste
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 60.0 * waste;
            // if next item is large, dead space is more costly
            score += 0.3 * next_item_size as f64 * waste;
        }
    }

    // Tight fit bonus: small post_residual generally better.
    score -= 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        // baseline penalty for opening a new bin
        score += 120.0;
        // if this bin is the only fitting option, opening new is acceptable
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
        // if next item is huge, a fresh bin may be better
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 80.0;
        }
    }

    // Prefer bins below mean residual (fill emptier bins less, keep balance).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Late in stream: conserve bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already dominates).

    // Lookahead reward: if the next item fits exactly or well into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= (bin_capacity as f64) * 0.6 * (1.0 - chain_waste / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: nearly eliminate dead space
        }
    }
    // If next item cannot fit in post_residual, penalize small leftovers mildly
    // unless the leftover is tiny (usable by later small items).
    if next_item_size > post_residual && post_residual > 0 {
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.1 {
            score -= 8.0; // tiny dead space is acceptable
        } else {
            score += 6.0 * frac; // medium leftover that blocks next item
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when existing
    // residuals are poor fits. Give the empty bin a moderate baseline penalty so
    // decent fits into open bins win, but allow it to win when fits are bad.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // High mean residual => open bins have plenty of space => discourage new bin.
        score += 40.0 + 30.0 * pressure;
        // Early in the stream, new bins are cheap (many items to come to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If no open bin fits at all, new bin is mandatory: drop the penalty.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Prefer placing into bins whose residual is closest to the item (best fit),
        // scaled by how many alternatives exist.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness;
        // Slight preference for bins with residual below the mean (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Penalize creating residual that is too small for the minimum plausible item,
    // but only late in the stream when future small items are less likely to save it.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * progress;
    }

    // Mild bonus for using bins that are already partially filled when many bins are open
    // (encourages closing bins rather than spreading across many).
    if open_bins_count > 3 && bin_residual < bin_capacity {
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post / cap; // normalized post residual
    let base = post;

    // Smooth polynomial coupling of post residual with stream progress
    let poly = pr * pr * (1.0 - pr) * (1.0 - pr);
    let progress_term = 60.0 * (0.5 + progress) * poly * cap * 0.1;

    // Penalize very small dead space (wasted slivers) more strongly as stream advances
    let sliver = if post_residual > 0 { (cap / post as f64).ln() } else { 10.0 };
    let sliver_term = 8.0 * sliver * (0.4 + 0.6 * progress);

    // Reward tight fits (small post residual relative to item)
    let tight_fit = (item_size as f64) / (bin_residual.max(1) as f64);
    let fit_bonus = -30.0 * tight_fit * tight_fit;

    // Last-chance bin: strongly favor using it
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Lookahead: bonus if next item fits in post residual
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= post {
        -12.0 * (1.0 - (next_item_size as f64) / cap)
    } else if next_item_size > 0 {
        6.0
    } else {
        0.0
    };

    // Mild preference for filling bins with low mean residual (consolidation)
    let mean_term = 3.0 * (mean_residual - post) / cap;

    // New-bin candidate: penalize opening new bins, more so early in stream
    let is_new = bin_residual == bin_capacity;
    let new_bin_pen = if is_new { 40.0 + 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64 } else { 0.0 };

    base + progress_term + sliver_term + fit_bonus + last_chance + lookahead + mean_term + new_bin_pen
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space (decile granularity).
    let class = post_residual / 10;
    // Dead space penalty: leftover in the smallest harmonic classes is valuable.
    let dead_penalty = match class {
        0 => 40.0,
        1 => 18.0,
        2 => 8.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Perfectly reusable residual classes for future items (multiples of 10, 25, 50).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 {
        score -= 3.0;
    }

    // Lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Harmonic coupling: leftover class matches next item's class -> very good.
        if post_residual / 10 == next_item_size / 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // This placement strands the next item.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive for large items
    // or when the current bin's fit is poor.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Opening a bin wastes capacity for small items.
        score += 25.0 * (1.0 - frac);
        if item_size >= 60 {
            score -= 15.0;
        }
        if fitting_bins_count > 0 && item_size < 40 {
            score += 20.0; // don't open bins for small items when one fits elsewhere
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64 * (bin_residual as f64 / cap);

    // Late-stream tightening: waste hurts more near the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 / cap) * 10.0;

    // Deviation from mean residual: prefer bins that are already well-filled.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver => strong penalty on top of its small value
    }

    // Penalize gaps that cannot fit the known next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer tight fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: neutral residual = capacity; make it moderately attractive
    // only when existing bins would leave very poor fits, otherwise keep it worse.
    if bin_residual == bin_capacity {
        score -= 8.0;
        // If this bin is a last-resort situation, allow opening a new bin.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Slight preference for bins below mean residual (tighter bins first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer smallest post residual (best fit), with slight superlinearity
    score = post_residual as f64 * 1.0 + (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            // Perfect chain: this item leaves exactly room for the next
            score -= 500.0;
        } else {
            score -= 150.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the upcoming item
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Compare against mean residual: bins tighter than average are more valuable to fill
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (bin_residual as f64) < mr {
        score -= 0.3 * (mr - bin_residual as f64);
    } else {
        score += 0.2 * (bin_residual as f64 - mr);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current bin would waste a lot
    if bin_residual == bin_capacity && item_size > 0 {
        // Opening a fresh bin costs roughly the item's size in unused capacity later;
        // make it expensive but allow it if the item is huge relative to any fit
        score += 250.0 - 1.0 * item_size as f64;
        // If lookahead suggests a big next item, a fresh bin is more attractive
        if next_item_size > 50 {
            score -= 60.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    // Slight time decay: early in stream, be a bit more willing to open bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Penalize small dead space after placement (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 45.0;
        } else if next_item_size as u32 > post_residual {
            // Next item won't fit here anyway; slight penalty for wasting space now.
            score += 8.0 * (1.0 - fill);
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 55.0;

        // Prefer new bin when existing bins have high residual spread (fragmentation).
        let mean_fit_gap = mean_residual - item_size as f64;
        if mean_fit_gap > 0.0 && mean_fit_gap < 15.0 {
            // Other bins fit decently; discourage opening new bin.
            open_cost += 30.0;
        }

        // Early in stream: be more liberal with new bins (exploration).
        open_cost -= 20.0 * (1.0 - progress);

        // If many bins already open, discourage proliferation.
        open_cost += 1.5 * open_bins_count as f64;

        score += open_cost;
    }

    // Slight preference for bins with residual close to mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: quadratic coupling of post_residual with fill fraction
    let mut score = pr * (1.0 + 0.8 * fit_ratio * fit_ratio) + 0.35 * pr * pr / cap;

    // Smooth stream-progress coupling: later in stream, penalize waste more
    let prog_term = 0.6 * progress * (1.0 - progress) + 1.2 * progress * progress;
    score *= 1.0 + 0.5 * prog_term;

    // Dead-space penalty: residual too small for any plausible future item
    let dead_zone = ((30.0 - pr).max(0.0) / 30.0).powi(2);
    score += 25.0 * dead_zone;

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - (pr - nx) / cap;
            score -= 18.0 * (0.5 + 0.5 * snug);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 4.0 * ((nx - pr) / cap).min(1.0);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly; relax late in the stream or when
    // open bins are already fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        let fragmentation = ((mean_residual - pr).abs()) / cap;
        let mut new_bin_penalty = 40.0 + 20.0 * (1.0 - progress);
        new_bin_penalty -= 25.0 * fragmentation.min(1.0);
        // a new bin is attractive if item is large and next item is small
        if next_item_size > 0 && (next_item_size as f64) < item_size as f64 {
            new_bin_penalty -= 10.0 * fit_ratio;
        }
        score += new_bin_penalty.max(5.0);
    }

    // Mild preference for bins tighter than the mean (compactness)
    score += 2.0 * ((pr - mean_residual) / cap).max(-1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small post residuals (tight fits)
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 30.0;
    } else if pr <= 10 {
        score -= 12.0;
    } else {
        // dead-space penalty grows for awkward residual classes
        let quarter = (pr as f64) / cap;
        if quarter < 0.2 { score -= 4.0; }
        else if quarter < 0.35 { score += 8.0; } // unusable mid-dead zone
        else if quarter < 0.5 { score += 3.0; }
        // modulo classes: residuals like 10,20,... are reusable by typical items
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 10 == 1 || pr % 10 == 9 { score += 5.0; } // awkward residues
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr && pr - next_item_size <= 10 {
            score -= 18.0;
        } else if next_item_size > pr {
            // next item won't fit here; slight penalty for wasting residual
            score += 2.0 * ((pr as f64) / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 40.0;
        // more attractive when many bins are open and fragmented
        score -= 0.5 * open_bins_count as f64;
        if item_size >= 50 { score -= 15.0; } // big items prefer fresh bins
        if next_item_size > 0 && next_item_size > bin_residual.saturating_sub(item_size) {
            score -= 10.0;
        }
    }

    // Stream progression: later in stream, prefer consolidation over new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Tie-break with mean residual: prefer bins deviating below mean (tighter bins)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are near-perfect; residuals that are small but usable are penalized
    // because they risk becoming dead space later.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fill, ideal
    } else if post_residual < 10 {
        score -= 45.0; // unusable sliver: effectively a full bin
    } else {
        // penalize small-but-usable gaps super-linearly (dead space risk)
        let dead_risk = (10.0f64).mul_add(-1.0, pr) / 90.0; // 0..1
        score += (1.0 - dead_risk) * (1.0 - dead_risk) * 25.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 20.0;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> consolidate into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item is large and would not fit post-residual, mild penalty
    // unless post_residual is dead space anyway.
    if next_item_size > post_residual && post_residual >= 10 {
        score += 6.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is the "emptiest" bin; prefer filling fuller bins instead.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.4;
    } else {
        score += dev * 0.1;
    }

    // New-bin candidate: make it attractive only when no good existing fit
    // exists (few fitting bins) or stream is early; otherwise penalize.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        score += 30.0 + scarcity * 8.0 - progress * 10.0;
        // opening a new bin is fine if next item is huge and won't fit elsewhere
        if next_item_size >= 60 && fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
