pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items
    if post_residual > 0 {
        let useless = (post_residual as f64 / 100.0).powi(3);
        score += 30.0 * useless;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty,
    // but it becomes attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the item fits poorly anywhere (large residual left), opening is fine
        if post_residual > 20 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening new bins unless necessary
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
    }

    // Lookahead: if next item would fit into the post residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // Penalize if this placement leaves a residual that is awkwardly just below next item
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    let spread = mean_residual - post_residual as f64;
    if spread > 0.0 {
        score += 0.05 * spread;
    } else {
        score += 0.05 * spread; // symmetric small correction
    }

    // Prefer bins with lower residual overall (fill fuller bins first)
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Slight penalty for accumulating too many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]
    let p = progress;

    // Smooth interaction: waste penalty grows super-linearly with progress.
    score += 40.0 * p * x * x * (1.0 - 0.5 * x);

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - x;
    score -= 25.0 * tightness * tightness * (0.5 + p);

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 * (0.5 + p);
    }

    // Penalize opening new bins when many bins are already open and mean residual is large.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 20.0 + 30.0 * open_bins_count as f64 * mean_norm * (1.0 - p);
    }

    // Lookahead coupling: favor bins whose post residual can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (0.5 + p);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Mild global regularization toward bins with residuals near the mean.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (0, 1, 2, 5, 10) are near-perfect packs.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -40.0
    } else if pr <= 2 {
        -30.0
    } else if pr <= 5 {
        -22.0
    } else if pr <= 10 {
        -14.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Modulo arithmetic on post_residual: residues coprime-friendly with
    // common item sizes (multiples of 10 grid) are reusable.
    let grid = (bin_capacity / 10).max(1);
    let residue_mod = (pr % grid) as f64;
    score += 3.0 * residue_mod;

    // Integer-division threshold classes on post_residual.
    let quarter = bin_capacity / 4;
    if pr < quarter {
        score -= 8.0; // tight bin, good to fill further
    } else if pr < bin_capacity / 2 {
        score += 2.0;
    } else {
        score += 6.0; // large leftover, less urgent
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly reward; if next item can't fit at all, penalize dead space.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - pr).min(30) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bins are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins are preferred...
        score += 15.0;
        // ...but if the item barely fits anywhere (tight fits across open bins),
        // opening a fresh bin is reasonable.
        let tight_fit = bin_residual - item_size <= 5;
        if tight_fit && fitting_bins_count <= 2 {
            score -= 18.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer denser bins (small mean residual means bins are filling up;
    // placing into a fuller-than-average bin keeps fragmentation low).
    let this_frac = (bin_residual as f64) / cap;
    let mean_frac = mean_residual / cap;
    if this_frac < mean_frac {
        score -= 5.0 * (mean_frac - this_frac);
    } else {
        score += 3.0 * (this_frac - mean_frac);
    }

    // Mild pressure against accumulating many open bins.
    score += (open_bins_count as f64) * 0.15;

    // Exact fill is always best.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward using bins that are already fairly full (small residual before placement).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many alternatives: slight penalty to discourage spreading items thinly.
    if fitting_bins_count > 2 {
        score += 3.0;
    }

    // Open-bin pressure: discourage opening new bins when open bins exist and fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to number of open bins,
        // but allow if next item pairs well with the leftover space.
        score += 20.0 + 8.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 10.0; // opening a bin here wastes pairing opportunity
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Lookahead: reward leaving post_residual that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize post_residual that is too small for anything useful (dead space).
    if post_residual > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    // Late in stream, tighten bins more aggressively to close them out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * fill_ratio;

    // Mean residual coupling: when open bins are mostly empty, prefer reusing them.
    if mean_residual > (item_size as f64) * 1.5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
