pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    score -= (cap - post_residual as f64).sqrt() * 2.0;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 8.0 + 12.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            // Dead space risk: post residual too small for next item
            score += 4.0 * (nxt - post_residual as f64) / cap;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when good fitting bins exist and stream is late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= bin_residual as f64 {
            score -= 5.0;
        }
    }

    // Fragmentation penalty: small post residual relative to mean residual is fine,
    // large post residual wastes space others could use.
    if post_residual as f64 > mean_residual {
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    // Mild penalty for very many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: quadratic growth of dead space, amplified late in stream
    let norm_pr = pr / cap;
    score += 18.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth saturating term
    score -= 12.0 * (1.0 - (norm_pr * std::f64::consts::PI).cos()) * (1.0 - progress);

    // Lookahead synergy: next item fits exactly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * (1.0 - slack) * (1.0 - progress);
    } else if next_item_size > post_residual {
        // next item cannot follow: penalize proportionally to how stranded it is
        score += 6.0 * (next_item_size as f64 / cap) * (0.3 + progress);
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Many open bins: prefer consolidating into existing ones
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Deviation from mean residual: prefer bins near the mean to keep balance
    score += 0.15 * ((pr - mean_residual).abs() / cap) * 10.0;

    // New-bin candidate: neutral baseline; only chosen when open bins score poorly
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
        // allow new bin early when item is huge relative to capacity
        if (item_size as f64 / cap) > 0.7 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "usable" class (large enough for typical small items) are rewarded.
    let class = post_residual / 10; // 0..=10 capacity-fraction classes
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: leftover below 10 is nearly unusable.
    if post_residual < 10 {
        score += 60.0 - 40.0 * progress;
    } else if post_residual < 20 {
        score += 18.0 - 10.0 * progress;
    } else {
        // Reward leftover sizes that form harmonic classes matching common item sizes.
        let usable = (post_residual >= 25 && post_residual <= 40) || (post_residual >= 50 && post_residual <= 60);
        if usable {
            score -= 8.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: does the next item fit in the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Coupling: exact harmonic match is excellent.
            let gap = (post_residual as i64 - next_item_size as i64) as f64;
            score -= 25.0 - 0.4 * gap;
        } else {
            // Next item won't fit here; mild penalty scaled by how far off.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is a fallback.
    if bin_residual == bin_capacity {
        // Penalize new bins, but less when the item is large relative to capacity
        // (large items are fine in fresh bins) or late in the stream.
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 70.0 - 50.0 * large_item + 15.0 * progress;
        // If no open bin can even fit the item, opening is mandatory.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Reward using existing bins, more when many are open (consolidation).
        score -= 2.0 * (open_bins_count.min(20) as f64).sqrt();
    }

    // Mild preference for bins deviating from the mean residual toward tight fits.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Modulo harmonic bonus: post_residual divisible into clean classes (20/25/50).
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    let _ = class;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small for the smallest plausible item (1..100 range),
    // so anything below a small threshold is nearly unusable.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // Dead space: penalize proportionally to how close it is to zero.
        score += (10.0 - pr) * 6.0;
    }

    // Perfect or near-perfect fit reward.
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Tight fit relative to bin residual: fraction of residual consumed by item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bin pressure: penalize creating more bins / spreading items thin.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin for an awkward item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin, scaled by stream progression
        // (later in stream, less future to amortize a new bin, so slightly more reluctant).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 + progress * 10.0;

        // But if the item is large relative to capacity and mean residual is small,
        // a fresh bin is attractive.
        if item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    }

    // Lookahead: if next item would fit exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual: mild penalty for wasting space.
        score += pr * 0.3;
    }

    // Mean residual coupling: prefer bins whose residual is below average when mean is high
    // (consolidate space into few bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when next item exactly fills post_residual (perfect pairing)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        // exact match bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // next item too large for post residual: dead space penalty grows
        if next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: minimize waste directly
        score += 0.5 * post_residual as f64;
    }

    // compare against mean residual: bins below mean residual are tighter, prefer them
    score -= 0.3 * (mean_residual - post_residual as f64);

    // last-chance bin bonus: only one bin can fit this item
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // new-bin candidate: penalize opening a new bin unless current open bins are poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score = 0.8 * waste + 20.0 * (1.0 - progress);
        // opening a bin is fine when next item is small and fits the fresh residual
        if next_item_size > 0 {
            score -= 0.4 * (bin_capacity - next_item_size) as f64;
        }
        if fitting_bins_count > 0 {
            score += 30.0; // discourage new bin when an open bin fits
        }
    }

    // slight preference for tight fits overall
    score += 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: small post_residual is good, non-linearly
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness).powi(3) * 20.0;

    // Penalize dead space that can never be used by typical items (residual < 10 was old rule; now items >=1)
    if post_residual > 0 && post_residual < 5 {
        score += 15.0; // nearly unusable sliver
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // mild spreading penalty to avoid fragmenting many bins
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // even better if next item exactly fills the remaining space
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // next item won't fit here; penalize leaving awkward remainder
            score += 3.0;
        }
    } else {
        // last item: prefer exact fill
        score -= 5.0 * (1.0 - tightness);
    }

    // Relative to mean residual: prefer bins tighter than average early, looser late
    let rel = mean_residual - bin_residual as f64;
    score += rel * (0.5 - 0.6 * progress);

    // Avoid opening new bins when many are open and progress is late
    let new_bin_penalty = 8.0 + 20.0 * progress + 0.3 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // But if no existing bin fits (fitting_bins_count refers to this new bin too),
        // the penalty is unavoidable, which is correct.
        // Early stream: opening fresh bins is cheaper
        score -= 10.0 * (1.0 - progress);
    }

    // Large items: prefer bins with just enough room
    if item_size > bin_capacity / 2 {
        score -= 4.0;
    }

    // Slight preference for bins with residual close to item size (minimize waste)
    let waste_ratio = (post_residual as f64) / (bin_residual.max(1) as f64);
    score += waste_ratio * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual dominates, with mild non-linear shrinkage
    // (dead space matters less as it approaches capacity scale)
    let mut score = post + 0.35 * (post * post / cap);

    // Smooth polynomial coupling: residual tightness vs stream progress.
    // Early on, prefer filling bins tightly (penalize large post_residual more);
    // later, allow looser packing since new bins amortize over fewer items.
    let tightness = 1.0 - post / cap;
    score -= 18.0 * tightness * (1.0 - progress) * (1.0 - progress);

    // Last-chance bonus: strongly reward using a bin that is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize slightly so we only open when truly better,
    // but let progress modulate (late stream: new bins are relatively cheaper)
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            // next item won't fit: penalize wasting large residuals
            score += 3.0 * (post / cap) * (post / cap);
        }
    }

    // Mean-residual alignment: prefer bins near the mean to keep residuals balanced
    score += 0.05 * (post - mean_residual).abs();

    // Mild penalty for many open bins to discourage bin proliferation
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward perfect closures and
    // residuals that form "friendly" classes for future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure: ideal
    } else {
        // class by residual magnitude relative to capacity
        let frac = pr as f64 / cap;
        if pr <= 10 {
            score -= 25.0; // nearly closed, tiny dead space
        } else if pr <= 20 {
            score -= 8.0;
        } else if pr <= 35 {
            score += 4.0; // awkward mid class
        } else if pr <= 60 {
            score -= 5.0; // useful class (fits most mid items)
        } else {
            score -= 12.0; // large residual still very usable
        }
        let _ = frac;

        // Modulo-10 harmonic coupling: residuals divisible by 10 pair well
        // with the integer item sizes.
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 5 == 0 { score -= 2.0; }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 10.0;
            // modulo harmony between next item and post residual
            if pr % 10 == next_item_size % 10 { score -= 4.0; }
        } else {
            // next item cannot follow here: penalize proportional waste
            score += 0.05 * (next_item_size - pr) as f64;
        }
    } else {
        // last item: any bin that closes fully is best
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere else. New bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred by default.
        score += 30.0;
        // Large items are fine in a fresh bin.
        if item_size >= 60 { score -= 25.0; }
        // If next item is also large, a fresh bin is attractive.
        if next_item_size >= 60 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
        // As the stream progresses, discourage bin proliferation slightly.
        score += 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference for bins with below-mean residual (tighter packing).
    score += 0.10 * (mean_residual - bin_residual as f64);

    // Small penalty per open bin to encourage consolidation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item && post_residual > 0 {
        score += 500.0; // fully dead gap (can't happen for >=1, but guard)
    }
    // Unusable gap: cannot fit the next item either -> strong penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0 + 0.5 * post_residual as f64;
    }

    // Reward tight fits (low post_residual relative to item).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // New-bin candidate control: an empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when stream is early or item is large.
        let mut new_bin_cost = 120.0;
        new_bin_cost -= progress * 30.0;              // late stream: bins persist longer, be pickier
        new_bin_cost -= tightness * 40.0;             // large items justify fresh bins
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            new_bin_cost -= 20.0; // fresh bin can host next item too
        }
        if fitting_bins_count == 0 {
            new_bin_cost -= 200.0; // no alternative
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward if next item exactly fills post_residual,
    // penalize if next item cannot use the leftover space
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // perfect chaining: this bin becomes exactly full next step
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item can still fit here
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item cannot fit in the leftover -> dead space risk
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Penalize residuals below the smallest plausible item (unusable dead space)
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfectly closed bin is ideal
    }

    // Relative-to-mean coupling: prefer bins with above-mean residual
    // (consume slack where it is abundant, preserve tight bins)
    let dev = (bin_residual as f64) - mean_residual;
    score -= 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else {
        // mild diversity pressure when many bins fit
        score += 0.3 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let stream_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // opening cost grows over the stream; also grows with open bins count
        let open_cost = 30.0 + 40.0 * stream_frac + 2.0 * open_bins_count as f64;
        // discount if the fit elsewhere would be terrible (large post_residual waste)
        let waste_elsewhere = post_residual as f64; // = capacity here, but compare via next item
        let lookahead_bonus = if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            -10.0
        } else {
            0.0
        };
        score += open_cost + lookahead_bonus;
        let _ = waste_elsewhere;
    }

    // Mild late-stream conservatism: prefer closing bins tightly near the end
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    // Base: prefer small post-residual (tight fit)
    let mut score = post;

    // Penalize large unusable dead space quadratically
    if post < 10.0 {
        score -= 30.0 * (1.0 - post / 10.0);
    } else {
        score += 0.02 * post * post;
    }

    // Perfect fit reward
    if post == 0.0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward leaving room compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // next item can also fit here; good if it fills well
            let combined = item + nxt;
            if (residual - combined).abs() < 1.0 {
                score -= 60.0; // exact two-item fill
            } else {
                score -= 10.0 * (1.0 - (post - nxt) / cap);
            }
        } else if post > 0.0 && nxt > post {
            // dead space blocks next item; mild penalty scaled by deadness
            score += 0.3 * nxt * (post / residual.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // existing bins are crowded or the item is huge
    let is_new_bin = bin_residual == bin_capacity && bin_residual == post + item_size as u32;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        let avg_free = mean_residual;
        let item_frac = item / cap;
        // open new bin only when: many open bins already, item is big,
        // and mean residual is small (poor fits elsewhere)
        let openness = 0.5 * crowd + 50.0 * item_frac + (cap - avg_free) * 0.5 + 30.0 * progress;
        score += 120.0 - openness.min(120.0);
    }

    // Slight preference for bins with residual near capacity multiples of common sizes
    let waste_ratio = post / cap;
    score += 15.0 * waste_ratio * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear penalty growth
    let mut score = pr as f64;
    score += 30.0 * norm_post * norm_post * (1.0 + t);

    // Smooth stream-progress coupling: late stream -> tolerate larger dead space less
    score += 20.0 * norm_post * t * (1.0 - norm_item);

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 {
        let gap = norm_post - norm_next;
        if gap >= 0.0 {
            score -= 15.0 * gap * (1.0 - t);
        } else {
            score += 10.0 * (-gap) * (0.5 + 0.5 * t);
        }
    }

    // Last-chance bin bonus (only one fitting bin left)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_post);
    }

    // Penalize bins far from mean residual (encourage balanced packing) with quadratic coupling
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.5 + t);

    // Slight preference for tight fills as stream progresses
    score -= 5.0 * norm_item * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well the leftover aligns with
    // typical future item sizes (capacity fractions).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional position of post_residual within the bin capacity.
    let frac = post / cap;

    // Harmonic penalty: leftover in "dead zones" (just above half, just above
    // a third, etc.) is hard to fill. Penalize leftovers that are slightly
    // larger than a unit fraction of capacity.
    let mut dead_penalty = 0.0;
    for k in 1..=4u32 {
        let unit = cap / (k as f64);
        let slack = post - unit;
        if slack > 0.0 && slack < 15.0 {
            dead_penalty += (15.0 - slack) * (5.0 / k as f64);
        }
    }
    score += dead_penalty;

    // Reward tight fits strongly (small post_residual is ideal).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Modulo-class logic: leftovers that are exact multiples of common item
    // sizes are reusable; reward them.
    if post_residual > 0 {
        let mut best_mult = 0.0;
        for m in [10u32, 15, 20, 25, 30, 40, 50].iter() {
            if post_residual % m == 0 {
                let q = post_residual / m;
                let reward = 12.0 * (q as f64).min(3.0);
                if reward > best_mult { best_mult = reward; }
            }
        }
        score -= best_mult;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 45.0;
        } else if gap <= 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: it must be chosen only when all open fits
    // are poor. Base it slightly above a decent fit's score, with penalties
    // reduced when many bins are open or the item is large.
    if bin_residual == bin_capacity {
        score = 45.0 + frac * 20.0;
        // Large items waste less in a fresh bin; encourage opening new bins
        // for big items when open bins are scarce.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (item_size as f64 / 100.0) * 15.0;
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        score -= progress * 5.0;
        // If many bins fit the item, opening a new one is rarely worth it.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    }

    // Slight preference to fill emptier bins first (reduce bin spread).
    if bin_residual < bin_capacity {
        score += (mean_residual - post) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0) + 15.0;
    } else if post_residual > 10 && post_residual <= 20 {
        // Moderately awkward gaps also penalized, scaled by gap smallness.
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 40.0; // perfect fit: eliminate bin
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin (unless dead space would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        // Still keep dead-space penalty dominant: if post_residual is tiny-unusable,
        // the earlier penalty can outweigh this discount, allowing new-bin opening.
    }

    // New-bin candidate: neutral baseline, slightly favored when open bins are crowded
    // or when the lookahead item would benefit from a fresh full residual.
    if bin_residual == bin_capacity {
        score = 45.0 - 0.15 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= post_residual.max(1) {
            // lookahead can't fit anywhere useful; fresh bin helps future items
            score -= 6.0;
        }
        // Late in the stream, avoid opening bins for marginal gains.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        return score;
    }

    // Prefer bins whose residual is close to what we consume (minimize waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio;

    // Mild pressure to close nearly-full bins early to reduce open bin count.
    score -= 0.1 * open_bins_count as f64;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement (sets up a perfect follow-up).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size <= 10 {
        score -= 6.0;
    } else if next_item_size > post_residual {
        // next item can't use this residual: residual is dead for lookahead
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after next placement, but mildly
            score += 0.4 * slack;
        } else {
            // next item cannot follow here; penalize proportionally to wasted lookahead
            let miss = (next_item_size - post_residual) as f64;
            score += 0.8 * miss;
        }
    }

    // Relative to mean residual: bins below mean residual are more "loaded",
    // favor filling them further (best-fit-like consolidation).
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // spread preference: slight penalty to keep alternatives open
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base = 30.0 + 0.5 * (bin_capacity as f64 - post_residual as f64);
        // discourage opening new bins when decent fitting bins exist
        score += base + 10.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0; // extra penalty if lookahead also fails in a fresh bin
        }
    }

    // Late-stream consolidation: prefer compacting into fewer bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64 / (1.0 + mean_residual / 10.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Base cost of opening a new bin.
        let mut new_bin_score = bin_capacity as f64 * 0.75;

        // If other bins fit the item, opening a new bin is wasteful unless
        // the fit elsewhere would be terrible. Estimate best alternative fit
        // via mean residual as a proxy.
        if fitting_bins_count > 0 {
            // Average alternative leaves post-residual ~ mean_residual - item_size.
            let alt_post = (mean_residual - item_size as f64).max(0.0);
            // Reward opening a new bin when alternatives leave much dead space
            // relative to a fresh bin's post-residual.
            let fresh_post = (bin_capacity as u32).saturating_sub(item_size);
            if (fresh_post as f64) < alt_post {
                new_bin_score -= (alt_post - fresh_post as f64) * 0.6;
            } else {
                new_bin_score += (fresh_post as f64 - alt_post) * 0.4;
            }
        }

        // Lookahead: if next item fits in a fresh bin's post-residual,
        // a new bin is more attractive (pairs large items together).
        if next_item_size > 0 {
            let fresh_post = (bin_capacity as u32).saturating_sub(item_size);
            if next_item_size <= fresh_post {
                new_bin_score -= 8.0;
            } else {
                new_bin_score += 6.0;
            }
        }

        // Late in the stream, avoid opening bins that will stay nearly empty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += progress * 15.0;

        return new_bin_score;
    }

    // Existing bin: prefer tight fits (small post_residual).
    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: post_residual too small for typical future items
    // (items >= 10 per original spec, but be conservative for 1..100 range).
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits in post_residual, this is
    // a great chaining placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // This placement strands the bin for the known next item.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer filling bins that are already relatively full
    // (low residual relative to mean keeps large gaps consolidated).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.25;
    } else {
        score += (resid_f - mean_residual) * 0.15;
    }

    // Mild pressure to use many open bins early (consolidation),
    // less so when few bins are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tighten preference for small residuals.
    let progress_coupling = pr * (1.0 + 0.8 * progress * progress) * (1.0 - progress * 0.3);
    score += 0.5 * progress_coupling;

    // Penalize near-full bins that leave tiny unusable slivers (dead space),
    // but reward genuinely tight fits. Smooth quadratic well around small pr.
    let tiny_sliver = (pr / cap).powi(2);
    score += 12.0 * tiny_sliver * (1.0 - tiny_sliver).max(0.0);

    // Lookahead: penalize if the next item cannot fit in the post residual.
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 6.0 + 0.05 * (next_item_size as f64 - pr);
    } else if next_item_size > 0 {
        // reward leaving just enough room for the next item
        let snug = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= 4.0 * snug.max(0.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure to consolidate: bins below mean residual are less attractive.
    score += 0.15 * (mean_residual - pr).max(0.0);

    // New empty bin candidate: discourage unless residuals elsewhere are hopeless.
    if (bin_residual as f64 - cap).abs() < 1e-9 {
        score += 8.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    if post_residual == 0 {
        score -= 250.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Harmonic classes: classify post_residual by integer-division buckets.
    // Residual classes 1..=10 are "dead space" prone for future items (min size 1).
    let class = post_residual / 10; // 0..10
    let class_penalty: f64 = match class {
        0 => 30.0,  // residual 1..=9: nearly unusable dead space
        1 => 10.0,  // residual 10..=19
        2 => 4.0,
        3 => 1.0,
        4 => -2.0,  // residual 40..=49: sweet spot for mid items
        5 => -4.0,  // residual 50..=59: very reusable
        6 => -2.0,
        7 => 2.0,
        8 => 5.0,
        9 => 8.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving residual it can't use.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Penalize new-bin candidate (bin_residual == bin_capacity) unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 55.0 };
        score += 90.0 - pressure;
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Fragmentation guard: avoid leaving residual smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild bonus for bins tighter than the mean residual (consolidating fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight preference for already-opened bins over creating new ones implicitly.
    score -= 3.0 * (open_bins_count.min(10) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (item sizes >= 1, so any gap < 10 is likely wasted forever).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Zero-waste perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward filling bins deeply (large item in this bin = good consolidation).
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Lookahead (k=2): if the next item can also fit in the resulting gap,
    // this bin remains useful; reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap too small for the lookahead item: mild penalty for stranded space
        score += 8.0;
    }

    if bin_residual == bin_capacity {
        // Brand-new bin candidate: generally discourage, so we prefer
        // filling existing open bins.
        score += 25.0 + (open_bins_count as f64) * 1.5;
        // But if NO open bin can fit the item except barely (last chance),
        // opening a fresh bin is still discouraged; existing-bin logic below
        // handles the last-chance reward instead.
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing else fits: new bin is fine
        }
    } else {
        // Existing open bin: base preference to reuse.
        score -= 10.0;
        // Last chance: if this is the ONLY bin that can fit the item,
        // strongly prefer placing here over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
    }

    // Open-bins pressure: mildly prefer consolidating into bins when many
    // bins are open, to avoid bin proliferation.
    score += (open_bins_count as f64) * 0.3;

    // Prefer bins whose residual deviates favorably from the mean
    // (below-mean residual = this bin is already well filled).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in the stream, be extra thrifty: tighten tolerance for waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item fits perfectly in the leftover space.
        score -= (100.0 / (1.0 + diff)) * 1.5;
        // Slight penalty if the next item cannot fit here at all (post_residual < next).
        if post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: any residual is dead space; prefer fullest packing.
        score += 5.0;
    }

    // Penalize large dead space relative to mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage opening a new bin when reasonable fits exist:
    // new bin has residual == capacity; penalize unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Large items (>~60%) are fine in a fresh bin; small items should use existing space.
        score += (1.0 - tightness) * 60.0;
        // But if no open bin fits well (high mean residual waste), allow new bin.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
    }

    // Mild preference for tighter existing bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is already good via base score.

    // Lookahead: if the next item can fit in the post-residual, this bin
    // remains useful, so reward it; otherwise penalize stranded dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / 100.0);
        } else {
            // Dead space that the next item cannot use.
            let waste = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += 0.35 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist,
    // unless the fit into the new bin is very tight (item nearly fills it).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // A new bin is attractive only when the item is large (good fill).
        score += 18.0 * (1.0 - tightness) - 10.0 * tightness;
        // If many bins are open and residuals are large, discourage new bins more.
        score += 0.15 * (open_bins_count as f64).min(20.0);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0; // fresh bin can host the next item too
        }
    }

    // Global pressure: when mean residual is low, filling existing bins is precious.
    let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Reward tight fits: square of normalized post residual, penalizing large waste
    let prn = pr / cap;
    score += 8.0 * prn * prn * cap;

    // Stream-progress coupling: later in the stream, waste matters more
    score += 10.0 * t * prn * cap;

    // Reward using bins that otherwise would be wasted (low mean residual bins)
    let mean_gap = (mean_residual - bin_residual as f64) / cap;
    score -= 6.0 * mean_gap;

    // Last-chance bin bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: favor leaving room for the next item
    if next_item_size > 0 {
        let need = next_item_size as f64;
        let diff = pr - need;
        if diff < 0.0 {
            score += 0.5 * (-diff);
        } else {
            score -= 0.3 * diff / cap * 10.0;
        }
        // smooth polynomial interaction of leftover vs next need
        let x = (pr / cap) - (need / cap);
        score += 3.0 * x * x * cap;
    }

    // Prefer denser packing among many open bins
    score += 0.02 * open_bins_count as f64 * prn;

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class penalty: dead space in "awkward" residue classes is worse.
    // Class by post_residual mod 10: residues 1..9 (non-decade) create unusable slivers.
    let pr = post_residual as u32;
    let class = pr % 10;
    if pr > 0 {
        if class == 0 {
            score -= 6.0; // perfect decade residual: highly reusable
        } else if class >= 5 {
            score -= 2.0 * (class as f64) / 10.0; // medium slivers
        } else {
            score += (6 - class as i32) as f64; // tiny slivers 1..4 penalized
        }
    }

    // Integer-division threshold: post_residual bucketed by fifths of capacity.
    let fifth = bin_capacity / 5;
    let bucket = pr / fifth.max(1);
    score -= bucket as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // Penalize slightly when many alternatives exist to keep competition honest.
        score += (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack % 10 == 0 {
                score -= 5.0;
            } else {
                score -= 3.0 * (1.0 - slack as f64 / cap);
            }
        } else {
            score += 4.0; // post_residual too small for next item: dead-end risk
        }
    }

    // New-bin candidate handling: empty bin gets a base handicap so we only
    // open a new bin when existing fits are genuinely poor.
    if bin_residual == bin_capacity {
        score += 14.0;
        // But if current item is large relative to capacity, opening fresh is fine.
        score -= 10.0 * (item_size as f64 / cap);
        // Early in the stream, having few bins makes opening new ones cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * (1.0 - progress);
        // If mean residual across open bins is small, new bin is more attractive.
        score -= 3.0 * (1.0 - mean_residual / cap).max(0.0);
    }

    // Mild preference to spread load when many bins are open with high mean residual.
    score += 0.5 * ((mean_residual - post_residual as f64).abs() / cap);

    // Progress-aware tightening: late in stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item (or the lookahead item) are "unusable" — penalize them heavily.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64 * 3.0;
    }
    // Also penalize gaps smaller than the next item if next item is large:
    // this bin likely becomes dead after this placement anyway.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 12.0;

    // Perfect fit: extremely attractive.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has residual == capacity, so it gets a penalty
    // proportional to open_bins_count, while real bins don't).
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 2.5;
        // But if no open bin fits well, allow opening: soften when the only
        // fitting bin has terrible post-fit residual.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        // Real bins get a mild bonus for consolidation when bin count is high.
        score -= (open_bins_count as f64).sqrt() * 0.6;
    }

    // Prefer bins whose residual is close to the item (minimal waste).
    let waste_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= waste_ratio * 6.0;

    // Slight preference for bins with residuals near the item size mid-stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += residual_gap * 0.05 * (1.0 - progress * 0.5);

    // Mean-residual coupling: if this bin is far below mean residual (already
    // crowded), using it preserves large gaps elsewhere for future items.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space)
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: strongly reward when the next item fits
    // exactly or nearly exactly into the post residual of this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect chain: both items pack into this bin
        } else if gap <= 10.0 {
            score -= 40.0 - gap * 2.0;
        } else {
            // partial credit proportional to how well next item fills the bin
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize leaving residual that is
        // smaller than next_item_size (unusable dead space for lookahead).
        let waste = post_residual as f64;
        score += 10.0 * (1.0 - waste / bin_capacity as f64);
    }

    // Compare against mean residual across open bins: prefer bins with
    // below-average residual (filler bins), discourage opening from rich bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when the item is large or no good fit exists; otherwise discourage.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_fit = next_item_size == 0
            || (post_residual < next_item_size && post_residual > 0);
        if large_item > 0.5 || poor_fit {
            score -= 20.0;
        } else {
            score += 45.0; // keep using existing bins for small/chainable items
        }
    }

    // Mild late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core fit quality: reward tight fits (low post_residual) super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead (k=2): if the next item can still fit after this placement,
    // reward this bin; otherwise penalize creating a gap the next item can't use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Dead space relative to the lookahead item.
            score += 0.35 * (post_residual as f64).powf(1.2);
        }
        // Chain fit: next item leaves room for a third placement too.
        if post_residual >= next_item_size && post_residual - next_item_size >= 10 {
            score -= 5.0;
        }
    } else {
        // Last item: maximize packing density aggressively.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 15.0 + 0.5 * open_bins_count as f64;
        let poor_fit = (post_residual as f64) > 60.0 || (next_item_size > 0 && post_residual < next_item_size);
        if poor_fit {
            score -= new_bin_penalty * 0.6;
        } else {
            score += new_bin_penalty;
        }
    }

    // Global state coupling: prefer filling bins when many are open (consolidation pressure).
    score -= 0.15 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual alignment: prefer bins whose residual is close to the mean
    // (keeps residual distribution balanced) but reward below-mean residuals.
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev;
    if dev < 0.0 {
        score -= 0.05 * dev.abs();
    }

    // Time horizon: late in the stream, be greedy about closing gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small-residual trap: avoid leaving residuals in the awkward 20..40 range.
    if post_residual >= 20 && post_residual <= 40 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post residual, with non-linear (quadratic/cubic) shaping
    let mut score = post_norm * (1.0 + 2.0 * post_norm * post_norm);

    // Smooth coupling of post residual with stream progress:
    // late in the stream, waste matters more (tighter packing pressure)
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: item_size relative to residual, smooth interaction
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * fit_ratio * fit_ratio * (1.0 - post_norm);

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - post_norm);
    }

    // Penalize opening a new bin when existing bins fit well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        // new bin cost decreases with mean residual being small (open bins nearly full)
        let open_pressure = (mean_residual / cap).max(0.0);
        score += 6.0 * scarcity * (0.5 + 0.5 * (1.0 - open_pressure));
        // early stream: opening bins is cheaper; late stream: reuse strongly preferred
        score += 4.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        let gap = ((post - nxt).abs() / cap).min(1.0);
        score -= 2.5 * fits_next * (1.0 - gap * gap);
        // penalize leaving a gap just below the next item size (dead space)
        let near_miss = if post < nxt && post > 0.0 { (nxt - post) / cap } else { 0.0 };
        score += 3.0 * near_miss * near_miss * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins when residuals are large
    let spread = open_bins_count as f64 * (mean_residual / cap).max(0.0);
    score += 0.02 * spread * spread;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual left behind in other bins.
        // Penalize strongly unless this is a last-chance situation with bad fits.
        let pressure = if fitting_bins_count <= 1 { 8.0 } else { 45.0 };
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += pressure + 25.0 * progress;
        // Large items justify fresh bins a bit more.
        score -= (item_size as f64) * 0.15;
        return score;
    }

    // ---- Tight fit reward: harmonic class of post_residual ----
    // post_residual < 10 is nearly unusable dead space => excellent placement.
    if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 12.0;
    }

    // ---- Lookahead chaining: next item exactly fills the remainder ----
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect two-item closure
        } else if next_item_size <= post_residual {
            // next item still fits here: keep this bin attractive
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // remainder cannot host next item: penalize medium dead space
            if post_residual >= 10 && post_residual <= 49 {
                score += (50 - post_residual as i32) as f64 * 0.3;
            }
        }
    }

    // ---- Last-chance bonus: only this bin fits the item ----
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // ---- Harmonic modulo classes on post_residual ----
    // Residuals that are exact multiples of 10 pair well with typical sizes.
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 6.0;
    } else if cls >= 7 {
        score += 3.0; // awkward leftover class
    }

    // ---- Integer-division thresholds on post_residual ----
    let q = post_residual / 25; // 0..=4 harmonic bands
    score += match q {
        0 => -20.0,
        1 => -5.0,
        2 => 5.0,
        3 => 15.0,
        _ => 0.0,
    };

    // ---- Spread-aware nudge: prefer bins below mean residual (balancing) ----
    score += ((post_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // minimum item are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual <= 20 {
        // Small but potentially usable gaps: mild penalty to prefer
        // placements leaving larger, more reusable space.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: small relative waste is good.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_ratio) * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 18.0 + open_pressure * 10.0;
    } else {
        // Existing bin: slight reward proportional to open-bin pressure.
        score -= open_pressure * 3.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly (sets up a perfect follow-up).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            // Next item leaves dead space: mild penalty.
            score += 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Post residual unusable for the lookahead item: penalize.
            score += 8.0;
        }
    }

    // Mean-residual coupling: bins far below mean residual are under-used;
    // prefer filling bins that are already heavily loaded.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Late-stream consolidation: near the end, prefer existing bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    } else {
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 120.0;
        } else if post_residual < next_item_size {
            // Dead space relative to the lookahead item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
        // If next item cannot fit anywhere else after this placement, prefer bins
        // whose post_residual still accommodates it comfortably.
        if post_residual >= next_item_size {
            score -= 0.4 * next_item_size as f64;
        }
    }

    // Relative to mean residual: prefer filling below-average-residual (fuller) bins.
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last chance: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_penalty = if fitting_bins_count > 0 {
            // Compare against best achievable post_residual among fitting bins (approx via mean).
            (mean_residual - item_size as f64).max(0.0)
        } else {
            0.0
        };
        score = item_size as f64 + 50.0 + 100.0 * progress - 0.8 * waste_penalty;
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: squash post_residual so near-zero residuals dominate.
    score = score * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // (avoids opening a new bin when a decent fit exists).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly-ish in the post residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize dead space mildly,
            // more so when the dead space is small and unusable.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 3.0 * (1.0 - dead / bin_capacity as f64);
            }
        }
    }

    // Penalize very small post residuals that create unusable slivers (<10),
    // unless they are exactly zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // New-bin candidate handling: opening a bin is costly; penalize more when
    // many bins are already open, fitting bins exist, and late in the stream.
    if is_new_bin {
        let mut open_penalty = 12.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            open_penalty += 8.0 + 6.0 * progress;
        }
        // But if the item is large and mean residual is small, new bin is fine.
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.7 && mean_residual < item_size as f64 {
            open_penalty -= 10.0;
        }
        score += open_penalty;
    } else {
        // Existing bin: slight reward proportional to how well it uses mean state.
        if bin_residual as f64 > mean_residual {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let item_f = item_size as f64;

    // Core waste term: super-linear in post_residual (dead space is quadratic-bad)
    let mut score = post_f * (1.0 + 0.012 * post_f / cap_f);

    // Smooth coupling with stream progress: early on, tolerate slack (bins may absorb
    // future small items); late in the stream, dead space is unrecoverable.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score *= progress_weight;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = 1.0 - post_f / cap_f;
    score -= 6.0 * tightness * tightness * (item_f / cap_f);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize opening a new bin, more so as the stream progresses
    let is_new_bin = (bin_residual as f64 - cap_f).abs() < 0.5;
    if is_new_bin {
        score += 18.0 + 30.0 * progress;
    }

    // Lookahead: if the next item would fit the post-residual, reward leaving useful space
    if next_item_size > 0 && next_item_size <= post_residual {
        let useful = next_item_size as f64 / cap_f;
        score -= 4.0 + 8.0 * useful * useful;
    } else if next_item_size > 0 {
        // Penalize leaving space that the next item cannot use
        score += 2.0 * (post_f / cap_f);
    }

    // Slight preference for bins whose residual deviates from the mean residual
    // (fill down the "most wasted" bins first when fits are comparable)
    let dev = (bin_residual as f64 - mean_residual) / cap_f;
    score += 1.5 * dev * dev * (1.0 - progress);

    // Mild congestion term: many open bins -> consolidate
    score += 0.15 * open_bins_count as f64 * (post_f / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues divisible into
    // "usable" buckets get rewarded, awkward dead-space buckets penalized.
    let pr = post_residual;
    let class = pr / 10; // integer division: 0..=10 harmonic class
    score += match class {
        0 => -18.0,               // near-perfect fit, minimal waste
        1 => -10.0,
        2 => -4.0,
        3 => 0.0,
        4 => 4.0,
        5 => 8.0,
        6 => 12.0,
        7 => 15.0,
        8 => 18.0,
        9 => 21.0,
        _ => 24.0,                // near-empty bin leftover = wasted opportunity
    };

    // Lookahead coupling: if the next item exactly fits the post residual,
    // this is a golden pairing — reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after that pairing
            let pr2 = pr - next_item_size;
            score -= 8.0 + (pr2 as f64).min(15.0);
        } else {
            // next item won't fit here: penalize proportionally to how
            // "wasted" the residual is relative to the next item
            let gap = (next_item_size - pr) as f64;
            score += (gap * 0.35).min(20.0);
        }
    }

    // Modular dead-space penalty: residuals that are small-but-unusable
    // (below the minimum plausible item size band) are almost worthless.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }
    // Residuals in awkward modulo bands (e.g. 11..19) rarely pair well.
    if pr >= 11 && pr <= 19 {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when existing
    // bins are crowded or this bin is genuinely a fresh necessity.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when there are open bins that fit.
        let pressure = open_bins_count as f64;
        score += 20.0 + pressure * 3.0;
        // But if no open bin fits (fitting_bins_count == 0 among open bins
        // is reflected by this call being the only viable one), relax:
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mean-residual coupling: when the fleet of open bins is already loose
    // (high mean residual), avoid making it looser with a sloppy fit.
    let slack = (post_residual as f64) - mean_residual;
    if slack > 0.0 {
        score += slack * 0.15;
    } else {
        score += slack * 0.05;
    }

    // Mild preference for tighter fits as bins multiply.
    score += (open_bins_count as f64) * (post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let dead_threshold = 9.0; // gaps below smallest item granularity are near-waste
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Tightness ratio: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Deviation from mean residual: prefer bins that are already partially filled
    // (residual well below mean) to consolidate load.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0; // creates a gap the next item cannot use
    }

    // New-bin candidate handling: a fresh empty bin should only win when no
    // open bin offers a decent fit. Penalize it, scaling with how much
    // residual it would waste relative to the item.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0;
        let waste_penalty = (bin_capacity - item_size) as f64 * 0.25;
        let late_stream = (step_index as f64 / total_items.max(1) as f64) * 6.0;
        score += base_penalty + waste_penalty + late_stream;
        // If this bin is the only option, soften the penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits here; reward proportionally to how snugly.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the next item: penalize small unusable remnants.
        score += 10.0 + 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare post_residual against mean residual: keep residual distribution balanced.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Slight bias toward filling existing bins more as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress;

    // Penalize leaving very small dead space (unusable fragments), reward exact fills.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize small unusable residuals that no future item (min size 1..100) can exploit well.
    if post_residual > 0 && post_residual < item_size.min(60) {
        score += 12.0;
    }

    // Lookahead: perfect follow-up fit is highly desirable.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial lookahead compatibility: reward proportionally.
        let compat = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * compat;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use leftover: penalize leftover that becomes dead space.
        score += 0.35 * (post_residual as f64);
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate: make it unattractive unless current bin fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, new bins are cheap; later, avoid bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // If many bins are already open, prefer filling them.
        score += 1.5 * open_bins_count as f64;
    }

    // Global residual state: when mean residual is high, prefer bins with residual
    // close to the mean (balance), otherwise prefer bins below mean (compact them).
    if bin_residual as f64 > mean_residual {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: late in stream, prioritize exact/near-exact fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && post_residual <= 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: reward tight fits via normalized post-residual
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is penalized more aggressively (quadratic ramp)
    let progress_waste = post * post / (cap * cap) * (0.4 + 1.6 * progress * progress);
    score += progress_waste;

    // Smooth interaction: item size vs post residual — large items into small-post bins favored
    let size_coupling = (item / cap) * (cap - post) * 0.05;
    score -= size_coupling;

    // Last-chance bonus: strongly reward using the only fitting bin, ramping smoothly
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    } else {
        // mild penalty for many alternatives to encourage consolidation
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.8;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily (smooth kernel)
    if next_item_size > 0 {
        let gap = (post as u32).abs_diff(next_item_size) as f64;
        let fit_kernel = (gap / cap).powi(2);
        score -= 8.0 * (1.0 - fit_kernel.min(1.0));
    }

    // Mean-residual divergence: prefer bins near the mean (keeps flexibility), smooth quadratic
    let dev = (post - mean_residual) / cap;
    score += dev * dev * 5.0;

    // New-bin candidate handling: empty bin gets neutral-ish score that becomes
    // attractive only when all fits are poor (large post_residual elsewhere)
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.1 * progress) - (fitting_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction does it fall in?
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap_f;

    // Class boundaries: 0.0, 0.1, 0.2, 0.5 — dead-space tiers
    if post == 0 {
        // Perfect fit: strongly reward
        score -= 50.0;
    } else if frac <= 0.10 {
        // Nearly full: small dead space, reward
        score -= 10.0;
    } else if frac <= 0.20 {
        // Moderate dead space: neutral-ish
        score -= 2.0;
    } else if frac <= 0.50 {
        // Half-empty: penalize slightly
        score += 3.0;
    } else {
        // More than half empty: wasteful for small items
        score += 8.0;
    }

    // Integer-division harmonic class on post_residual (mod 10 buckets)
    let class = post_residual / 10;
    match class {
        0 => score -= 6.0,            // 0-9 residual: excellent
        1 => score -= 3.0,            // 10-19: good
        2 => score -= 1.0,            // 20-29: ok
        3 | 4 => score += 1.5,        // 30-49: mediocre
        _ => score += 4.0,            // 50+: large residual left
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer leaving slack in a good harmonic class (small)
            score += slack * 0.15;
            if slack <= 10.0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; if this bin is the last fitting bin, penalize refusal risk
            if fitting_bins_count == 1 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin bonus: only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity)
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early when many items remain, bad late
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = post_residual as f64 + 15.0 + 20.0 * (1.0 - progress);
        // But if existing fit would leave huge dead space, allow new bin
        if post_residual == bin_capacity {
            // neutral baseline for genuine new bin
            score = cap_f - item_size as f64 + 10.0;
        }
    }

    // Mean residual context: if this bin's residual is far below mean, it's tighter — reward using it
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (bin_res_f - mean_residual) / mean_residual;
        score += dev * 4.0;
    }

    // Slight preference to fill bins with more open bins around (consolidation)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize leaving a gap that the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += 0.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a baseline cost that scales with
    // stream progression; late in the stream, opening bins is more costly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 + 25.0 + 30.0 * progress;
        // Allow new bin only if no existing bin fits well.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item fills this bin exactly afterwards.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score += diff * 0.6;
        }
        // Bonus if next item can still fit after this placement (keeps bin useful).
        if post_residual >= next_item_size {
            score -= 5.0;
        }
        // Penalize leaving dead space that next item cannot use.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.4;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 10.0;
    }

    // Reward tight fits relative to mean residual of open bins.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= tightness * 8.0;

    // Penalize bins whose residual deviates far above mean (hoarding space).
    if post_residual as f64 > mean_residual * 1.5 {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists or stream is early.
    if is_new_bin {
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual > 0 && post_residual < 20);
        if poor_fit {
            score -= 12.0 + 10.0 * (1.0 - progress);
        } else {
            score += 30.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Mild preference for consolidating into fewer bins over time.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Exact-fill bonus: zero post residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item
    // are wasted; penalize them proportionally.
    let waste = (post_residual as f64) / (bin_capacity as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - waste);
    }

    // Last-chance boost: if this is the only bin that fits, prefer it over
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 40.0;
        // If no open bin fits, opening is unavoidable: remove penalty.
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
        // Lookahead: if next item is large and would waste this bin's space,
        // opening a fresh bin now is more attractive.
        if next_item_size > 0 {
            let next_fit_here = (next_item_size as f64) <= post_residual as f64;
            if !next_fit_here {
                score -= 15.0;
            } else if (post_residual as f64) - (next_item_size as f64) < 10.0 {
                score += 10.0; // next item would nearly fill new bin too, prefer existing bins
            }
        }
        // Late in the stream, discourage extra bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead synergy: if next item exactly fills this bin's post residual,
    // big reward for choosing this bin now.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && (next_item_size as u32) < post_residual {
        // Partial credit when next item still fits after this placement.
        score -= 8.0;
    }

    // Fragmentation guard: penalize bins far below mean residual (likely
    // scattered leftovers), unless this placement fixes it.
    let dev = (bin_residual as f64) - mean_residual;
    if dev < 0.0 {
        score -= 0.15 * dev; // below-mean bins: reward (consolidate small bins)
    } else {
        score += 0.05 * dev;
    }

    // Mild penalty scaling with number of open bins to encourage reuse
    // rather than proliferation of many partially filled bins.
    if bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let p2 = progress * progress;
    score += norm_pr * norm_pr * (20.0 + 60.0 * progress) - norm_pr * (10.0 * p2);

    // Penalize large dead space late in the stream (smooth cubic ramp).
    score += (pr * pr * pr) / (cap * cap) * (0.5 + 1.5 * progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 80.0 * progress;
    }

    // New-bin candidate: only attractive when existing bins are tight.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_tightness = (cap - mean_residual) / cap;
        score += 15.0 + 45.0 * avg_tightness * (1.0 - progress);
        // If the next item fits into the post-residual, discourage opening new bin.
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score += 25.0;
        }
    } else if next_item_size > 0 {
        // Reward bins whose leftover can host the lookahead item (smooth coupling).
        let fits_next = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        let tightness = 1.0 - pr / cap;
        score -= fits_next * 12.0 * tightness * (0.5 + progress);
        // Penalize near-perfect fill that strands the lookahead item.
        let stranded = if fits_next < 0.5 && pr > 0.0 { 1.0 } else { 0.0 };
        score += stranded * (pr / cap) * 18.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins early on.
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: strongly discourage unless nothing else fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Forced opening: make it the clear winner.
            return -1000.0;
        }
        // Otherwise new bins are expensive; only attractive for huge items
        // that would leave a terrible fit elsewhere.
        let base = 3000.0
            - (item_size as f64 - 50.0).max(0.0) * 2.0
            - fitting_bins_count as f64 * 500.0;
        return base;
    }

    // Perfect fill: best possible outcome.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty: tiny unusable leftovers (harmonic class 1..=10).
    if post_residual <= 10 {
        score += 60.0;
    }

    // Harmonic class logic on post_residual modulo 20:
    // leftovers that are multiples of 20 (and especially 0 mod 20) are more
    // reusable by typical item sizes drawn from a coarse-grained stream.
    let class = (post_residual % 20) as f64;
    score += class * 0.75;

    // Extra reward for the "harmonic" residuals 20/40/60/80.
    if post_residual % 20 == 0 {
        score -= 8.0;
    }
    // Mid-range quarter classes (10, 30, 50, 70, 90) are second-best.
    if post_residual % 20 == 10 {
        score -= 3.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact pairing is gold.
            if next_item_size == post_residual {
                score -= 200.0;
            } else {
                score -= 15.0;
            }
        } else {
            // Next item can't use this bin's leftover: mild penalty.
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer tighter ones — base term already does,
        // but dampen over-penalization of dead space.
        score -= 2.0 * (fitting_bins_count.min(5) as f64);
    }

    // Late in the stream, closing bins out cleanly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64).max(0.0) * 0.05;

    // Slight tilt toward bins below the mean residual (consolidation).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            // Gap too small for any item (min size 1..100, but tiny gaps are waste)
            score += (10.0 - pr) * 3.0;
        } else if pr < 20.0 {
            // Small gap: likely unusable dead space
            score += (20.0 - pr) * 1.5;
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Open bins pressure: discourage spreading when many bins are already open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 2.0);
    score += pressure * 0.4;

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 - slack * 0.15;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter fill)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make empty bin moderately attractive only when
    // existing fits are poor (large post_residual elsewhere) or none fit well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 45.0;
        // If only this new bin can fit, it must be chosen
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Late in stream with few bins, opening fresh is cheap
        if progress > 0.8 && open_bins_count < 4 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: bin closes exactly after next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 60.0;
        } else {
            score += gap as f64 * 0.5;
        }
        // Reward if next item fits with small slack relative to mean residual.
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if (slack as f64) < mean_residual * 0.5 {
                score -= 15.0;
            }
        } else {
            // Next item cannot follow here: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 5.0;
    }

    // Penalize dead space that is too small to be useful (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Slight penalty for very empty bins unless it's a new-bin candidate decision.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // New-bin candidate: make it moderately attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        if crowded < 0.15 {
            score -= 12.0;
        } else {
            score += 15.0 + crowded * 20.0;
        }
    }

    // Early stream: prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that leave small post-residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Perfect fill gets a huge bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item can fit into the post-residual,
    // this bin is even more valuable; otherwise penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 0.2 * item_size as f64;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tight;

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 2 {
        score -= 0.15 * (open_bins_count.min(50) as f64) * tight;
    }

    // Mean residual context: if this bin's residual is far below the mean,
    // it is the "smallest hole" — good Best-Fit behavior.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.1 * (mean_residual - residual_f).min(50.0);
    } else {
        score += 0.05 * (residual_f - mean_residual).min(50.0);
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large relative to capacity or no bin fits well. Make the
    // empty-bin baseline moderately high so tight fits in open bins win,
    // but low enough when the item is big.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64) / (bin_capacity as f64);
        score += 18.0 - 20.0 * big_item;
        // If no existing bin could fit at all, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late in the stream, prefer reusing open bins.
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_fit = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    // Base: reward tight fits (small post_residual) with smooth quadratic shaping
    let mut score = pr * (1.0 + 0.9 * fit_ratio * fit_ratio);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, tight packing matters more
    score -= 12.0 * (1.0 - pr / cap) * progress * (1.0 - progress * 0.5);

    // Penalize post_residual that neither fits next item nor is small (dead space)
    let waste = if next_item_size > 0 {
        let gap = pr - next_fit * cap;
        if gap > 0.0 { gap } else { 0.0 }
    } else { 0.0 };
    score += 0.35 * waste * waste / cap;

    // Reward bins whose residual pairs well with the next item (smooth kernel)
    if next_item_size > 0 && pr >= next_fit * cap {
        let closeness = 1.0 - (pr - next_fit * cap) / cap;
        score -= 8.0 * closeness * closeness;
    }

    // Last-chance bonus: smooth in fitting_bins_count
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.3);
    }

    // Mild penalty when many bins are open and this one is near-empty
    let emptiness = 1.0 - bin_residual as f64 / cap;
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * emptiness * emptiness;

    // New-bin candidate adjustment: prefer opening a new bin early or for large items
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * (1.0 - fit_ratio) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quarter-capacity classes.
    // Class 0: post_residual == 0 (perfect fill) -> strong reward.
    // Class 1: 1..=25 (dead space, likely unusable) -> penalty.
    // Class 2: 26..=50 (medium) -> mild penalty unless next item fits.
    // Class 3: 51..=75 (usable) -> mild reward.
    // Class 4: >75 (nearly full) -> neutral-ish.
    let pr = post_residual as f64;
    let class = if post_residual == 0 { 0 }
        else if post_residual <= bin_capacity / 4 { 1 }
        else if post_residual <= bin_capacity / 2 { 2 }
        else if post_residual <= (3 * bin_capacity) / 4 { 3 }
        else { 4 };

    match class {
        0 => score -= 40.0,
        1 => {
            // Dead space penalty scaled by how "wasted" the bin is.
            let waste = pr / cap;
            score += 12.0 * waste;
            // If the next item exactly fills this dead space, reward instead.
            if next_item_size > 0 && next_item_size == post_residual {
                score -= 30.0;
            }
        }
        2 => {
            score += 4.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 10.0;
            }
        }
        3 => {
            score -= 3.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 8.0;
            }
        }
        _ => {}
    }

    // Integer-division threshold: exact half-fill bonus (classic harmonic class).
    if post_residual == bin_capacity / 2 {
        score -= 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible dead space).
    if fitting_bins_count == 1 && class != 1 {
        score -= 15.0;
    } else if fitting_bins_count == 1 && class == 1 {
        score -= 5.0;
    }

    // New empty bin candidate: post_residual == bin_capacity.
    // Should only win when all alternatives are bad: keep its score high
    // but slightly below a class-1 dead-space fit.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + (open_bins_count as f64) * 0.5;
        // Late in the stream, opening new bins is cheaper (fewer future regrets).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Slight preference for tighter (fuller) bins overall.
    score += 0.02 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the enemy.
    // A residual that is too small to hold even the smallest plausible item (1)
    // is perfect (0). Residuals in the "awkward" band (1..=10) are already tight;
    // the truly wasteful zone is mid-range leftovers that nothing will ever fill.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    } else if post_residual <= 5 {
        // Nearly perfect: still very good.
        score -= 40.0 - pr * 2.0;
    } else {
        // Dead-space penalty grows super-linearly for mid-range gaps,
        // but saturates for large residuals that remain useful.
        let dead = if pr <= 30.0 {
            (30.0 - pr) * (30.0 - pr) * 0.12
        } else {
            0.0
        };
        score += dead;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins dilute future placement choices;
    // discourage spreading across too many bins, encouraging consolidation.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling: if average residual across open bins is already
    // small, avoid wasting this bin's larger residual on a poor fit.
    if mean_residual < 20.0 && post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward
    // for reserving this bin's leftover for it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits here: mild reward, keeps options open.
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into existing bins would create bad dead space. Give it a moderate
    // baseline so it loses to good fits but beats terrible ones.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual small).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this bin is a perfect pairing target.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a large awkward gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // Last item: strongly prefer minimal post residual.
        score -= 15.0;
    }

    // Compare post residual to mean residual across open bins:
    // leaving less than average is good (tight packing), more is wasteful.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin expensive unless the item
    // is large relative to residual (poor fit in existing bins).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin.
        score += 55.0;
        // If the item leaves a big residual that the next item can't use,
        // opening a new bin is even less attractive.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 10.0;
        }
        // Late in the stream, avoid opening bins with big leftover space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty for accumulating many open bins with scattered residuals.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of post residual.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64) * 12.0;

    // Penalize dead space that cannot fit even the smallest plausible future item.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powi(3);
        score += dead * 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        } else {
            // Next item still fits: mild reward scaled by remaining slack.
            score -= (post_residual - next_item_size) as f64 * 0.05;
        }
    }

    // Last-chance bonus: this is the only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0;
        // Attractive if this bin would leave very tight fit (item nearly fills bin).
        if item_size >= bin_capacity * 9 / 10 {
            score -= 18.0;
        }
        // Less attractive when many open bins already have slack.
        score += mean_residual * 0.08;
        // Early in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 6.0;
        // If no other bin fits, opening is necessary (fitting_bins_count==1 includes this bin only).
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Mild preference for fuller bins among open candidates (best-fit reinforcement).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Discourage scattering across too many bins when mean residual is high.
    if open_bins_count > 4 && mean_residual > item_size as f64 * 2.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let fit_norm = pr / cap;

    // Core: quadratic penalty on leftover space (tight fits win).
    let mut score = pr * pr / cap;

    // Smooth stream-progress coupling: early on tolerate slack, late prefer tight packing.
    score *= 0.7 + 0.6 * progress * progress;

    // Non-linear interaction: leftover space matters more when mean residual is high (many loose bins).
    score += fit_norm * fit_norm * mean_residual * (0.5 + progress);

    // Lookahead coupling: reward leaving space that fits the next item, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - gap * gap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across too many open bins relative to stream length.
    score += (open_bins_count as f64).sqrt() * 0.4 * (1.0 - progress);

    // New-bin candidate: empty-bin call gets post_residual = capacity; the quadratic core
    // already penalizes it, add a smooth extra reservation cost that decays with progress.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + fit_norm * cap * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose leftover lands in "useful" residue
    // classes (multiples of 10, or >= 50 for future large items) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure
    } else if pr % 10 == 0 {
        score -= 12.0; // aligned residual is reusable by typical items
    } else if pr >= 50 {
        score -= 6.0; // large residual still flexible
    } else if pr < 10 {
        score -= 8.0; // tiny dead space, effectively closed
    } else {
        // awkward mid-range dead space: penalize proportionally to its awkwardness
        score += (10 - (pr % 10)) as f64 * 0.8;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = post - n;
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item won't fit here; residual becomes dead for the lookahead
            score += 4.0 + (n - post) / cap * 6.0;
        }
    }

    // Last-chance bin: strongly prefer filling it rather than wasting it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless current
    // fit is bad or many open bins already cluster high residuals.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= post_residual.min(bin_residual) {
            // item barely fits anywhere; new bin keeps flexibility
            score -= 20.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0; // existing bins nearly full; new bin reasonable
        }
        // early in stream, keep bins open to consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Fraction-of-capacity coupling: reward placing items into bins where
    // item_size / capacity matches the fill fraction class (integer division).
    let fill_class = (bin_capacity - bin_residual) / 25;
    let item_class = item_size / 25;
    if fill_class == item_class {
        score -= 5.0;
    }

    // Mild pressure to prefer bins with lower residual among ties.
    score += (bin_residual as f64) * 0.05;
    // Slight preference for bins below mean residual (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Strict dead-space avoidance: residuals too small to hold anything useful are toxic.
    // Penalize gaps that cannot fit even the smallest plausible follow-up item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // If the lookahead item cannot fit in the resulting gap, this placement strands space.
    if next_item_size > 0 && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        score += 1.5 * stranded;
        // Extra penalty if the gap is dead anyway.
        if post_residual < 10 {
            score += 25.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leaving room for the next item is valuable.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, consolidate; with few, spreading is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    score += 0.15 * pressure * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base cost of opening a bin, waived when forced or late with large items.
        score = 70.0 - 80.0 * desperation - 10.0 * (item_size as f64 / 100.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= (100.0 - diff as f64).max(0.0) * 0.9;
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving dead space too small for the next item
        if post_residual < next_item_size && post_residual > 0 {
            let smallest_possible = 1u32;
            if post_residual < smallest_possible.max(next_item_size.min(10)) {
                score += 25.0;
            }
        }
    } else {
        // Last item: prefer tightest fit, no lookahead
        score -= 10.0;
    }

    // Penalize residuals below the minimum plausible item size (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: prefer bins that end up closer to the mean
    // (keeps residual distribution balanced), scaled mildly.
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += mean_dev * 0.15;

    // New-bin candidate: only attractive when current bin fit is very poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win; relax if many items remain
        // and residual after placing in this new bin equals next item size.
        let mut new_bin_score = bin_capacity as f64 * 0.5;
        if next_item_size > 0 && post_residual == next_item_size {
            new_bin_score -= 70.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 200.0;
        }
        // Late in the stream, discourage new bins slightly more
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += progress * 20.0;
        score = score.min(new_bin_score.max(score));
        // For the new-bin call itself, override with its own evaluation:
        return new_bin_score;
    }

    // Reward tight fits overall (small post_residual)
    score -= (bin_capacity - post_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize creating small unusable dead space (< min item size 1..=10 threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap < 10 {
            score -= 15.0;
        } else {
            score -= 5.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }
    // Penalize if next item cannot use the leftover space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer filling the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // More open bins => mild pressure to consolidate into existing bins.
    score += 0.15 * open_bins_count as f64;

    // Global residual pressure: if mean residual is low, avoid wasting large-residual bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual.max(1.0);
        score += 6.0 * (rel - 1.0).abs();
    }

    // Time horizon: early in stream, be more exploratory (favor new bins for large items);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score -= 3.0; // exploratory phase: slightly favor any placement / new bins
    } else {
        score += 10.0 * progress; // late phase: penalize everything, tighten selection
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_cost = 45.0;
        // Cheaper to open a new bin early in the stream.
        new_bin_cost *= 1.0 - 0.4 * progress;
        // Expensive if many bins already open (consolidation pressure).
        new_bin_cost += 1.2 * open_bins_count as f64;
        // If this is the only fitting option (item fits new bin trivially), reduce cost.
        if fitting_bins_count == 0 {
            new_bin_cost -= 30.0;
        }
        // If next item is large, a fresh bin may serve it well.
        if next_item_size > 0 && next_item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_cost -= 10.0;
        }
        score = new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (low post_residual), with a convex polynomial
    // so small residuals are strongly preferred over moderate ones.
    let mut score = post * (1.0 + 0.9 * (post / cap) * (post / cap));

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, leave room for future items (mild penalty on tight fits);
    // late, pack tightly (amplify post_residual penalty).
    let progress_coupling = 0.5 + progress;
    score += 2.0 * progress_coupling * (post / cap).powi(3) * cap;

    // Penalize bins far from the mean residual (encourages residual homogeneity),
    // weighted smoothly by post_residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev * (1.0 + post / cap);

    // Last-chance bin (only fitting bin): reward using it, smoothly scaled
    // by how well it fits.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post / cap);
    }

    // Lookahead: if next item could fill this bin's post-residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 8.0 * (1.0 - (post - nx) / cap);
        } else {
            // post_residual too small for next item: mild penalty (dead space risk)
            score += 6.0 * (1.0 - post / nx.min(cap));
        }
    }

    // New-bin candidate (empty bin): penalize so it is only chosen when all
    // open bins fit badly. Penalty shrinks when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64).ln1p();
        score += 30.0 + 20.0 / (1.0 + congestion);
    } else {
        // Reward using already-open bins slightly, more when many are open.
        score -= 3.0 * (open_bins_count as f64).ln1p() * (1.0 - post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (0..=10, and the 11..=20 band) are either
    // perfect closures or near-closures -> reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 40 {
        score -= 5.0;
    } else {
        // Large leftover is wasteful unless it matches the next item.
        score += 10.0 * frac;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin; if next item cannot fit, the leftover is dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 35.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item can't use this leftover -> penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when the current item is large
    // relative to capacity (a fresh bin wastes little) or no bin fits well.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / cap) > 0.6;
        let poor_fit_everywhere = fitting_bins_count == 0
            || (post_residual > 30 && next_item_size > post_residual);
        if large_item || poor_fit_everywhere {
            score -= 55.0;
        } else {
            // Prefer reusing an existing bin for small/medium items.
            score += 40.0;
        }
    }

    // Mean-residual coupling: when open bins are already loose on average,
    // reusing them is cheap; tighten preference toward tightest bin.
    score += 0.15 * (mean_residual - post).max(0.0);

    // Harmonic class of item size via integer division thresholds:
    // items in [1..25] are "fillers" -> prefer stuffing them into tight leftovers.
    let item_class = item_size / 25; // 0,1,2,3
    match item_class {
        0 => score -= 8.0,
        1 => score -= 2.0,
        2 => score += 2.0,
        _ => score += 6.0,
    }

    // Modulo-10 harmonic band on post_residual: residues near multiples of 10
    // pair well with typical item granularities.
    let band = post_residual % 10;
    if band == 0 {
        score -= 12.0;
    } else if band >= 8 {
        score -= 6.0;
    } else if band <= 2 {
        score -= 4.0;
    }

    // Mild stream-progress term: late in the stream, be greedier about closures.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 20.0 * progress * (1.0 - frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual in awkward range)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Dead space that cannot fit the lookahead item is worse
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure from many open bins: favor filling existing bins
    score += (open_bins_count as f64) * 2.0;

    // Mean residual coupling: prefer bins below mean residual (tighter packing)
    score += (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: make it unattractive unless open bins are crowded
    if bin_residual == bin_capacity {
        score += 50.0 + (open_bins_count as f64) * 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward an exact or near match
    // between post_residual and the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // exact match: big reward
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // near-match reward decaying with gap
            score -= 40.0 / (1.0 + gap / 10.0);
            // penalize overshooting next item (dead space it can't use)
            if (post_residual as i64) < (next_item_size as i64) {
                score += (next_item_size as f64 - post_residual as f64) * 0.5;
            }
        }
        // chain feasibility: if next item also fits here after this, encourage tight packing
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // last item: just prefer tightest fit
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill.
    let rel = mean_residual - bin_residual as f64;
    score += rel * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item, avoid
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating small unusable dead space (fragmentation guard),
    // unless it matches the next item (already rewarded above).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild penalty on opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
        // but a new bin is fine if the item is huge relative to capacity
        if item_size * 4 >= bin_capacity * 3 {
            score -= 20.0;
        }
    }

    // Progress-based nudge: late in the stream, prefer tighter fits more strongly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: prefer small post residual (tight fit), scaled non-linearly.
    let mut score = post * (1.0 + 0.5 * progress);

    // Non-linear penalty for large dead space: quadratic in normalized post residual.
    let post_norm = post / cap;
    score += 40.0 * post_norm * post_norm;

    // Reward tight fits: fraction of bin filled by this item, smooth coupling.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 - progress * 0.3);

    // Exact or near-exact fit reward (smooth exponential).
    if post <= 5 {
        score -= 20.0 * (1.0 - post as f64 / 6.0);
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize creating small unusable residual.
        score += 8.0 * (1.0 - post / cap) * (1.0 - progress);
    }

    // Coupling with mean residual: avoid placing into bins far from the mean
    // when mean residual is small (bins are nearly full overall).
    let dev = (residual - mean_residual).abs() / cap;
    score += 10.0 * dev * (1.0 - mean_residual / cap);

    // New-bin candidate: empty bin (residual == capacity). Penalize mildly so it
    // wins only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to ever host a realistic item are poison.
    let min_item = 1u32;
    let dead_threshold = if next_item_size > min_item { next_item_size } else { min_item };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect fit: strongly reward zero post residual.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Tightness reward: the closer the fill, the better (non-linear coupling).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill * fill;

    // Penalize leaving large-but-awkward gaps: post residual in (0, 10) is near-dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 55.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins;
    // when few bins are open, mild encouragement of consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost so it only wins when open bins are unattractive.
        score += 20.0 + new_bin_bonus;
        // But if the next item exactly fills the remainder after this placement, new bin is great.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 80.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean (tighter bins),
    // penalize dumping into the loosest bin.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 8.0;
    } else if bin_res_f > mean_residual * 1.5 {
        score += 6.0;
    }

    // Late in the stream, close out bins aggressively: reward near-full placements more.
    if progress > 0.8 && post_residual <= 15 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a convex penalty on dead space.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // 2-step lookahead: strongly reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        // Perfect chain fit: big reward.
        if diff < 0.5 {
            score -= 30.0;
        } else {
            score += 0.9 * diff;
        }
        // Bonus if next item also fits perfectly leaving near-zero residual (3-step chain).
        if pr >= nxt && (pr - nxt) < 10.0 {
            score -= 8.0;
        }
        // Penalize placements that leave residual just below next item size (unusable for lookahead).
        if pr < nxt && pr > 0.0 {
            score += 6.0 * (1.0 - pr / nxt);
        }
    } else {
        // Last item: minimize residual as much as possible.
        score -= 5.0;
    }

    // Reward filling bins that are relatively full compared to the fleet mean.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: make a fresh bin moderately expensive so we prefer
    // good fits into open bins, but cheap enough when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If many open bins exist, opening yet another is costlier.
        score += 1.5 * open_bins_count as f64;
        // If the next item is large, an empty bin is valuable for future flexibility.
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Mild preference to consolidate into few bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post residual).
    let mut score = post;

    // Reward near-perfect fits strongly.
    if post <= 5.0 {
        score -= 30.0;
    } else if post <= 15.0 {
        score -= 12.0;
    }

    // Penalize creating dead space that nothing can use (min item 1, but
    // typical items are larger; dead space below a useful threshold is waste).
    let waste_threshold = 10.0_f64.min(res);
    if post < waste_threshold && post > 0.0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() <= 2.0 {
            score -= 15.0;
        } else if nxt <= post {
            score -= 6.0;
        } else if post > 0.0 && nxt > post {
            // next item won't fit here; leaving moderate post residual is ok,
            // but tiny post residual is bad.
            if post < 10.0 {
                score += 10.0;
            }
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins flexible); later, pack tightly into existing bins.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized generally, but less so early on
        // or when many items won't fit well elsewhere.
        let mut new_bin_score = cap * 0.5 + 40.0; // high base penalty
        new_bin_score -= progress * 60.0;          // cheaper to open early
        new_bin_score += (open_bins_count as f64) * 2.0; // spread cost
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // must open
        }
        // If next item is large and this item is small, opening fresh is fine.
        if next_item_size >= 60 && item <= 30 {
            new_bin_score -= 10.0;
        }
        return new_bin_score;
    }

    // Existing-bin adjustments: prefer fuller bins (lower residual before placement).
    score += (cap - res) * 0.05;

    // Prefer bins with residual close to item size (good fit ratio).
    let fit_ratio = item / res.max(1.0);
    score += (1.0 - fit_ratio) * 5.0;

    // Global state: if mean residual across open bins is high, we have slack
    // everywhere -> pack tighter, penalize loose fits mildly.
    if mean_residual > cap * 0.5 {
        score += (mean_residual - cap * 0.5) * 0.1;
    }

    // Late stream: stronger tight-packing pressure.
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (small post_residual) mildly; later, penalize
    // wasted residual quadratically to force consolidation into few bins.
    let poly = pr * pr / (cap * cap);
    score += poly * (0.5 + 2.5 * progress * progress);

    // Cubic interaction: large residuals become progressively more costly as stream advances.
    score += (pr / cap).powi(3) * 10.0 * progress;

    // Reward near-perfect fills smoothly (post_residual close to zero).
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * item_size as f64 * 0.15;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Smooth penalty when this bin's residual deviates from the mean residual,
    // encouraging homogenization of open-bin spaces.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Lookahead coupling: reward leaving a residual that still fits the next item,
    // penalize residual that is just barely too small (dead space).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 4.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 6.0 * (1.0 - pr / n);
        }
    }

    // Mild penalty for proliferating open bins when progress is high.
    score += (open_bins_count as f64).ln() * (1.0 + 4.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes via integer division thresholds.
    // Residuals in 0..=9 are nearly unusable (item sizes >= 1 but typically >= 10).
    let pr = post_residual;
    let dead_penalty = if pr == 0 {
        -30.0 // perfect fit: strongly favored
    } else if pr <= 9 {
        25.0 // tiny dead space: worst outcome short of waste
    } else if pr <= 19 {
        10.0
    } else if pr <= 29 {
        4.0
    } else if pr <= 49 {
        0.0
    } else {
        -2.0 // large residual may still host future items
    };
    score += dead_penalty;

    // Modular class: residuals that are multiples of common size classes are reusable.
    let reusable = (pr % 10 == 0 && pr > 0) || (pr % 20 == 0 && pr > 0);
    if reusable { score -= 5.0; }

    // Lookahead coupling: if next item fits into post_residual exactly or well, reward.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - pr as f64).abs() < 1.0 {
            score -= 18.0; // next item exactly fills this bin
        } else if next_item_size <= pr {
            score -= 8.0 * (1.0 - (pr as f64 - ni) / cap);
        } else {
            // next item cannot use the residual -> penalize wasted space proportionally
            score += 6.0 * (1.0 - pr as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / cap; // for new bin: 1 - item/cap
        score += 60.0 - 55.0 * (1.0 - fit_quality);
        // open a new bin early when many bins are open and mean residual is high (dispersion)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 3 && mean_residual > 0.5 * cap && progress < 0.8 {
            score -= 20.0;
        }
    } else {
        // Prefer tighter bins: reward small bin_residual relative to item
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * tightness;
        // mild preference to keep number of open bins low
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * 0.35;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: strongly favor using the only bin that fits, avoiding
    // a new bin for this item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, allow opening a new bin for good fits.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += pressure;

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement; if post residual is just barely too small
    // for the next item, mildly penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Mean-residual coupling: prefer bins with residual below the mean
    // (consolidate space) when mean is high.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: an empty bin should only win when the item is
    // large relative to capacity or no good fit exists. Penalize opening
    // a new bin mildly, but not when the item is huge.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        if large_item > 0.8 {
            score -= 30.0; // big item: fresh bin is fine
        } else if large_item > 0.5 {
            score -= 5.0;
        } else {
            score += 22.0; // small item: strongly prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of post_residual with next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - match_quality / bin_capacity as f64).max(0.0);
    }

    // Penalize small dead space that nothing can use (min item ~1, typical >10)
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Compare against mean residual: prefer bins with below-average residual (tighter bins)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early stream: be conservative, prefer filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can still be placed here: reward proportional to how well it fills.
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: slight penalty for leaving a stranded gap.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer bins where the item fits most snugly (already handled),
        // mild penalty to diversify selection.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base preference for reusing open bins.
        score += 30.0;
        // But if this bin is the only fitting option, opening new is fine.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 0.3 * mean_residual;
        // Large items justify fresh bins more than small ones.
        score -= 0.1 * item_size as f64;
    }

    // Favor filling bins with small residuals fully rather than fragmenting large-residual bins.
    if bin_residual < 2 * item_size {
        score -= 3.0;
    }

    // Mild preference for bins with below-average residual (fill the emptiest-tightest first).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Normalized post-residual and item size
    let r = post / cap;
    let s = item / cap;

    // Base: quadratic coupling between post-residual and item size.
    // Large leftover (r) is good only if item was large; small item leaving
    // big residual is fine too, but tiny residual is dead space -> penalize.
    let mut score = r * (1.0 - r) * 4.0; // 0 at r=0 (perfect fit), peak at r=0.5
    score = score * (1.0 - 0.5 * s);     // large items deserve tighter fits

    // Penalize very small unusable residuals with a smooth non-linear term
    score += (r - 0.12).abs().powf(1.5) * 6.0;

    // Interaction with stream progress: late in stream, prefer tighter packing
    score += r * r * (1.0 + 2.0 * progress) * 2.0;

    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 1.5 * (1.0 - (post - nxt) / cap);
        } else {
            score += 0.8 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // New-bin candidate: opening a new bin should only win when the fit
    // into existing bins would be terrible. Penalize the empty bin smoothly.
    if bin_residual == bin_capacity {
        score += 2.5 + 3.0 * (1.0 - progress) - 1.0 * s;
    }

    // Mild bonus for bins below mean residual (balance load)
    score -= 0.3 * ((post - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the gap left behind ---
    // Class the post_residual into residue classes mod 10 (capacity fractions).
    let gap_class = (post_residual % 10) as f64;
    // Gaps that are "harmonically clean" (multiples of 10) are reusable by
    // typical item sizes; ragged gaps are dead space -> penalize.
    if post_residual == 0 {
        score -= 30.0; // perfect fit, ideal
    } else if post_residual % 10 == 0 {
        score -= 8.0; // clean gap, likely reusable
    } else {
        // ragged gap: penalize proportional to how far from a multiple of 10
        score += gap_class * 0.6;
    }

    // Integer-division threshold classes on post_residual:
    // tiny gaps (<10) are almost surely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // mid gaps (10..=20) are moderately useful
    if post_residual >= 10 && post_residual <= 20 {
        score -= 3.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here too: strong reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + slack * 0.15;
            // exact two-item harmony (post_residual == next_item_size)
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            // next item won't fit after this placement: mild penalty,
            // worse if the leftover gap is small (dead space)
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.05;
        }
        // modulo coupling: next item in same residue class as gap
        if next_item_size % 10 == post_residual % 10 && post_residual > 0 {
            score -= 4.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // this is the only bin that fits; avoid opening a new bin
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin; allow it only when it looks
        // genuinely better than squeezing into a poor fit.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 55.0 + progress * 10.0;
        // If existing bins would leave tiny dead gaps, opening a bin is good.
        if post_residual > 0 && post_residual < 15 && item_size >= 10 {
            new_bin_score -= 25.0;
        }
        // Large items (>= 70) almost fill a fresh bin: favorable.
        if item_size >= 70 {
            new_bin_score -= 15.0;
        }
        // Many open bins with high mean residual: prefer reusing them.
        new_bin_score += (open_bins_count as f64).ln1p() * 5.0
            + (mean_residual / bin_capacity as f64) * 20.0;
        // Harmonic bonus: fresh bin keeps a clean multiple-of-10 gap class
        new_bin_score -= 5.0;
        return new_bin_score;
    }

    // --- General fit tightness reward ---
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Slight preference to fill bins with lower residual first (best-fit core)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (1..=10) are unusable -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Penalize leaving residual that cannot fit the lookahead item while
    // the current bin could have been avoided.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward residual that still accommodates the next item (keeps bin useful).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: discourage spreading across many bins when a new
    // empty bin candidate exists (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // New bin baseline: attractive only if few open bins or item is large.
        score = 55.0 - 3.0 * (open_bins_count as f64).ln().max(0.0) - fill_ratio * 20.0;
        if fitting_bins_count == 1 {
            // An open bin fits and is the only option -> new bin should lose.
            score += 30.0;
        }
    } else {
        // Mild preference for filling bins that are already well utilized.
        let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * used_frac;
    }

    // Progress-aware: late in the stream, avoid opening new bins even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead coupling: penalize dead space that next item can't use, reward if it can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.35 * (post_residual as f64 - next_item_size as f64).min(30.0);
        } else {
            score += 0.9 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    } else {
        // Last item: pure tightness reward.
        score -= 0.5;
    }

    // Small unusable dead space (below min item size 1 handled generically): penalize
    // residuals that are tiny relative to capacity (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Tight fit reward relative to bin: small post_residual overall.
    score -= 0.25 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Context: late in stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress;

    // Compare against mean residual: bins with residual far below mean are already
    // "wasted"; prefer placing into bins with residual near/above mean.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference for filling fuller bins (relative fill ratio).
    score -= 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bin less attractive unless lookahead suggests
    // it enables a perfect two-item packing (e.g. item + next fill capacity exactly).
    if bin_residual == bin_capacity {
        let pair_fill = item_size as f64 + next_item_size as f64;
        if next_item_size > 0 && (pair_fill - bin_capacity as f64).abs() < 1.0 {
            score -= 20.0; // opening fresh bin enables perfect pair
        } else {
            score += 18.0; // discourage spreading when open bins can fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward consuming large chunks of the bin (deep fill preference).
    score -= 2.0 * item;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: penalize leaving a residual that cannot fit the next item (dead space risk).
    if next_item_size > 0 && post > 0.0 && post < next {
        score += 0.6 * (next - post);
    }
    // Reward residuals that remain usable for the next item.
    if next_item_size > 0 && post >= next && post > 0.0 {
        score -= 5.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base penalty so existing bins are preferred when they fit well.
        score += 15.0;
        // If open bins are heavily fragmented (low mean residual), opening a fresh
        // bin is attractive: subtract to make the new bin competitive.
        if mean_residual < item * 0.5 {
            score -= 25.0;
        }
        // Early in the stream, a fresh bin preserves flexibility.
        let t = step_index as f64 / (total_items.max(1) as f64);
        if t < 0.25 {
            score -= 8.0;
        }
    }

    // Penalize tiny unusable residuals (dead space <= 10).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Slight time-dependent flexibility term: early on, keep bins roomy.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 3.0 * (post / cap);

    // Congestion effect: many open bins -> prefer consolidating into existing ones.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: penalize wasted residual, but with a smooth non-linear (quadratic) coupling
    // to stream progress. Early on, small residuals are fine; late in the stream,
    // dead space becomes more costly.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear interaction: normalized residual squared scaled by progress.
    score += 12.0 * norm_post * norm_post * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual relative to item size) with a smooth term.
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 10.0 * tightness * tightness * (1.0 - progress);

    // Lookahead coupling: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_quality = 1.0 - (diff / cap).min(1.0);
        score -= 8.0 * fit_quality * fit_quality;
    } else {
        // Last item: strongly prefer minimizing final residual.
        score += 5.0 * norm_post;
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new bin
    // by rewarding this bin smoothly.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_post);
    }

    // Mild penalty when this bin's residual deviates from the mean residual
    // (encourages balanced residual distribution, weighted by openness).
    let dev = (post - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: neutral baseline with slight smooth offset so that
    // opening a new bin is only chosen when open-bin scores are worse.
    if bin_residual == bin_capacity {
        score += cap * (0.55 + 0.25 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quantum (C=100 typical).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual in {0, cap/2, cap/3, cap/4} are reusable slots.
    let harmonics = [0u32, bin_capacity / 2, bin_capacity / 3, bin_capacity / 4];
    if harmonics.contains(&post_residual) {
        score -= 40.0;
    }

    // Dead-space penalty: small unusable post_residual (cannot fit even min item ~1..10).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(10) {
        score += 25.0;
    }

    // Classify post_residual by integer division thresholds (capacity fractions).
    let frac = post / cap; // in [0,1)
    if frac < 0.10 {
        score += 15.0; // tiny sliver, likely dead
    } else if frac < 0.25 {
        score += 5.0;  // quarter class
    } else if frac < 0.50 {
        score -= 8.0;  // half class: very reusable
    } else {
        score -= 12.0; // large residual: flexible
    }

    // Lookahead coupling: does post_residual harmonically fit next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact modulo match with next item is ideal
            if post_residual % next_item_size == 0 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            score += 10.0; // next item won't fit here; keep residual large elsewhere
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from many open bins: prefer filling existing bins tighter.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += mean_residual * 0.05 / pressure;

    // New-bin candidate: penalize so it's chosen only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 60.0 + pressure * 10.0;
        // But early in the stream, opening bins is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 40.0;
        // If next item is huge and current item small, fresh bin preserves flexibility.
        if next_item_size >= bin_capacity / 2 && item_size <= bin_capacity / 4 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose leftover can still hold the next item (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0; // leftover too small for next item: mild dead-space penalty
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage opening a new bin when others fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin && fitting_bins_count > 0 {
        score += 15.0 + (open_bins_count as f64).sqrt() * 5.0;
    }
    if is_new_bin {
        // New bin leaves large residual; slight reward so it beats terrible fits.
        score -= 5.0;
    }

    // Mean residual coupling: prefer placing into bins already tighter than average.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.3;

    // Slight preference for fuller bins as stream progresses.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward placements whose post_residual
    // exactly matches the next item (perfect chain packing).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        if post == next {
            // Perfect follow-up fit: strongly reward.
            score -= 40.0;
        } else if post > next {
            // Next item fits: reward proportionally to how snug the fit is.
            score -= 12.0 * (next / post);
        } else {
            // Dead space: post_residual cannot host next item.
            // Penalize proportionally to wasted fraction of residual.
            let waste = (next - post) / next;
            score += 18.0 * waste;
        }

        // Extra coupling: if this placement leaves a residual that could
        // host the next item, but the residual is small (< 10), it's dead.
        if post < 10.0 && post < next {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current
    // item fits poorly everywhere or residuals are high.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - item_size) as f64;
        // Prefer a new bin only when existing bins would leave big waste.
        let threshold = 0.35 * bin_capacity as f64;
        if post_residual as f64 >= threshold || mean_residual < threshold * 0.5 {
            score -= 5.0; // new bin is reasonable
        } else {
            score += 25.0; // discourage new bin, use existing capacity
        }
        let _ = poor_fit;
    }

    // Mild penalty for bins whose residual deviates far above the mean
    // (keeps bin selection balanced across open bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Late in the stream, tighten packing: penalize large leftovers more.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Penalize dead space relative to item size: residual that can't hold next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room for the lookahead item.
            score -= 0.5 * (next_item_size as f64).min(post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless fit is terrible.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mut penalty = 18.0;
        if fill_ratio > 0.6 {
            penalty -= 10.0 * (fill_ratio - 0.6);
        }
        if fitting_bins_count <= 1 {
            penalty -= 12.0;
        }
        score += penalty;
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= 2.0 + 0.15 * open_bins_count as f64;
    }

    // Global residual balance: prefer bins with residual near mean residual
    // (keeps bin pool homogeneous, easier future packing).
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * drift;

    // Time horizon: early in stream, be conservative (favor tight fits more);
    // late in stream, just fill anything to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);
    score += 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer filling bins tightly (low post_residual wins).
    let mut score = post;

    // Smooth reward for tight fits: (item/residual)^2 coupling, scaled by post-residual.
    let fit_ratio = if bin_residual > 0 { item / bin_residual as f64 } else { 0.0 };
    score -= 8.0 * fit_ratio * fit_ratio * (cap - post) / cap;

    // Penalize dead space quadratically, but relax as stream progresses
    // (late in the stream, closing out bins tightly matters more).
    let dead = post / cap;
    score += 6.0 * dead * dead * (1.0 - 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; keep flexibility.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: reward bins whose post-residual can still fit the
    // next item smoothly (polynomial interaction), penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            let closeness = 1.0 - gap / cap;
            score -= 4.0 * closeness * closeness;
        } else {
            score += 2.0 * (-gap / cap) * (1.0 + progress);
        }
    } else {
        // Last item: maximize final fill.
        score += 3.0 * dead;
    }

    // New-bin candidate (empty bin): make it slightly unattractive by default
    // so existing bins are used unless this score is genuinely beaten by
    // tight-fit bonuses elsewhere. Smoothly relax with progress.
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    // Mild regularization toward bins with larger residual (spread waste),
    // interacting smoothly with mean residual.
    score += 0.3 * (mean_residual - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in a
    // "reusable" residue class are favored; dead-space classes penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: perfect fit -> massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class 2: small unusable residue (< 10, minimum item size) is dead space.
        if post_residual < 10 {
            score += 60.0;
        }
        // Class 3: residue in "harmonic" bands that commonly pair with
        // typical item sizes (multiples of 10 / 25 / 50) get discounts.
        if post_residual % 10 == 0 {
            score -= 12.0;
        }
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
        // Integer-division thresholds on post_residual.
        match post_residual / 20 {
            0 => score += 25.0,        // 1..19: nearly dead
            1 => score += 5.0,         // 20..39: tight but usable
            2 => score -= 4.0,         // 40..59: comfortable
            3 => score -= 6.0,         // 60..79: very reusable
            _ => score -= 3.0,         // 80+: half-empty, wasteful use
        }
    }

    // Lookahead coupling: reward residues that can host the next item,
    // penalize when only this bin could fit the current item (last chance).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Exact lookahead fit is especially valuable.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            score += 10.0;
        }
    }

    if fitting_bins_count == 1 {
        // Last chance before opening a new bin: strongly favor using it.
        score -= 80.0;
    } else if fitting_bins_count == 0 {
        // Shouldn't happen for a fitting candidate, but guard.
        score += 200.0;
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty keeps existing bins preferred unless they are poor fits.
        score += 90.0;
        // Reward opening a new bin when mean residual is low (bins are tight)
        // and late in the stream where fragmentation dominates.
        score -= crowding * 70.0 + progress * 25.0;
        // If the current item is large, a fresh bin is safer.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild preference for bins tighter than the current average.
    score += (pr - mean_residual) * 0.3;

    // Slight penalty for proliferating bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading further
    // unless the fit is tight; encourage opening new bins when few are open.
    let open_pressure = open_bins_count as f64 * 0.8;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; cheaper when many bins open
        // and current fit would leave large dead space.
        score += 25.0 + open_pressure * 0.5;
    } else {
        score -= open_pressure * 0.3;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping loose bins available for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: prefer bins whose post-residual is small (good fill).
    score = post_residual as f64 * (1.0 + 0.002 * (bin_capacity as f64 - post_residual as f64));

    // 2-step lookahead: strongly reward a post_residual that exactly (or nearly)
    // accommodates the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // Next item fits here afterwards: reward proportionally to tightness of that fit.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit after this placement: mild penalty scaled by shortfall.
            score += 8.0 * (gap / bin_capacity as f64);
        }
        // Exact match bonus (perfect 2-step packing).
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 25.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are valuable, keep using them.
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin unless the item fits poorly everywhere else
    // (i.e., post_residual into an existing bin would be tiny/dead-space-prone).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 45.0
            + 0.3 * post_residual as f64
            + (open_bins_count as f64).sqrt() * 5.0;
        // If next item is small and could use leftover space, opening a fresh bin
        // is slightly less bad.
        let relief = if next_item_size > 0 && (next_item_size as f64) >= post_residual as f64 {
            10.0
        } else {
            0.0
        };
        score += new_bin_penalty - relief;
    } else {
        // Existing bin: reward usage to discourage unnecessary bin proliferation.
        score -= 5.0;
    }

    // Slight progression bias: later in the stream, tighten up and avoid waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Reward tight fits: subtract for small post_residual relative to capacity.
    let tightness = 1.0 - pr / cap;
    score -= 18.0 * tightness * tightness * (1.0 + progress);

    // Non-linear coupling: post_residual * item_size normalized interaction.
    let inter = (pr * isz) / (cap * cap);
    score -= 10.0 * inter * (1.0 - inter);

    // Penalize creating dead space that likely can't fit typical items.
    if pr > 0.0 && pr < 10.0 {
        score += 6.0 * (10.0 - pr) / 10.0;
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: reward if next item fits snugly into the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let nx = next_item_size as f64;
        let snug = 1.0 - ((pr - nx) / cap).abs();
        score -= 8.0 * snug * snug;
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // Penalize bins whose post residual blocks the next item.
        score += 4.0 * ((next_item_size as f64 - pr) / cap);
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balance).
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate handling: make empty bin moderately attractive only
    // when few bins fit or item is large relative to residuals.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let big_item = isz / cap;
        let pressure = scarcity * (0.4 + big_item) * (0.5 + progress);
        score = cap - 30.0 * pressure;
        // Late stream: opening new bins is cheaper than wrecking old ones.
        score -= 10.0 * progress * progress;
    }

    // Mild penalty for proliferating open bins early in the stream.
    score += 1.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: quarter-class index (0..3)
    let quarter = (bin_capacity / 4).max(1);
    let class = post_residual / quarter;
    // Reward small post_residual within its class (tight fit), reward lower classes strongly
    let class_center = (class * quarter + quarter / 2) as f64;
    score += (post - class_center) * 0.3;
    score -= (3.0 - class.min(3) as f64) * 2.0;

    // Dead-space penalty: post_residual too small to ever fit anything (min item 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // "Harmonic trap": residual just below a common item size band
    for band in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
        if post_residual >= band && post_residual < band + 3 {
            score += 8.0;
        }
    }

    // Lookahead: reward if next item fits into post_residual (keeps bin useful)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + (post_residual as f64 - next_item_size as f64).min(10.0) * 0.4;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin is attractive early in stream or when many bins already open fit poorly
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bin generally; discount when item is large (hard to place later)
        let mut nb = 20.0;
        if item_size as f64 > 0.6 * cap {
            nb -= 10.0;
        }
        if fitting_bins_count == 0 {
            nb -= 30.0; // no alternative
        }
        if progress < 0.2 {
            nb -= 5.0; // early stream: fresh bins fine
        }
        score += nb;
    } else {
        // Slight preference for fuller existing bins
        score -= (1.0 - (bin_residual as f64 / cap)) * 3.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good "filler" target
    let dev = mean_residual - post;
    if dev > 0.0 {
        score += dev * 0.05;
    } else {
        score += dev * 0.02;
    }

    // Modulo/harmonic tie-breaker on post_residual: prefer residuals divisible into small classes
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        // The smaller (and thus more useless) the gap, the bigger the penalty.
        score += (dead_threshold - post_residual) as f64 * 25.0;
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual (small waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Pressure from many open bins: discourage spreading across bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is far from the mean (consolidate large gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item cannot fit in post residual but could fit elsewhere, mild penalty
    // for creating a gap that strands the lookahead item.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when the item would leave a large gap in an existing bin, or when the
    // current item is large and would fragment a nearly-full bin.
    if bin_residual == bin_capacity {
        let gap_elsewhere = (bin_residual - item_size) as f64; // same value for empty bin
        // Base attractiveness of a fresh bin: moderate.
        score = gap_elsewhere * 0.5 + 30.0;
        // If placing in an existing bin would create tiny dead space, favor new bin.
        if post_residual > 0 && post_residual < dead_threshold {
            score -= 50.0;
        }
        // If many bins are open, prefer reusing existing bins instead.
        score += open_bins_count as f64 * 2.0;
        // Early in the stream, new bins are cheap; later, avoid proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Penalize leftover gap after a hypothetical next-item placement.
            score += slack * 0.6;
        } else {
            // Next item cannot fit here; penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.35;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than the mean.
    let resid_f = post_residual as f64;
    score += (resid_f - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize opening a new bin when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * (bin_capacity as f64 - item_size as f64);
        // But allow new bin if no open bin fits well (dead-space avoidance for big items).
        if item_size as f64 > mean_residual {
            score -= 35.0;
        }
    }

    // Late-stream consolidation: keep filling existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin, more strongly when
    // alternatives exist and the fit elsewhere is reasonable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let alt_bonus = if fitting_bins_count > 0 { 25.0 + 15.0 * progress } else { 0.0 };
        score += 40.0 + alt_bonus;
        // Less penalty late in stream when bins are fragmented.
        if open_bins_count > 4 { score -= 10.0; }
        return score;
    }

    // Reward tight fits (low post residual) non-linearly.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score += tight * tight * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 5.0 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space the next item cannot use: penalize small slivers.
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins with residual below mean (fill fuller bins first),
    // scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) < mean_residual {
        score -= 8.0 * (1.0 + progress);
    } else {
        score += 4.0 * progress;
    }

    // Mild penalty for very large residual bins early (save them for big items).
    if bin_residual > 60 && progress < 0.5 && item_size < 40 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate larger residuals; late: aggressively minimize them.
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 18.0 * (pr / cap) * (1.0 - progress) * (1.0 + 0.5 * prog2);
    score -= 14.0 * (pr / cap) * prog3;

    // Reward tight fits: penalize when post_residual is small relative to item size.
    let tightness = 1.0 - (pr / cap);
    score -= 10.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post-residual, favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap) * (0.5 + progress);
        } else {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.6 + 0.4 * progress);
    }

    // Discourage spreading across many open bins when residuals are already large.
    score += 1.5 * (open_bins_count as f64).ln() * (mean_residual / cap);

    // New-bin candidate: penalize mildly early, more strongly late in the stream.
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity quarters:
    // residuals in (0,10] are "dead space" -> heavy penalty; residuals that
    // still admit mid-size items are valuable -> reward.
    let q = post_residual / 25; // 0..4 harmonic class
    match q {
        0 => {
            if post_residual == 0 { score -= 30.0; }        // perfect fit
            else { score += 12.0; }                          // dead space < 25
        }
        1 => { score -= 4.0; }                               // 25..49: usable
        2 => { score -= 8.0; }                               // 50..74: very usable
        _ => { score -= 6.0; }                               // 75..99: flexible
    }

    // Lookahead coupling: reward if the next item fits into post_residual,
    // scaled by how snugly it fits (integer-division threshold classes).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        let fit_bonus = if slack == 0 { 25.0 } else if slack <= 10 { 15.0 } else if slack <= 25 { 8.0 } else { 3.0 };
        score -= fit_bonus;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: residual likely becomes waste
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large (fills the fresh bin well) or no decent fit exists.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill >= 0.5 {
            score -= 10.0 + 10.0 * fill;   // large item: fresh bin is fine
        } else {
            score += 15.0;                 // small item: keep filling open bins
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure toward bins below mean residual (balance load),
    // keeping some bins tight for future large items.
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12] are effectively unusable
    // for typical items (sizes >= 1 but practical items rarely fit tiny gaps).
    // Penalize them heavily, scaled by how "dead" the gap is.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64) / 12.0;
    }

    // Reward near-perfect fits (post_residual == 0) strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to capacity: waste fraction penalty.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out; penalize slightly per open bin
    // so tight fits in existing bins beat opening new ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the item leaves a very awkward residual in every
    // fitting bin, or no bins fit. Give empty bin a mild default penalty so
    // existing decent fits win.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If lookahead item could combine with the leftover, opening a fresh
        // bin that keeps large residual is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Existing-bin bonus when leftover can host the next item (chaining).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > post_residual as u32 && next_item_size > 0 {
            // Leftover can't fit next item: dead space risk, small penalty.
            score += 5.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already "cramped" — using it up is good (reduces fragmentation).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.15 * (mean_residual - resid_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // perfect chaining: bin closed after next item
        } else if next_item_size <= post_residual {
            // next item fits, but reward proportional to how much it consumes
            let consumed = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * consumed;
            // penalize leaving a sliver that next item barely leaves behind
            let next_left = post_residual - next_item_size;
            if next_left > 0 && next_left < 10 {
                score += 50.0; // tiny dead sliver after next placement
            }
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 30.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // (poor fit elsewhere) or no real fitting alternative exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.75 {
            score -= 120.0; // large item: fresh bin is fine
        } else {
            score += 250.0 * (1.0 - fill_ratio); // discourage wasting fresh bins
        }
        // more open bins => keep using them rather than growing the set
        score += 20.0 * open_bins_count as f64;
    }

    // Slight late-stream tightening: near the end, prefer tighter packs.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 3.0; // creates stranded space vs. next item
        }
        // Reward exact two-item closure: item + next fills the bin.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: discourage opening a new bin when it would be wasteful,
    // but encourage it when open bins fit badly (large post_residual) or few bins fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 15.0;
        // Cheaper to open a bin late in the stream (fewer future chances to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // If existing bins fit poorly, opening fresh is less bad.
        if post_residual >= item_size && (post_residual as f64) < mean_residual {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Lookahead: a fresh bin guarantees room for the next item too.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 4.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual
    // (filling emptier bins keeps tight bins for tight items).
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 1.5;
    }

    // Slight penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: normalized post-residual (dead space), scaled by progress
    let norm_post = post / cap;
    let mut score = norm_post * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + 2.0 * progress * (1.0 - progress)) + norm_post.powi(3) * (1.5 * progress);
    score += poly;

    // Tight fit reward: quadratic bonus for small post-residual
    score -= (1.0 - norm_post).powi(3) * 0.35;

    // Penalize bins that leave unusable space relative to mean residual
    score += 0.15 * (post - mean_residual) / cap;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = (post_residual as u64) >= (next_item_size as u64);
        if fits_next {
            score -= 0.25 * (1.0 - (next_item_size as f64 / cap));
        } else {
            score += 0.2 * (1.0 - progress);
        }
    }

    // New-bin candidate: neutral-ish score that becomes attractive only when
    // existing bins are all poor fits (large post-residual)
    if bin_residual == bin_capacity {
        score = 0.9 + 0.3 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 1.5;
        }
    }

    // Mild penalty for spreading across many open bins early
    score += 0.02 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 bands.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty grows for residuals that are "awkward" (small, non-round).
    if pr > 0 {
        let awkward = match class {
            0 => 0.0,               // perfectly round residual is reusable
            1..=3 => 6.0,           // tiny slivers are dead space
            4..=6 => 2.5,
            7..=9 => 1.0,
            _ => 0.0,
        };
        // Slivers hurt more late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += awkward * (0.5 + progress);
    }

    // Zero post_residual = perfect fit: strong reward.
    if pr == 0 {
        score -= 25.0;
    }

    // Harmonic pairing: can the lookahead item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead fits: reward proportional to how well it nests.
            let nest_quality = (pr - next_item_size) as f64;
            score -= 8.0 + 10.0 * (1.0 - nest_quality / bin_capacity as f64);
        } else {
            // Lookahead won't fit here: mild penalty if this bin was a good host otherwise.
            score += 3.0;
        }
        // Harmonic class match: item and lookahead in same mod-10 class chain well.
        if next_item_size % 10 == item_size % 10 && next_item_size <= pr {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a decent host,
    // i.e. when fitting bins are scarce or the best fit is poor.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let poor_hosts = (mean_residual - item_size as f64).max(0.0) < 10.0;
        if scarcity > 0.5 || poor_hosts {
            score -= 12.0 * scarcity;
        } else {
            // Prefer reusing open bins when they fit reasonably.
            score += 20.0;
        }
        // Opening bins late is cheap (fewer future items to place).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Prefer tighter bins generally: reward small pre-residual relative to item.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 5.0 * tightness;

    // Mean-residual coupling: when open bins are collectively full, conserve them.
    if mean_residual < item_size as f64 * 1.2 && bin_residual >= item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are heavily penalized (they are effectively wasted capacity).
    if post_residual > 0 {
        let gap = post_residual as f64;
        // dead-space severity rises sharply as the gap shrinks below 10
        if gap < 10.0 {
            score += (10.0 - gap) * 12.0;
        } else if gap < 20.0 {
            score += (20.0 - gap) * 3.0;
        }
        // exact fit is ideal
        if post_residual == 0 {
            score -= 60.0;
        }
    } else {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening new bins.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins already open
        score += pressure * 4.0;
        // but if this bin is the only option, allow it
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    } else {
        // existing bin: reward using it when bin count is high
        score -= pressure * 0.8;
    }

    // Lookahead: if the next item fits in the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item would NOT fit in post residual but post residual is decently large,
    // slight penalty for fragmenting space.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 15 {
        score += 15.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin -> prefer filling it.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    // Stream progression: early on, be slightly more willing to open bins;
    // later, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match lookahead: leaving exactly next_item_size is ideal
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Post-residual that cannot fit next item is wasted dead space
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 + (post_residual as f64) * 0.15;
    }
    // Post-residual larger than next item but wastefully large
    if next_item_size > 0 && post_residual > next_item_size {
        score += (post_residual - next_item_size) as f64 * 0.35;
    }

    // Tight fits are good
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 12.0;
            if next_item_size > 0 && post_residual >= next_item_size {
                score += 8.0;
            }
        }
        // A new bin is attractive when residuals elsewhere are tiny
        if mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; add mild non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Reward leaving space usable by next item, scaled by how well it fits.
            let next_fit = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 20.0 * next_fit;
        } else {
            // Post-residual too small for next item: penalize dead space.
            let dead = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += 0.25 * dead;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin, unless the fit
    // into an existing bin would be very poor or lookahead is large.
    if bin_residual == bin_capacity {
        let mut penalty = 40.0;
        // If item is large relative to capacity, opening fresh bin is less bad.
        penalty -= 0.2 * item_size as f64;
        // If existing bins are crowded (low mean residual), new bin is more attractive.
        penalty -= 0.15 * (mean_residual - post_residual as f64);
        // If many bins fit the item, opening a new bin is wasteful.
        penalty += 3.0 * (fitting_bins_count as f64).min(8.0);
        // Lookahead: if next item fits in the fresh bin's residual alongside, soften penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            penalty -= 15.0;
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += 20.0 * progress;
        score += penalty;
    }

    // Mild global pressure: when many bins are open, favor consolidation.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean in a "fillable" way.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * dev * dev * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth non-linear coupling
    let mut score = post.powf(1.3) * (1.0 + 0.5 * progress);

    // Tight-fit reward: strong discount as post_residual approaches 0
    let tightness = (-norm_post * 4.0).exp();
    score -= 40.0 * tightness;

    // Penalize post-residuals that are "dead" (too small for typical future items)
    // smooth valley: residuals just below ~20 are wasteful
    let deadness = (-(post - 20.0).powi(2) / 200.0).exp();
    score += 15.0 * deadness * (1.0 - progress);

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits in the post-residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            let slack = (post - next) / cap;
            score -= 20.0 * (-slack * 6.0).exp();
        } else {
            // penalize blocking next item slightly
            score += 8.0 * ((next - post) / cap);
        }
    }

    // New-bin candidate: neutral-ish score that scales with stream progress
    // early on, opening bins is cheap; late, avoid spreading
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 10.0 * (1.0 - progress);
    }

    // Mild preference to fill bins with larger residuals when many bins are open
    score += 0.05 * mean_residual * (open_bins_count as f64).powf(0.5) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer smallest post_residual (tight fit), but not zero-waste obsession.
    score = post_residual as f64 * 1.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Small leftovers that are "useless" (cannot hold typical future items) should be penalized.
    let pr_mod = post_residual % 10;
    let dead_zone = post_residual > 0 && post_residual < 10; // unusable sliver
    if dead_zone {
        score += 500.0; // creating dead space < 10 is terrible
    }

    // Class-based bonus: post_residual divisible by common item sizes is reusable.
    if post_residual >= 10 {
        if post_residual % 10 == 0 { score -= 25.0; }
        if post_residual % 20 == 0 { score -= 15.0; }
        if post_residual % 50 == 0 { score -= 20.0; }
        if post_residual % 25 == 0 { score -= 10.0; }
    }

    // Lookahead: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 800.0; // chain fill: perfect
        } else if gap < 10 {
            score += 300.0; // next item creates dead space here — bad
        } else {
            score -= (gap as f64).ln() * 20.0; // mild reward for reusable remainder
        }
    }
    // If next item does NOT fit in this bin's post residual but fits nowhere else either,
    // this bin is a last chance — strongly prefer filling it.
    if next_item_size > 0 && next_item_size > post_residual && fitting_bins_count == 1 {
        score -= 600.0;
    }

    // Last-chance bin logic: only one bin can fit this item.
    if fitting_bins_count == 1 {
        score -= 400.0;
    }

    // New-bin candidate: empty bin (residual == capacity). Only attractive when
    // all open bins would leave big dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty: reusing an open bin is usually better.
        score += 350.0;
        // But if the item is large and open bins are crowded, new bin is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 50 {
            score -= 150.0 * progress;
        }
        if open_bins_count == 0 {
            score -= 2000.0; // must open first bin
        }
        // If mean residual across open bins is small (they're full), new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 400.0;
        }
        // Perfect-fit classes for a fresh bin: leaving 100 residual is neutral.
        score -= 0.0;
    }

    // Prefer bins whose residual is already below mean (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 15.0;
    }

    // Mild penalty for opening many bins late in the stream.
    if open_bins_count > 0 && bin_residual == bin_capacity {
        score += 10.0 * open_bins_count as f64;
    }

    // Integer-division threshold on post_residual: chunks of 33 (capacity/3).
    let third = bin_capacity / 3;
    if post_residual >= third && post_residual < 2 * third {
        score -= 12.0; // mid-range remainder is quite reusable
    } else if post_residual >= 2 * third {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space more than proportionally.
    let dead_threshold = 9.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Pressure: many open bins -> prefer filling existing bins, avoid opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Allow opening a new bin when item is large relative to residual fits elsewhere.
        if (item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item would fit in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0;
    }

    // Prefer bins whose residual is close to what we consume (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Progress-based mild scaling of dead-space penalty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match bonus: next item fits tightly in post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to shortfall
        let shortfall = (next_item_size - post_residual) as f64;
        score += 0.4 * shortfall;
    }

    // Penalize small dead space that no item (min size 1..10) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins whose post residual stays near/below mean
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: only attractive when current fit is terrible
    // or no real bin fits well; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream, be more frugal about wasted space
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively when many bins compete.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= fit_ratio * fit_ratio * 40.0;

    // Penalize dead space that no plausible item can use: residual < 10 means unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement would block a next item that currently fits elsewhere — mild penalty.
            score += 10.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * (open_bins_count as f64).ln().max(1.0) * 12.0;

    // Mean-residual coupling: if this bin is much emptier than average, slight penalty
    // (save roomy bins for large future items).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 15.0;

    // Time horizon: late in the stream, favor closing out bins (max fill) since
    // fewer future items remain to exploit slack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= fill * progress * 30.0;

    // New-bin candidate: make opening a new bin costly unless current bins are nearly full
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fill == 0.0 && mean_residual < 35.0 {
            score -= 30.0; // open bins are all tight; a fresh bin is fine
        }
        if post_residual as f64 >= bin_capacity as f64 * 0.55 {
            score += 20.0; // large item wasting a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial shaping: reward tight fits (small post_residual) with
    // a quartic bowl that rises steeply as dead space grows.
    let mut score = 4.0 * x - 6.0 * x * x + 4.0 * x * x * x - x * x * x * x;
    score = 1.0 - score; // in [0,1]-ish, low when x small

    // Base linear term keeps monotone pressure toward tight fits.
    score += pr;

    // Non-linear coupling with stream progress: late in the stream, dead space
    // becomes costlier (fewer chances to reuse it), so penalize more.
    let late = progress * progress;
    score += 12.0 * late * x * x * cap * 0.1;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement (smooth kernel instead of hard switch).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_kernel = (-gap * gap / 50.0).exp();
        score -= 8.0 * fit_kernel * (1.0 - late);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    // Coupling with mean residual: placing into a bin near the mean is neutral;
    // creating post residual far from mean residual wastes spread.
    score += 0.02 * (pr - mean_residual).abs();

    // New-bin candidate (bin_residual == bin_capacity): penalize mildly so it is
    // chosen only when its (necessarily large) post residual beats all open bins,
    // i.e. when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;

    // Reward tight fits: fill fraction of the bin consumed by this item.
    let fill = item_size as f64 / cap;
    score -= 18.0 * fill * fill;

    // Harmonic dead-space penalty: residues in "wasteful" classes
    // (small but unusable gaps) are penalized more than near-empty bins.
    let residue_class = post_residual % 10;
    if post_residual > 0 {
        let class_penalty = match residue_class {
            0 => -6.0,          // perfectly harmonic gap (divisible by 10)
            1..=4 => 10.0,      // tiny dead slivers are worst
            5..=9 => 2.0,       // moderate gap, still reusable for small items
            _ => 0.0,
        };
        score += class_penalty * (1.0 + post_frac);
    }

    // Integer-division threshold: if the NEXT item fits harmonically into
    // the post residual, strongly favor this bin (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = (post_residual / next_item_size.max(1)) as f64;
        score -= 14.0 + 4.0 * chain_fit.min(4.0);
    } else if next_item_size > 0 {
        // Next item cannot use this gap: penalize proportional dead space.
        score += 8.0 * post_frac;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large and current residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).abs() / cap;
        let large_item = item_size as f64 / cap > 0.6;
        if large_item || open_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 12.0 + 10.0 * (1.0 - fragmentation);
        }
    } else {
        // Prefer bins whose residual is already below the item's harmonic
        // complement: they are "committed" bins.
        let committed = (bin_residual as f64) < 2.0 * (item_size as f64);
        if committed {
            score -= 5.0;
        }
    }

    // Mild progression bias: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_frac);

    // Tie-break toward bins with residual close to the open-bin mean
    // (keeps the bin pool balanced).
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: prefer reusing existing bins.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }
    // If next item almost fits, slight penalty for wasting potential.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins are tight.
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        if avg_tightness < 0.15 && open_bins_count > 0 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Late in stream: consolidate, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly or closely.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-chain: item then next item fills bin
        } else if gap <= 5.0 {
            score -= 20.0;
        } else if gap <= 10.0 {
            score -= 8.0;
        } else {
            // penalize leaving residual the next item cannot use
            score += gap * 0.15;
        }
        // Bonus if the next item could fit into the leftover space at all
        if next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average
    // residual (consume the most constrained space first).
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.35;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // unless the item is large and would leave a tight residual anyway.
    if bin_residual == bin_capacity {
        score += 18.0 + (open_bins_count as f64).powf(0.5) * 2.0;
        // allow new-bin opening when the item fits very snugly
        let snug = (bin_capacity - item_size) as f64;
        if snug <= 5.0 {
            score -= 20.0;
        }
        // late in the stream, avoid opening bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual penalty
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward bins whose post-residual can hold the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space that next item can't use: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // New-bin candidate handling: only attractive when existing fit is poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // Cheaper to open new bin late in stream (fewer future items to fill it)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 35.0;
        // If item barely fits anywhere (large item), new bin is reasonable
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // If many open bins already, avoid spreading too thin
        score += open_bins_count as f64 * 1.5;
        // If mean residual is small, bins are nearly full — new bin fine
        if mean_residual < item_size as f64 * 1.2 {
            score -= 25.0;
        }
    }

    // Slight preference for bins with residuals close to the item (minimize fragmentation)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 25.0;

    // Prefer bins whose residual is small relative to mean (use fullest bins first)
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild preference for tight fits. Late: strong pressure to fill bins.
    let tightness = post / cap;
    let progress_coupling = (progress * progress) * 40.0 * (1.0 - tightness) * tightness;
    score += progress_coupling;

    // Reward near-perfect fills smoothly (quartic dip near zero residual).
    let norm = tightness;
    score -= 30.0 * (1.0 - norm) * (1.0 - norm) * (1.0 - norm) * (1.0 - norm);

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = ((nxt - post) / cap).max(0.0);
        score += 25.0 * unusable * unusable;
        // Reward leaving space exactly usable by next item.
        let usable_gap = 1.0 - ((post - nxt) / cap).abs().min(1.0);
        score -= 15.0 * usable_gap * usable_gap;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin, more so when many open bins could still absorb.
    if bin_residual == bin_capacity {
        score += 35.0 + 8.0 * (open_bins_count as f64).sqrt() + 20.0 * (1.0 - progress);
        // Extra penalty if some open bin already fits the item.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Slight penalty for deviating far from mean residual (balance avoidance of waste).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10.
    // Small residues are "dead space" classes -> penalize non-zero residues.
    let r = post_residual % 10;
    score += (r as f64) * 1.5;

    // Reward exact fills (perfect packing class).
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward near-exact fills within the same decade class.
    if post_residual <= 5 {
        score -= 50.0;
    }

    // Integer-division thresholds: post_residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score -= 20.0; // tight fit is good
    } else if post_residual < 2 * quarter {
        score += 5.0;
    } else if post_residual < 3 * quarter {
        score += 15.0;
    } else {
        score += 25.0; // large leftover is wasteful
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_post = post_residual - next_item_size;
        score -= 30.0;
        if nxt_post % 10 == 0 {
            score -= 40.0; // harmonic alignment with next item
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // next item won't reuse this residual
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 3 * quarter || (fitting_bins_count <= 1);
        if poor_fit {
            score -= 10.0;
        } else {
            score += 60.0 + (open_bins_count as f64) * 2.0;
        }
    }

    // Slight preference to fill bins with larger residuals early (balance load).
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    // Stream progression: later in stream, be more aggressive about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (10.0 - r as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins left with (near-)zero residual.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead-space penalty: residual after placement that cannot host the next item
    // is wasted capacity relative to the lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (post_residual as f64);
    }

    // If the gap can host the next item, reward it (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.2 * item_size as f64;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, tolerate imperfect fits rather than spawning bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 0.8 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when it leaves a large,
    // flexible residual early in the stream or when mean residual is low.
    if bin_residual == bin_capacity {
        score -= 5.0 + 20.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fit (low post residual relative to item size)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if fit_ratio < 0.1 {
        score -= 8.0;
    } else if fit_ratio < 0.25 {
        score -= 3.0;
    }

    // Aggressive 2-step lookahead: strongly reward exact match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 12.0 - 0.6 * gap;
            } else {
                // leftover after next item would be dead space; penalize
                score += 0.15 * gap;
            }
        } else {
            // next item cannot fit here; penalize proportionally
            let miss = (next_item_size - post_residual) as f64;
            score += 0.1 * miss;
        }
    }

    // Compare post_residual against mean residual of open bins
    if (post_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize opening new bins when open bins exist that fit reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0;
        // allow new bin only if no good fit exists anywhere
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Late in stream: prefer compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but dampen so tiny differences matter less.
    score = (post_residual as f64).powf(1.25);

    // Tight-fit reward: near-perfect packing gets strongly favored.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    } else if post_residual <= 10 {
        score -= 3.0;
    }

    // Dead-space penalty: residuals too small for the smallest item (<=9) are waste.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0 + 0.05 * next_item_size as f64;
            // Bonus if next item fills bin almost exactly.
            let gap = post_residual - next_item_size;
            if gap <= 3 {
                score -= 6.0;
            }
        } else {
            // Post residual useless for next item: mild penalty proportional to waste.
            score += 0.03 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item fits badly everywhere else. Penalize the empty-bin candidate
    // proportionally to how much residual capacity already exists in the system.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let system_pressure = mean_residual / bin_capacity as f64;
        // If mean residual across open bins is large, reusing is better.
        score += 14.0 + 20.0 * system_pressure + 10.0 * (1.0 - progress);
        // Late in the stream, avoid proliferation of nearly-empty bins.
        if open_bins_count > 4 {
            score += 0.5 * open_bins_count as f64;
        }
        // But if the item is huge and would leave a big post residual in any
        // open bin anyway, the fresh bin is comparatively fine.
        score -= 0.05 * item_size as f64;
    }

    // Prefer consolidating into bins with below-average residual (fill the fullest bins first).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.10 * diff;
    }

    // Time-horizon modulation: early on, be conservative (keep bins flexible);
    // late, pack aggressively (minimize absolute waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: post residual, with non-linear polynomial shaping.
    // Small post_residual is good (tight fit) -> reward via quadratic term.
    let mut score = post * (1.0 + 2.0 * post_norm * (1.0 - post_norm));

    // Smooth interaction: progress-weighted tightness bonus.
    // Early in stream, keep bins flexible (penalize very small post_residual slightly less);
    // late in stream, prefer tight fits strongly.
    let tightness = 1.0 - post_norm; // 0..1, higher = tighter fit
    score -= 8.0 * tightness * tightness * (0.35 + 0.65 * progress);

    // Penalize dead space that's too small for typical items (unusable slivers),
    // smoothly via cubic in post_norm.
    let dead = if post_norm > 0.0 { post_norm * post_norm * post_norm } else { 0.0 };
    score += 6.0 * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fill_after = nxt / post.max(1.0);
            score -= 4.0 * fill_after * fill_after;
        } else {
            score += 1.5;
        }
    }

    // Mild penalty for spreading across many open bins (encourage consolidation),
    // scaled by how far this bin deviates from mean residual.
    let dev = post - mean_residual;
    score += 0.4 * dev * (open_bins_count as f64).ln_1p() / cap;

    // New-bin candidate handling: empty bin gets a smooth adaptive penalty so it
    // only wins when open bins are genuinely poor fits.
    if (bin_residual as f64 - cap).abs() < 1e-9 {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 3.0 + 4.0 * (1.0 - progress) * scarcity + 2.0 * post_norm;
    }

    // Small smooth coupling of item size with progress: large items late in stream
    // prefer roomier bins (penalize tight fits for big items).
    score += 3.0 * fit_ratio * tightness * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-fit residual (mod-based dead-space classes) ----
    // Residuals that are "harmonically useful" (divisible into common item sizes)
    // should be favored. Class the residual by integer division into buckets.
    let res = post_residual;
    let res_class = res / 10; // coarse harmonic bucket (0..10)

    // Small residual = tight fit = good. Reward quadratically.
    score -= (bin_capacity as f64 - res as f64).powi(2) * 0.01 / bin_capacity as f64;

    // Exact fit: huge reward
    if res == 0 {
        score -= 1000.0;
    }

    // ---- Modulo harmony: residual divisible by small sizes is reusable ----
    if res > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50] {
            if res % m == 0 {
                harmony += 6.0;
            }
        }
        if res % 5 == 0 {
            harmony += 2.0;
        }
        score -= harmony;
    }

    // Dead zone: residual too small for any plausible item (items >= 1, but
    // tiny slivers under ~10 are near-dead given typical distributions).
    if res > 0 && res < 10 {
        score += 25.0; // penalize creating unusable slivers
    }

    // ---- Lookahead coupling: does next item fit in post-residual? ----
    if next_item_size > 0 && res >= next_item_size {
        // Chain fit is excellent: reward proportionally to how snugly next fits.
        let slack = (res - next_item_size) as f64;
        score -= 30.0 + (bin_capacity as f64 - slack) * 0.05;
    } else if next_item_size > 0 && res > 0 && next_item_size > res {
        // Next item won't fit here: mild penalty scaled by how badly it misses.
        score += (next_item_size - res) as f64 * 0.15;
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 {
        // If this is the only bin that fits, using it avoids opening a new bin.
        // Reward unless the fit is terrible (huge post residual waste avoided anyway).
        score -= 20.0;
        if res > 40 {
            score += 10.0; // but a very loose fit in the only fitting bin is still wasteful
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: must be worse than any decent fit.
        score += 60.0;
        // Open a new bin preferentially when existing bins fit poorly:
        // if mean residual is small (bins are full-ish), a fresh bin is fine.
        score -= mean_residual * 0.3;
        // Early in the stream, keeping options open is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // Many open bins: prefer consolidating rather than spreading.
        score += open_bins_count as f64 * 1.5;
        // If next item is large, a fresh bin with full capacity is attractive.
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    // ---- Mean-residual pressure: placing into a bin far below mean residual
    // balances the pool of residuals (keeps future fits viable). ----
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05; // favor bins with residual above the mean (use the fullest fitting bin)

    // ---- Fine harmonic tiebreak on residual class ----
    // Even-bucket residuals (10,20,30,...) are slightly preferred targets.
    if res_class % 2 == 0 && res > 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are nearly unusable later.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as i32) as f64 * 8.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 4.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when mean is high.
    if mean_residual > 30.0 && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate: only attractive when current bin would leave terrible dead space
    // or no bin fits well; empty bin has full residual, keep its score high unless desperate.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with stream progress and open bins.
        score += 15.0 + open_bins_count as f64 * 1.5;
        // If placing here would leave a bad gap in an existing bin anyway, new bin is fine.
        if post_residual > 0 && post_residual <= 10 && fitting_bins_count >= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: fill the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after also fitting the next item — mildly penalize large slack.
            let slack_after_next = post_residual - next_item_size;
            score += 0.5 * slack_after_next as f64;
            score -= 30.0; // bonus for lookahead compatibility
        } else {
            // Post residual can't fit next item: dead-space risk, penalize proportionally.
            score += 0.3 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer tighter-than-average bins.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && post_residual < next_item_size && post_residual > 0;
        if fitting_bins_count == 0 || poor_fit {
            score -= 150.0;
        } else {
            score += 250.0; // discourage opening new bins when fits exist
        }
    }

    // Slight stream-progression pressure to consolidate late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows as post_residual shrinks toward 0.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Perfect fill is gold.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 0.35 * (post_residual as f64 - next_item_size as f64);
        } else {
            // Next item won't fit here; mildly penalize wasting a large residual.
            score += 0.10 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or when open bins are all fairly full (poor fits everywhere).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let crowded = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        score += 8.0; // base reluctance to open a new bin
        score -= 20.0 * item_frac;                 // large items justify fresh bins
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0); // many bins => consolidation pressure
        if mean_residual < item_size as f64 {
            score -= 10.0; // no open bin has room worth using
        }
        let _ = crowded;
    }

    // Time-horizon modulation: late in the stream, prefer filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tight;

    // Global slack: if mean residual is high, be pickier about wasted space.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;
    let mut score = post;

    // Non-linear dead-space penalty: quadratic in post_residual, amplified by stream progress.
    score += 2.0 * post_norm * post_norm * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as the stream matures.
    score -= 8.0 * (1.0 - post_norm).powi(3) * (0.3 + 0.7 * progress);

    // Penalize residual that cannot fit a plausible future item (smooth coupling with mean residual).
    let mean_n = mean_residual / cap;
    score += 3.0 * (post_norm - mean_n).abs() * cap * 0.3;

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 5.0 * (1.0 - (nxt / cap)).powi(2);
        } else {
            let gap = (nxt - post) / cap;
            score += 4.0 * gap * gap * cap;
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: smooth penalty that eases late in the stream or when no alternatives exist.
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count as f64).recip();
        score += 10.0 * (1.0 - 0.5 * progress) - 4.0 * pressure * fit_ratio;
    }

    // Mild dispersion penalty: prefer bins whose residual diverges from the mean when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.4 * (post_norm - mean_n).abs() * cap * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover belongs to a "useful"
    // residue class (divisible by common small item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty: tiny leftovers (< 10) are nearly unusable.
    if pr < 10 && pr > 0 {
        score += 40.0;
    }

    // Harmonic reward: post_residual divisible by 10, 20, 25, 50 classes
    if pr == 0 {
        score -= 100.0; // perfect fit
    } else {
        let mut harmony = 0.0;
        if pr % 10 == 0 { harmony += 6.0; }
        if pr % 20 == 0 { harmony += 4.0; }
        if pr % 25 == 0 { harmony += 4.0; }
        if pr % 50 == 0 { harmony += 5.0; }
        score -= harmony;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            score -= 10.0 * (next_item_size as f64 / cap);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 8.0 * (prf / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling fuller bins: reward small post_residual relative to capacity.
    score -= 15.0 * (1.0 - prf / cap);

    // New-bin candidate: only attractive when current bin would leave a bad fit
    // (large post_residual that doesn't match next item) or many bins already open.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && next_item_size != pr { 1.0 } else { 0.0 };
        score = 30.0 + 20.0 * bad_fit + 2.0 * open_bins_count as f64
              - 10.0 * (mean_residual / cap);
        if pr >= 70 {
            score -= 15.0; // current placement would waste a lot; new bin may be better
        }
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size <= pr {
            score += 50.0; // keep using the last-chance bin instead
        }
    }

    // Mild stream-phase modulation: early on, be more conservative about tight fits.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - phase);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for even the
    // smallest plausible future item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Penalize residuals too small for the lookahead item (dead space for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.25;
    }
    // Reward residuals that exactly fit the next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64 / bin_capacity as f64) * 8.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, tight existing residuals). Otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
        if item_size >= 70 {
            score -= 18.0;
        }
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 + 5.0 {
            score += 20.0;
        }
    }

    // Mild alignment with mean residual: prefer bins near the mean (typical slots).
    score -= (mean_residual - post_residual as f64).abs() * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward post_residual matching next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: post_residual == next_item_size -> strong reward
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // next item fits but leaves slack; mild penalty proportional to slack
            score += 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit; penalize by the shortfall
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
        // soft attraction toward exact match
        score += 0.1 * diff;
    } else {
        // last item: prefer minimal waste
        score += 0.0;
    }

    // Prefer tight fits overall: reward small post_residual relative to mean residual
    score += 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins exist that fit comfortably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // new bin is attractive only if item is large relative to residual pattern
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness < 0.6 && mean_residual >= item_size as f64 * 1.2 {
            score += 20.0; // discourage new bin; existing space suffices
        } else {
            score += 3.0; // slight default penalty to keep bins closed
        }
    }

    // Late in stream: consolidate harder (avoid spreading items)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64 * 0.1;

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0; // nearly full bin is fine actually; small hole is dead space
        score -= 20.0; // but a full bin means no waste — net reward
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post_residual < next_item_size as f64 && next_item_size > 0 {
        // leftover space cannot fit the next item: dead space penalty
        score += 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // this bin can also host the lookahead item: strong reward
        score -= 0.4 * (post_residual as f64 - next_item_size as f64).min(30.0);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Cost of opening a bin grows with number of open bins and stream progress.
        score += 40.0 + 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // But if the item is large and mean residual is small, opening may be better.
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Late in the stream, consolidate: penalize spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * progress;

    score
}
